def _ensure_task_exists(task_id: str) -> None:
    if not _task_store.exists(task_id):
        raise HTTPException(404, "任务不存在")


def _expired_task_snapshot(task_id: str) -> dict[str, Any]:
    """Terminal tombstone for an in-memory task lost during a service restart.

    Task snapshots deliberately live in process memory.  A browser tab running
    an older bundle otherwise treats a post-restart 404 as a transient error
    and retries forever.  Returning a terminal snapshot lets both old and new
    clients release their pollers without pretending the task is still active.
    """

    return {
        "id": task_id,
        "task_id": task_id,
        "status": "stopped",
        "progress": "",
        "logs": [],
        "success": 0,
        "skipped": 0,
        "errors": [],
        "error": "任务运行时快照已因服务重启过期，已停止轮询",
        "control": {"stop_requested": True},
        "expired": True,
    }


def _ensure_task_mutable(task_id: str) -> None:
    _ensure_task_exists(task_id)
    snapshot = _task_store.snapshot(task_id)
    if snapshot.get("status") in TERMINAL_TASK_STATUSES:
        raise HTTPException(409, "任务已结束，无法再执行控制操作")


def _bounded_register_config_int(
    config: dict[str, Any],
    key: str,
    *,
    default: int,
    minimum: int = 1,
    maximum: int = REGISTER_CONCURRENCY_HARD_LIMIT,
) -> int:
    raw = config.get(key)
    try:
        parsed = float(raw)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(parsed) or not parsed.is_integer():
        return default
    return max(minimum, min(maximum, int(parsed)))


def _bounded_register_config_float(
    config: dict[str, Any],
    key: str,
    *,
    default: float,
    minimum: float = 0.0,
    maximum: float = REGISTER_DELAY_MAX_SECONDS,
) -> float:
    raw = config.get(key)
    try:
        parsed = float(raw)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(parsed):
        return default
    return max(minimum, min(maximum, parsed))


def _validate_register_delay(value: Any, label: str) -> float:
    try:
        parsed = float(value)
    except (TypeError, ValueError) as exc:
        raise HTTPException(400, f"{label}必须是 0 到 3600 之间的有限数字") from exc
    if not math.isfinite(parsed) or not 0 <= parsed <= REGISTER_DELAY_MAX_SECONDS:
        raise HTTPException(400, f"{label}必须是 0 到 3600 之间的有限数字")
    return parsed


def _normalize_register_runtime_controls(
    prepared: RegisterTaskRequest,
    original: RegisterTaskRequest,
    config: dict[str, Any],
    *,
    forced_serial_reason: str = "",
) -> dict[str, Any]:
    supplied = set(getattr(original, "model_fields_set", set()) or set())
    if str(prepared.platform or "").strip().lower() != "chatgpt":
        requested_concurrency = int(original.concurrency)
        control = {
            "executor_mode": "legacy",
            "requested_concurrency": requested_concurrency,
            "effective_concurrency": prepared.concurrency,
            "default_concurrency": 1,
            "concurrency_cap": REGISTER_CONCURRENCY_HARD_LIMIT,
            "concurrency_reason": "",
            "requested_delay_seconds": float(original.register_delay_seconds or 0),
            "requested_delay_max_seconds": float(original.register_delay_max_seconds or 0),
            "effective_delay_seconds": float(prepared.register_delay_seconds or 0),
            "effective_delay_max_seconds": float(prepared.register_delay_max_seconds or 0),
            "delay_source": "legacy",
        }
        prepared._register_control = control
        return control

    browser_executor = str(prepared.executor_type or "protocol").strip().lower() in {
        "headless",
        "headed",
    }
    executor_mode = "browser" if browser_executor else "protocol"
    if browser_executor:
        default_concurrency = _bounded_register_config_int(
            config,
            "chatgpt_register_browser_default_concurrency",
            default=REGISTER_BROWSER_DEFAULT_CONCURRENCY,
            maximum=REGISTER_BROWSER_MAX_CONCURRENCY,
        )
        concurrency_cap = _bounded_register_config_int(
            config,
            "chatgpt_register_browser_max_concurrency",
            default=REGISTER_BROWSER_DEFAULT_MAX_CONCURRENCY,
            maximum=REGISTER_BROWSER_MAX_CONCURRENCY,
        )
    else:
        default_concurrency = _bounded_register_config_int(
            config,
            "chatgpt_register_protocol_default_concurrency",
            default=REGISTER_PROTOCOL_DEFAULT_CONCURRENCY,
            maximum=REGISTER_PROTOCOL_MAX_CONCURRENCY,
        )
        concurrency_cap = _bounded_register_config_int(
            config,
            "chatgpt_register_protocol_max_concurrency",
            default=REGISTER_PROTOCOL_MAX_CONCURRENCY,
            maximum=REGISTER_PROTOCOL_MAX_CONCURRENCY,
        )
    default_concurrency = min(default_concurrency, concurrency_cap)

    requested_concurrency: int | None = None
    if "concurrency" in supplied:
        requested_concurrency = int(original.concurrency)
        if requested_concurrency < 1:
            raise HTTPException(400, "注册并发必须是大于等于 1 的整数")
    selected_concurrency = requested_concurrency or default_concurrency
    effective_concurrency = min(
        selected_concurrency,
        concurrency_cap,
        max(int(prepared.count or 1), 1),
    )
    concurrency_reason = ""
    if forced_serial_reason:
        effective_concurrency = 1
        concurrency_reason = forced_serial_reason
    elif selected_concurrency > concurrency_cap:
        concurrency_reason = f"{executor_mode}_cap"
    elif selected_concurrency > max(int(prepared.count or 1), 1):
        concurrency_reason = "target_count"
    prepared.concurrency = max(effective_concurrency, 1)

    configured_delay_min = _bounded_register_config_float(
        config,
        "chatgpt_register_delay_seconds",
        default=REGISTER_DELAY_DEFAULT_SECONDS,
    )
    configured_delay_max = _bounded_register_config_float(
        config,
        "chatgpt_register_delay_max_seconds",
        default=REGISTER_DELAY_DEFAULT_MAX_SECONDS,
    )
    if configured_delay_max == 0 and configured_delay_min > 0:
        configured_delay_max = configured_delay_min
    elif configured_delay_max < configured_delay_min:
        configured_delay_min = REGISTER_DELAY_DEFAULT_SECONDS
        configured_delay_max = REGISTER_DELAY_DEFAULT_MAX_SECONDS

    delay_min_supplied = "register_delay_seconds" in supplied
    delay_max_supplied = "register_delay_max_seconds" in supplied
    requested_delay_min = (
        _validate_register_delay(original.register_delay_seconds, "注册最小启动延时")
        if delay_min_supplied
        else None
    )
    requested_delay_max = (
        _validate_register_delay(original.register_delay_max_seconds, "注册最大启动延时")
        if delay_max_supplied
        else None
    )
    if not delay_min_supplied and not delay_max_supplied:
        effective_delay_min = configured_delay_min
        effective_delay_max = configured_delay_max
        delay_source = "system_default"
    elif delay_min_supplied and not delay_max_supplied:
        # Legacy clients only sent one delay field. Preserve its fixed-delay
        # meaning instead of unexpectedly combining it with the new max default.
        effective_delay_min = float(requested_delay_min or 0)
        effective_delay_max = effective_delay_min
        delay_source = "request_fixed_legacy"
    else:
        effective_delay_min = (
            float(requested_delay_min)
            if requested_delay_min is not None
            else min(configured_delay_min, float(requested_delay_max or 0))
        )
        if float(requested_delay_max or 0) == 0 and effective_delay_min > 0:
            effective_delay_max = effective_delay_min
            delay_source = "request_fixed"
        else:
            effective_delay_max = float(requested_delay_max or 0)
            delay_source = "request_range"
    if effective_delay_max < effective_delay_min:
        raise HTTPException(400, "注册最大启动延时不能小于最小启动延时")
    prepared.register_delay_seconds = effective_delay_min
    prepared.register_delay_max_seconds = effective_delay_max

    control = {
        "executor_mode": executor_mode,
        "requested_concurrency": requested_concurrency,
        "effective_concurrency": prepared.concurrency,
        "default_concurrency": default_concurrency,
        "concurrency_cap": concurrency_cap,
        "concurrency_reason": concurrency_reason,
        "requested_delay_seconds": requested_delay_min,
        "requested_delay_max_seconds": requested_delay_max,
        "effective_delay_seconds": effective_delay_min,
        "effective_delay_max_seconds": effective_delay_max,
        "delay_source": delay_source,
    }
    prepared._register_control = control
    return control


_REGISTER_PROXY_ALIASES = (
    "proxy",
    "proxy_url",
    "register_proxy",
    "probe_proxy",
    "dynamic_proxy_template",
)
_REGISTER_PROXY_MODE_ALIASES = (
    "proxy_mode",
    "register_proxy_mode",
    "probe_proxy_mode",
)
_REGISTER_PROXY_COUNTRY_ALIASES = (
    "proxy_country_code",
    "register_proxy_country_code",
    "probe_proxy_country_code",
)
_REGISTER_PROXY_FAILOVER_ALIASES = (
    "proxy_failover",
    "register_proxy_failover",
    "probe_proxy_failover",
)

_DYNAMIC_PROXY_COMMON_RUNTIME_KEYS = (
    "dynamic_proxy_probe_enabled",
    "dynamic_proxy_require_country_match",
    "dynamic_proxy_probe_timeout_seconds",
    "dynamic_proxy_max_attempts",
)
_MIYAIP_RUNTIME_KEYS = (
    "miyaip_crc",
    "miyaip_key_name",
    "miyaip_pool",
    "miyaip_gateway_server",
    "miyaip_protocol",
    "miyaip_request_timeout_seconds",
)
_TASK_PROXY_RUNTIME_KEYS = (
    "proxy",
    "proxy_mode",
    "dynamic_proxy_provider",
    "proxy_country_code",
    "proxy_failover",
    "proxy_max_candidates",
    "proxy_min_score",
    "dynamic_proxy_ip_retention_minutes",
    *_DYNAMIC_PROXY_COMMON_RUNTIME_KEYS,
    *_MIYAIP_RUNTIME_KEYS,
)


def _normalize_miyaip_runtime_values(values: dict[str, Any]) -> dict[str, Any]:
    from core.miyaip_proxy import normalize_miyaip_config

    try:
        config = normalize_miyaip_config(
            crc=values.get("miyaip_crc"),
            key_name=values.get("miyaip_key_name"),
            pool=values.get("miyaip_pool"),
            gateway_server=values.get("miyaip_gateway_server"),
            protocol=values.get("miyaip_protocol"),
            timeout_seconds=values.get("miyaip_request_timeout_seconds"),
        )
    except ValueError as exc:
        raise HTTPException(400, str(exc)) from exc
    return {
        "miyaip_crc": config.crc,
        "miyaip_key_name": config.key_name,
        "miyaip_pool": config.pool,
        "miyaip_gateway_server": config.gateway_server,
        "miyaip_protocol": config.protocol,
        "miyaip_request_timeout_seconds": config.request_timeout_seconds,
    }


def _first_register_proxy_value(
    values: dict[str, Any],
    aliases: tuple[str, ...],
    *,
    allow_empty: bool = False,
) -> tuple[bool, Any]:
    for key in aliases:
        if key not in values:
            continue
        value = values.get(key)
        if allow_empty or value not in (None, ""):
            return True, value
    return False, None


def _canonical_register_proxy_mode(
    value: Any,
    *,
    has_proxy: bool,
    global_mode: str,
) -> str:
    mode = str(value or "").strip().lower()
    if mode in {"global", "config", "task", "task_proxy", "default", "inherit"}:
        if has_proxy:
            return "specified"
        mode = str(global_mode or "dynamic").strip().lower()
    if not mode:
        mode = "specified" if has_proxy else str(global_mode or "dynamic").strip().lower()
    if mode in {"none", "no_proxy", "direct", "直连"}:
        return "direct"
    if mode in {"manual", "explicit"}:
        return "specified"
    if mode in {"specified", "pool", "dynamic"}:
        return mode
    return "specified" if has_proxy else "dynamic"


def _normalize_register_proxy_controls(
    prepared: RegisterTaskRequest,
    original: RegisterTaskRequest,
    config: dict[str, Any],
) -> dict[str, Any]:
    """Freeze the resolver's effective proxy controls at enqueue time."""

    request_extra = original.extra if isinstance(original.extra, dict) else {}
    supplied_fields = set(getattr(original, "model_fields_set", set()) or set())

    has_extra_proxy, extra_proxy = _first_register_proxy_value(
        request_extra,
        _REGISTER_PROXY_ALIASES,
    )
    if "proxy" in supplied_fields and original.proxy not in (None, ""):
        request_proxy = str(original.proxy or "").strip()
        has_request_proxy = bool(request_proxy)
    else:
        request_proxy = str(extra_proxy or "").strip() if has_extra_proxy else ""
        has_request_proxy = bool(request_proxy)

    global_mode = str(config.get("task_proxy_mode") or "dynamic").strip().lower()
    has_extra_mode, extra_mode = _first_register_proxy_value(
        request_extra,
        _REGISTER_PROXY_MODE_ALIASES,
    )
    if "proxy_mode" in supplied_fields and str(original.proxy_mode or "").strip():
        raw_mode = original.proxy_mode
    elif has_extra_mode:
        raw_mode = extra_mode
    else:
        raw_mode = ""
    raw_mode_text = str(raw_mode or "").strip().lower()
    inherits_global_proxy = (
        not has_request_proxy
        and (
            not raw_mode_text
            or raw_mode_text
            in {"global", "config", "task", "task_proxy", "default", "inherit"}
        )
    )
    mode = _canonical_register_proxy_mode(
        raw_mode,
        has_proxy=has_request_proxy,
        global_mode=global_mode,
    )

    dynamic_provider = ""
    dynamic_runtime: dict[str, Any] = {}
    if mode == "dynamic":
        from core.dynamic_proxy import dynamic_proxy_supported
        from core.task_proxy_config import normalize_dynamic_proxy_provider

        if (
            "dynamic_proxy_provider" in supplied_fields
            and str(original.dynamic_proxy_provider or "").strip()
        ):
            raw_provider = original.dynamic_proxy_provider
        elif str(request_extra.get("dynamic_proxy_provider") or "").strip():
            raw_provider = request_extra.get("dynamic_proxy_provider")
        elif request_proxy and dynamic_proxy_supported(request_proxy):
            raw_provider = "cliproxy"
        elif inherits_global_proxy:
            raw_provider = config.get("dynamic_proxy_provider") or "cliproxy"
        else:
            # Missing provider is the legacy Cliproxy contract. New clients
            # submit the global provider explicitly when inheriting defaults.
            raw_provider = "cliproxy"
        try:
            dynamic_provider = normalize_dynamic_proxy_provider(raw_provider)
        except ValueError as exc:
            raise HTTPException(400, str(exc)) from exc

        if dynamic_provider == "miyaip" and request_proxy:
            raise HTTPException(400, "MiyaIP 动态代理不接受 Cliproxy 模板覆盖")
        dynamic_runtime["dynamic_proxy_provider"] = dynamic_provider
        for key in _DYNAMIC_PROXY_COMMON_RUNTIME_KEYS:
            value = request_extra.get(key)
            if value in (None, ""):
                value = config.get(key)
            if value not in (None, ""):
                dynamic_runtime[key] = value
        if dynamic_provider == "miyaip":
            for key in _MIYAIP_RUNTIME_KEYS:
                value = request_extra.get(key)
                if value in (None, ""):
                    value = config.get(key)
                dynamic_runtime[key] = value if value is not None else ""
            dynamic_runtime.update(_normalize_miyaip_runtime_values(dynamic_runtime))
        else:
            retention = request_extra.get("dynamic_proxy_ip_retention_minutes")
            if retention in (None, ""):
                retention = original.dynamic_proxy_ip_retention_minutes or config.get(
                    "dynamic_proxy_ip_retention_minutes"
                )
            if retention not in (None, ""):
                dynamic_runtime["dynamic_proxy_ip_retention_minutes"] = retention

    if not request_proxy:
        if mode == "dynamic" and dynamic_provider == "cliproxy":
            request_proxy = str(
                config.get("dynamic_proxy_template")
                or config.get("task_proxy_url")
                or ""
            ).strip()
        elif mode == "specified":
            request_proxy = str(config.get("task_proxy_url") or "").strip()

    has_extra_country, extra_country = _first_register_proxy_value(
        request_extra,
        _REGISTER_PROXY_COUNTRY_ALIASES,
        allow_empty=True,
    )
    if "proxy_country_code" in supplied_fields:
        country = str(original.proxy_country_code or "").strip().upper()
    elif has_extra_country:
        country = str(extra_country or "").strip().upper()
    elif mode == "dynamic":
        country = str(
            config.get("dynamic_proxy_default_country")
            or config.get("task_proxy_country_code")
            or ""
        ).strip().upper()
    else:
        country = str(config.get("task_proxy_country_code") or "").strip().upper()

    has_extra_failover, extra_failover = _first_register_proxy_value(
        request_extra,
        _REGISTER_PROXY_FAILOVER_ALIASES,
    )
    if "proxy_failover" in supplied_fields:
        failover = bool(original.proxy_failover)
    elif has_extra_failover:
        failover = _is_truthy(extra_failover)
    else:
        failover = _is_truthy(config.get("task_proxy_failover"))

    prepared.proxy = request_proxy or None
    prepared.proxy_mode = mode
    prepared.dynamic_proxy_provider = dynamic_provider
    prepared.proxy_country_code = country
    prepared.proxy_failover = failover
    prepared._dynamic_proxy_runtime = dynamic_runtime
    return {
        "proxy": request_proxy,
        "proxy_mode": mode,
        "dynamic_proxy_provider": dynamic_provider,
        "proxy_country_code": country,
        "proxy_failover": failover,
    }


def _resolve_register_unique_exit_ip_policy(
    prepared: RegisterTaskRequest,
    original: RegisterTaskRequest,
    config: dict[str, Any],
) -> dict[str, Any]:
    request_extra = original.extra if isinstance(original.extra, dict) else {}
    raw_policy: Any = None
    source = "default"
    if request_extra.get("chatgpt_register_unique_exit_ip_policy") not in (None, ""):
        raw_policy = request_extra.get("chatgpt_register_unique_exit_ip_policy")
        source = "request_policy"
    elif request_extra.get("chatgpt_register_unique_exit_ip_enabled") not in (None, ""):
        raw_policy = "required" if _is_truthy(request_extra.get("chatgpt_register_unique_exit_ip_enabled")) else "off"
        source = "request_legacy_bool"
    elif config.get("chatgpt_register_unique_exit_ip_policy") not in (None, ""):
        raw_policy = config.get("chatgpt_register_unique_exit_ip_policy")
        source = "config_policy"
    elif config.get("chatgpt_register_unique_exit_ip_enabled") not in (None, ""):
        raw_policy = "required" if _is_truthy(config.get("chatgpt_register_unique_exit_ip_enabled")) else "off"
        source = "config_legacy_bool"
    else:
        raw_policy = "auto"

    policy_text = str(raw_policy or "auto").strip().lower()
    if policy_text in {"1", "true", "yes", "on", "required", "strict"}:
        policy = "required"
    elif policy_text in {"0", "false", "no", "off", "disabled"}:
        policy = "off"
    elif policy_text == "auto":
        policy = "auto"
    else:
        raise HTTPException(
            400,
            "chatgpt_register_unique_exit_ip_policy 必须是 auto、required 或 off",
        )

    proxy_controls = _normalize_register_proxy_controls(
        prepared,
        original,
        config,
    )
    mode = str(proxy_controls["proxy_mode"])
    failover_enabled = bool(proxy_controls["proxy_failover"])
    rotatable = mode in {"dynamic", "pool"} or (
        mode == "specified" and failover_enabled
    )
    # The implicit policy is intentionally conservative: only dynamic mode is
    # guaranteed to mint a fresh candidate on demand. Pool/specified modes stay
    # opt-in even when failover exists because their candidate set may be small.
    auto_eligible = mode == "dynamic"
    enabled = policy == "required" or (policy == "auto" and auto_eligible)
    # Freeze the resolved network mode together with the registration controls.
    # Otherwise a request that relies on global dynamic mode can enable the
    # policy here but miss the dynamic refresh budget inside the runner.
    prepared.extra["chatgpt_register_unique_exit_ip_policy"] = policy
    prepared.extra["chatgpt_register_unique_exit_ip_enabled"] = enabled
    result = {
        "policy": policy,
        "source": source,
        "enabled": enabled,
        "proxy_mode": mode,
        "rotatable": rotatable,
        "auto_eligible": auto_eligible,
    }
    prepared._register_unique_exit_ip = result
    return result


def _prepare_register_request(req: RegisterTaskRequest) -> RegisterTaskRequest:
    from core.config_store import config_store
    from services.chatgpt_core.registration_diagnostics import (
        DIAGNOSTIC_MODE_OFF,
        normalize_registration_diagnostics_mode,
    )

    config = config_store.get_all().copy()
    req_data = req.model_dump()
    req_data["extra"] = deepcopy(req_data.get("extra") or {})
    prepared = RegisterTaskRequest(**req_data)

    from services.chatgpt_core.browser_identity import (
        REGISTER_BROWSER_FAMILY_OPTIONS,
        normalize_protocol_browser_family,
    )

    if str(prepared.platform or "").strip().lower() == "chatgpt":
        supplied = set(getattr(req, "model_fields_set", set()) or set())
        configured_browser_family = str(
            config.get("default_browser_family") or "random"
        ).strip()
        requested_browser_family = (
            prepared.browser_family
            if "browser_family" in supplied
            else configured_browser_family
        )
        raw_browser_family = str(requested_browser_family or "").strip()
        normalized_browser_family = normalize_protocol_browser_family(
            raw_browser_family,
            default="",
        )
        if not raw_browser_family:
            normalized_browser_family = "random"
        if normalized_browser_family not in REGISTER_BROWSER_FAMILY_OPTIONS:
            raise HTTPException(
                400,
                "browser_family 必须是 random、chrome、firefox 或 safari",
            )
        browser_executor = str(prepared.executor_type or "protocol").strip().lower() in {
            "headless",
            "headed",
        }
        if browser_executor and normalized_browser_family not in {"random", "firefox"}:
            raise HTTPException(
                400,
                "无头/有头浏览器当前由 Camoufox Firefox 执行，只支持 browser_family=firefox；协议执行器才支持 Chrome、Firefox、Safari",
            )
        # A deep browser task must not retain random as an unresolved choice.
        # Protocol tasks keep random frozen and resolve it once per attempt.
        prepared.browser_family = (
            "firefox" if browser_executor else normalized_browser_family
        )
    else:
        prepared.browser_family = "random"

    try:
        prepared.registration_diagnostics_mode = (
            normalize_registration_diagnostics_mode(
                prepared.registration_diagnostics_mode
            )
        )
    except ValueError as exc:
        raise HTTPException(400, str(exc)) from exc
    if prepared.registration_diagnostics_mode != DIAGNOSTIC_MODE_OFF:
        if str(prepared.platform or "").strip().lower() != "chatgpt":
            raise HTTPException(400, "注册诊断仅支持 ChatGPT 注册任务")
        if str(prepared.executor_type or "").strip().lower() not in {
            "protocol",
            "headless",
            "headed",
        }:
            raise HTTPException(400, "注册诊断仅支持协议、无头浏览器或有头浏览器执行器")

    def _validate_unique_exit_ip_requirements() -> None:
        if prepared.platform != "chatgpt":
            return
        unique_policy = _resolve_register_unique_exit_ip_policy(prepared, req, config)
        if not unique_policy["enabled"]:
            return
        mode = str(unique_policy.get("proxy_mode") or "dynamic").strip().lower()
        if unique_policy["policy"] == "required" and mode in {"none", "no_proxy", "direct", "直连"}:
            raise HTTPException(400, "开启强制独立出口 IP 时不能使用直连模式；请改用动态代理、代理池或可切换的多代理。")
        if mode in {"manual", "explicit"}:
            mode = "specified"
        failover_enabled = bool(prepared.proxy_failover)
        if unique_policy["policy"] == "required" and mode == "specified" and int(prepared.count or 1) > 1 and not failover_enabled:
            raise HTTPException(
                400,
                "单个指定代理无法满足多个账号独立出口 IP；请开启失败切换/代理池/动态代理，或把注册数量降为 1。",
            )

    registration_entry = str(
        prepared.extra.get("chatgpt_registration_entry")
        or prepared.extra.get("registration_entry")
        or ""
    ).strip().lower().replace("-", "_")
    if prepared.platform == "chatgpt" and registration_entry in {"phone", "phone_signup", "sms", "sms_signup"}:
        prepared.extra["chatgpt_registration_entry"] = "phone_signup"
        prepared.extra["chatgpt_registration_mode"] = "access_token_only"
        prepared.extra["chatgpt_has_refresh_token_solution"] = False
        # 手机号本身是注册标识；串行能避免同一个号池号码在并发任务里被重复领取。
        _normalize_register_runtime_controls(
            prepared,
            req,
            config,
            forced_serial_reason="phone_signup",
        )
        _validate_unique_exit_ip_requirements()
        return prepared

    mail_provider = prepared.extra.get("mail_provider") or config_store.get(
        "mail_provider", ""
    )

    if mail_provider == "manual_email_otp":
        if prepared.platform != "chatgpt":
            raise HTTPException(400, "manual_email_otp 模式目前只支持 ChatGPT")
        prepared.email = str(prepared.email or "").strip()
        if not prepared.email:
            raise HTTPException(400, "manual_email_otp 模式必须填写邮箱地址")
        existing_account_capture = prepared.extra.get("chatgpt_existing_account_capture")
        if isinstance(existing_account_capture, str):
            existing_account_capture = existing_account_capture.strip().lower() in {"1", "true", "yes", "on"}
        else:
            existing_account_capture = bool(existing_account_capture)
        prepared.count = 1
        prepared.concurrency = 1
        if not existing_account_capture:
            prepared.password = None
        prepared.extra["manual_email_address"] = prepared.email
        prepared.extra["chatgpt_existing_account_capture"] = existing_account_capture

    if str(mail_provider or "").strip().lower() in {"email_api", "api_email", "email_otp_api", "mail_api_otp"}:
        if prepared.platform != "chatgpt":
            raise HTTPException(400, "email_api 模式目前只支持 ChatGPT")
        from core.base_mailbox import parse_email_api_lines

        lines = prepared.extra.get("email_api_lines") or prepared.extra.get("email_api_accounts") or ""
        gmail_variant_seed = str(
            prepared.extra.get("email_api_gmail_variant_random_seed")
            or f"{time.time_ns()}-{random.getrandbits(64):016x}"
        ).strip()
        candidates, errors = parse_email_api_lines(
            lines,
            gmail_dot_variant_enabled=_is_truthy(prepared.extra.get("email_api_gmail_dot_variant_enabled", True)),
            gmail_variant_count=prepared.extra.get("email_api_gmail_variant_count", 2),
            gmail_variant_rules=prepared.extra.get("email_api_gmail_variant_rules", "all"),
            gmail_plus_tag_template=prepared.extra.get("email_api_gmail_plus_tag_template", "r{rand}"),
            gmail_variant_random_seed=gmail_variant_seed,
            default_scheme=str(prepared.extra.get("email_api_default_scheme") or "https"),
        )
        if errors:
            first = errors[0]
            raise HTTPException(400, f"Email API 行解析失败: 第 {first.get('line')} 行 {first.get('reason')}")
        if not candidates:
            raise HTTPException(400, "email_api 模式请至少提供一条 email----api")
        prepared.extra["mail_provider"] = "email_api"
        prepared.extra["email_api_candidates"] = candidates
        prepared.extra["email_api_candidate_count"] = len(candidates)
        prepared.extra["email_api_gmail_variant_random_seed"] = gmail_variant_seed
        if _is_truthy(prepared.extra.get("email_api_use_all_identities", True)):
            prepared.count = len(candidates)
        else:
            prepared.count = min(max(int(prepared.count or 1), 1), len(candidates))
        prepared.email = None

    if mail_provider in {"tempmail_local", "tempmail_api"}:
        mode = str(prepared.extra.get("tempmail_mode") or config_store.get("tempmail_mode", "fixed_domain") or "fixed_domain").strip().lower()
        if mode == "fixed_domain":
            domains = _normalize_domain_list(prepared.extra.get("tempmail_fixed_domains"))
            if not domains:
                domains = _normalize_domain_list(config_store.get("tempmail_fixed_domains", ""))
            primary_domain = str(prepared.extra.get("tempmail_primary_domain") or config_store.get("tempmail_primary_domain", "") or "").strip().lstrip("@.")
            if primary_domain and primary_domain not in domains:
                domains.append(primary_domain)
            if not domains:
                raise HTTPException(400, "固定域名模式下请至少选择一个 TempMail 可用域名")
            prepared.extra["tempmail_mode"] = "fixed_domain"
            prepared.extra["tempmail_fixed_domains"] = domains
            prepared.extra["tempmail_primary_domain"] = primary_domain or domains[0]

    if mail_provider == "luckmail":
        prepared.extra["luckmail_project_code"] = "openai"

    forced_serial_reason = "manual_email_otp" if mail_provider == "manual_email_otp" else ""
    _normalize_register_runtime_controls(
        prepared,
        req,
        config,
        forced_serial_reason=forced_serial_reason,
    )
    _validate_unique_exit_ip_requirements()
    return prepared


def _registration_mailbox_task_meta(effective_extra: dict[str, Any]) -> dict[str, Any]:
    """Freeze the non-secret mailbox selector used by one registration task."""
    from services.chatgpt_core.mailbox_state import normalize_mailbox_provider

    provider = normalize_mailbox_provider(effective_extra.get("mail_provider"))[:80]
    if provider != "tempmail_local":
        return {
            "provider": provider,
            "mode": "",
            "primary_domain": "",
            "domains": [],
            "domain_count": 0,
        }

    mode = str(effective_extra.get("tempmail_mode") or "fixed_domain").strip().lower()[:40]
    primary_domains = _normalize_domain_list(
        [effective_extra.get("tempmail_primary_domain")]
    )
    primary_domain = primary_domains[0] if primary_domains else ""

    if mode in {"task_subdomain", "ready_subdomain", "random_domain"}:
        domains = [primary_domain] if primary_domain else []
    else:
        domains = _normalize_domain_list(effective_extra.get("tempmail_fixed_domains"))
        if primary_domain and primary_domain not in domains:
            domains.append(primary_domain)

    return {
        "provider": provider,
        "mode": mode,
        "primary_domain": primary_domain,
        "domains": domains[:64],
        "domain_count": len(domains),
    }


def _create_task_record(
    task_id: str, req: RegisterTaskRequest, source: str, meta: dict | None = None
):
    _task_store.create(
        task_id,
        platform=req.platform,
        total=req.count,
        source=source,
        meta=meta,
        # Only the registration runner can safely drain active account attempts.
        supports_after_current=True,
    )


def _bool_config_default_true(value: Any) -> bool:
    return parse_route_bool(value, default=True)


def _coerce_existing_account_login_route_event(
    value: Any,
    *,
    fallback_email: str = "",
    default_blocked: bool = False,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    routed = bool(value.get("routed"))
    blocked = bool(value.get("blocked")) or bool(default_blocked)
    enabled = parse_route_bool(value.get("enabled"), default=not blocked)
    event = build_existing_account_login_route_event(
        email=str(value.get("email") or fallback_email or "").strip(),
        reason=value.get("reason") or value.get("message") or "",
        stage=str(value.get("stage") or "register_complete_flow"),
        enabled=enabled,
        routed=routed,
        blocked=blocked,
        action=(
            "skip_save"
            if blocked
            else "login_recovery"
            if routed
            else str(value.get("action") or "")
        ),
        source=str(value.get("source") or "registration"),
        base_event=value,
    )
    if fallback_email and not event.get("email"):
        event["email"] = str(fallback_email).strip()
    return event


def _record_existing_account_login_route(task_id: str, event: dict[str, Any]) -> None:
    route_event = _coerce_existing_account_login_route_event(event)
    if not route_event:
        return
    try:
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        route_items = latest_meta.get(LOGIN_ROUTE_TASK_META_KEY)
        if not isinstance(route_items, list):
            route_items = []
        email_key = str(route_event.get("email") or "").strip().lower()
        action_key = str(route_event.get("action") or "").strip().lower()
        reason_key = str(route_event.get("reason") or "").strip()[:120]
        duplicate_index = -1
        for idx, item in enumerate(route_items):
            if not isinstance(item, dict):
                continue
            if (
                str(item.get("email") or "").strip().lower() == email_key
                and str(item.get("action") or "").strip().lower() == action_key
                and str(item.get("reason") or "").strip()[:120] == reason_key
            ):
                duplicate_index = idx
                break
        if duplicate_index >= 0:
            route_items[duplicate_index] = {**dict(route_items[duplicate_index]), **route_event}
        else:
            route_items.append(route_event)
        _task_store.update_meta(task_id, {LOGIN_ROUTE_TASK_META_KEY: route_items[-500:]})
    except Exception as exc:
        _log(task_id, f"[WARN] 已注册邮箱路由记录写入任务快照失败: {exc}")


def _create_standalone_task_record(
    task_id: str,
    *,
    platform: str,
    source: str,
    total: int = 1,
    meta: dict | None = None,
    supports_after_current: bool = True,
) -> None:
    _task_store.create(
        task_id,
        platform=platform,
        total=max(int(total or 1), 1),
        source=source,
        meta=meta,
        # Most standalone records are account/order batches and use the same
        # dispatch gate.  One-account external sessions (for example GoPay)
        # opt out explicitly because "完成当前后停止" has no next item.
        supports_after_current=supports_after_current,
    )


def enqueue_register_task(
    req: RegisterTaskRequest,
    *,
    background_tasks: BackgroundTasks | None = None,
    source: str = "manual",
    meta: dict | None = None,
) -> str:
    supplied_fields = set(getattr(req, "model_fields_set", set()) or set())
    link_setting_supplied = "registration_paypal_link_enabled" in supplied_fields
    prepared = _prepare_register_request(req)
    if prepared.platform == "chatgpt":
        registration_zero_amount_enabled = bool(
            getattr(prepared, "registration_zero_amount_eligibility_enabled", False)
        )
        prepared.registration_zero_amount_eligibility_enabled = (
            registration_zero_amount_enabled
        )
        if registration_zero_amount_enabled:
            registration_zero_amount_country = (
                _normalize_registration_zero_amount_country(
                    getattr(
                        prepared,
                        "registration_zero_amount_checkout_country",
                        "VN",
                    )
                )
            )
        else:
            registration_zero_amount_country = str(
                getattr(
                    prepared,
                    "registration_zero_amount_checkout_country",
                    "VN",
                )
                or "VN"
            ).strip().upper()
            if not (
                len(registration_zero_amount_country) == 2
                and registration_zero_amount_country.isascii()
                and registration_zero_amount_country.isalpha()
            ):
                registration_zero_amount_country = "VN"
        prepared.registration_zero_amount_checkout_country = registration_zero_amount_country
        prepared._registration_eligibility_runtime = {}
        if registration_zero_amount_enabled:
            prepared._registration_eligibility_runtime = (
                _safe_registration_zero_amount_eligibility_settings(
                    registration_zero_amount_country
                )
            )
        registration_paypal_payment_enabled = bool(
            getattr(prepared, "registration_paypal_payment_enabled", False)
        )
        legacy_combined = not link_setting_supplied
        raw_link_enabled = getattr(prepared, "registration_paypal_link_enabled", None)
        registration_paypal_link_enabled = (
            registration_paypal_payment_enabled
            if legacy_combined
            else bool(raw_link_enabled)
        )
        if not legacy_combined:
            if registration_paypal_link_enabled and not registration_zero_amount_enabled:
                raise HTTPException(400, "开启注册后提链前必须先开启注册后 0 元检测")
            if registration_paypal_payment_enabled and not registration_paypal_link_enabled:
                raise HTTPException(400, "开启注册后支付前必须先开启注册后提链")
        prepared.registration_paypal_link_enabled = registration_paypal_link_enabled
        prepared.registration_paypal_payment_enabled = (
            registration_paypal_payment_enabled
        )
        prepared._registration_pipeline_legacy_combined = legacy_combined
        prepared._registration_paypal_payment_runtime = {}
        if registration_paypal_link_enabled:
            prepared._registration_paypal_payment_runtime = (
                _registration_paypal_payment_settings()
                if legacy_combined
                else _registration_paypal_payment_settings(
                    include_payment=registration_paypal_payment_enabled
                )
            )
    elif bool(getattr(prepared, "registration_paypal_link_enabled", False)) or bool(
        getattr(prepared, "registration_paypal_payment_enabled", False)
    ):
        raise HTTPException(400, "注册后 PayPal 提链和支付仅支持 ChatGPT 注册任务")
    task_id = f"task_{int(time.time() * 1000)}_{uuid.uuid4().hex[:8]}"
    prepared_extra = _build_effective_register_extra(prepared)
    initial_meta = dict(meta or {})
    if prepared.platform == "chatgpt":
        browser_executor = str(prepared.executor_type or "protocol").strip().lower() in {
            "headless",
            "headed",
        }
        initial_meta.setdefault(
            "registration_browser",
            {
                "browser_family": prepared.browser_family,
                "selection": (
                    "fixed"
                    if prepared.browser_family != "random"
                    else "per_attempt_random"
                ),
                "executor_type": str(prepared.executor_type or "protocol"),
                "deep_context": browser_executor,
            },
        )
        initial_meta.setdefault(
            "registration_zero_amount_eligibility_request",
            {
                "enabled": prepared.registration_zero_amount_eligibility_enabled,
                "checkout_country_code": prepared.registration_zero_amount_checkout_country,
            },
        )
        frozen_paypal_payment = dict(
            getattr(prepared, "_registration_paypal_payment_runtime", {}) or {}
        )
        initial_meta.setdefault(
            "registration_paypal_link_request",
            {
                "enabled": bool(prepared.registration_paypal_link_enabled),
                "link_profile": dict(frozen_paypal_payment.get("link_profile") or {}),
            },
        )
        initial_meta.setdefault(
            "registration_paypal_payment_request",
            {
                "enabled": prepared.registration_paypal_payment_enabled,
                "link_profile": dict(frozen_paypal_payment.get("link_profile") or {}),
                "payment_profile": dict(
                    frozen_paypal_payment.get("payment_profile") or {}
                ),
            },
        )
        initial_meta.setdefault(
            "registration_pipeline_request",
            {
                "zero_amount_enabled": prepared.registration_zero_amount_eligibility_enabled,
                "payment_link_enabled": bool(prepared.registration_paypal_link_enabled),
                "payment_enabled": prepared.registration_paypal_payment_enabled,
                "legacy_combined": bool(prepared._registration_pipeline_legacy_combined),
            },
        )
    initial_meta.setdefault(
        "proxy",
        _custom_email_proxy_meta(
            {
                "proxy": prepared.proxy or "",
                "proxy_mode": prepared.proxy_mode,
                "dynamic_proxy_provider": prepared.dynamic_proxy_provider,
                "proxy_country_code": prepared.proxy_country_code,
                "proxy_failover": prepared.proxy_failover,
                "proxy_max_candidates": prepared.proxy_max_candidates,
                "proxy_min_score": prepared.proxy_min_score,
            }
        ),
    )
    initial_meta["registration_diagnostics"] = {
        "mode": prepared.registration_diagnostics_mode,
        "enabled": prepared.registration_diagnostics_mode != "off",
        "artifact_count": 0,
        "recording_count": 0,
    }
    register_control = dict(getattr(prepared, "_register_control", {}) or {})
    unique_exit_ip_control = dict(
        getattr(prepared, "_register_unique_exit_ip", {}) or {}
    )
    if register_control:
        initial_meta.setdefault("registration_control", register_control)
    if unique_exit_ip_control:
        initial_meta.setdefault(
            "register_unique_exit_ip_policy",
            unique_exit_ip_control,
        )
    registration_entry = str(
        prepared_extra.get("chatgpt_registration_entry")
        or prepared_extra.get("registration_entry")
        or ""
    ).strip().lower().replace("-", "_")
    is_phone_signup_task = prepared.platform == "chatgpt" and registration_entry in {"phone", "phone_signup", "sms", "sms_signup"}
    if is_phone_signup_task:
        phone_lines = [
            str(line or "").strip()
            for line in str(prepared_extra.get("chatgpt_phone_signup_phone_lines") or "").splitlines()
            if str(line or "").strip()
        ]
        selected_prefixes = prepared_extra.get("chatgpt_phone_signup_selected_prefixes") or prepared_extra.get("selected_prefixes") or []
        if not isinstance(selected_prefixes, list):
            selected_prefixes = [str(selected_prefixes)] if str(selected_prefixes or "").strip() else []
        if source == "manual":
            source = "phone_signup"
        initial_meta.setdefault(
            "phone_signup",
            {
                "enabled": True,
                "target_count": int(prepared.count or 1),
                "use_pool": _is_truthy(prepared_extra.get("chatgpt_phone_signup_use_pool")),
                "manual_phone_line_count": len(phone_lines),
                "prefix_bind_enabled": _is_truthy(prepared_extra.get("chatgpt_phone_signup_prefix_bind_enabled")),
                "prefix_sample_enabled": _is_truthy(prepared_extra.get("chatgpt_phone_signup_prefix_sample_enabled")),
                "selected_prefixes": [str(value or "").strip() for value in selected_prefixes if str(value or "").strip()],
            },
        )
        initial_meta.setdefault("phone_count", len(phone_lines) or int(prepared.count or 1))
    else:
        initial_meta.setdefault(
            "registration_mailbox",
            _registration_mailbox_task_meta(prepared_extra),
        )
    _create_task_record(task_id, prepared, source, initial_meta)
    _save_task_log(
        prepared.platform,
        prepared.email or "",
        "running",
        detail=_build_task_log_detail(
            task_id,
            {
                "email": prepared.email or "",
                "attempt_outcome": "task_created",
                "requested_count": int(prepared.count or 0),
                "requested_concurrency": register_control.get("requested_concurrency"),
                "effective_concurrency": int(prepared.concurrency or 0),
                "requested_delay_seconds": register_control.get("requested_delay_seconds"),
                "requested_delay_max_seconds": register_control.get("requested_delay_max_seconds"),
                "effective_delay_seconds": float(prepared.register_delay_seconds or 0),
                "effective_delay_max_seconds": float(prepared.register_delay_max_seconds or 0),
                "source": source,
                "meta": dict(initial_meta or {}),
                "extra_flags": {
                    "mail_provider": str(prepared_extra.get("mail_provider") or ""),
                    "existing_account_capture": _is_truthy(prepared_extra.get("chatgpt_existing_account_capture")),
                    "existing_account_login_route_enabled": _bool_config_default_true(
                        prepared_extra.get("chatgpt_existing_account_login_route_enabled")
                    ),
                    "register_unique_exit_ip_enabled": _is_truthy(
                        prepared_extra.get("chatgpt_register_unique_exit_ip_enabled")
                    ),
                    "registration_diagnostics_mode": prepared.registration_diagnostics_mode,
                    "zero_amount_stop_enabled": _is_truthy(
                        prepared_extra.get("chatgpt_access_token_only_zero_amount_stop_enabled")
                    ),
                    "zero_amount_stop_threshold": str(
                        prepared_extra.get("chatgpt_access_token_only_zero_amount_stop_threshold") or ""
                    ),
                },
            },
        ),
    )
    if background_tasks is None:
        thread = threading.Thread(
            target=_run_register, args=(task_id, prepared), daemon=True
        )
        thread.start()
    else:
        background_tasks.add_task(_run_register, task_id, prepared)
    return task_id


def has_active_register_task(
    *, platform: str | None = None, source: str | None = None
) -> bool:
    return _task_store.has_active(platform=platform, source=source)


def _resolve_resume_auth_allow_phone_verification(value: Any = None) -> bool:
    if value is not None:
        return _is_truthy(value)
    from core.config_store import config_store

    return _is_truthy(config_store.get("chatgpt_resume_auth_allow_phone_verification", "false"))


def _resolve_resume_auth_phone_modes(value: Any = None) -> dict[str, bool]:
    legacy = _resolve_resume_auth_allow_phone_verification(value)
    from core.config_store import config_store

    cfg = config_store.get_all().copy()

    def _cfg_bool(key: str, default: bool) -> bool:
        if key not in cfg or cfg.get(key) in (None, ""):
            return default
        return _is_truthy(cfg.get(key))

    return {
        "allow_phone_verification": bool(legacy),
        "allow_add_phone_verification": _cfg_bool(
            "chatgpt_resume_auth_allow_add_phone_verification",
            bool(legacy),
        ),
        "allow_existing_phone_verification": _cfg_bool(
            "chatgpt_resume_auth_allow_existing_phone_verification",
            True,
        ),
    }


def _format_phone_modes_for_log(modes: dict[str, bool]) -> str:
    return (
        f"兼容总开关={'允许' if modes.get('allow_phone_verification') else '不允许'}，"
        f"add_phone新绑={'允许' if modes.get('allow_add_phone_verification') else '不允许'}，"
        f"已绑手机号二次验证={'允许' if modes.get('allow_existing_phone_verification') else '不允许'}"
    )


def enqueue_resume_subscription_auth_task(
    account_id: int,
    *,
    allow_phone_verification: bool | None = None,
    background_tasks: BackgroundTasks | None = None,
) -> str:
    account_id_value = int(account_id or 0)
    if account_id_value <= 0:
        raise HTTPException(400, "account_id 无效")
    resolved_modes = _resolve_resume_auth_phone_modes(allow_phone_verification)
    resolved_allow_phone_verification = resolved_modes["allow_phone_verification"]

    with Session(engine) as session:
        account = session.get(AccountModel, account_id_value)
        if account is None or account.platform != "chatgpt":
            raise HTTPException(404, "ChatGPT 账号不存在")
        email = str(account.email or "")

    task_id = f"task_{int(time.time() * 1000)}"
    source = "resume_subscription_auth"
    meta = {
        "account_id": account_id_value,
        "email": email,
        "allow_phone_verification": resolved_allow_phone_verification,
        "allow_add_phone_verification": resolved_modes["allow_add_phone_verification"],
        "allow_existing_phone_verification": resolved_modes["allow_existing_phone_verification"],
    }
    _create_standalone_task_record(
        task_id,
        platform="chatgpt",
        source=source,
        total=1,
        meta=meta,
    )
    _save_task_log(
        "chatgpt",
        email,
        "running",
        detail=_build_task_log_detail(
            task_id,
            {
                "email": email,
                "account_id": account_id_value,
                "attempt_outcome": "task_created",
                "source": source,
                "meta": meta,
            },
        ),
    )
    if background_tasks is None:
        thread = threading.Thread(
            target=_run_resume_subscription_auth,
            args=(task_id, account_id_value, resolved_allow_phone_verification),
            daemon=True,
        )
        thread.start()
    else:
        background_tasks.add_task(
            _run_resume_subscription_auth,
            task_id,
            account_id_value,
            resolved_allow_phone_verification,
        )
    return task_id


def _normalize_batch_account_ids(account_ids: list[int] | None) -> list[int]:
    normalized: list[int] = []
    seen: set[int] = set()
    for raw in account_ids or []:
        try:
            value = int(raw or 0)
        except Exception:
            continue
        if value <= 0 or value in seen:
            continue
        seen.add(value)
        normalized.append(value)
    return normalized


def _filtered_chatgpt_accounts(session: Session, req: Any) -> list[AccountModel]:
    # Match the status normalization used by GET /accounts before freezing IDs.
    # No task, resource import, or external action has started at this point.
    reconcile_rate_limited_accounts(session, platform="chatgpt")
    try:
        resolution = resolve_filtered_accounts(
            session,
            platform="chatgpt",
            filter_source=req,
            verify_expected_total=bool(getattr(req, "all_filtered", False)),
        )
    except AccountFilterScopeChangedError as exc:
        raise HTTPException(status_code=exc.status_code, detail=exc.detail) from exc
    return list(resolution.rows)


def _task_account_filter_audit(
    req: AccountFilterRequestMixin,
    *,
    matched_accounts: list[dict[str, Any]],
    eligible_accounts: list[dict[str, Any]],
    skipped_accounts: list[dict[str, Any]],
) -> dict[str, Any]:
    matched_items = matched_accounts if bool(req.all_filtered) else [
        *matched_accounts,
        *eligible_accounts,
        *skipped_accounts,
    ]
    matched_ids = [int(item.get("account_id") or 0) for item in matched_items if isinstance(item, dict)]
    frozen_ids = [int(item.get("account_id") or 0) for item in eligible_accounts if isinstance(item, dict)]
    return build_account_filter_audit(
        req,
        frozen_ids,
        matched_total=len({account_id for account_id in matched_ids if account_id > 0}),
        matched_account_ids=matched_ids,
        all_filtered=bool(req.all_filtered),
    )


def _task_filter_meta(req: AccountFilterRequestMixin, audit: dict[str, Any]) -> dict[str, Any]:
    return {
        "all_filtered": bool(req.all_filtered),
        **dict(audit.get("filter") or {}),
    }


def _chatgpt_account_access_token(account: AccountModel) -> str:
    try:
        extra = account.get_extra()
    except Exception:
        extra = {}
    if not isinstance(extra, dict):
        extra = {}
    return str(extra.get("access_token") or getattr(account, "token", "") or "").strip()


def _idea_submit_unavailable_reason(account: AccountModel) -> str:
    try:
        extra = account.get_extra()
    except Exception:
        extra = {}
    if not isinstance(extra, dict):
        extra = {}
    marker = extra.get("idea_submit") if isinstance(extra.get("idea_submit"), dict) else {}
    if bool(marker.get("unavailable") or extra.get("idea_submit_unavailable")):
        reason = str(marker.get("reason") or extra.get("idea_submit_unavailable_reason") or "").strip()
        return f"账号已标记不可用于 Idea 提交{f': {reason}' if reason else ''}"

    # Backward compatibility for rows written before the dedicated Idea marker:
    # old failures only set generic chatgpt_account_unavailable plus a failed
    # baxigpt_cdk snapshot.
    baxigpt_cdk = extra.get("baxigpt_cdk") if isinstance(extra.get("baxigpt_cdk"), dict) else {}
    if bool(extra.get("chatgpt_account_unavailable")) and str(baxigpt_cdk.get("status") or "").strip().lower() == "failed":
        reason = str(extra.get("chatgpt_unavailable_reason") or baxigpt_cdk.get("last_error_message") or "").strip()
        return f"账号已标记不可用于 Idea 提交{f': {reason}' if reason else ''}"
    return ""


PAYPAL_BIND_ALLOWED_SUBSCRIPTION_TYPES = {"free"}
PAYPAL_BIND_BLOCKED_SUBSCRIPTION_TYPES = {"plus", "team", "pro", "enterprise"}
PAYPAL_BIND_ALREADY_PAID_MARKERS = (
    "user is already paid",
    "already paid",
    "you have paid",
)


def _paypal_bind_account_extra(account: AccountModel) -> dict[str, Any]:
    try:
        extra = account.get_extra()
    except Exception:
        return {}
    return extra if isinstance(extra, dict) else {}


def _paypal_bind_account_item(account: AccountModel, extra: dict[str, Any] | None = None) -> dict[str, Any]:
    extra = extra if isinstance(extra, dict) else _paypal_bind_account_extra(account)
    return {
        "account_id": int(account.id or 0),
        "email": str(account.email or ""),
        "status": str(account.status or ""),
        "subscription_type": account_subscription_type(account, extra),
        "account_validity": account_validity(account, extra),
    }


def _paypal_bind_detect_external_state(*values: Any) -> str:
    parts: list[str] = []
    for value in values:
        if value is None:
            continue
        if isinstance(value, (dict, list, tuple)):
            try:
                parts.append(json.dumps(value, ensure_ascii=False))
            except Exception:
                parts.append(str(value))
        else:
            parts.append(str(value))
    text = "\n".join(parts).strip().lower()
    if not text:
        return ""
    if any(marker in text for marker in PAYPAL_BIND_ALREADY_PAID_MARKERS):
        return "already_paid"
    return ""


def _is_resume_auth_candidate(account: AccountModel) -> bool:
    status = str(getattr(account, "status", "") or "").strip().lower()
    if status == "pending_payment":
        return True

    extra = account.get_extra()
    capabilities = extra.get("chatgpt_capabilities") if isinstance(extra.get("chatgpt_capabilities"), dict) else {}
    auth_level = str(capabilities.get("auth_level") or "").strip().lower()
    upload_gate = str(capabilities.get("upload_gate") or "").strip().lower()
    if auth_level in {"registered_auth_pending", "access_token_only", "invalid"}:
        return True
    if upload_gate in {"blocked_missing_at", "blocked_missing_rt", "blocked_missing_workspace"}:
        return True
    return False


def _resolve_batch_resume_auth_accounts(
    req: BatchResumeSubscriptionAuthTaskRequest,
) -> tuple[list[dict[str, Any]], list[int], list[dict[str, Any]], list[dict[str, Any]]]:
    requested_ids = _normalize_batch_account_ids(req.account_ids)
    if requested_ids:
        if len(requested_ids) > 1000:
            raise HTTPException(400, "单次最多处理 1000 个账号")
        with Session(engine) as session:
            rows = session.exec(
                select(AccountModel)
                .where(AccountModel.platform == "chatgpt")
                .where(AccountModel.id.in_(requested_ids))
            ).all()
            row_map = {int(row.id or 0): row for row in rows if int(row.id or 0) > 0}

        eligible: list[dict[str, Any]] = []
        skipped: list[dict[str, Any]] = []
        missing_ids: list[int] = []
        for account_id in requested_ids:
            account = row_map.get(account_id)
            if account is None:
                missing_ids.append(account_id)
                continue
            if _is_resume_auth_candidate(account):
                eligible.append(
                    {
                        "account_id": account_id,
                        "email": str(account.email or ""),
                        "status": str(account.status or ""),
                    }
                )
            else:
                skipped.append(
                    {
                        "account_id": account_id,
                        "email": str(account.email or ""),
                        "status": str(account.status or ""),
                        "reason": "账号当前无需补抓 Auth",
                    }
                )
        return eligible, missing_ids, skipped, []

    if not bool(req.all_filtered):
        raise HTTPException(400, "请提供 account_ids，或指定 all_filtered=true")

    with Session(engine) as session:
        rows = _filtered_chatgpt_accounts(session, req)
        if len(rows) > 1000:
            raise HTTPException(400, "单次最多处理 1000 个账号")

    eligible = []
    skipped = []
    matched = []
    for account in rows:
        account_id = int(account.id or 0)
        if account_id <= 0:
            continue
        matched.append(
            {
                "account_id": account_id,
                "email": str(account.email or ""),
                "status": str(account.status or ""),
            }
        )
        if _is_resume_auth_candidate(account):
            eligible.append(matched[-1])
        else:
            skipped.append(
                {
                    **matched[-1],
                    "reason": "账号当前无需补抓 Auth",
                }
            )
    return eligible, [], skipped, matched


def _parse_phone_binding_upload_lines(raw_lines: Any) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Parse pasted phone/API lines through the shared uploaded-phone parser."""
    from services.chatgpt_core.phone_service import parse_uploaded_phone_lines

    uploaded_entries, errors = parse_uploaded_phone_lines(raw_lines)
    entries: list[dict[str, Any]] = []
    for entry in uploaded_entries:
        source_api_url = str(getattr(entry, "source_api_url", "") or entry.api_url).strip()
        entries.append(
            {
                "line_no": int(entry.line_no or 0),
                "phone": entry.phone,
                "api_url": entry.api_url,
                "source_api_url": source_api_url,
                "raw_line": entry.raw_line or f"{entry.phone}----{entry.api_url}",
                "pool_managed": False,
            }
        )
    return entries, errors


def _resolve_phone_binding_item_api(item: dict[str, Any]) -> dict[str, Any]:
    """Freeze one task item to the effective Relay/direct URL.

    ``source_api_url`` always remains the supplier URL. ``api_url`` and the
    canonical raw line are the actual URL used by polling/copy/OAIPay output.
    """
    from services.chatgpt_core.phone_api_forwarding import resolve_phone_api_url

    resolved_item = dict(item or {})
    source_api_url = str(
        resolved_item.get("source_api_url")
        or resolved_item.get("api_url")
        or ""
    ).strip()
    resolution = resolve_phone_api_url(source_api_url, strict=True)
    request_api_url = str(resolution.request_api_url or "").strip()
    raw_line = str(resolved_item.get("raw_line") or "").strip()
    if raw_line and source_api_url and source_api_url in raw_line:
        raw_line = raw_line.replace(source_api_url, request_api_url, 1)
    elif not raw_line:
        raw_line = f"{str(resolved_item.get('phone') or '').strip()}----{request_api_url}"
    resolved_item.update(
        {
            "source_api_url": source_api_url,
            "api_url": request_api_url,
            "forwarded_api_url": request_api_url if resolution.forwarded else "",
            "api_forwarded": bool(resolution.forwarded),
            "forward_status": resolution.status,
            "raw_line": raw_line,
        }
    )
    return resolved_item


def _import_manual_phone_entries_to_pool(
    phone_entries: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], dict[str, int]]:
    """Upsert pasted phone/API rows into the phone pool and mark them pool-managed.

    粘贴面板里的号码仍按“本轮固定列表”执行，不切换成动态取号；
    但启动任务前先写入 phone_pool，确保后续绑定/探测/失败结果能走统一
    record_task_status 回写链路。
    """
    from services.chatgpt_core.phone_pool_repository import PhonePoolRepository

    repo = PhonePoolRepository()
    imported = existing = skipped = 0
    managed_items: list[dict[str, Any]] = []
    for item in phone_entries:
        next_item = dict(item)
        phone = str(next_item.get("phone") or "").strip()
        api_url = str(next_item.get("source_api_url") or next_item.get("api_url") or "").strip()
        next_item["source_api_url"] = api_url
        try:
            before = repo.get(phone)
            if before is None:
                record = repo.add(
                    phone=phone,
                    api_url=api_url,
                    label="绑定面板导入",
                )
                if record is None:
                    skipped += 1
                else:
                    imported += 1
            else:
                record = before
                if api_url and str(getattr(before, "api_url", "") or "").strip() != api_url:
                    update = getattr(repo, "update", None)
                    if callable(update):
                        updated_record = update(int(getattr(before, "id", 0) or 0), api_url=api_url)
                        if updated_record is not None:
                            record = updated_record
                    else:
                        # 兼容旧仓库对象/测试桩：没有 update 时退回 add 的 upsert 语义。
                        updated_record = repo.add(phone=phone, api_url=api_url, label="绑定面板导入")
                        if updated_record is not None:
                            record = updated_record
                existing += 1
        except Exception as exc:
            record = None
            skipped += 1
            next_item["pool_import_error"] = redact_log_text(exc)

        if record is not None:
            record_id = int(getattr(record, "id", 0) or 0)
            next_item["id"] = record_id or int(next_item.get("id") or 0)
            next_item["pool_id"] = record_id or int(next_item.get("pool_id") or 0)
            next_item["pool_managed"] = True
        managed_items.append(next_item)

    return managed_items, {"imported": imported, "existing": existing, "skipped": skipped}


def _resolve_phone_binding_test_accounts(
    req: PhoneBindingTestTaskRequest,
) -> tuple[list[dict[str, Any]], list[int], list[dict[str, Any]], list[dict[str, Any]]]:
    requested_ids = _normalize_batch_account_ids(req.account_ids)
    limit = max(int(req.limit or 0), 0)
    if requested_ids:
        if len(requested_ids) > 1000:
            raise HTTPException(400, "单次最多处理 1000 个账号")
        with Session(engine) as session:
            rows = session.exec(
                select(AccountModel)
                .where(AccountModel.platform == "chatgpt")
                .where(AccountModel.id.in_(requested_ids))
            ).all()
        row_map = {int(row.id or 0): row for row in rows if int(row.id or 0) > 0}
        eligible: list[dict[str, Any]] = []
        missing_ids: list[int] = []
        for account_id in requested_ids:
            account = row_map.get(account_id)
            if account is None:
                missing_ids.append(account_id)
                continue
            eligible.append(
                {
                    "account_id": account_id,
                    "email": str(account.email or ""),
                    "status": str(account.status or ""),
                }
            )
        if limit > 0:
            eligible = eligible[:limit]
        return eligible, missing_ids, [], []

    if not bool(req.all_filtered):
        raise HTTPException(400, "请提供 account_ids，或指定 all_filtered=true")

    with Session(engine) as session:
        rows = _filtered_chatgpt_accounts(session, req)

    matched: list[dict[str, Any]] = []
    for account in rows:
        account_id = int(account.id or 0)
        if account_id <= 0:
            continue
        matched.append(
            {
                "account_id": account_id,
                "email": str(account.email or ""),
                "status": str(account.status or ""),
            }
        )
    eligible = list(matched)
    skipped: list[dict[str, Any]] = []
    if limit > 0:
        overflow = eligible[limit:]
        eligible = eligible[:limit]
        skipped.extend({**item, "reason": f"超过本次限制 limit={limit}"} for item in overflow)
    if len(eligible) > 1000:
        raise HTTPException(400, "单次最多处理 1000 个账号")
    return eligible, [], skipped, matched


def _saved_stripe_pix_user_link(account: AccountModel) -> tuple[str, str]:
    """Return a currently uploadable PIX link without copying it into task meta."""

    try:
        extra = account.get_extra()
    except Exception:
        extra = {}
    summary = account_payment_link_summary(account, extra if isinstance(extra, dict) else {})
    if str(summary.get("platform") or "").strip().lower() != "pix":
        return "", "账号没有已保存的 PIX 支付链接"
    if str(summary.get("link_status") or "").strip().lower() == PIX_SAVED_LINK_SUBMITTED_STATUS:
        return "", PIX_SAVED_LINK_SUBMITTED_REASON

    pay_link = str(summary.get("url") or "").strip()
    try:
        parsed = urlsplit(pay_link)
    except (TypeError, ValueError):
        return "", "已保存的 PIX 支付链接格式无效"
    if (
        parsed.scheme.lower() != "https"
        or (parsed.hostname or "").lower() != PIX_USER_LINK_HOST
        or not str(parsed.path or "").startswith(PIX_USER_LINK_PATH_PREFIX)
    ):
        return "", "已保存的 PIX 链接不是可上传的 Stripe PIX 指令链接"
    if payment_link_expires_soon(summary):
        return "", "已保存的 PIX 支付链接即将到期，请先重新生成"
    return pay_link, ""


def _mark_saved_pix_user_link_submitted(
    account_id: int,
    *,
    pix_pay_link: str,
    duplicate: bool = False,
) -> bool:
    """Mark only the exact saved PIX link consumed by the submission service.

    The remote service treats one Stripe PIX instruction URL as single-use.
    Keep that fact on the link cache instead of marking the whole account
    unavailable: a subsequent long-link sync or a newly generated URL remains
    usable. The exact-URL comparison prevents a late task result from changing
    a newer link that was synced while the task was running.
    """

    expected_url = str(pix_pay_link or "").strip()
    if not expected_url:
        return False

    with Session(engine) as session:
        account = session.get(AccountModel, int(account_id or 0))
        if account is None or account.platform != "chatgpt":
            return False
        try:
            extra = account.get_extra()
        except Exception:
            extra = {}
        if not isinstance(extra, dict):
            return False
        cached = extra.get("chatgpt_last_payment_link")
        if not isinstance(cached, dict):
            return False
        summary = account_payment_link_summary(account, extra)
        if (
            str(summary.get("platform") or "").strip().lower() != "pix"
            or str(summary.get("url") or "").strip() != expected_url
        ):
            return False

        now = datetime.now(timezone.utc).isoformat()
        cached["link_status"] = PIX_SAVED_LINK_SUBMITTED_STATUS
        cached["link_status_reason"] = (
            "PIX 管理端已存在该支付链接"
            if duplicate
            else "已提交至 PIX 管理端，等待支付结果"
        )
        cached["link_status_updated_at"] = now
        cached["pix_submitted_at"] = now
        extra["chatgpt_last_payment_link"] = cached
        account.set_extra(extra)
        account.updated_at = datetime.now(timezone.utc)
        session.add(account)
        session.commit()
    return True


def _resolve_baxigpt_cdk_submit_accounts(
    req: BaxiGptCdkSubmitTaskRequest,
    *,
    require_access_token: bool = True,
    require_saved_pix_link: bool = False,
) -> tuple[list[dict[str, Any]], list[int], list[dict[str, Any]], list[dict[str, Any]]]:
    requested_ids = _normalize_batch_account_ids(req.account_ids)
    limit = max(int(req.limit or 0), 0)
    if requested_ids:
        if len(requested_ids) > 1000:
            raise HTTPException(400, "单次最多处理 1000 个账号")
        with Session(engine) as session:
            rows = session.exec(
                select(AccountModel)
                .where(AccountModel.platform == "chatgpt")
                .where(AccountModel.id.in_(requested_ids))
            ).all()
        row_map = {int(row.id or 0): row for row in rows if int(row.id or 0) > 0}
        matched: list[dict[str, Any]] = []
        eligible: list[dict[str, Any]] = []
        skipped: list[dict[str, Any]] = []
        missing_ids: list[int] = []
        for account_id in requested_ids:
            account = row_map.get(account_id)
            if account is None:
                missing_ids.append(account_id)
                continue
            item = {
                "account_id": account_id,
                "email": str(account.email or ""),
                "status": str(account.status or ""),
            }
            matched.append(item)
            # Uploading an already saved Stripe PIX link is independent of
            # the account's historical Idea eligibility marker.  Auto-extract
            # still uses the existing Idea gate.
            idea_unavailable_reason = (
                "" if require_saved_pix_link else _idea_submit_unavailable_reason(account)
            )
            if idea_unavailable_reason:
                skipped.append({**item, "reason": idea_unavailable_reason})
                continue
            if require_saved_pix_link:
                _, link_reason = _saved_stripe_pix_user_link(account)
                if link_reason:
                    skipped.append({**item, "reason": link_reason})
                    continue
            if require_access_token and not _chatgpt_account_access_token(account):
                skipped.append({**item, "reason": "账号缺少 Access Token"})
                continue
            eligible.append(item)
        if limit > 0:
            overflow = eligible[limit:]
            eligible = eligible[:limit]
            skipped.extend({**item, "reason": f"超过本次限制 limit={limit}"} for item in overflow)
        return eligible, missing_ids, skipped, matched

    if not bool(req.all_filtered):
        raise HTTPException(400, "请提供 account_ids，或指定 all_filtered=true")

    with Session(engine) as session:
        rows = _filtered_chatgpt_accounts(session, req)

    matched: list[dict[str, Any]] = []
    eligible: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for account in rows:
        account_id = int(account.id or 0)
        if account_id <= 0:
            continue
        item = {
            "account_id": account_id,
            "email": str(account.email or ""),
            "status": str(account.status or ""),
        }
        matched.append(item)
        idea_unavailable_reason = (
            "" if require_saved_pix_link else _idea_submit_unavailable_reason(account)
        )
        if idea_unavailable_reason:
            skipped.append({**item, "reason": idea_unavailable_reason})
            continue
        if require_saved_pix_link:
            _, link_reason = _saved_stripe_pix_user_link(account)
            if link_reason:
                skipped.append({**item, "reason": link_reason})
                continue
        if require_access_token and not _chatgpt_account_access_token(account):
            skipped.append({**item, "reason": "账号缺少 Access Token"})
            continue
        eligible.append(item)
    if limit > 0:
        overflow = eligible[limit:]
        eligible = eligible[:limit]
        skipped.extend({**item, "reason": f"超过本次限制 limit={limit}"} for item in overflow)
    if len(eligible) > 1000:
        raise HTTPException(400, "单次最多处理 1000 个账号")
    return eligible, [], skipped, matched


def _paypal_bind_skip_reason(account: AccountModel, extra: dict[str, Any] | None = None) -> str:
    extra = extra if isinstance(extra, dict) else _paypal_bind_account_extra(account)
    status = str(getattr(account, "status", "") or "").strip().lower()
    validity = account_validity(account, extra)
    subscription_type = account_subscription_type(account, extra)
    if validity != "valid":
        return "账号无效，不能提交 PayPal 绑定"
    if status == "subscribed" or subscription_type in PAYPAL_BIND_BLOCKED_SUBSCRIPTION_TYPES:
        label = subscription_type if subscription_type != "unknown" else status or "subscribed"
        return f"账号已订阅({label})，默认不提交 PayPal 绑定"
    if subscription_type not in PAYPAL_BIND_ALLOWED_SUBSCRIPTION_TYPES:
        return f"账号订阅状态不是明确 Free({subscription_type})，不能提交 PayPal 绑定"
    if not _chatgpt_account_access_token(account):
        return "账号缺少 Access Token"
    return ""


def _resolve_chatgpt_paypal_bind_accounts(
    req: ChatGptPaypalBindTaskRequest,
) -> tuple[list[dict[str, Any]], list[int], list[dict[str, Any]], list[dict[str, Any]]]:
    requested_ids = _normalize_batch_account_ids(req.account_ids)
    limit = max(int(req.limit or 0), 0)
    if requested_ids:
        if len(requested_ids) > 1000:
            raise HTTPException(400, "单次最多处理 1000 个账号")
        with Session(engine) as session:
            rows = session.exec(
                select(AccountModel)
                .where(AccountModel.platform == "chatgpt")
                .where(AccountModel.id.in_(requested_ids))
            ).all()
        row_map = {int(row.id or 0): row for row in rows if int(row.id or 0) > 0}
        matched: list[dict[str, Any]] = []
        eligible: list[dict[str, Any]] = []
        skipped: list[dict[str, Any]] = []
        missing_ids: list[int] = []
        for account_id in requested_ids:
            account = row_map.get(account_id)
            if account is None:
                missing_ids.append(account_id)
                continue
            extra = _paypal_bind_account_extra(account)
            item = _paypal_bind_account_item(account, extra)
            matched.append(item)
            reason = _paypal_bind_skip_reason(account, extra)
            if reason:
                skipped.append({**item, "reason": reason})
            else:
                eligible.append(item)
        if limit > 0:
            overflow = eligible[limit:]
            eligible = eligible[:limit]
            skipped.extend({**item, "reason": f"超过本次限制 limit={limit}"} for item in overflow)
        return eligible, missing_ids, skipped, matched

    if not bool(req.all_filtered):
        raise HTTPException(400, "请提供 account_ids，或指定 all_filtered=true")

    with Session(engine) as session:
        rows = _filtered_chatgpt_accounts(session, req)

    matched: list[dict[str, Any]] = []
    eligible: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for account in rows:
        account_id = int(account.id or 0)
        if account_id <= 0:
            continue
        extra = _paypal_bind_account_extra(account)
        item = _paypal_bind_account_item(account, extra)
        matched.append(item)
        reason = _paypal_bind_skip_reason(account, extra)
        if reason:
            skipped.append({**item, "reason": reason})
        else:
            eligible.append(item)
    if limit > 0:
        overflow = eligible[limit:]
        eligible = eligible[:limit]
        skipped.extend({**item, "reason": f"超过本次限制 limit={limit}"} for item in overflow)
    if len(eligible) > 1000:
        raise HTTPException(400, "单次最多处理 1000 个账号")
    return eligible, [], skipped, matched


