def _json_object_from_config(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    text = str(value or "").strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
    except Exception:
        return {}
    return dict(parsed) if isinstance(parsed, dict) else {}


def _filtered_payment_link_request_params(params: dict[str, Any] | None) -> dict[str, Any]:
    """Freeze either the upstream profile contract or the local short-link mode.

    Provider, base proxy and runtime strategy belong to openai-pay-long-link's
    active admin profile. Team checkout explicitly freezes billing country,
    proxy country and checkout UI mode so none can inherit an unrelated payment
    rail from the upstream admin profile. The restored short-link branch accepts
    only country/currency; proxy selection remains server-side.
    """

    source = params if isinstance(params, dict) else {}
    if is_local_short_payment_link_params(source):
        normalized = normalize_payment_link_params(
            {
                **source,
                "plan": "plus",
                "payment_source": PAYMENT_SOURCE_CHATGPT_HOSTED,
                "payment_link_format": PAYMENT_LINK_FORMAT_SHORT,
                "profile_hash": "",
            }
        )
        return {
            "plan": "plus",
            "generation_kind": "plus_checkout",
            "country": normalized["country"],
            "currency": normalized["currency"],
            "proxy": "",
            "payment_source": PAYMENT_SOURCE_CHATGPT_HOSTED,
            "payment_link_format": PAYMENT_LINK_FORMAT_SHORT,
            "reuse_cached_link": source.get("reuse_cached_link") is not False,
        }
    raw_plan = str(source.get("plan") or "plus").strip().lower()
    is_team = raw_plan in {"team", "team_checkout", "chatgptteamplan", "chatgpt_team_plan"}
    normalized: dict[str, Any] = {
        "plan": "team" if is_team else "plus",
        "generation_kind": PAYMENT_LINK_GENERATION_TEAM if is_team else "plus_checkout",
        "payment_source": PAYMENT_SOURCE_LONG_LINK,
        "payment_link_format": PAYMENT_LINK_FORMAT_LONG_LINK,
        "reuse_cached_link": source.get("reuse_cached_link") is not False,
    }
    if is_team:
        nested = source.get("team_plan_data") or source.get("teamPlanData")
        nested = dict(nested) if isinstance(nested, dict) else {}
        team_data: dict[str, Any] = {}

        def first_explicit(*candidates: tuple[dict[str, Any], str]) -> Any:
            for container, key in candidates:
                if key in container and container.get(key) not in (None, ""):
                    return container.get(key)
            return None

        workspace = first_explicit(
            (nested, "workspace_name"),
            (nested, "workspaceName"),
            (source, "workspace_name"),
            (source, "team_workspace_name"),
            (source, "teamWorkspaceName"),
        )
        interval = first_explicit(
            (nested, "price_interval"),
            (nested, "priceInterval"),
            (source, "price_interval"),
            (source, "team_price_interval"),
            (source, "teamPriceInterval"),
        )
        seats = first_explicit(
            (nested, "seat_quantity"),
            (nested, "seatQuantity"),
            (source, "seat_quantity"),
            (source, "team_seat_quantity"),
            (source, "teamSeatQuantity"),
        )
        if workspace is not None:
            team_data["workspace_name"] = str(workspace).strip()
        if interval is not None:
            team_data["price_interval"] = str(interval).strip().lower()
        if seats is not None:
            team_data["seat_quantity"] = seats
        if team_data:
            normalized["team_plan_data"] = team_data
        normalized["billing_country"] = normalize_team_billing_country(source)
        normalized["checkout_proxy_region"] = normalize_team_checkout_proxy_region(source)
        normalized["checkout_ui_mode"] = normalize_team_checkout_ui_mode(source)

        for canonical, aliases in {
            "promo_code": ("promo_code", "promoCode"),
            "cancel_url": ("cancel_url", "cancelUrl"),
            "plan_name": ("plan_name", "planName"),
        }.items():
            value = first_explicit(*((source, alias) for alias in aliases))
            if value is not None:
                normalized[canonical] = str(value).strip()
    return normalized


def _build_batch_payment_link_params(account: AccountModel, request_params: dict[str, Any]) -> dict[str, Any]:
    del account
    params = _filtered_payment_link_request_params(request_params)
    # These values are frozen from the long-link profile above, never accepted
    # from the batch request.  They are needed only to decide whether an
    # existing generic link belongs to this exact profile.
    params["country"] = str(request_params.get("country") or "").strip().upper()
    params["currency"] = str(request_params.get("currency") or "").strip().upper()
    params["profile_hash"] = str(request_params.get("profile_hash") or "").strip()
    params["generation_kind"] = payment_link_generation_kind(params)
    params["variant_key"] = payment_link_variant_key(params)
    return params


def _payment_link_params_from_profile(
    request_params: dict[str, Any],
    profile: dict[str, Any],
) -> dict[str, Any]:
    """Merge the redacted, frozen long-link profile into task parameters."""

    merged = _filtered_payment_link_request_params(request_params)
    profile_detail = profile.get("profile") if isinstance(profile.get("profile"), dict) else {}
    plan = str(profile.get("plan") or profile_detail.get("plan") or merged.get("plan") or "plus").strip().lower()
    if plan in {"team", "team_checkout", "chatgptteamplan"}:
        merged["plan"] = PAYMENT_LINK_PLAN_TEAM
        team = profile.get("team") if isinstance(profile.get("team"), dict) else profile_detail.get("team")
        if not isinstance(team, dict):
            team = profile.get("team_plan_data") if isinstance(profile.get("team_plan_data"), dict) else {}
        if not team and isinstance(profile_detail.get("team_plan_data"), dict):
            team = profile_detail.get("team_plan_data")
        existing_team = merged.get("team_plan_data") if isinstance(merged.get("team_plan_data"), dict) else {}
        merged["team_plan_data"] = {
            "workspace_name": str(team.get("workspace_name") or team.get("workspaceName") or existing_team.get("workspace_name") or "").strip(),
            "price_interval": str(team.get("price_interval") or team.get("priceInterval") or existing_team.get("price_interval") or "month").strip().lower(),
            "seat_quantity": team.get("seat_quantity") or team.get("seatQuantity") or existing_team.get("seat_quantity") or 2,
        }
        merged["cancel_url"] = str(
            team.get("cancel_url")
            or team.get("cancelUrl")
            or merged.get("cancel_url")
            or ""
        ).strip()
        merged["promo_code_digest"] = str(
            profile.get("promo_code_digest")
            or profile_detail.get("promo_code_digest")
            or team.get("promo_code_digest")
            or ""
        ).strip()
        merged["plan_name"] = str(
            profile.get("plan_name") or profile_detail.get("plan_name") or "chatgptteamplan"
        ).strip()
        profile_regions = profile.get("regions") if isinstance(profile.get("regions"), dict) else profile_detail.get("regions")
        profile_regions = profile_regions if isinstance(profile_regions, dict) else {}
        merged["checkout_proxy_region"] = str(
            profile_regions.get("checkout")
            or merged.get("checkout_proxy_region")
            or ""
        ).strip().upper()
        merged["checkout_ui_mode"] = normalize_team_checkout_ui_mode({
            "checkout_ui_mode": profile.get("checkout_ui_mode")
            or profile_detail.get("checkout_ui_mode")
            or merged.get("checkout_ui_mode"),
        })
    else:
        merged["plan"] = "plus"
    profile_country = str(
        profile.get("country")
        or profile.get("billing_country")
        or profile_detail.get("country")
        or profile_detail.get("billing_country")
        or ""
    ).strip().upper()
    profile_currency = str(profile.get("currency") or profile_detail.get("currency") or "").strip().upper()
    if merged["plan"] == PAYMENT_LINK_PLAN_TEAM:
        requested_billing_country = normalize_team_billing_country(merged)
        if profile_country != requested_billing_country:
            raise ValueError(
                "long-link 返回的 Team 账单国家与任务配置不一致: "
                f"requested={requested_billing_country}, actual={profile_country or '<empty>'}"
            )
        merged["billing_country"] = requested_billing_country
    merged["country"] = profile_country
    merged["currency"] = profile_currency
    merged["profile_hash"] = str(profile.get("profile_hash") or profile_detail.get("profile_hash") or "").strip()
    merged["generation_kind"] = payment_link_generation_kind(merged)
    merged["variant_key"] = payment_link_variant_key(merged)
    return merged


_PAYMENT_LINK_HISTORY_SUCCESS_STATUSES = frozenset({"succeeded"})
_PAYMENT_LINK_HISTORY_IN_FLIGHT_STATUSES = frozenset({
    "submitting",
    "queued",
    "running",
})
_PAYMENT_LINK_PAID_TERMINAL_STATUSES = frozenset({
    "paid",
    "already_paid",
    "paid_cleaned",
    "upi_paid_cleaned",
    "ideal_paid_cleaned",
})
_PAYMENT_LINK_IN_FLIGHT_MIN_TTL_SECONDS = 30 * 60
_PAYMENT_LINK_IN_FLIGHT_GRACE_SECONDS = 5 * 60


def _payment_link_inflight_ttl_seconds() -> float:
    """Return a bounded freshness window for durable remote-job claims.

    ``payment_link_generations`` survives a process restart, while the task
    runtime does not.  A fresh queued/running row must therefore block a
    competing task, but an old row from a crashed worker must eventually be
    retriable.  The remote job timeout is the natural upper bound; retain a
    minimum window for deployments with an accidentally tiny env value.
    """

    try:
        timeout = float(os.getenv("OPENAI_PAY_LONG_LINK_JOB_TIMEOUT_SECONDS") or 1800.0)
    except (TypeError, ValueError):
        timeout = 1800.0
    if timeout != timeout or timeout <= 0:
        timeout = 1800.0
    return max(
        float(_PAYMENT_LINK_IN_FLIGHT_MIN_TTL_SECONDS),
        timeout + float(_PAYMENT_LINK_IN_FLIGHT_GRACE_SECONDS),
    )


def _coerce_payment_link_datetime(value: Any) -> datetime | None:
    if isinstance(value, datetime):
        parsed = value
    else:
        text_value = str(value or "").strip()
        if not text_value:
            return None
        try:
            parsed = datetime.fromisoformat(text_value.replace("Z", "+00:00"))
        except (TypeError, ValueError):
            return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _payment_link_account_created_at_text(value: Any) -> str:
    """Use the same naive timestamp representation SQLite stores for accounts."""

    if isinstance(value, datetime):
        # SQLAlchemy's SQLite DateTime adapter persists a timezone-aware value
        # without the offset.  Preserve the wall-clock fields so this matches
        # ``CAST(accounts.created_at AS TEXT)`` used by the SQL list projection.
        return value.replace(tzinfo=None).isoformat(sep=" ")
    return str(value or "").strip()


def _payment_link_account_identity_values(account: AccountModel) -> tuple[str, str]:
    return (
        str(getattr(account, "email", "") or "").strip().lower(),
        _payment_link_account_created_at_text(getattr(account, "created_at", None)),
    )


def _payment_link_account_identity(account: AccountModel) -> str:
    """Bind an asynchronous payment result to one immutable account row."""

    account_email, account_created_at = _payment_link_account_identity_values(account)
    source = "\x1f".join(
        (
            str(int(getattr(account, "id", 0) or 0)),
            str(getattr(account, "platform", "") or "").strip().lower(),
            account_email,
            account_created_at,
        )
    )
    return hashlib.sha256(source.encode("utf-8")).hexdigest()


def _payment_link_generation_matches_account(
    row: PaymentLinkGenerationModel | None,
    account: AccountModel | None,
) -> bool:
    """Return whether a persisted generation belongs to the current account row."""

    if row is None or account is None:
        return False
    if int(getattr(row, "account_id", 0) or 0) != int(getattr(account, "id", 0) or 0):
        return False
    expected_email, expected_created_at = _payment_link_account_identity_values(account)
    row_email = str(getattr(row, "account_email", "") or "").strip().lower()
    row_created_at = _payment_link_account_created_at_text(getattr(row, "account_created_at", ""))
    return bool(expected_email and expected_created_at and row_email and row_created_at) and (
        row_email == expected_email and row_created_at == expected_created_at
    )


def _payment_link_generation_matches_pending(
    row: PaymentLinkGenerationModel | None,
    pending: dict[str, Any],
) -> bool:
    """Check a request row against the immutable identity captured at submit time."""

    if row is None:
        return False
    pending_email = str(pending.get("account_email") or "").strip().lower()
    pending_created_at = _payment_link_account_created_at_text(pending.get("account_created_at"))
    row_email = str(getattr(row, "account_email", "") or "").strip().lower()
    row_created_at = _payment_link_account_created_at_text(getattr(row, "account_created_at", ""))
    return bool(pending_email and pending_created_at and row_email and row_created_at) and (
        int(getattr(row, "account_id", 0) or 0) == int(pending.get("account_id", 0) or 0)
        and row_email == pending_email
        and row_created_at == pending_created_at
    )


def _payment_link_pending_matches_account(account: AccountModel | None, pending: dict[str, Any]) -> bool:
    if account is None or str(getattr(account, "platform", "") or "").strip().lower() != "chatgpt":
        return False
    expected_email, expected_created_at = _payment_link_account_identity_values(account)
    pending_email = str(pending.get("account_email") or "").strip().lower()
    pending_created_at = _payment_link_account_created_at_text(pending.get("account_created_at"))
    if not pending_email or not pending_created_at or pending_email != expected_email or pending_created_at != expected_created_at:
        return False
    expected = str(pending.get("account_identity") or "").strip()
    return bool(expected) and _payment_link_account_identity(account) == expected


def _payment_link_pending_identity_kwargs(pending: dict[str, Any]) -> dict[str, str]:
    """Return the persisted identity fields captured before remote submit."""

    return {
        "account_email": str(pending.get("account_email") or "").strip().lower(),
        "account_created_at": _payment_link_account_created_at_text(
            pending.get("account_created_at")
        ),
    }


def _payment_link_generation_activity_at(row: PaymentLinkGenerationModel) -> datetime | None:
    # updated_at is written on every remote status transition.  The string
    # fallbacks cover rows created by older migrations that predate it.
    for field_name in ("updated_at", "persisted_at", "submitted_at", "started_at", "created_at"):
        parsed = _coerce_payment_link_datetime(getattr(row, field_name, None))
        if parsed is not None:
            return parsed
    return None


def _payment_link_generation_is_fresh_inflight(
    row: PaymentLinkGenerationModel,
    *,
    now: datetime | None = None,
) -> bool:
    status = str(getattr(row, "status", "") or "").strip().lower()
    if status not in _PAYMENT_LINK_HISTORY_IN_FLIGHT_STATUSES:
        return False
    activity_at = _payment_link_generation_activity_at(row)
    if activity_at is None:
        # A malformed timestamp must not become a permanent account lock.
        return False
    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    age_seconds = (current.astimezone(timezone.utc) - activity_at).total_seconds()
    return age_seconds <= _payment_link_inflight_ttl_seconds()


def _payment_link_generation_has_url(row: PaymentLinkGenerationModel) -> bool:
    # ``url`` is the canonical durable success artifact. Keeping this strict
    # matches the account-list SQL projection and avoids treating incidental
    # URLs in a diagnostic result payload as a successful extraction.
    return bool(_validated_payment_link_url(getattr(row, "url", "")))


def _payment_link_generation_matches_variant(
    row: PaymentLinkGenerationModel | None,
    params: dict[str, Any] | None,
) -> bool:
    """Match history by product/config variant, not only by account id."""

    if row is None:
        return False
    expected = normalize_payment_link_params(params)
    raw_result = row.get_result() if hasattr(row, "get_result") else {}
    actual = {
        **raw_result,
        "plan": raw_result.get("plan") or getattr(row, "generation_kind", "") or "plus",
        "generation_kind": raw_result.get("generation_kind") or getattr(row, "generation_kind", "") or "",
        "profile_hash": raw_result.get("profile_hash") or getattr(row, "profile_hash", "") or "",
        "variant_key": raw_result.get("variant_key") or getattr(row, "variant_key", "") or "",
    }
    actual_normalized = normalize_payment_link_params(actual)
    if actual_normalized.get("generation_kind") != expected.get("generation_kind"):
        return False
    expected_is_short = is_local_short_payment_link_params(expected)
    actual_is_short = is_local_short_payment_link_params(actual_normalized)
    if expected_is_short or actual_is_short:
        if expected_is_short != actual_is_short:
            return False
        return all(
            actual_normalized.get(key) == expected.get(key)
            for key in (
                "country",
                "currency",
                "proxy",
                "payment_source",
                "payment_link_format",
            )
        )
    if expected.get("plan") == PAYMENT_LINK_PLAN_TEAM:
        return all(actual_normalized.get(key) == expected.get(key) for key in (
            "workspace_name",
            "price_interval",
            "seat_quantity",
            "promo_code_digest",
            "cancel_url",
            "plan_name",
            "country",
            "currency",
            "checkout_proxy_region",
            "checkout_ui_mode",
        ))
    expected_profile = str(expected.get("profile_hash") or "").strip()
    actual_profile = str(actual_normalized.get("profile_hash") or "").strip()
    return not expected_profile or not actual_profile or expected_profile == actual_profile


def _validated_payment_link_url(value: Any) -> str:
    """Match the account-list contract for a browser-openable payment URL."""

    url = str(value or "").strip()
    if not url or len(url) > 8192:
        return ""
    try:
        parsed = urlsplit(url)
    except (TypeError, ValueError):
        return ""
    if parsed.scheme.lower() not in {"http", "https"} or not parsed.netloc:
        return ""
    return url


def _payment_link_current_cache_url(cached: dict[str, Any]) -> str:
    if not isinstance(cached, dict):
        return ""
    link_format = str(cached.get("payment_link_format") or "long_hosted").strip()
    for field_name in (
        "url",
        "paypal_url",
        "provider_redirect_url",
        "approval_url",
        "checkout_url",
        "cashier_url",
    ):
        raw_value = cached.get(field_name)
        if not str(raw_value or "").strip():
            continue
        normalized = normalize_payment_link_url(raw_value, link_format)
        validated = _validated_payment_link_url(normalized)
        if validated:
            return validated
    return ""


def _load_payment_link_history_by_account(
    session: Session,
    account_ids: list[int] | set[int] | tuple[int, ...],
) -> dict[int, list[PaymentLinkGenerationModel]]:
    ids: list[int] = []
    for value in account_ids:
        try:
            normalized = int(value or 0)
        except (TypeError, ValueError):
            continue
        if normalized > 0 and normalized not in ids:
            ids.append(normalized)
    ids.sort()
    if not ids:
        return {}
    rows = session.exec(
        select(PaymentLinkGenerationModel).where(PaymentLinkGenerationModel.account_id.in_(ids))
    ).all()
    grouped: dict[int, list[PaymentLinkGenerationModel]] = {}
    for row in rows:
        grouped.setdefault(int(row.account_id or 0), []).append(row)
    return grouped


def _payment_link_paid_terminal_marker(
    account: AccountModel,
    cached: dict[str, Any],
    extra: dict[str, Any],
) -> bool:
    """Detect an explicit paid/already-paid terminal, including old payloads."""

    def is_paid_status(value: Any) -> bool:
        return str(value or "").strip().lower().replace("-", "_") in _PAYMENT_LINK_PAID_TERMINAL_STATUSES

    if is_paid_status(cached.get("link_status")):
        return True
    if bool(extra.get("chatgpt_payment_already_paid")):
        return True
    if is_paid_status(extra.get("chatgpt_payment_status")):
        return True
    if str(extra.get("chatgpt_checkout_error_code") or "").strip().lower().replace("-", "_") in {
        "already_paid",
        "paid",
        "paid_cleaned",
    }:
        return True

    # GoPay and older checkout adapters persist their terminal state in a
    # nested snapshot rather than changing AccountModel.status immediately.
    for key in ("chatgpt_gopay", "chatgpt_payment", "payment"):
        snapshot = extra.get(key)
        if not isinstance(snapshot, dict):
            continue
        if any(
            is_paid_status(snapshot.get(field_name))
            for field_name in ("phase", "status", "state", "payment_status", "upstream_status")
        ):
            return True
        result = snapshot.get("result")
        if isinstance(result, dict) and any(
            is_paid_status(result.get(field_name))
            for field_name in ("phase", "status", "state", "payment_status", "upstream_status")
        ):
            return True

    # Some historical rows only retained the upstream error text.
    marker_text = " ".join(
        str(extra.get(key) or "").strip().lower()
        for key in ("chatgpt_checkout_error_body", "chatgpt_skip_save_reason", "chatgpt_unavailable_reason")
    )
    if any(token in marker_text for token in ("already paid", "user is already paid", "you have paid")):
        return True
    del account  # Kept in the signature for call-site readability.
    return False


def _payment_link_skip_reason(
    account: AccountModel,
    *,
    force_refresh: bool = False,
    session: Session | None = None,
    exclude_request_id: str = "",
    history_rows: list[PaymentLinkGenerationModel] | None = None,
    variant_params: dict[str, Any] | None = None,
) -> str:
    """Return a durable, account-level generation guard reason.

    The current cache decides whether a matching URL can be reused.  This
    helper covers the separate historical dimension: successful generations,
    cleaned PIX tombstones, explicit paid terminals, and fresh remote claims.
    """

    status = str(getattr(account, "status", "") or "").strip().lower()
    try:
        extra = account.get_extra()
    except Exception:
        extra = {}
    if not isinstance(extra, dict):
        extra = {}
    desired_params = variant_params if isinstance(variant_params, dict) else {"plan": "plus"}
    desired_plan = str(desired_params.get("plan") or "plus").strip().lower()
    cached = payment_link_cache_for_params(extra, desired_params)
    # Preserve the historical Plus guard before the remote profile is known:
    # a legacy/current pointer may not carry the normalized format or profile
    # hash yet, but it is still durable success evidence.  Never apply this
    # fallback to Team, where a Plus pointer must remain independent.
    raw_current = extra.get("chatgpt_last_payment_link")
    if (
        desired_plan != PAYMENT_LINK_PLAN_TEAM
        and not is_local_short_payment_link_params(desired_params)
        and not is_local_short_payment_link_params(raw_current)
        and isinstance(raw_current, dict)
    ):
        raw_plan = str(raw_current.get("plan") or "plus").strip().lower()
        if raw_plan not in {PAYMENT_LINK_PLAN_TEAM, "team_checkout", "chatgptteamplan"}:
            if (
                _payment_link_current_cache_url(raw_current)
                or str(raw_current.get("link_status") or "").strip().lower() in PAYMENT_LINK_CLEANED_STATUSES
            ):
                cached = raw_current
    legacy_cached = extra.get("chatgpt_paypal_url")
    legacy_cached = legacy_cached if isinstance(legacy_cached, dict) else {}

    if status == "invalid":
        return "账号已失效，不能生成支付链接" if bool(force_refresh) else "账号已失效，默认不预生成支付链接"
    if (
        _payment_link_paid_terminal_marker(account, cached, extra)
        or (
            str(desired_params.get("plan") or "plus").strip().lower() != PAYMENT_LINK_PLAN_TEAM
            and _payment_link_paid_terminal_marker(account, legacy_cached, {})
        )
    ):
        return "账号已明确支付完成，不能重复生成支付链接"
    if status == "subscribed":
        return "账号已订阅，不能生成支付链接" if bool(force_refresh) else "账号已订阅，默认不预生成支付链接"
    if is_local_short_payment_link_params(desired_params) and not has_chatgpt_web_session(extra):
        return "账号缺少 ChatGPT Web Session Cookie，不能生成登录态短链"

    loaded_history_rows = list(history_rows or [])
    if history_rows is None and session is not None and int(getattr(account, "id", 0) or 0) > 0:
        loaded_history_rows = session.exec(
            select(PaymentLinkGenerationModel)
            .where(PaymentLinkGenerationModel.account_id == int(account.id or 0))
            .order_by(PaymentLinkGenerationModel.id.desc())
        ).all()

    normalized_excluded_request_id = str(exclude_request_id or "").strip()
    for row in loaded_history_rows:
        if normalized_excluded_request_id and str(row.request_id or "").strip() == normalized_excluded_request_id:
            continue
        # A numeric account id can be reused.  Empty or mismatched identity
        # fields are legacy/orphan history and must not block the replacement.
        if not _payment_link_generation_matches_account(row, account):
            continue
        if _payment_link_generation_is_fresh_inflight(row) and _payment_link_generation_matches_variant(row, desired_params):
            return "已有支付链接生成任务正在进行"

    # Force refresh is an explicit operator override for historical success or
    # expired/cancelled links, but never for a paid terminal or an in-flight job.
    if bool(force_refresh):
        return ""

    cached_status = str(cached.get("link_status") or "").strip().lower()
    if cached_status in PAYMENT_LINK_CLEANED_STATUSES:
        return "已有支付链接提取记录（链接已清理），默认不重复生成"
    if _payment_link_current_cache_url(cached) or (
        desired_plan != PAYMENT_LINK_PLAN_TEAM and _payment_link_current_cache_url(legacy_cached)
    ):
        return "已有当前支付链接，默认不重复生成"
    if any(
        str(row.status or "").strip().lower() in _PAYMENT_LINK_HISTORY_SUCCESS_STATUSES
        and _payment_link_generation_matches_account(row, account)
        and _payment_link_generation_matches_variant(row, desired_params)
        and _payment_link_generation_has_url(row)
        for row in loaded_history_rows
    ):
        return "已有支付链接提取成功记录，默认不重复生成"
    return ""


def _sync_payment_link_account_status(session: Session, account: AccountModel) -> dict[str, Any]:
    from services.chatgpt_core.local_status_refresh import sync_chatgpt_account_local_status

    return sync_chatgpt_account_local_status(session, account)


