    "login_required",
    "web_session_available",
    "plan_name",
    "country",
    "currency",
    "payment_link_format",
    "payment_source",
    "link_type",
    "link_expires_at",
    "link_expiry_source",
    "profile_hash",
    "remote_batch_id",
    "remote_job_id",
    "remote_request_id",
    "generated_at",
    "created_at",
    "provider_redirect_url",
    "long_url",
    "stripe_redirect_url",
    "stripe_hosted_url",
