_TASK_LOG_CHECKPOINT_LOCK = threading.Lock()
_TASK_LOG_CHECKPOINT_STATE: dict[str, tuple[int, float]] = {}
_TASK_LOG_CHECKPOINT_EVERY_ENTRIES = 200
_TASK_LOG_CHECKPOINT_EVERY_SECONDS = 10.0
# SQLite serializes writers, but the TaskLog upsert is a select-then-insert
# transaction. Keep those transactions serialized in-process so a running
# checkpoint and terminal callback cannot both observe a missing row.
_TASK_LOG_PERSIST_LOCK = threading.RLock()
_TASK_LOG_CHECKPOINT_WRITE_LOCK = threading.Lock()
_TASK_LOG_CHECKPOINT_PENDING: dict[str, dict[str, Any]] = {}
_TASK_LOG_CHECKPOINT_WORKER: threading.Thread | None = None
_TASK_LOG_CHECKPOINT_IDLE = threading.Event()
_TASK_LOG_CHECKPOINT_IDLE.set()
_TASK_LOG_CHECKPOINT_WRITE_RETRIES = 3


def _is_task_log_checkpoint_lock_error(exc: Exception) -> bool:
    error_text = str(exc or "").strip().lower()
    return any(
        marker in error_text
        for marker in (
            "database is locked",
            "database table is locked",
            "database schema is locked",
            "sqlite_busy",
            "busy snapshot",
        )
    )


def _run_task_log_checkpoint_writer() -> None:
    """Persist coalesced running snapshots without blocking task workers."""

    global _TASK_LOG_CHECKPOINT_WORKER
    while True:
        with _TASK_LOG_CHECKPOINT_WRITE_LOCK:
            if not _TASK_LOG_CHECKPOINT_PENDING:
                _TASK_LOG_CHECKPOINT_WORKER = None
                _TASK_LOG_CHECKPOINT_IDLE.set()
                return
            task_id, snapshot = next(iter(_TASK_LOG_CHECKPOINT_PENDING.items()))
            _TASK_LOG_CHECKPOINT_PENDING.pop(task_id, None)

        for attempt in range(_TASK_LOG_CHECKPOINT_WRITE_RETRIES):
            # A busy first write can outlive several task log updates. Fold
            # the newest queued state into the retry instead of durably
            # writing every obsolete intermediate snapshot.
            with _TASK_LOG_CHECKPOINT_WRITE_LOCK:
                newer_snapshot = _TASK_LOG_CHECKPOINT_PENDING.pop(task_id, None)
            if newer_snapshot is not None:
                snapshot = newer_snapshot
            try:
                _persist_task_snapshot(
                    task_id,
                    attempt_outcome="task_running_checkpoint",
                    snapshot=snapshot,
                )
                break
            except Exception as exc:
                retryable = _is_task_log_checkpoint_lock_error(exc)
                if retryable and attempt + 1 < _TASK_LOG_CHECKPOINT_WRITE_RETRIES:
                    time.sleep(0.05 * (attempt + 1))
                    continue
                logger.warning(
                    "active task log checkpoint persistence failed task_id=%s retryable=%s",
                    task_id,
                    retryable,
                    exc_info=True,
                )
                break


def _discard_task_log_checkpoint(task_id: str) -> None:
    """Drop a queued running checkpoint after a durable terminal write."""

    task_key = str(task_id or "").strip()
    if not task_key:
        return
    with _TASK_LOG_CHECKPOINT_WRITE_LOCK:
        _TASK_LOG_CHECKPOINT_PENDING.pop(task_key, None)


def _queue_task_log_checkpoint(task_id: str, snapshot: dict[str, Any]) -> None:
    """Keep only the newest pending snapshot for each task."""

    global _TASK_LOG_CHECKPOINT_WORKER
    task_key = str(task_id or "").strip()
    if not task_key:
        return
    with _TASK_LOG_CHECKPOINT_WRITE_LOCK:
        _TASK_LOG_CHECKPOINT_PENDING[task_key] = snapshot
        _TASK_LOG_CHECKPOINT_IDLE.clear()
        if _TASK_LOG_CHECKPOINT_WORKER is not None and _TASK_LOG_CHECKPOINT_WORKER.is_alive():
            return
        worker = threading.Thread(
            target=_run_task_log_checkpoint_writer,
            name="task-log-checkpoint-writer",
            daemon=True,
        )
        _TASK_LOG_CHECKPOINT_WORKER = worker
        worker.start()


def _wait_for_task_log_checkpoints(timeout_seconds: float = 5.0) -> bool:
    """Wait for queued checkpoints; used by deterministic isolated tests."""

    return _TASK_LOG_CHECKPOINT_IDLE.wait(timeout=max(float(timeout_seconds or 0.0), 0.0))


def _maybe_persist_task_log_checkpoint(task_id: str, message: str) -> None:
    """Periodically persist the active log window.

    Terminal callbacks cover cooperative stops, but a worker can also be
    killed by a browser hard-timeout or a process restart before its ``finally``
    block runs.  A low-frequency checkpoint leaves enough history for the
    persisted task row without turning every log line into a SQLite write.
    """
    task_key = str(task_id or "").strip()
    if not task_key:
        return
    try:
        task_exists = _task_store.exists(task_key)
    except Exception:
        task_exists = False
    if not task_exists:
        with _TASK_LOG_CHECKPOINT_LOCK:
            _TASK_LOG_CHECKPOINT_STATE.pop(task_key, None)
        return

    # Use wall-clock time here rather than the task-control monotonic clock;
    # runners/tests may deliberately stub ``time.monotonic`` for retry timing.
    now = time.time()
    text = str(message or "").lower()
    urgent = any(
        marker in text
        for marker in ("[stop]", "[interrupted]", "中断", "任务已手动停止", "[fatal]", "[error]", "[summary]")
    )
    with _TASK_LOG_CHECKPOINT_LOCK:
        previous_count, previous_at = _TASK_LOG_CHECKPOINT_STATE.get(task_key, (0, now))
        next_count = previous_count + 1
        should_persist = urgent or next_count >= _TASK_LOG_CHECKPOINT_EVERY_ENTRIES or now - previous_at >= _TASK_LOG_CHECKPOINT_EVERY_SECONDS
        if should_persist:
            _TASK_LOG_CHECKPOINT_STATE[task_key] = (0, now)
        else:
            _TASK_LOG_CHECKPOINT_STATE[task_key] = (next_count, previous_at)
    if not should_persist:
        return
    snapshot = _task_store_snapshot_or_none(task_key)
    if snapshot is None:
        return
    runtime_status = str(snapshot.get("status") or "").strip().lower()
    if runtime_status in TERMINAL_TASK_STATUSES:
        with _TASK_LOG_CHECKPOINT_LOCK:
            _TASK_LOG_CHECKPOINT_STATE.pop(task_key, None)
        return
    _queue_task_log_checkpoint(task_key, snapshot)


def _log(
    task_id: str,
    msg: str,
    level: str = "info",
    *,
    expose_phone: bool = False,
    expose_otp: bool = False,
):
    """向任务追加一条日志。

    level=debug 的日志会统一加 [DEBUG] 前缀，前端据此拆分 Info/Debug 视图；
    已经带 [DEBUG] 的上游日志不重复加前缀。
    """
    # An explicit empty message is a visual separator, not a timestamped log event.
    if msg == "":
        _task_store.append_log(task_id, "")
        print()
        return

    ts = beijing_log_time()
    text = str(msg or "")
    normalized_level = str(level or "info").strip().lower() or "info"
    if normalized_level == "debug" and not text.lstrip().upper().startswith("[DEBUG]"):
        text = f"[DEBUG] {text}"
    if "[手机号绑定]" in text:
        text = sanitize_phone_binding_log_line(
            text,
            debug=normalized_level == "debug",
        )
    else:
        text = redact_log_text(text, expose_phone=expose_phone, expose_otp=expose_otp)
    entry = f"[{ts}] {text}"
    _task_store.append_log(task_id, entry)
    _maybe_persist_task_log_checkpoint(task_id, text)
    print(entry)


def _sanitize_task_snapshot_for_response(snapshot: dict[str, Any]) -> dict[str, Any]:
    """Sanitize one task snapshot without remasking phone-binding Info logs."""

    raw_snapshot = dict(snapshot or {})
    safe_snapshot = sanitize_task_detail(raw_snapshot)
    if not isinstance(safe_snapshot, dict):
        return {}
    safe_snapshot.setdefault("timezone", PROJECT_TIMEZONE_NAME)
    if (
        str(raw_snapshot.get("source") or "").strip() == "phone_binding_test"
        and isinstance(raw_snapshot.get("logs"), list)
    ):
        safe_snapshot["logs"] = [
            sanitize_phone_binding_log_line(line)
            for line in raw_snapshot.get("logs") or []
        ]
    return safe_snapshot


def _claim_next_task_attempt(control) -> int:
    """Claim one new account/phone/order at a graceful-stop boundary.

    Every batch runner calls this immediately before it begins a new unit of
    work.  ``RegisterTaskControl.start_attempt`` returns ``None`` only after
    an after-current request (or an immediate request racing a dispatcher).
    Convert that into the existing cooperative stop path for serial runners;
    already claimed attempts never call this helper again and therefore finish
    normally under graceful mode.
    """
    attempt_id = control.start_attempt()
    if attempt_id is None:
        raise StopTaskRequested("已完成当前执行单元，停止后续任务")
    return attempt_id


def _sleep_with_task_control(
    control,
    seconds: float,
    *,
    attempt_id: int | None = None,
    interval_seconds: float = 0.5,
) -> None:
    """Sleep in bounded slices so immediate stop is never delayed by a timer."""
    remaining = max(float(seconds or 0), 0.0)
    interval = max(min(float(interval_seconds or 0.5), 1.0), 0.05)
    while remaining > 0:
        control.checkpoint(attempt_id=attempt_id)
        chunk = min(interval, remaining)
        time.sleep(chunk)
        remaining -= chunk
    control.checkpoint(attempt_id=attempt_id)


def _clear_task_current(task_id: str) -> None:
    task_key = str(task_id or "").strip()
    stale_keys = [key for key in _TASK_STAGE_STARTED_AT if key[0] == task_key]
    for key in stale_keys:
        _TASK_STAGE_STARTED_AT.pop(key, None)
    try:
        _task_store.update_meta(task_id, {"current": {}})
    except Exception:
        pass


def _set_task_current(
    task_id: str,
    *,
    task: str,
    task_label: str = "",
    item_index: int | None = None,
    item_total: int | None = None,
    email: str = "",
    account_id: int | str | None = None,
    phone: str = "",
    phone_index: int | str | None = None,
    phone_total: int | str | None = None,
    phase: str = "",
    phase_label: str = "",
    stage_index: int | None = None,
    stage_total: int | None = None,
    last_message: str = "",
    next_step: str = "",
    resource_touched: bool | None = None,
    reset_started_at: bool = False,
) -> dict[str, Any]:
    phase_key = str(phase or "").strip() or "unknown"
    cache_key = (str(task_id or "").strip(), phase_key)
    if reset_started_at or cache_key not in _TASK_STAGE_STARTED_AT:
        _TASK_STAGE_STARTED_AT[cache_key] = beijing_now_iso()
    payload = build_task_current_state(
        task=task,
        task_label=task_label or task,
        item_index=item_index,
        item_total=item_total,
        email=email,
        account_id=account_id,
        phone=phone,
        phase=phase,
        phase_label=phase_label,
        stage_index=stage_index,
        stage_total=stage_total,
        started_at=_TASK_STAGE_STARTED_AT.get(cache_key, ""),
        last_message=last_message,
        next_step=next_step,
        resource_touched=resource_touched,
    )
    _task_store.update_meta(task_id, {"current": payload})
    return payload


def _task_timeline_log(
    task_id: str,
    *,
    task: str,
    message: str = "",
    item_index: int | None = None,
    item_total: int | None = None,
    email: str = "",
    account_id: int | str | None = None,
    phone: str = "",
    phone_index: int | str | None = None,
    phone_total: int | str | None = None,
    phase: str = "",
    phase_label: str = "",
    stage_index: int | None = None,
    stage_total: int | None = None,
    next_step: str = "",
    resource_touched: bool | None = None,
    level: str = "info",
    reset_started_at: bool = False,
) -> str:
    line = format_task_timeline_log(
        task,
        message,
        item_index=item_index,
        item_total=item_total,
        email=email,
        account_id=account_id,
        phone=phone,
        phone_index=phone_index,
        phone_total=phone_total,
        stage_index=stage_index,
        stage_total=stage_total,
        phase_label=phase_label,
        debug=str(level or "info").strip().lower() == "debug",
    )
    _set_task_current(
        task_id,
        task=task,
        task_label=task,
        item_index=item_index,
        item_total=item_total,
        email=email,
        account_id=account_id,
        phone=phone,
        phase=phase,
        phase_label=phase_label,
        stage_index=stage_index,
        stage_total=stage_total,
        last_message=message or phase_label,
        next_step=next_step,
        resource_touched=resource_touched,
        reset_started_at=reset_started_at,
    )
    _log(
        task_id,
        line,
        level,
        expose_phone=(
            str(task or "").strip() in {"手机绑定", "手机号绑定"}
            and str(level or "info").strip().lower() != "debug"
        ),
        expose_otp=False,
    )
    return line


