def _run_batch_sub2api_upload(task_id: str, account_ids: list[int]):
    from services.sub2api_sync import backfill_chatgpt_account_to_sub2api

    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    primary_email = ""

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    skipped_items = list(meta.get("skipped_items") or [])
    missing_ids = list(meta.get("missing_ids") or [])
    try:
        for missing_id in missing_ids:
            _log(task_id, f"[MISS] 账号不存在: account_id={missing_id}")
            errors.append(f"account_id={missing_id}: 账号不存在")

        for item in skipped_items:
            _log(task_id, f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - {item.get('reason') or '已跳过'}")

        for index, account_id in enumerate(account_ids, start=1):
            control.checkpoint(consume_skip=False)
            email = ""
            attempt_id = _claim_next_task_attempt(control)
            try:
                control.checkpoint(attempt_id=attempt_id)
                with Session(engine) as session:
                    account = session.get(AccountModel, int(account_id or 0))
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    email = str(account.email or "")
                    if not primary_email:
                        primary_email = email

                    _log(task_id, f"[Sub2API] {index}/{total} 开始上传: {email or account_id}")
                    outcome = backfill_chatgpt_account_to_sub2api(account, session=session, commit=True)
                    ok = bool(outcome.get("ok"))
                    uploaded = bool(outcome.get("uploaded"))
                    skipped = bool(outcome.get("skipped"))
                    message_text = str(outcome.get("message") or "")
                    if ok and uploaded:
                        success_count += 1
                        _log(task_id, f"[OK] Sub2API 上传成功: {email or account_id} - {message_text or '上传成功'}")
                    elif ok and skipped:
                        skipped_count += 1
                        _log(task_id, f"[SKIP] Sub2API 已存在/跳过: {email or account_id} - {message_text or '已跳过'}")
                    else:
                        errors.append(f"{email or account_id}: {message_text or '上传失败'}")
                        _log(task_id, f"[FAIL] Sub2API 上传失败: {email or account_id} - {message_text or '上传失败'}")
            except SkipCurrentAttemptRequested as exc:
                skipped_count += 1
                _log(task_id, f"[SKIP] 已跳过 Sub2API 上传: {email or account_id} - {exc}")
            except StopTaskRequested:
                raise
            except Exception as exc:
                error_text = str(exc or "Sub2API 上传失败")
                errors.append(f"{email or account_id}: {error_text}")
                _log(task_id, f"[FAIL] Sub2API 上传异常: {email or account_id} - {error_text}")
            finally:
                control.finish_attempt(attempt_id)
                _task_store.set_progress(task_id, f"{index}/{total}")

        final_status = "done"
        summary_message = f"批量 Sub2API 上传完成: 成功 {success_count} 个，跳过 {skipped_count + len(skipped_items)} 个，失败 {len(errors)} 个"
        _log(task_id, f"[SUMMARY] {summary_message}")
        log_status = "success" if not errors else "failed"
        _save_task_log(
            "chatgpt",
            primary_email,
            log_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_sub2api_upload_success" if log_status == "success" else "batch_sub2api_upload_failed",
                    "source": "batch_sub2api_upload",
                    "meta": {
                        **meta,
                        "runtime_success": success_count,
                        "runtime_skipped": skipped_count,
                        "runtime_errors": errors,
                    },
                },
            ),
        )
        _task_store.finish(
            task_id,
            status=final_status,
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors,
            error="" if not errors else summary_message,
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_sub2api_upload_stopped",
                    "source": "batch_sub2api_upload",
                    "meta": {
                        **meta,
                        "runtime_success": success_count,
                        "runtime_skipped": skipped_count,
                        "runtime_errors": errors,
                    },
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors,
            error=str(exc),
        )
    finally:
        _task_store.cleanup()


def _run_batch_oaipay_upload(
    task_id: str,
    account_ids: list[int],
    category_id: int | None = None,
    category_mode: str = "auto",
    fallback_category_id: int | None = None,
):
    from services.oaipay_sync import backfill_chatgpt_account_to_oaipay

    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    category_success_counts: dict[str, int] = {}
    primary_email = ""

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    skipped_items = list(meta.get("skipped_items") or [])
    missing_ids = list(meta.get("missing_ids") or [])
    mode = _normalize_oaipay_category_mode(category_mode or meta.get("category_mode") or "auto")
    if fallback_category_id is None and meta.get("fallback_category_id") is not None:
        try:
            fallback_category_id = int(meta.get("fallback_category_id"))
        except Exception:
            fallback_category_id = None

    if mode == "manual":
        _log(task_id, f"[OAIPay] 分类策略: 固定分类 #{category_id or '-'}；所有账号按该分类上传")
    else:
        fallback_label = f"#{fallback_category_id}" if fallback_category_id else "全局默认分组"
        _log(task_id, f"[OAIPay] 分类策略: 自动分类；未命中自动规则时使用兜底 {fallback_label}")

    try:
        for missing_id in missing_ids:
            _log(task_id, f"[MISS] 账号不存在: account_id={missing_id}")
            errors.append(f"account_id={missing_id}: 账号不存在")

        for item in skipped_items:
            _log(task_id, f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - {item.get('reason') or '已跳过'}")

        for index, account_id in enumerate(account_ids, start=1):
            control.checkpoint(consume_skip=False)
            email = ""
            attempt_id = _claim_next_task_attempt(control)
            try:
                control.checkpoint(attempt_id=attempt_id)
                with Session(engine) as session:
                    account = session.get(AccountModel, int(account_id or 0))
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    email = str(account.email or "")
                    if not primary_email:
                        primary_email = email

                    _log(task_id, f"[OAIPay] {index}/{total} 开始上传: {email or account_id}")
                    outcome = backfill_chatgpt_account_to_oaipay(
                        account,
                        session=session,
                        commit=True,
                        category_id=category_id,
                        category_mode=mode,
                        fallback_category_id=fallback_category_id,
                    )
                    ok = bool(outcome.get("ok"))
                    uploaded = bool(outcome.get("uploaded"))
                    skipped = bool(outcome.get("skipped"))
                    message_text = str(outcome.get("message") or "")
                    category_label = _oaipay_category_label_from_result(outcome)
                    category_suffix = f" -> {category_label}" if category_label else ""
                    if ok and uploaded:
                        success_count += 1
                        if category_label:
                            category_success_counts[category_label] = category_success_counts.get(category_label, 0) + 1
                        _log(task_id, f"[OK] OAIPay 上传成功: {email or account_id}{category_suffix} - {message_text or '上传成功'}")
                    elif ok and skipped:
                        skipped_count += 1
                        _log(task_id, f"[SKIP] OAIPay 已存在/跳过: {email or account_id}{category_suffix} - {message_text or '已跳过'}")
                    else:
                        errors.append(f"{email or account_id}: {message_text or '上传失败'}")
                        _log(task_id, f"[FAIL] OAIPay 上传失败: {email or account_id}{category_suffix} - {message_text or '上传失败'}")
            except SkipCurrentAttemptRequested as exc:
                skipped_count += 1
                _log(task_id, f"[SKIP] 已跳过 OAIPay 上传: {email or account_id} - {exc}")
            except StopTaskRequested:
                raise
            except Exception as exc:
                error_text = str(exc or "OAIPay 上传失败")
                errors.append(f"{email or account_id}: {error_text}")
                _log(task_id, f"[FAIL] OAIPay 上传异常: {email or account_id} - {error_text}")
            finally:
                control.finish_attempt(attempt_id)
                _task_store.set_progress(task_id, f"{index}/{total}")

        final_status = "done"
        category_summary = ""
        if category_success_counts:
            category_summary = "；分类分布: " + "，".join(f"{label}={count}" for label, count in category_success_counts.items())
        summary_message = f"批量 OAIPay 上传完成: 成功 {success_count} 个，跳过 {skipped_count + len(skipped_items)} 个，失败 {len(errors)} 个{category_summary}"
        _log(task_id, f"[SUMMARY] {summary_message}")
        log_status = "success" if not errors else "failed"
        _save_task_log(
            "chatgpt",
            primary_email,
            log_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_oaipay_upload_success" if log_status == "success" else "batch_oaipay_upload_failed",
                    "source": "batch_oaipay_upload",
                    "meta": {
                        **meta,
                        "runtime_success": success_count,
                        "runtime_skipped": skipped_count,
                        "runtime_errors": errors,
                        "runtime_category_counts": category_success_counts,
                    },
                },
            ),
        )
        _task_store.finish(
            task_id,
            status=final_status,
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors,
            error="" if not errors else summary_message,
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_oaipay_upload_stopped",
                    "source": "batch_oaipay_upload",
                    "meta": {
                        **meta,
                        "runtime_success": success_count,
                        "runtime_skipped": skipped_count,
                        "runtime_errors": errors,
                        "runtime_category_counts": category_success_counts,
                    },
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors,
            error=str(exc),
        )
    finally:
        _task_store.cleanup()


_IDEA_SUBMIT_SUCCESS_STATUSES = {"paid", "success", "completed"}
_IDEA_SUBMIT_FAILED_STATUSES = {"failed", "fail", "error", "invalid", "expired", "cancelled", "canceled"}
_IDEA_SUBMIT_UNSUBMITTED_STATUSES = {"skipped", "skip", "unsubmitted", "submit_failed", "missing"}
_IDEA_ACCOUNT_UNAVAILABLE_MARKERS = (
    "当前账号没有资格",
    "账号没有资格",
    "没有开通资格",
    "没有资格",
    "无资格",
    "请换号",
    "换号重试",
    "no trial eligibility",
    "not eligible",
    "ineligible",
    "eligibility",
    "account unavailable",
)
_IDEA_NON_ACCOUNT_TRANSIENT_MARKERS = (
    "节点网络异常",
    "底层网络波动",
    "tls",
    "timeout",
    "timed out",
    "connection",
    "网络繁忙",
    "稍后再试",
    "rate limit",
    "429",
    "502",
    "503",
    "504",
)


def _is_saved_pix_user_link_already_submitted_reason(reason: Any) -> bool:
    """Recognize only a remote duplicate *link* response, never a CDK error."""

    text = str(reason or "").strip().lower()
    if not text:
        return False
    chinese_link = any(marker in text for marker in ("pix 支付链接", "pix支付链接", "支付链接", "付款链接"))
    chinese_duplicate = any(marker in text for marker in ("已被提交", "已提交过", "重复提交", "请勿重复使用"))
    english_link = any(marker in text for marker in ("pix payment link", "pix pay link", "payment link"))
    english_duplicate = any(marker in text for marker in (
        "already submitted", "has been submitted", "duplicate submission", "do not reuse",
    ))
    return (chinese_link and chinese_duplicate) or (english_link and english_duplicate)


def _is_idea_account_unavailable_reason(reason: Any) -> bool:
    text = str(reason or "").strip().lower()
    if not text:
        return False
    if any(marker in text for marker in _IDEA_ACCOUNT_UNAVAILABLE_MARKERS):
        return True
    if any(marker in text for marker in _IDEA_NON_ACCOUNT_TRANSIENT_MARKERS):
        return False
    return False


def _idea_submit_account_key(item: dict[str, Any] | None, fallback: str = "") -> str:
    payload = item if isinstance(item, dict) else {}
    try:
        account_id = int(payload.get("account_id") or payload.get("id") or 0)
    except Exception:
        account_id = 0
    if account_id > 0:
        return f"id:{account_id}"
    email = str(payload.get("email") or "").strip().lower()
    if email:
        return f"email:{email}"
    return fallback


def _idea_submit_compact_item(item: dict[str, Any] | None, *, fallback_status: str = "") -> dict[str, Any]:
    payload = dict(item or {}) if isinstance(item, dict) else {}
    compact: dict[str, Any] = {}
    for key in (
        "account_id",
        "email",
        "status",
        "reason",
        "cdk_id",
        "display_id",
        "finished_at",
        "idea_marked_unavailable",
    ):
        if key in payload and payload.get(key) not in (None, ""):
            compact[key] = payload.get(key)
    if fallback_status and not compact.get("status"):
        compact["status"] = fallback_status
    return compact


def _normalize_idea_submit_result_status(value: Any) -> str:
    status = str(value or "").strip().lower()
    if status in _IDEA_SUBMIT_SUCCESS_STATUSES:
        return "paid"
    if status in _IDEA_SUBMIT_FAILED_STATUSES:
        return "failed"
    if status == "timeout":
        return "timeout"
    if status in _IDEA_SUBMIT_UNSUBMITTED_STATUSES:
        return "unsubmitted"
    if status in {"submitted", "processing", "polling"}:
        return "pending"
    return status or "pending"


def _build_idea_submit_runtime_summary(
    *,
    pairs: list[dict[str, Any]],
    missing_ids: list[int],
    skipped_accounts: list[dict[str, Any]],
    runtime_results: list[dict[str, Any]],
    submitted_count: int = 0,
    target_success_count: int = 0,
    errors: list[str] | None = None,
    payment_channel: str = "ideal",
) -> dict[str, Any]:
    """Build an operator-facing Idea submit summary with stable account groups.

    `runtime_results` is append-only while the task runs.  This summary is the
    canonical grouped view used by the final log, task history, and live panel:
    success accounts, upstream failed accounts, timeout accounts, and accounts
    that never received an upstream order.
    """
    by_key: dict[str, dict[str, Any]] = {}
    order: list[str] = []

    def put(item: dict[str, Any], *, status: str = "", reason: str = "", overwrite: bool = True) -> None:
        key = _idea_submit_account_key(item, fallback=f"row:{len(order)}")
        if not key:
            key = f"row:{len(order)}"
        if key not in by_key:
            by_key[key] = {}
            order.append(key)
        if overwrite:
            by_key[key].update({k: v for k, v in item.items() if v not in (None, "")})
        else:
            by_key[key] = {
                **{k: v for k, v in item.items() if v not in (None, "")},
                **by_key[key],
            }
        if status:
            by_key[key]["status"] = status
        if reason and not by_key[key].get("reason"):
            by_key[key]["reason"] = reason

    for pair in pairs or []:
        put(dict(pair or {}), status="pending", overwrite=False)

    for item in skipped_accounts or []:
        reason = str((item or {}).get("reason") or "创建任务时已跳过").strip()
        put(dict(item or {}), status="unsubmitted", reason=reason, overwrite=True)

    for missing_id in missing_ids or []:
        put(
            {"account_id": int(missing_id or 0), "reason": "账号不存在"},
            status="unsubmitted",
            overwrite=True,
        )

    for result in runtime_results or []:
        payload = dict(result or {})
        normalized = _normalize_idea_submit_result_status(payload.get("status"))
        if normalized == "unsubmitted" and not payload.get("reason"):
            payload["reason"] = "未提交到上游"
        put(payload, status=normalized, overwrite=True)

    success_accounts: list[dict[str, Any]] = []
    failed_accounts: list[dict[str, Any]] = []
    timeout_accounts: list[dict[str, Any]] = []
    unsubmitted_accounts: list[dict[str, Any]] = []
    pending_accounts: list[dict[str, Any]] = []
    marked_unavailable_accounts: list[dict[str, Any]] = []

    for key in order:
        item = by_key.get(key) or {}
        normalized = _normalize_idea_submit_result_status(item.get("status"))
        item["status"] = normalized
        compact = _idea_submit_compact_item(item, fallback_status=normalized)
        if normalized == "paid":
            success_accounts.append(compact)
        elif normalized == "failed":
            failed_accounts.append(compact)
            if bool(item.get("idea_marked_unavailable")):
                marked_unavailable_accounts.append(compact)
        elif normalized == "timeout":
            timeout_accounts.append(compact)
        elif normalized == "unsubmitted":
            unsubmitted_accounts.append(compact)
        else:
            pending_accounts.append(compact)

    total_accounts = len(order)
    failed_total = len(failed_accounts)
    timeout_total = len(timeout_accounts)
    unsubmitted_total = len(unsubmitted_accounts)
    paid_total = len(success_accounts)

    return {
        "source": "baxigpt_cdk_submit",
        "payment_channel": _normalize_baxigpt_payment_channel(payment_channel),
        "generated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "total_accounts": total_accounts,
        "pair_count": len(pairs or []),
        "target_success_count": int(target_success_count or 0),
        "submitted": int(submitted_count or 0),
        "paid": paid_total,
        "failed": failed_total,
        "timeout": timeout_total,
        "unsubmitted": unsubmitted_total,
        "pending": len(pending_accounts),
        "marked_unavailable": len(marked_unavailable_accounts),
        "success_accounts": success_accounts,
        "failed_accounts": failed_accounts,
        "timeout_accounts": timeout_accounts,
        "unsubmitted_accounts": unsubmitted_accounts,
        "pending_accounts": pending_accounts,
        "marked_unavailable_accounts": marked_unavailable_accounts,
        "errors": list(errors or []),
    }


def _idea_submit_log_item_text(item: dict[str, Any]) -> str:
    email = str(item.get("email") or "").strip()
    account_id = str(item.get("account_id") or "").strip()
    label = email or (f"account_id={account_id}" if account_id else "-")
    suffixes: list[str] = []
    display_id = str(item.get("display_id") or "").strip()
    if not display_id:
        order_id = str(item.get("order_id") or "").strip()
        if "::" in order_id:
            display_id = order_id.rsplit("::", 1)[-1].strip()
        elif order_id and not any(marker in order_id.lower() for marker in ("cdk", "test-", "idea-")):
            display_id = order_id
    if display_id:
        suffixes.append(f"task={display_id}")
    reason = str(item.get("reason") or "").strip()
    if reason:
        suffixes.append(reason[:120])
    return f"{label} | {' | '.join(suffixes)}" if suffixes else label


def _log_idea_submit_group_summary(task_id: str, title: str, items: list[dict[str, Any]], *, limit: int = 500) -> None:
    count = len(items or [])
    _log(task_id, f"[SUMMARY] {title} {count} 个")
    if count <= 0:
        return
    shown = items[:limit]
    for item in shown:
        _log(task_id, f"[SUMMARY][{title}] {_idea_submit_log_item_text(item)}")
    if count > limit:
        _log(task_id, f"[SUMMARY][{title}] 还有 {count - limit} 个未在日志展开，可在任务详情 JSON 查看")


def _run_pix_submit(
    task_id: str,
    pairs: list[dict[str, Any]],
    settings: dict[str, Any],
    pix_cdks: list[dict[str, str]],
) -> None:
    """Run PIX tasks while keeping CDKs, links, and status tokens in memory.

    User-link mode reads the already persisted account link only at execution
    time. It never copies that URL into task metadata, runtime results, or
    task logs. A preflight-authorized site CDK is consumed one unit at a time
    while this task holds a cross-instance lease; accepted orders are then
    polled as a batch. External one-success CDKs remain blocked after paid.
    Explicit failures may be reused only when their outcome is known safe;
    uncertain outcomes remain locked for manual reconciliation.
    """

    from services.chatgpt_core.baxigpt_client import BaxiGptClient, BaxiGptRequestError

    control = _task_store.control_for(task_id)
    client = BaxiGptClient()
    pix_submit_mode = _normalize_pix_submit_mode(settings.get("pix_submit_mode"))
    use_saved_pix_link = pix_submit_mode == PIX_SUBMIT_MODE_USER_LINK
    requested_target_success_count = max(int(settings.get("target_success_count") or 0), 0)
    raw_pix_cdks = (
        [{"code": str(pix_cdks or "").strip(), "fingerprint": _pix_cdk_usage_store.fingerprint(pix_cdks)}]
        if isinstance(pix_cdks, str)
        else list(pix_cdks or [])
    )
    pix_cdk_label_count = len(raw_pix_cdks)
    pix_cdks = [
        {
            "code": str(item.get("code") or "").strip(),
            "fingerprint": str(item.get("fingerprint") or "").strip(),
            "label": f"PIX CDK #{index}" if pix_cdk_label_count > 1 else "PIX CDK",
            # Preflight fills these fields before the first submission.  A
            # missing preflight method is kept as a legacy compatibility path
            # for older test/development clients and remains one-success by
            # default.
            "source": str(item.get("source") or "").strip().lower(),
            "capacity_exact": bool(item.get("capacity_exact")),
            "available_uses": max(int(item.get("available_uses") or 0), 0),
            "preflight_state": str(item.get("preflight_state") or "").strip().lower(),
            "preflight_message": str(item.get("preflight_message") or "").strip(),
            "preflight_required": True,
            "lease_held": False,
            "task_lease": False,
            "release_forbidden": False,
            # Unknown/legacy upstream responses must be treated as external
            # one-success credentials until preflight says otherwise.
            "reuse_policy": str(item.get("reuse_policy") or "one_success").strip().lower(),
        }
        for index, item in enumerate(raw_pix_cdks, start=1)
        if str(item.get("code") or "").strip() and str(item.get("fingerprint") or "").strip()
    ]
    target_success_count = (
        min(requested_target_success_count, len(pairs))
        if requested_target_success_count > 0
        else len(pairs)
    )
    total = max(target_success_count, 1)
    submitted_count = 0
    success_count = 0
    timeout_count = 0
    skipped_count = 0
    errors: list[str] = []
    runtime_results: list[dict[str, Any]] = []
    primary_email = ""
    failure_continue = _is_truthy(settings.get("failure_continue"))
    submit_interval_seconds = max(int(settings.get("submit_interval_seconds") or 0), 0)
    status_poll_interval_seconds = max(int(settings.get("status_poll_interval_seconds") or 5), 1)
    status_poll_timeout_seconds = max(
        int(settings.get("status_poll_timeout_seconds") or IDEA_SUBMIT_DEFAULT_POLL_WARNING_SECONDS),
        status_poll_interval_seconds,
        IDEA_SUBMIT_DEFAULT_POLL_WARNING_SECONDS,
    )
    sensitive_pix_links: set[str] = set()

    def safe_text(value: Any, *status_tokens: Any) -> str:
        text = str(value or "")
        for secret in ([item["code"] for item in pix_cdks], *sensitive_pix_links, *status_tokens):
            secret_text = str(secret or "").strip()
            if secret_text:
                text = text.replace(secret_text, "[REDACTED]")
        return redact_log_text(text)[:1000]

    def sync_preflight_meta() -> None:
        _task_store.update_meta(
            task_id,
            {
                "pix_cdk_preflight": [
                    {
                        "label": str(item.get("label") or "PIX CDK"),
                        "source": str(item.get("source") or ""),
                        "capacity_exact": bool(item.get("capacity_exact")),
                        "available_uses": max(int(item.get("available_uses") or 0), 0),
                        "state": str(item.get("preflight_state") or ""),
                        "can_submit": bool(item.get("can_submit")),
                    }
                    for item in pix_cdks
                ],
            },
        )

    def run_pix_preflight() -> tuple[bool, str]:
        """Populate in-memory CDK capabilities before any reservation.

        The raw CDK values remain in this function's local objects only.  A
        missing method is tolerated for old fakes, but a real client failure
        stops the batch rather than guessing a multi-credit capacity.
        """
        method = getattr(client, "preflight_pix_cdks", None)
        if not callable(method):
            # Legacy development clients do not know the read-only endpoint.
            # Preserve their explicit response hint, otherwise one-success.
            for item in pix_cdks:
                item["preflight_required"] = False
                item["can_submit"] = True
                item["source"] = item.get("source") or "legacy"
                item["preflight_state"] = item.get("preflight_state") or "legacy"
                item["available_uses"] = max(int(item.get("available_uses") or 0), 1)
                item["capacity_exact"] = bool(item.get("capacity_exact"))
            sync_preflight_meta()
            return True, ""

        submit_mode = "pix_unified_user_link" if use_saved_pix_link else "pix_unified_auto_extract"
        codes = [str(item.get("code") or "") for item in pix_cdks]
        try:
            result = method(cdks=codes, submit_mode=submit_mode)
        except Exception as exc:
            # Do not include the exception's raw request payload in task data.
            message = safe_text(exc)
            for item in pix_cdks:
                item["can_submit"] = False
                item["preflight_state"] = "preflight_error"
                item["preflight_message"] = "PIX CDK 预检失败，请稍后重试"
            sync_preflight_meta()
            return False, message or "PIX CDK 预检失败"

        raw_items = result.get("items") if isinstance(result, dict) and isinstance(result.get("items"), list) else []
        by_index: dict[int, dict[str, Any]] = {}
        valid_preflight = isinstance(result, dict) and result.get("ok") is True

        def strict_bool(value: Any) -> tuple[bool, bool]:
            if isinstance(value, bool):
                return value, True
            if isinstance(value, int) and value in {0, 1}:
                return bool(value), True
            text = str(value or "").strip().lower()
            if text in {"true", "1", "yes", "on"}:
                return True, True
            if text in {"false", "0", "no", "off"}:
                return False, True
            return False, False

        for raw in raw_items:
            if not isinstance(raw, dict):
                continue
            try:
                index = int(raw.get("index") or 0)
            except (TypeError, ValueError):
                index = 0
            if index <= 0 or index in by_index:
                valid_preflight = False
                continue
            source = str(raw.get("source") or "").strip().lower()
            authoritative, source_authoritative_ok = strict_bool(raw.get("authoritative"))
            can_submit_hint, source_can_submit_ok = strict_bool(raw.get("can_submit"))
            capacity_hint, source_capacity_ok = strict_bool(raw.get("capacity_exact"))
            try:
                available_hint = max(int(raw.get("available_uses") or 0), 0)
                available_hint_ok = True
            except (TypeError, ValueError):
                available_hint = 0
                available_hint_ok = False
            if (
                not source_authoritative_ok
                or not source_can_submit_ok
                or not source_capacity_ok
                or not available_hint_ok
                or (
                    source == "site_cdk"
                    and (not authoritative or not capacity_hint)
                )
                or (
                    source == "external_pix_cdk"
                    and (authoritative or capacity_hint or (can_submit_hint and available_hint != 1))
                )
                or (
                    source not in {"site_cdk", "external_pix_cdk"}
                    and (authoritative or can_submit_hint or capacity_hint or available_hint > 0)
                )
            ):
                valid_preflight = False
            if index > 0:
                by_index[index] = raw
        if len(raw_items) != len(pix_cdks) or set(by_index) != set(range(1, len(pix_cdks) + 1)):
            valid_preflight = False
        if not valid_preflight:
            for item in pix_cdks:
                item["can_submit"] = False
                item["preflight_state"] = "preflight_invalid"
                item["preflight_message"] = "PIX CDK 预检响应不完整，请稍后重试"
            sync_preflight_meta()
            return False, "PIX CDK 预检响应不完整"
        for position, item in enumerate(pix_cdks, start=1):
            raw = by_index.get(position) or {}
            item["source"] = str(raw.get("source") or "").strip().lower()
            item["capacity_exact"], capacity_exact_ok = strict_bool(raw.get("capacity_exact"))
            try:
                item["available_uses"] = max(int(raw.get("available_uses") or 0), 0)
            except (TypeError, ValueError):
                item["available_uses"] = 0
                item["preflight_state"] = "preflight_invalid"
                valid_preflight = False
            item["can_submit"], can_submit_ok = strict_bool(raw.get("can_submit"))
            item["can_submit"] = item["can_submit"] and item["available_uses"] > 0
            item["preflight_state"] = str(raw.get("state") or "missing").strip().lower()
            item["preflight_message"] = safe_text(raw.get("message") or "")
            item["preflight_required"] = True
            # A malformed source/capability response is not safe to reuse.
            if not item["source"] or not item["can_submit"]:
                item["can_submit"] = False
            if not (capacity_exact_ok and can_submit_ok):
                item["can_submit"] = False
            item["reuse_policy"] = (
                "after_paid"
                if item["capacity_exact"] and item["source"] == "site_cdk"
                else "one_success"
            )
        sync_preflight_meta()
        return True, ""

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")
    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    missing_ids = list(meta.get("missing_ids") or [])
    skipped_accounts = list(meta.get("skipped_accounts") or [])
    preflight_ok, preflight_error = run_pix_preflight()
    if not preflight_ok:
        _log(task_id, f"[PIX][PREFLIGHT] {preflight_error or '预检失败，停止新的提交'}")

    def sync_meta() -> None:
        summary = _build_idea_submit_runtime_summary(
            pairs=pairs,
            missing_ids=missing_ids,
            skipped_accounts=skipped_accounts,
            runtime_results=runtime_results,
            submitted_count=submitted_count,
            target_success_count=target_success_count,
            errors=errors,
            payment_channel="pix",
        )
        _task_store.update_meta(
            task_id,
            {
                "runtime_results": list(runtime_results),
                "runtime_submitted": submitted_count,
                "runtime_success": success_count,
                "runtime_timeout": timeout_count,
                "runtime_skipped": skipped_count,
                "runtime_errors": list(errors),
                "idea_submit_summary": summary,
            },
        )

    def append_result(**payload: Any) -> None:
        safe_payload = {
            "finished_at": beijing_now_iso(),
            **payload,
        }
        if "reason" in safe_payload:
            safe_payload["reason"] = safe_text(safe_payload.get("reason"))
        # The runner never includes status_token in a result. Keep this guard
        # so a later refactor cannot accidentally leak it through task meta.
        safe_payload.pop("status_token", None)
        runtime_results.append(safe_payload)
        sync_meta()

    def persist_account_state(
        account_id: int,
        *,
        status: str,
        order_id: str = "",
        display_id: str = "",
        reason: str = "",
        mark_unavailable: bool = False,
        local_status_refresh: dict[str, Any] | None = None,
        persist_idea_state: bool | None = None,
    ) -> None:
        if persist_idea_state is None:
            # A saved PIX link is a payment-resource operation, not an Idea
            # eligibility check.  Keep any existing Idea marker untouched.
            persist_idea_state = not use_saved_pix_link
        status_value = _normalize_idea_submit_result_status(status)
        if status_value == "pending":
            status_value = "submitted"
        safe_reason = safe_text(reason)
        now = datetime.now(timezone.utc).isoformat()
        with Session(engine) as session:
            account = session.get(AccountModel, int(account_id or 0))
            if account is None or account.platform != "chatgpt":
                return
            try:
                extra = account.get_extra()
            except Exception:
                extra = {}
            if not isinstance(extra, dict):
                extra = {}
            existing = extra.get("baxigpt_cdk") if isinstance(extra.get("baxigpt_cdk"), dict) else {}
            payload = {
                "status": status_value,
                "upstream_status": status_value,
                "payment_channel": "pix",
                "pix_submit_mode": pix_submit_mode,
                "code_masked": "PIX CDK",
                "cdk_id": 0,
                "order_id": str(order_id or existing.get("order_id") or "").strip(),
                "display_id": str(display_id or existing.get("display_id") or "").strip(),
                "remote_email": str(account.email or ""),
                "task_id": task_id,
                "submitted_at": str(existing.get("submitted_at") or now),
                "paid_at": now if status_value == "paid" else str(existing.get("paid_at") or ""),
                "last_checked_at": now,
                "last_error_message": safe_reason if safe_reason else "",
            }
            if isinstance(local_status_refresh, dict):
                payload["local_status_refresh"] = dict(local_status_refresh)
            elif isinstance(existing.get("local_status_refresh"), dict):
                payload["local_status_refresh"] = dict(existing["local_status_refresh"])
            extra["baxigpt_cdk"] = payload

            history = extra.get("baxigpt_cdk_history")
            if not isinstance(history, list):
                history = []
            previous = history[-1] if history and isinstance(history[-1], dict) else {}
            if not history or any(
                str(previous.get(key) or "") != str(payload.get(key) or "")
                for key in ("status", "upstream_status", "order_id", "display_id", "last_error_message")
            ):
                history.append(dict(payload))
            extra["baxigpt_cdk_history"] = history[-20:]

            if persist_idea_state:
                previous_marker = extra.get("idea_submit") if isinstance(extra.get("idea_submit"), dict) else {}
                marker = {
                    "available": not bool(mark_unavailable),
                    "unavailable": bool(mark_unavailable),
                    "reason": safe_reason if mark_unavailable else "",
                    "marked_at": now if mark_unavailable else "",
                    "cleared_at": now if status_value == "paid" else "",
                    "source": "baxigpt_cdk_submit",
                    "payment_channel": "pix",
                    "pix_submit_mode": pix_submit_mode,
                    "cdk_id": 0,
                    "code_masked": "PIX CDK",
                    "task_id": task_id,
                    "order_id": payload["order_id"],
                    "display_id": payload["display_id"],
                    "status": status_value,
                }
                if status_value == "paid" and previous_marker.get("reason"):
                    marker["previous_reason"] = safe_text(previous_marker.get("reason"))
                extra["idea_submit"] = marker
                if mark_unavailable:
                    extra["chatgpt_account_unavailable"] = True
                    extra["chatgpt_unavailable_reason"] = safe_reason
                    extra["chatgpt_skip_save_account"] = True
                    extra["chatgpt_skip_save_reason"] = safe_reason
                    extra["chatgpt_invalid_registration_failure"] = True
                    extra["chatgpt_invalid_registration_reason"] = safe_reason
                    extra["idea_submit_unavailable"] = True
                    extra["idea_submit_unavailable_reason"] = safe_reason
                    extra["idea_submit_unavailable_at"] = now
                elif status_value == "paid":
                    for key in ("idea_submit_unavailable", "idea_submit_unavailable_reason", "idea_submit_unavailable_at"):
                        extra.pop(key, None)

            account.set_extra(extra)
            account.updated_at = datetime.now(timezone.utc)
            session.add(account)
            upsert_account_list_state_for_account_ids(session, [account.id], commit=False)
            session.commit()

    def refresh_paid_account_local_status(account_id: int, order_id: str, display_id: str) -> dict[str, Any] | None:
        with Session(engine) as session:
            account = session.get(AccountModel, int(account_id or 0))
            if account is None or account.platform != "chatgpt":
                _log(task_id, f"[PIX][WARN] paid 后本地状态刷新跳过: account_id={account_id} 不存在")
                return None
            try:
                refresh_result = sync_chatgpt_account_local_status(session, account)
                summary = summarize_status_refresh(refresh_result, trigger="pix_submit_paid")
            except Exception as exc:
                summary = {
                    "trigger": "pix_submit_paid",
                    "refreshed_at": datetime.now(timezone.utc).isoformat(),
                    "status": str(getattr(account, "status", "") or ""),
                    "error": safe_text(exc),
                }
            # sync_chatgpt_account_local_status owns a commit; open a fresh
            # persistence write below so the PIX state remains the newest extra.
        persist_account_state(
            account_id,
            status="paid",
            order_id=order_id,
            display_id=display_id,
            local_status_refresh=summary,
        )
        return summary

    def mark_saved_pix_link_submitted(account_id: int, pix_pay_link: str, *, duplicate: bool = False) -> bool:
        if not use_saved_pix_link:
            return False
        try:
            marked = _mark_saved_pix_user_link_submitted(
                account_id,
                pix_pay_link=pix_pay_link,
                duplicate=duplicate,
            )
        except Exception as exc:
            _log(task_id, f"[PIX][WARN] 已保存链接提交状态写回失败: {safe_text(exc)}")
            return False
        if not marked:
            _log(task_id, "[PIX][DEBUG] 已保存链接已在任务执行期间更新，保留新链接状态", "debug")
        return marked

    def wait_with_control(seconds: int, attempt_id: int) -> None:
        remaining = float(max(seconds, 0))
        while remaining > 0:
            control.checkpoint(attempt_id=attempt_id)
            chunk = min(1.0, remaining)
            time.sleep(chunk)
            remaining -= chunk

    def cdk_owner_account_id(cdk: dict[str, Any], account_id: int) -> int:
        return int(cdk.get("lease_account_id") or 0) if bool(cdk.get("lease_held")) else int(account_id or 0)

    def acquire_cdk_lease(cdk: dict[str, Any], account_id: int) -> bool:
        """Reserve a site card for the task or an external card for one account."""
        if bool(cdk.get("release_forbidden")):
            return False
        if bool(cdk.get("lease_held")):
            return True
        task_lease = bool(
            cdk.get("capacity_exact")
            and str(cdk.get("source") or "").strip().lower() == "site_cdk"
        )
        owner_account_id = 0 if task_lease else int(account_id or 0)
        try:
            usage = _pix_cdk_usage_store.reserve(
                cdk["fingerprint"], task_id=task_id, account_id=owner_account_id,
            )
            if (
                usage.state != PIX_CDK_STATE_RESERVED
                or usage.task_id != task_id
                or int(usage.account_id or 0) != owner_account_id
            ):
                _log(task_id, f"[SKIP][PIX] {cdk.get('label') or 'PIX CDK'} 已被其他任务占用或待复核")
                return False
            cdk["lease_held"] = True
            cdk["task_lease"] = task_lease
            cdk["lease_account_id"] = owner_account_id
            return True
        except Exception as exc:
            _log(task_id, f"[PIX][WARN] CDK 预留失败: {safe_text(exc)}")
            return False

    def cdk_has_active_order(cdk: dict[str, Any], *, exclude_order_id: str = "") -> bool:
        fingerprint = str(cdk.get("fingerprint") or "")
        for active in active_orders:
            if str(active.get("order_id") or "") == str(exclude_order_id or ""):
                continue
            active_cdk = active.get("cdk") if isinstance(active.get("cdk"), dict) else {}
            if fingerprint and str(active_cdk.get("fingerprint") or "") == fingerprint:
                return True
        return False

    def release_cdk(
        cdk: dict[str, Any],
        account_id: int,
        *,
        reusable: bool,
        requeue: bool,
        exclude_order_id: str = "",
    ) -> bool:
        """Release an explicit failure; keep a task lease while requeueing."""
        # An upstream outcome that is unknown/manual-review must be treated as
        # authoritative for this CDK.  Other concurrent orders may report a
        # known failure, but they must not release, requeue, or block the same
        # reservation after one path has marked it unsafe to reuse.
        if bool(cdk.get("release_forbidden")):
            _log(task_id, f"[PIX][WARN] {cdk.get('label') or 'PIX CDK'} 已标记待复核，拒绝释放/重排/阻断")
            return False
        try:
            owner_account_id = cdk_owner_account_id(cdk, account_id)
            if reusable:
                if (
                    requeue
                    and bool(cdk.get("task_lease"))
                    and int(cdk.get("available_uses") or 0) <= 0
                ):
                    # The upstream already accepted the final exact-capacity
                    # unit. A later task failure does not refund that unit.
                    requeue = False
                if (
                    bool(cdk.get("lease_held"))
                    and not requeue
                    and bool(cdk.get("task_lease"))
                    and cdk_has_active_order(cdk, exclude_order_id=exclude_order_id)
                ):
                    # Keep the task lease until all already accepted orders
                    # using this fingerprint have reached a known state.
                    cdk["deferred_release"] = True
                    return True
                # A requeued item stays under this task's lease. This prevents
                # another instance from interleaving submissions between two
                # exact-quota uses of the same CDK.
                if bool(cdk.get("lease_held")) and bool(cdk.get("task_lease")) and requeue:
                    if cdk not in available_cdks:
                        available_cdks.append(cdk)
                    return True
                released = _pix_cdk_usage_store.release(
                    cdk["fingerprint"], task_id=task_id, account_id=owner_account_id,
                )
                cdk["lease_held"] = False
                if released and requeue:
                    available_cdks.append(cdk)
                elif not released:
                    _log(task_id, f"[PIX][WARN] {cdk['label']} 当前占用已变化，未重新加入可用队列")
                return bool(released)
            else:
                _pix_cdk_usage_store.mark_blocked(
                    cdk["fingerprint"], task_id=task_id, account_id=owner_account_id,
                )
                cdk["lease_held"] = False
                return True
        except Exception as exc:
            cdk["release_forbidden"] = True
            _log(task_id, f"[PIX][WARN] CDK 状态同步失败: {safe_text(exc)}")
            return False

    def lock_cdk_for_review(cdk: dict[str, Any], account_id: int, *, order_id: str = "") -> None:
        # Even if the database write below fails, cleanup must not release a
        # reservation whose upstream outcome is unknown.
        cdk["release_forbidden"] = True
        available_cdks[:] = [item for item in available_cdks if item is not cdk]
        try:
            owner_account_id = cdk_owner_account_id(cdk, account_id)
            _pix_cdk_usage_store.mark_uncertain(
                cdk["fingerprint"], task_id=task_id, account_id=owner_account_id, order_id=order_id,
            )
            cdk["lease_held"] = False
        except Exception as exc:
            _log(task_id, f"[PIX][WARN] CDK 待复核锁定失败: {safe_text(exc)}")

    def release_idle_cdk_leases(*, include_external: bool = False) -> None:
        """Release task leases that no longer need another submission."""
        for cdk in pix_cdks:
            if not bool(cdk.get("lease_held")):
                continue
            if bool(cdk.get("release_forbidden")):
                continue
            if not include_external and not bool(cdk.get("capacity_exact")):
                continue
            try:
                released = _pix_cdk_usage_store.release(
                    cdk["fingerprint"], task_id=task_id, account_id=cdk_owner_account_id(cdk, 0),
                )
                if released:
                    cdk["lease_held"] = False
            except Exception as exc:
                _log(task_id, f"[PIX][WARN] 任务级 CDK 释放失败: {safe_text(exc)}")

    def cdk_error_is_terminal(reason: str) -> bool:
        lower = str(reason or "").lower()
        return any(marker in lower for marker in (
            "cdk_used", "cdk_invalid", "cdk_disabled", "卡密已使用", "卡密无效", "卡密已禁用",
        ))

    def cdk_error_is_capacity_exhausted(reason: str) -> bool:
        lower = str(reason or "").lower()
        return any(marker in lower for marker in (
            "cdk余额不足", "当前剩余: 0", "额度已耗尽", "余额不足",
            "insufficient balance", "balance exhausted", "no remaining balance",
        ))

    def cdk_reuse_after_paid(cdk: dict[str, str]) -> bool:
        return str(cdk.get("reuse_policy") or "").strip().lower() == "after_paid"

    def mark_remaining_unsubmitted(pending_accounts: list[dict[str, Any]], reason: str) -> None:
        nonlocal skipped_count
        while pending_accounts:
            item = pending_accounts.pop(0)
            skipped_count += 1
            _log(task_id, f"[UNSUBMITTED][PIX] {item.get('email') or item.get('account_id')} - {reason}")
            append_result(
                account_id=item["account_id"],
                email=item.get("email"),
                cdk_id=0,
                code_masked="PIX CDK",
                payment_channel="pix",
                status="unsubmitted",
                reason=reason,
            )

    _log(
        task_id,
        f"[PIX] {'上传已保存链接' if use_saved_pix_link else '自动提链'}任务启动: "
        f"候选 {len(pairs)} 个，CDK {len(pix_cdks)} 个，目标成功 {target_success_count} 个，"
        f"提交间隔 {submit_interval_seconds}s，轮询间隔 {status_poll_interval_seconds}s",
    )
    for missing_id in missing_ids:
        _log(task_id, f"[MISS] 账号不存在: account_id={missing_id}")
        errors.append(f"account_id={missing_id}: 账号不存在")
    for item in skipped_accounts:
        _log(task_id, f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - {item.get('reason') or '已跳过'}")

    pending_accounts = [dict(pair) for pair in pairs]
    available_cdks = [item for item in pix_cdks if bool(item.get("can_submit"))]
    for item in pix_cdks:
        if not bool(item.get("can_submit")):
            message = str(item.get("preflight_message") or item.get("preflight_state") or "预检不允许提交")
            _log(task_id, f"[PREFLIGHT][SKIP] {item.get('label') or 'PIX CDK'} - {safe_text(message)}")
    active_orders: list[dict[str, Any]] = []
    stop_new_submissions = False
    attempt_id: int | None = None
    try:
        attempt_id = _claim_next_task_attempt(control)
        while pending_accounts or active_orders:
            control.checkpoint(attempt_id=attempt_id)
            if control.is_stop_after_current_requested() and pending_accounts:
                stop_new_submissions = True
                mark_remaining_unsubmitted(
                    pending_accounts,
                    "已请求完成当前后停止；不再预留 CDK 或提交新的 PIX 订单",
                )
            target_reached = target_success_count > 0 and success_count >= target_success_count
            if target_reached and pending_accounts:
                mark_remaining_unsubmitted(
                    pending_accounts,
                    f"已达到本次目标成功数量 {target_success_count}，停止继续提交新账号",
                )
            if stop_new_submissions and pending_accounts:
                mark_remaining_unsubmitted(pending_accounts, "失败后继续已关闭，停止后续 PIX 提交")
            if pending_accounts and not active_orders and not available_cdks:
                mark_remaining_unsubmitted(pending_accounts, "没有可继续使用的 PIX CDK")

            # A target count is a submit window: do not create more in-flight
            # PIX tasks than can still contribute to the target.
            while pending_accounts and available_cdks and not stop_new_submissions and not target_reached:
                if control.is_stop_after_current_requested():
                    stop_new_submissions = True
                    mark_remaining_unsubmitted(
                        pending_accounts,
                        "已请求完成当前后停止；不再预留 CDK 或提交新的 PIX 订单",
                    )
                    break
                if target_success_count > 0 and len(active_orders) >= max(target_success_count - success_count, 0):
                    break
                control.checkpoint(attempt_id=attempt_id)
                item = pending_accounts[0]
                account_id = int(item.get("account_id") or 0)
                email = str(item.get("email") or "")
                if not primary_email and email:
                    primary_email = email
                with Session(engine) as session:
                    account = session.get(AccountModel, account_id)
                    if account is None or account.platform != "chatgpt":
                        account = None
                        token = ""
                        pix_pay_link = ""
                        skip_reason = "账号不存在或非 ChatGPT"
                    else:
                        skip_reason = "" if use_saved_pix_link else _idea_submit_unavailable_reason(account)
                        if use_saved_pix_link:
                            token = ""
                            pix_pay_link, link_reason = _saved_stripe_pix_user_link(account)
                            if not skip_reason and link_reason:
                                skip_reason = link_reason
                        else:
                            pix_pay_link = ""
                            token = "" if skip_reason else _chatgpt_account_access_token(account)
                            if not skip_reason and not token:
                                skip_reason = "账号缺少 Access Token"
                if skip_reason:
                    pending_accounts.pop(0)
                    skipped_count += 1
                    _log(task_id, f"[UNSUBMITTED][PIX] {email or account_id} - {skip_reason}")
                    append_result(
                        account_id=account_id,
                        email=email,
                        cdk_id=0,
                        code_masked="PIX CDK",
                        payment_channel="pix",
                        status="unsubmitted",
                        reason=skip_reason,
                    )
                    continue

                if pix_pay_link:
                    sensitive_pix_links.add(pix_pay_link)

                cdk = available_cdks.pop(0)
                if control.is_stop_after_current_requested():
                    # No reservation was made yet.  Restore the in-memory
                    # candidate and leave the account for the unsubmitted
                    # drain record below.
                    available_cdks.insert(0, cdk)
                    stop_new_submissions = True
                    mark_remaining_unsubmitted(
                        pending_accounts,
                        "已请求完成当前后停止；不再预留 CDK 或提交新的 PIX 订单",
                    )
                    break
                if not acquire_cdk_lease(cdk, account_id):
                    _log(task_id, f"[SKIP][PIX] {cdk['label']} 已成功核销、处理中或待复核，跳过该 CDK")
                    continue
                if control.is_stop_after_current_requested():
                    # The reservation is task-local and no upstream call has
                    # happened, so release it before recording this account
                    # as deliberately unsubmitted.
                    release_cdk(cdk, account_id, reusable=True, requeue=True)
                    stop_new_submissions = True
                    mark_remaining_unsubmitted(
                        pending_accounts,
                        "已请求完成当前后停止；不再预留 CDK 或提交新的 PIX 订单",
                    )
                    break
                pending_accounts.pop(0)
                _log(task_id, f"[PIX] 提交上游: {email or account_id}")
                try:
                    if control.is_stop_after_current_requested():
                        pending_accounts.insert(0, item)
                        release_cdk(cdk, account_id, reusable=True, requeue=True)
                        stop_new_submissions = True
                        mark_remaining_unsubmitted(
                            pending_accounts,
                            "已请求完成当前后停止；不再预留 CDK 或提交新的 PIX 订单",
                        )
                        break
                    if use_saved_pix_link:
                        submit_result = client.submit_pix_user_link(
                            pix_cdk=cdk["code"],
                            pix_pay_link=pix_pay_link,
                        )
                    else:
                        submit_result = client.submit_pix(pix_cdk=cdk["code"], access_token=token)
                    if not bool(submit_result.get("ok")):
                        reason = safe_text(submit_result.get("message") or "PIX 上游提交失败")
                        unknown = bool(submit_result.get("submission_unknown"))
                        if unknown:
                            timeout_count += 1
                            errors.append(f"{email or account_id}: {reason}")
                            persist_account_state(
                                account_id,
                                status="timeout",
                                reason=reason,
                            )
                            _log(task_id, f"[TIMEOUT][PIX] {email or account_id} - {reason}")
                            append_result(
                                account_id=account_id,
                                email=email,
                                cdk_id=0,
                                code_masked=cdk["label"],
                                payment_channel="pix",
                                status="timeout",
                                reason=reason,
                            )
                            lock_cdk_for_review(cdk, account_id)
                        else:
                            link_already_submitted = use_saved_pix_link and _is_saved_pix_user_link_already_submitted_reason(reason)
                            if link_already_submitted:
                                mark_saved_pix_link_submitted(account_id, pix_pay_link, duplicate=True)
                                reason = PIX_SAVED_LINK_SUBMITTED_REASON
                            errors.append(f"{email or account_id}: {reason}")
                            should_mark_unavailable = (
                                not use_saved_pix_link
                                and _is_idea_account_unavailable_reason(reason)
                            )
                            persist_account_state(
                                account_id,
                                status="failed",
                                reason=reason,
                                mark_unavailable=should_mark_unavailable,
                            )
                            _log(task_id, f"[FAIL][PIX] {email or account_id} - {reason}")
                            append_result(
                                account_id=account_id,
                                email=email,
                                cdk_id=0,
                                code_masked=cdk["label"],
                                payment_channel="pix",
                                status="failed",
                                reason=reason,
                                idea_marked_unavailable=should_mark_unavailable,
                            )
                            terminal_cdk_error = cdk_error_is_terminal(reason)
                            capacity_exhausted = cdk_error_is_capacity_exhausted(reason)
                            release_cdk(
                                cdk,
                                account_id,
                                reusable=not terminal_cdk_error,
                                requeue=(
                                    failure_continue
                                    and not terminal_cdk_error
                                    and not capacity_exhausted
                                ),
                            )
                            if capacity_exhausted:
                                _log(task_id, f"[PIX] {cdk['label']} 本站余额不足，本轮停止使用该卡；充值后可再次提交")
                        if not failure_continue:
                            stop_new_submissions = True
                        continue
                    remote_reuse_policy = str(submit_result.get("cdk_reuse_policy") or "").strip().lower()
                    if (
                        not bool(cdk.get("preflight_required"))
                        and remote_reuse_policy in {"after_paid", "one_success"}
                    ):
                        cdk["reuse_policy"] = remote_reuse_policy
                    submitted_count += 1
                    order_id = str(submit_result.get("order_id") or submit_result.get("task_id") or "").strip()
                    display_id = str(submit_result.get("display_id") or order_id).strip()
                    status_token = str(submit_result.get("status_token") or "").strip()
                    if not order_id or not status_token:
                        raise BaxiGptRequestError("PIX 上游未返回完整轮询凭据", request_outcome_unknown=True)
                    if use_saved_pix_link:
                        mark_saved_pix_link_submitted(account_id, pix_pay_link)
                    persist_account_state(
                        account_id,
                        status="submitted",
                        order_id=order_id,
                        display_id=display_id,
                    )
                    append_result(
                        account_id=account_id,
                        email=email,
                        cdk_id=0,
                        code_masked=cdk["label"],
                        payment_channel="pix",
                        status="submitted",
                        order_id=order_id,
                        display_id=display_id,
                    )
                    active_orders.append(
                        {
                            "account_id": account_id,
                            "email": email,
                            "order_id": order_id,
                            "display_id": display_id,
                            "status_token": status_token,
                            "cdk": cdk,
                            "history_only": bool(cdk.get("task_lease")),
                            "submitted_at": time.time(),
                            "timeout_warned": False,
                        }
                    )
                    if bool(cdk.get("task_lease")):
                        # The upstream has already atomically consumed one
                        # site-CDK unit. Keep the task lease and immediately
                        # make the next exact-capacity unit available; paid
                        # status is intentionally not a prerequisite.
                        cdk["available_uses"] = max(int(cdk.get("available_uses") or 0) - 1, 0)
                        if (
                            cdk["available_uses"] > 0
                            and not control.is_stop_after_current_requested()
                            and not (target_success_count > 0 and len(active_orders) >= max(target_success_count - success_count, 0))
                            and cdk not in available_cdks
                        ):
                            available_cdks.append(cdk)
                    _log(task_id, f"[PIX] 上游已受理: {email or account_id} task={display_id}")
                    if pending_accounts and submit_interval_seconds > 0:
                        wait_with_control(submit_interval_seconds, attempt_id)
                except BaxiGptRequestError as exc:
                    reason = safe_text(exc)
                    if bool(exc.request_outcome_unknown) or int(getattr(exc, "http_status", 0) or 0) >= 500:
                        timeout_count += 1
                        reason = "PIX 上游提交结果未知，请按账号人工复核；系统未自动重投"
                        errors.append(f"{email or account_id}: {reason}")
                        persist_account_state(
                            account_id,
                            status="timeout",
                            reason=reason,
                        )
                        _log(task_id, f"[TIMEOUT][PIX] {email or account_id} - {reason}")
                        append_result(
                            account_id=account_id,
                            email=email,
                            cdk_id=0,
                            code_masked=cdk["label"],
                            payment_channel="pix",
                            status="timeout",
                            reason=reason,
                        )
                        lock_cdk_for_review(cdk, account_id)
                    else:
                        link_already_submitted = use_saved_pix_link and _is_saved_pix_user_link_already_submitted_reason(reason)
                        if link_already_submitted:
                            mark_saved_pix_link_submitted(account_id, pix_pay_link, duplicate=True)
                            reason = PIX_SAVED_LINK_SUBMITTED_REASON
                        errors.append(f"{email or account_id}: {reason}")
                        should_mark_unavailable = (
                            not use_saved_pix_link
                            and _is_idea_account_unavailable_reason(reason)
                        )
                        persist_account_state(
                            account_id,
                            status="failed",
                            reason=reason,
                            mark_unavailable=should_mark_unavailable,
                        )
                        _log(task_id, f"[FAIL][PIX] {email or account_id} - {reason}")
                        append_result(
                            account_id=account_id,
                            email=email,
                            cdk_id=0,
                            code_masked=cdk["label"],
                            payment_channel="pix",
                            status="failed",
                            reason=reason,
                            idea_marked_unavailable=should_mark_unavailable,
                        )
                        terminal_cdk_error = cdk_error_is_terminal(reason)
                        capacity_exhausted = cdk_error_is_capacity_exhausted(reason)
                        release_cdk(
                            cdk,
                            account_id,
                            reusable=not terminal_cdk_error,
                            requeue=(
                                failure_continue
                                and not terminal_cdk_error
                                and not capacity_exhausted
                            ),
                        )
                        if capacity_exhausted:
                            _log(task_id, f"[PIX] {cdk['label']} 本站余额不足，本轮停止使用该卡；充值后可再次提交")
                    if not failure_continue:
                        stop_new_submissions = True
                except Exception as exc:
                    reason = safe_text(exc or "PIX 提交失败")
                    errors.append(f"{email or account_id}: {reason}")
                    # An untyped exception may have happened after the request
                    # left this process; keep this CDK locked rather than risk
                    # a duplicate charge.
                    persist_account_state(
                        account_id,
                        status="failed",
                        reason=reason,
                        mark_unavailable=False,
                    )
                    _log(task_id, f"[FAIL][PIX] {email or account_id} - {reason}")
                    append_result(
                        account_id=account_id,
                        email=email,
                        cdk_id=0,
                        code_masked=cdk["label"],
                        payment_channel="pix",
                        status="failed",
                        reason=reason,
                        idea_marked_unavailable=False,
                    )
                    lock_cdk_for_review(cdk, account_id)
                    if not failure_continue:
                        stop_new_submissions = True

            if not active_orders:
                continue
            _log(task_id, f"[PIX] 等待上游处理结果: 当前轮询 {len(active_orders)} 个任务")
            wait_with_control(status_poll_interval_seconds, attempt_id)
            still_active: list[dict[str, Any]] = []
            for order in active_orders:
                control.checkpoint(attempt_id=attempt_id)
                account_id = int(order["account_id"])
                email = str(order.get("email") or "")
                order_id = str(order["order_id"])
                display_id = str(order.get("display_id") or order_id)
                status_token = str(order["status_token"])
                cdk = order.get("cdk") if isinstance(order.get("cdk"), dict) else {}
                try:
                    status_result = client.pix_status(task_id=order_id, status_token=status_token)
                except BaxiGptRequestError as exc:
                    _log(task_id, f"[WAIT][PIX] {email or account_id} 状态查询异常，继续等待: {safe_text(exc, status_token)}")
                    still_active.append(order)
                    continue
                if not bool(status_result.get("ok")):
                    still_active.append(order)
                    continue
                status_value = _normalize_idea_submit_result_status(status_result.get("status"))
                reason = safe_text(status_result.get("message"), status_token)
                if status_value == "paid":
                    paid_usage_recorded = False
                    try:
                        if bool(order.get("history_only")):
                            _pix_cdk_usage_store.record_paid_history(
                                cdk["fingerprint"],
                                task_id=task_id,
                                account_id=account_id,
                                order_id=order_id,
                            )
                        else:
                            _pix_cdk_usage_store.mark_paid(
                                cdk["fingerprint"],
                                task_id=task_id,
                                account_id=account_id,
                                order_id=order_id,
                                retain_block=not cdk_reuse_after_paid(cdk),
                                reservation_account_id=cdk_owner_account_id(cdk, account_id),
                            )
                            # Legacy after-paid CDKs release the reservation
                            # as part of mark_paid; the next use must acquire a
                            # fresh task lease before submitting.
                            cdk["lease_held"] = False
                        paid_usage_recorded = True
                    except Exception as exc:
                        # The upstream is already paid. Keep this CDK locked
                        # instead of creating a reuse opportunity on a DB hiccup.
                        lock_cdk_for_review(cdk, account_id, order_id=order_id)
                        _log(task_id, f"[PIX][WARN] 成功 CDK 核销登记异常: {safe_text(exc)}")
                    success_count += 1
                    local_status_summary = refresh_paid_account_local_status(account_id, order_id, display_id)
                    _log(task_id, f"[OK][PIX] 开通成功: {email or account_id} task={display_id}")
                    append_result(
                        account_id=account_id,
                        email=email,
                        cdk_id=0,
                        code_masked=str(cdk.get("label") or "PIX CDK"),
                        payment_channel="pix",
                        status="paid",
                        order_id=order_id,
                        display_id=display_id,
                        local_status_refresh=local_status_summary,
                    )
                    # Legacy after-paid cards reserve again only after a durable
                    # paid write. Exact-capacity site cards already submitted
                    # their whole window under one task lease; external cards
                    # keep their one-success blocked row.
                    if (
                        paid_usage_recorded
                        and not bool(order.get("history_only"))
                        and cdk_reuse_after_paid(cdk)
                        and not control.is_stop_after_current_requested()
                        and not (target_success_count > 0 and success_count >= target_success_count)
                    ):
                        available_cdks.append(cdk)
                elif status_value == "failed":
                    reason = reason or "PIX 上游处理失败"
                    errors.append(f"{email or account_id}: {reason}")
                    should_mark_unavailable = (
                        not use_saved_pix_link
                        and _is_idea_account_unavailable_reason(reason)
                    )
                    persist_account_state(
                        account_id,
                        status="failed",
                        order_id=order_id,
                        display_id=display_id,
                        reason=reason,
                        mark_unavailable=should_mark_unavailable,
                    )
                    _log(task_id, f"[FAIL][PIX] {email or account_id} - {reason}")
                    append_result(
                        account_id=account_id,
                        email=email,
                        cdk_id=0,
                        code_masked=str(cdk.get("label") or "PIX CDK"),
                        payment_channel="pix",
                        status="failed",
                        order_id=order_id,
                        display_id=display_id,
                        reason=reason,
                        idea_marked_unavailable=should_mark_unavailable,
                    )
                    terminal_cdk_error = cdk_error_is_terminal(reason)
                    capacity_exhausted = cdk_error_is_capacity_exhausted(reason)
                    release_cdk(
                        cdk,
                        account_id,
                        reusable=not terminal_cdk_error,
                        requeue=(
                            failure_continue
                            and not terminal_cdk_error
                                and not capacity_exhausted
                            ),
                        exclude_order_id=order_id,
                    )
                    if capacity_exhausted:
                        _log(task_id, f"[PIX] {cdk['label']} 本站余额不足，本轮停止使用该卡；充值后可再次提交")
                    if not failure_continue:
                        stop_new_submissions = True
                elif time.time() - float(order["submitted_at"]) > IDEA_SUBMIT_HARD_POLL_TIMEOUT_SECONDS:
                    timeout_count += 1
                    reason = "超过 24 小时仍未返回终态，请按上游任务 ID 人工复核"
                    errors.append(f"{email or account_id}: {reason}")
                    persist_account_state(
                        account_id,
                        status="timeout",
                        order_id=order_id,
                        display_id=display_id,
                        reason=reason,
                    )
                    _log(task_id, f"[TIMEOUT][PIX] {email or account_id} task={display_id}")
                    append_result(
                        account_id=account_id,
                        email=email,
                        cdk_id=0,
                        code_masked=str(cdk.get("label") or "PIX CDK"),
                        payment_channel="pix",
                        status="timeout",
                        order_id=order_id,
                        display_id=display_id,
                        reason=reason,
                    )
                    lock_cdk_for_review(cdk, account_id, order_id=order_id)
                else:
                    if time.time() - float(order["submitted_at"]) > status_poll_timeout_seconds and not order.get("timeout_warned"):
                        order["timeout_warned"] = True
                        _log(
                            task_id,
                            f"[WAIT][PIX] {email or account_id} task={display_id} 已等待 {status_poll_timeout_seconds}s，继续轮询",
                        )
                    still_active.append(order)
            active_orders = still_active
            _task_store.set_progress(task_id, f"{success_count}/{total}")

        release_idle_cdk_leases(include_external=True)
        sync_meta()
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        summary = latest_meta.get("idea_submit_summary") if isinstance(latest_meta.get("idea_submit_summary"), dict) else {}
        success_accounts = list(summary.get("success_accounts") or [])
        failed_accounts = list(summary.get("failed_accounts") or [])
        timeout_accounts = list(summary.get("timeout_accounts") or [])
        unsubmitted_accounts = list(summary.get("unsubmitted_accounts") or [])
        summary_message = (
            "PIX 提交完成: "
            f"候选 {summary.get('total_accounts', len(pairs))} 个，上游已受理 {submitted_count} 个，"
            f"开通成功 {len(success_accounts)} 个，失败 {len(failed_accounts)} 个，"
            f"超时 {len(timeout_accounts)} 个，未提交 {len(unsubmitted_accounts)} 个"
        )
        if failed_accounts:
            summary_message = f"{summary_message}；首个失败: {_idea_submit_log_item_text(failed_accounts[0])}"
        elif timeout_accounts:
            summary_message = f"{summary_message}；存在需人工复核的账号"
        _log(task_id, f"[SUMMARY] {summary_message}")
        _log_idea_submit_group_summary(task_id, "成功账号", success_accounts)
        _log_idea_submit_group_summary(task_id, "失败账号", failed_accounts)
        _log_idea_submit_group_summary(task_id, "超时账号", timeout_accounts)
        _log_idea_submit_group_summary(task_id, "未提交账号", unsubmitted_accounts)

        failed_total = int(summary.get("failed") or 0)
        timeout_total = int(summary.get("timeout") or 0)
        unsubmitted_total = int(summary.get("unsubmitted") or 0)
        target_completed = target_success_count > 0 and success_count >= target_success_count
        log_status = "success" if target_completed and timeout_total == 0 else "failed"
        finish_error = "" if log_status == "success" else summary_message
        _task_store.finish(
            task_id,
            status="done" if log_status == "success" else "failed",
            success=success_count,
            skipped=unsubmitted_total,
            errors=errors,
            error=finish_error,
        )
        terminal_status = str(_task_store.snapshot(task_id).get("status") or log_status)
        _save_task_log(
            "chatgpt",
            primary_email,
            terminal_status,
            error=finish_error,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "pix_submit_success" if log_status == "success" else "pix_submit_failed",
                    "source": "baxigpt_cdk_submit",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                    "runtime_results": list(runtime_results),
                    "idea_submit_summary": summary,
                },
            ),
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP][PIX] {exc}")
        sync_meta()
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error=str(exc),
        )
    except Exception as exc:
        error_text = safe_text(exc or "PIX 提交任务异常")
        errors.append(error_text)
        _log(task_id, f"[FAIL][PIX] 任务异常: {error_text}")
        sync_meta()
        _task_store.finish(
            task_id,
            status="failed",
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error=error_text,
        )
        _save_task_log(
            "chatgpt",
            primary_email,
            "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "pix_submit_failed",
                    "source": "baxigpt_cdk_submit",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                    "runtime_results": list(runtime_results),
                },
            ),
        )
    finally:
        for order in active_orders:
            cdk = order.get("cdk") if isinstance(order.get("cdk"), dict) else {}
            if cdk:
                lock_cdk_for_review(
                    cdk,
                    int(order.get("account_id") or 0),
                    order_id=str(order.get("order_id") or ""),
                )
        release_idle_cdk_leases(include_external=True)
        if attempt_id is not None:
            control.finish_attempt(attempt_id)
        _clear_task_current(task_id)
        _task_store.cleanup()


def _run_baxigpt_cdk_submit(task_id: str, pairs: list[dict[str, Any]], settings: dict[str, Any]):
    from services.chatgpt_core.baxigpt_cdk_repository import BaxiGptCdkRepository, STATUS_PAID
    from services.chatgpt_core.baxigpt_client import BaxiGptClient

    control = _task_store.control_for(task_id)
    repo = BaxiGptCdkRepository()
    client = BaxiGptClient()
    requested_target_success_count = max(int(settings.get("target_success_count") or 0), 0)
    target_success_count = min(requested_target_success_count, len(pairs)) if requested_target_success_count > 0 else 0
    total = max(target_success_count or len(pairs), 1)
    submitted_count = 0
    success_count = 0
    timeout_count = 0
    skipped_count = 0
    errors: list[str] = []
    runtime_results: list[dict[str, Any]] = []
    primary_email = ""
    precheck = _is_truthy(settings.get("precheck"))
    failure_continue = _is_truthy(settings.get("failure_continue"))
    submit_interval_seconds = max(int(settings.get("submit_interval_seconds") or 0), 0)
    auto_poll_status = settings.get("auto_poll_status") is None or _is_truthy(settings.get("auto_poll_status"))
    status_poll_interval_seconds = max(int(settings.get("status_poll_interval_seconds") or 5), 1)
    status_poll_timeout_seconds = max(
        int(settings.get("status_poll_timeout_seconds") or IDEA_SUBMIT_DEFAULT_POLL_WARNING_SECONDS),
        status_poll_interval_seconds,
        IDEA_SUBMIT_DEFAULT_POLL_WARNING_SECONDS,
    )

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    missing_ids = list(meta.get("missing_ids") or [])
    skipped_accounts = list(meta.get("skipped_accounts") or [])

    def sync_meta() -> None:
        summary = _build_idea_submit_runtime_summary(
            pairs=pairs,
            missing_ids=missing_ids,
            skipped_accounts=skipped_accounts,
            runtime_results=runtime_results,
            submitted_count=submitted_count,
            target_success_count=target_success_count,
            errors=errors,
        )
        _task_store.update_meta(
            task_id,
            {
                "runtime_results": list(runtime_results),
                "runtime_submitted": submitted_count,
                "runtime_success": success_count,
                "runtime_timeout": timeout_count,
                "runtime_skipped": skipped_count,
                "runtime_errors": list(errors),
                "idea_submit_summary": summary,
            },
        )

    def wait_before_next(index: int, attempt_id: int | None = None) -> None:
        if index >= len(pairs) or submit_interval_seconds <= 0:
            return
        _log(task_id, f"[Idea] 等待提交间隔 {submit_interval_seconds}s 后继续下一个账号")
        remaining = float(submit_interval_seconds)
        while remaining > 0:
            control.checkpoint(attempt_id=attempt_id)
            chunk = min(1.0, remaining)
            time.sleep(chunk)
            remaining -= chunk

    def append_result(**payload: Any) -> None:
        runtime_results.append(
            {
                "finished_at": beijing_now_iso(),
                **payload,
            }
        )
        sync_meta()

    def mark_remaining_unsubmitted(reason: str) -> None:
        """Drain accounts that have not entered an upstream Idea order."""
        nonlocal skipped_count
        while pending_accounts:
            item = pending_accounts.pop(0)
            skipped_count += 1
            _log(task_id, f"[UNSUBMITTED] 未提交账号: {item.get('email')} - {reason}")
            append_result(
                account_id=item["account_id"],
                email=item.get("email"),
                cdk_id=item.get("last_cdk_id") or item.get("cdk_id"),
                code_masked=item.get("last_code_masked"),
                status="unsubmitted",
                reason=reason,
            )

    def log_debug(message: str) -> None:
        _log(task_id, f"[DEBUG][Idea] {message}")

    def response_brief(response: dict[str, Any] | None, *, keys: tuple[str, ...] = ()) -> dict[str, Any]:
        data = response if isinstance(response, dict) else {}
        selected = keys or (
            "ok",
            "status",
            "status_code",
            "remaining",
            "total",
            "used",
            "order_id",
            "display_id",
            "email",
            "message",
            "msg",
            "error",
            "detail",
        )
        return {key: data.get(key) for key in selected if key in data}

    def upstream_message(response: dict[str, Any] | None, fallback: str = "上游返回失败") -> str:
        data = response if isinstance(response, dict) else {}
        for key in ("message", "msg", "error", "detail", "reason"):
            text = str(data.get(key) or "").strip()
            if text:
                return text
        return fallback

    def refresh_paid_account_local_status(
        account_id: int,
        record: Any,
        *,
        order_id: str,
        display_id: str,
    ) -> dict[str, Any] | None:
        """上游 paid 后以本地 ChatGPT 状态刷新为唯一账号状态来源。

        卡密记录本身仍然记为 paid；账号主状态不再由外部 paid 标记直接改成
        subscribed，而是由 sync_chatgpt_account_local_status 的探测结果统一写入。
        """
        with Session(engine) as session:
            acc = session.get(AccountModel, int(account_id or 0))
            if acc is None or acc.platform != "chatgpt":
                _log(task_id, f"[Idea][WARN] paid 后本地状态刷新跳过: 未找到 ChatGPT 账号 account_id={account_id}")
                return None
            _log(task_id, f"[Idea] paid 已确认，开始刷新本地账号状态: {acc.email or acc.id}")
            refresh_ok = True
            try:
                refresh_result = sync_chatgpt_account_local_status(session, acc)
                summary = summarize_status_refresh(refresh_result, trigger="baxigpt_cdk_paid")
            except Exception as exc:
                refresh_ok = False
                summary = {
                    "trigger": "baxigpt_cdk_paid",
                    "refreshed_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                    "status": str(getattr(acc, "status", "") or ""),
                    "error": str(exc),
                }
            repo.persist_account_binding_extra(
                acc,
                record,
                status=STATUS_PAID,
                order_id=order_id,
                display_id=display_id,
                local_status_refresh=summary,
                apply_payment_state=False,
            )
            session.add(acc)
            session.commit()
            if refresh_ok:
                _log(
                    task_id,
                    "[Idea] 本地状态刷新完成: "
                    f"{acc.email or acc.id} "
                    f"status={summary.get('status') or '-'} "
                    f"plan={summary.get('subscription_plan') or '-'} "
                    f"auth={summary.get('auth_state') or '-'} "
                    f"gate={summary.get('upload_gate') or '-'}",
                )
            else:
                _log(task_id, f"[Idea][WARN] paid 后本地状态刷新失败，已写入失败摘要: {acc.email or acc.id} - {summary.get('error')}")
            return summary

    try:
        log_debug(
            "task settings: "
            f"pairs={len(pairs)} precheck={precheck} failure_continue={failure_continue} "
            f"submit_interval={submit_interval_seconds}s auto_poll={auto_poll_status} "
            f"poll_interval={status_poll_interval_seconds}s poll_warn={status_poll_timeout_seconds}s "
            f"target_success={target_success_count or 'all'} "
            f"code_source={meta.get('code_source') or '-'}"
        )
        for missing_id in missing_ids:
            _log(task_id, f"[MISS] 账号不存在: account_id={missing_id}")
            errors.append(f"account_id={missing_id}: 账号不存在")

        for item in skipped_accounts:
            _log(task_id, f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - {item.get('reason') or '已跳过'}")

        for index, pair in enumerate(pairs, start=1):
            email = str(pair.get("email") or "")
            if not primary_email and email:
                primary_email = email

        # 1. 提取去重的候选账号与卡密
        pending_accounts: list[dict[str, Any]] = []
        seen_acc_ids = set()
        for p in pairs:
            aid = int(p.get("account_id") or 0)
            if aid and aid not in seen_acc_ids:
                seen_acc_ids.add(aid)
                pending_accounts.append({"account_id": aid, "email": str(p.get("email") or ""), "cdk_id": int(p.get("cdk_id") or 0), "manual_code": bool(p.get("manual_code"))})

        candidate_cdk_ids = []
        for p in pairs:
            cid = int(p.get("cdk_id") or 0)
            if cid and cid not in candidate_cdk_ids:
                candidate_cdk_ids.append(cid)

        # 2. 预查卡密获取真实可用额度
        active_cdks: dict[int, dict[str, Any]] = {}
        unavailable_cdk_reasons: list[str] = []
        for cid in candidate_cdk_ids:
            control.checkpoint()
            if control.is_stop_after_current_requested():
                break
            rec = repo.get_by_id(cid)
            if not rec:
                _log(task_id, f"[SKIP] 卡密不存在: cdk_id={cid}")
                continue
            _log(task_id, f"[Idea] 预查卡密: {rec.code_masked}")
            try:
                info = client.code_info(rec.code_value)
                log_debug(f"code-info response {rec.code_masked}: {response_brief(info)}")
                repo.mark_code_info(rec.id, info)
                ok = bool(info.get("ok"))
                rem = int(info.get("remaining") or 0) if "remaining" in info else 0
                if not ok or ("remaining" in info and rem <= 0):
                    err_msg = upstream_message(info, f"卡密不可用 remaining={rem}")
                    _log(task_id, f"[SKIP] 卡密不可用: {rec.code_masked} ({err_msg})")
                    repo.mark_failure(rec.id, error_code="code_info_failed", error_message=err_msg, response=info)
                    reason = f"卡密 {rec.code_masked} 不可用: {err_msg}"
                    unavailable_cdk_reasons.append(reason)
                    errors.append(reason)
                    continue
                cap = rem if rem > 0 else max(len(pending_accounts), 1)
                _log(task_id, f"[Idea] 卡密可用: {rec.code_masked} | 可用额度={cap} 总额度={info.get('total', cap)}")
                active_cdks[rec.id] = {"record": rec, "remaining": cap}
            except Exception as exc:
                _log(task_id, f"[WARN] 预查卡密异常: {rec.code_masked} ({exc})")
                active_cdks[rec.id] = {"record": rec, "remaining": max(len(pending_accounts), 1)}

        if not active_cdks and unavailable_cdk_reasons:
            # 原先这里最终只会显示“额度不足”，把上游明确的禁用原因吞掉，
            # 运营看起来就像卡密池/粘贴都没有被读取。
            reason = unavailable_cdk_reasons[0]
            for account in pending_accounts:
                account["last_unsubmitted_reason"] = reason

        # 3. 逐一提交与处理结果轮询 (完全模拟单账号提交与动态查额度)
        active_orders: list[dict[str, Any]] = []
        stop_new_submissions = False
        attempt_id = _claim_next_task_attempt(control)
        def target_reached() -> bool:
            return target_success_count > 0 and success_count >= target_success_count

        def submit_window_full() -> bool:
            if target_success_count <= 0:
                return False
            remaining_needed = max(target_success_count - success_count, 0)
            return len(active_orders) >= remaining_needed

        try:
            while pending_accounts or active_orders:
                control.checkpoint(attempt_id=attempt_id)

                if control.is_stop_after_current_requested() and pending_accounts:
                    stop_new_submissions = True
                    mark_remaining_unsubmitted("已请求完成当前后停止；不再预查卡密或提交新的 Idea 订单")

                if target_reached():
                    if pending_accounts:
                        reason = f"已达到本次目标成功数量 {target_success_count}，停止继续提交新账号"
                        for pa in pending_accounts:
                            skipped_count += 1
                            _log(task_id, f"[UNSUBMITTED] 未提交账号: {pa.get('email')} - {reason}")
                            append_result(
                                account_id=pa["account_id"],
                                email=pa.get("email"),
                                cdk_id=pa.get("last_cdk_id"),
                                code_masked=pa.get("last_code_masked"),
                                status="unsubmitted",
                                reason=reason,
                            )
                        pending_accounts.clear()
                    if not active_orders:
                        break
                
                # 1. 逐一提交 (完全模拟单账号提交与动态查额度)
                if pending_accounts and not stop_new_submissions and not target_reached():
                    last_pending_count = -1
                    # 在进入轮询前，尽可能把本轮能提交的全部提交完
                    while pending_accounts and len(pending_accounts) != last_pending_count and not target_reached() and not submit_window_full():
                        last_pending_count = len(pending_accounts)
                        unassignable_accounts = []
                        deferred_for_target_window = False
                        
                        while pending_accounts:
                            control.checkpoint(attempt_id=attempt_id)
                            if control.is_stop_after_current_requested():
                                stop_new_submissions = True
                                mark_remaining_unsubmitted("已请求完成当前后停止；不再预查卡密或提交新的 Idea 订单")
                                break
                            if target_reached():
                                break
                            if submit_window_full():
                                deferred_for_target_window = True
                                break
                            acc_item = pending_accounts[0]
                            
                            assigned_cdk = None
                            for cid, cdk_data in list(active_cdks.items()):
                                rec = cdk_data["record"]
                                try:
                                    if control.is_stop_after_current_requested():
                                        stop_new_submissions = True
                                        break
                                    log_debug(f"提交前查验卡密: {rec.code_masked}")
                                    info = client.code_info(rec.code_value)
                                    ok = bool(info.get("ok"))
                                    real_rem = int(info.get("remaining") or 0) if "remaining" in info else 0
                                    if not ok or real_rem <= 0:
                                        cdk_data["remaining"] = 0
                                        continue
                                    
                                    cdk_data["remaining"] = real_rem
                                    assigned_cdk = cdk_data
                                    break
                                except Exception as exc:
                                    _log(task_id, f"[WARN] 提交前查验卡密异常: {rec.code_masked} ({exc})")
                                    cdk_data["remaining"] = 0
                                    continue
                                    
                            if stop_new_submissions:
                                mark_remaining_unsubmitted("已请求完成当前后停止；不再预查卡密或提交新的 Idea 订单")
                                break
                            if not assigned_cdk:
                                _log(task_id, f"[Idea] 卡密池已无可用额度，本轮剩余 {len(pending_accounts)} 个排队账号等待中...")
                                unassignable_accounts.extend(pending_accounts)
                                pending_accounts.clear()
                                break
                                
                            rec = assigned_cdk["record"]
                            pending_accounts.pop(0)
                            if control.is_stop_after_current_requested():
                                pending_accounts.insert(0, acc_item)
                                stop_new_submissions = True
                                mark_remaining_unsubmitted("已请求完成当前后停止；不再提交新的 Idea 订单")
                                break
                            
                            with Session(engine) as session:
                                acc = session.get(AccountModel, int(acc_item["account_id"]))
                                if not acc or acc.platform != "chatgpt":
                                    skipped_count += 1
                                    _log(task_id, f"[UNSUBMITTED] 账号不存在或非 ChatGPT，未提交到 Idea: {acc_item.get('email')}")
                                    append_result(account_id=acc_item["account_id"], email=acc_item.get("email"), cdk_id=rec.id, code_masked=rec.code_masked, status="unsubmitted", reason="账号不存在或非 ChatGPT")
                                    continue
                                token = _chatgpt_account_access_token(acc)
                                if not token:
                                    skipped_count += 1
                                    _log(task_id, f"[UNSUBMITTED] 账号缺少 Access Token，未提交到 Idea: {acc_item.get('email')}")
                                    append_result(account_id=acc_item["account_id"], email=acc_item.get("email"), cdk_id=rec.id, code_masked=rec.code_masked, status="unsubmitted", reason="账号缺少 Access Token")
                                    continue
                                    
                            _log(task_id, f"[Idea] 提交上游 (单行模式): 账号 {acc_item.get('email')} -> 卡密 {rec.code_masked}")
                            try:
                                if control.is_stop_after_current_requested():
                                    pending_accounts.insert(0, acc_item)
                                    stop_new_submissions = True
                                    mark_remaining_unsubmitted("已请求完成当前后停止；不再提交新的 Idea 订单")
                                    break
                                res = client.submit(code=rec.code_value, access_token=token)
                                log_debug(f"submit response {rec.code_masked}: {response_brief(res)}")
                                if not bool(res.get("ok")):
                                    err_msg = upstream_message(res, "上游提交失败")
                                    raise ValueError(err_msg)
                                    
                                assigned_cdk["remaining"] -= 1
                                
                                submitted_items = res.get("submitted_items") or []
                                sub_info = submitted_items[0] if submitted_items else {"order_id": f"{rec.code_value}::fallback_0", "display_id": f"fallback_0", "status": "submitted"}
                                order_id = str(sub_info.get("order_id") or "")
                                display_id = str(sub_info.get("display_id") or "")
                                
                                reserved_record = repo.reserve_for_account(rec.id, account_id=acc_item["account_id"], email=acc_item["email"], task_id=task_id) or rec
                                submitted_record = repo.mark_submit_success(reserved_record.id, {
                                    "ok": True,
                                    "status": str(sub_info.get("status") or res.get("status") or "submitted"),
                                    "order_id": order_id,
                                    "display_id": display_id,
                                    "email": acc_item.get("email") or sub_info.get("email") or "",
                                    "raw_response": res,
                                }) or reserved_record
                                with Session(engine) as session:
                                    acc = session.get(AccountModel, acc_item["account_id"])
                                    if acc:
                                        repo.persist_account_binding_extra(acc, submitted_record)
                                        session.add(acc)
                                        session.commit()
                                        
                                submitted_count += 1
                                active_orders.append({
                                    "vb": {"item": acc_item, "account": acc, "token": token},
                                    "cdk_data": assigned_cdk,
                                    "record": submitted_record,
                                    "order_id": order_id,
                                    "display_id": display_id,
                                    "submitted_at": time.time(),
                                    "timeout_warned": False,
                                })
                                _log(task_id, f"[Idea] 账号 {acc_item.get('email')} 提交成功，已加入后台轮询队列")
                                
                                wait_before_next(1, attempt_id=attempt_id)
                                
                            except Exception as exc:
                                err_text = str(exc or "Idea 提交失败")
                                _log(task_id, f"[FAIL] 卡密 {rec.code_masked} 提交账号 {acc_item.get('email')} 失败: {err_text}")
                                assigned_cdk["remaining"] = 0
                                
                                if not failure_continue:
                                    _log(task_id, "[Idea] 失败后继续已关闭，停止后续提交")
                                    errors.append(f"卡密 {rec.code_masked} 提交失败: {err_text}")
                                    skipped_count += 1
                                    _log(task_id, f"[UNSUBMITTED] 未提交账号: {acc_item.get('email')} - {err_text}")
                                    append_result(
                                        account_id=acc_item["account_id"],
                                        email=acc_item.get("email"),
                                        cdk_id=rec.id,
                                        code_masked=rec.code_masked,
                                        status="unsubmitted",
                                        reason=err_text,
                                    )
                                    for item in pending_accounts:
                                        skipped_count += 1
                                        append_result(
                                            account_id=item["account_id"],
                                            email=item.get("email"),
                                            status="unsubmitted",
                                            reason="失败后继续已关闭，本轮未提交",
                                        )
                                    pending_accounts.clear()
                                    unassignable_accounts.clear()
                                    break
                                else:
                                    skipped_count += 1
                                    _log(task_id, f"[UNSUBMITTED] 提交失败，已跳过该账号避免重复刷屏: {acc_item.get('email')} - {err_text}")
                                    append_result(
                                        account_id=acc_item["account_id"],
                                        email=acc_item.get("email"),
                                        cdk_id=rec.id,
                                        code_masked=rec.code_masked,
                                        status="unsubmitted",
                                        reason=err_text,
                                    )
                                    
                        if deferred_for_target_window:
                            break
                        pending_accounts = unassignable_accounts

                # 2. 如果没有任何提交成功的任务正在处理，且也没待处理账号了，则结束
                if not active_orders:
                    if not pending_accounts:
                        break
                    elif target_reached():
                        reason = f"已达到本次目标成功数量 {target_success_count}，停止继续提交新账号"
                        for pa in pending_accounts:
                            skipped_count += 1
                            _log(task_id, f"[UNSUBMITTED] 未提交账号: {pa.get('email')} - {reason}")
                            append_result(
                                account_id=pa["account_id"],
                                email=pa.get("email"),
                                cdk_id=pa.get("last_cdk_id"),
                                code_masked=pa.get("last_code_masked"),
                                status="unsubmitted",
                                reason=reason,
                            )
                        pending_accounts.clear()
                        break
                    else:
                        # 也没有可用卡密额度了，剩余账号放弃
                        for pa in pending_accounts:
                            skipped_count += 1
                            reason = str(pa.get("last_unsubmitted_reason") or "可用卡密额度不足或连续失败")
                            _log(task_id, f"[UNSUBMITTED] 未提交账号: {pa.get('email')} - {reason}")
                            append_result(
                                account_id=pa["account_id"],
                                email=pa.get("email"),
                                cdk_id=pa.get("last_cdk_id"),
                                code_masked=pa.get("last_code_masked"),
                                status="unsubmitted",
                                reason=reason,
                            )
                        pending_accounts.clear()
                        break
                    
                _log(task_id, f"[Idea] 等待上游处理结果中，当前监控处理中订单: {len(active_orders)} 个 (轮询间隔: {status_poll_interval_seconds}s)...")
                _sleep_with_task_control(
                    control,
                    status_poll_interval_seconds,
                    attempt_id=attempt_id,
                )
                
                still_active = []
                for order in active_orders:
                    control.checkpoint(attempt_id=attempt_id)
                    vb = order["vb"]
                    cdk_data = order["cdk_data"]
                    rec = order.get("record") or cdk_data["record"]
                    order_id = order["order_id"]
                    
                    try:
                        st_res = client.status(order_id)
                        st_str = str(st_res.get("status") or "processing").lower()
                        err_msg = str(st_res.get("message") or "")
                    except Exception:
                        st_str = "processing"
                        err_msg = ""
                        
                    if st_str in {"paid", "success", "completed"}:
                        success_count += 1
                        cdk_data["remaining"] -= 1
                        _log(task_id, f"[OK] Idea 开通成功: {vb['item'].get('email')} -> {rec.code_masked} (order_id={order_id})")
                        paid_record = repo.mark_submit_success(rec.id, {"status": "paid", "order_id": order_id, "display_id": order["display_id"], "email": vb['item'].get('email')}) or rec
                        order["record"] = paid_record
                        local_status_summary = None
                        try:
                            local_status_summary = refresh_paid_account_local_status(
                                vb["item"]["account_id"],
                                paid_record,
                                order_id=order_id,
                                display_id=order["display_id"],
                            )
                        except Exception as refresh_exc:
                            _log(task_id, f"[Idea][WARN] paid 后本地状态刷新失败: {vb['item'].get('email')} (order_id={order_id}) - {refresh_exc}")
                        append_result(
                            account_id=vb["item"]["account_id"],
                            email=vb["item"].get("email"),
                            cdk_id=rec.id,
                            code_masked=rec.code_masked,
                            status="paid",
                            order_id=order_id,
                            display_id=order["display_id"],
                            local_status_refresh=local_status_summary,
                        )
                        
                    elif st_str in {"failed", "expired", "cancelled", "canceled", "invalid", "error"}:
                        err_text = err_msg or "Idea 上游处理失败"
                        _log(task_id, f"[FAIL] Idea 开通失败: {vb['item'].get('email')} -> {rec.code_masked} 原因: {err_text}")
                        errors.append(f"{vb['item'].get('email')}: {err_text}")
                        failed_record = repo.mark_status_response(rec.id, {
                            "ok": True,
                            "status": "failed",
                            "order_id": order_id,
                            "display_id": order["display_id"],
                            "email": vb["item"].get("email"),
                            "message": err_text,
                        }) or rec
                        order["record"] = failed_record
                        
                        # 1. 只有上游明确反馈账号无资格/需换号时，才写入
                        #    “不可用于 Idea 提交”专用标记；网络/TLS/限流类失败
                        #    不污染账号级可用性。
                        should_mark_unavailable = _is_idea_account_unavailable_reason(err_text)
                        if should_mark_unavailable:
                            with Session(engine) as session:
                                acc = session.get(AccountModel, vb["item"]["account_id"])
                                if acc:
                                    repo.mark_account_ineligible(acc, failed_record, err_text)
                                    session.add(acc)
                                    session.commit()
                            _log(task_id, f"[Idea] 自动标记账号不可用于 Idea 提交: {vb['item'].get('email')} ({err_text})")
                        else:
                            _log(task_id, f"[Idea] 失败原因偏向上游/网络/卡密环境，未标记账号不可用于 Idea 提交: {vb['item'].get('email')} ({err_text})")
                        append_result(account_id=vb["item"]["account_id"], email=vb["item"].get("email"), cdk_id=rec.id, code_masked=rec.code_masked, status="failed", reason=err_text, order_id=order_id, display_id=order["display_id"], idea_marked_unavailable=should_mark_unavailable)
                        
                        # 2. 提交失败则卡密额度未消耗，若有候选账号继续换额度提交
                        if failure_continue and pending_accounts and not control.is_stop_after_current_requested():
                            _log(task_id, f"[Idea] 账号 {vb['item'].get('email')} 失败，保留候补账号等待下一轮提交")
                        elif control.is_stop_after_current_requested() and pending_accounts:
                            mark_remaining_unsubmitted("已请求完成当前后停止；失败订单不再换候补账号提交")
                        elif not failure_continue:
                            _log(task_id, "[Idea] 失败后继续已关闭，停止后续账号提交")
                            pending_accounts.clear()
                            
                    elif time.time() - order["submitted_at"] > IDEA_SUBMIT_HARD_POLL_TIMEOUT_SECONDS:
                        timeout_count += 1
                        _log(task_id, f"[WARN] 轮询安全上限超时，停止等待该账号: {vb['item'].get('email')} (task_id={order['display_id'] or order_id})")
                        append_result(account_id=vb["item"]["account_id"], email=vb["item"].get("email"), cdk_id=rec.id, code_masked=rec.code_masked, status="timeout", reason="超过 24 小时仍未返回终态", order_id=order_id, display_id=order["display_id"])
                    elif time.time() - order["submitted_at"] > status_poll_timeout_seconds:
                        if not order.get("timeout_warned"):
                            order["timeout_warned"] = True
                            _log(
                                task_id,
                                f"[WAIT] Idea 状态暂未返回: {vb['item'].get('email')} "
                                f"(task_id={order['display_id'] or order_id}) 已等待 {status_poll_timeout_seconds}s，继续轮询直到上游返回 paid/failed，不提前结束任务",
                            )
                        still_active.append(order)
                    else:
                        still_active.append(order)
                        
                active_orders = still_active
                _task_store.set_progress(task_id, f"{success_count}/{total}")
        finally:
            control.finish_attempt(attempt_id)
            _task_store.set_progress(task_id, f"{success_count}/{total}")

        sync_meta()
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        idea_summary = latest_meta.get("idea_submit_summary") if isinstance(latest_meta.get("idea_submit_summary"), dict) else {}
        failed_accounts = list(idea_summary.get("failed_accounts") or []) if isinstance(idea_summary, dict) else []
        timeout_accounts = list(idea_summary.get("timeout_accounts") or []) if isinstance(idea_summary, dict) else []
        unsubmitted_accounts = list(idea_summary.get("unsubmitted_accounts") or []) if isinstance(idea_summary, dict) else []
        success_accounts = list(idea_summary.get("success_accounts") or []) if isinstance(idea_summary, dict) else []
        marked_unavailable_accounts = list(idea_summary.get("marked_unavailable_accounts") or []) if isinstance(idea_summary, dict) else []
        summary_message = (
            "Idea 卡密提交完成: "
            f"候选 {idea_summary.get('total_accounts', len(pairs)) if isinstance(idea_summary, dict) else len(pairs)} 个，"
            f"上游已受理 {submitted_count} 个，开通成功 {len(success_accounts)} 个，"
            f"失败 {len(failed_accounts)} 个，超时 {len(timeout_accounts)} 个，"
            f"未提交 {len(unsubmitted_accounts)} 个"
        )
        if failed_accounts:
            summary_message = f"{summary_message}；首个失败: {_idea_submit_log_item_text(failed_accounts[0])}"
        elif errors:
            summary_message = f"{summary_message}；首个错误: {errors[0]}"
        elif timeout_accounts:
            summary_message = f"{summary_message}；存在超过 24 小时仍未返回终态的账号，请按上游任务 ID 复核"
        _log(task_id, f"[SUMMARY] {summary_message}")
        _log_idea_submit_group_summary(task_id, "成功账号", success_accounts)
        _log_idea_submit_group_summary(task_id, "失败账号", failed_accounts)
        _log_idea_submit_group_summary(task_id, "超时账号", timeout_accounts)
        _log_idea_submit_group_summary(task_id, "未提交账号", unsubmitted_accounts)
        _log_idea_submit_group_summary(task_id, "已标记不可用于 Idea 提交", marked_unavailable_accounts)
        sync_meta()
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        idea_summary = latest_meta.get("idea_submit_summary") if isinstance(latest_meta.get("idea_submit_summary"), dict) else idea_summary
        failed_total = int((idea_summary or {}).get("failed") or 0)
        timeout_total = int((idea_summary or {}).get("timeout") or 0)
        unsubmitted_total = int((idea_summary or {}).get("unsubmitted") or 0)
        log_status = "success" if success_count > 0 and not errors and failed_total == 0 and timeout_total == 0 else "failed"
        finish_error = "" if log_status == "success" else summary_message
        _task_store.finish(
            task_id,
            status="done" if log_status == "success" else "failed",
            success=success_count,
            skipped=unsubmitted_total,
            errors=errors,
            error=finish_error,
        )
        terminal_status = str(_task_store.snapshot(task_id).get("status") or log_status)
        _save_task_log(
            "chatgpt",
            primary_email,
            terminal_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "baxigpt_cdk_submit_success" if log_status == "success" else "baxigpt_cdk_submit_failed",
                    "source": "baxigpt_cdk_submit",
                    "meta": latest_meta,
                    "runtime_results": list(runtime_results),
                    "idea_submit_summary": idea_summary,
                },
            ),
        )
    except TaskInterruption as exc:
        _log(task_id, f"[STOP] {exc}")
        sync_meta()
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error=str(exc),
        )
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "baxigpt_cdk_submit_stopped",
                    "source": "baxigpt_cdk_submit",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                    "runtime_results": list(runtime_results),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error=str(exc),
        )
    finally:
        try:
            from services.chatgpt_core.baxigpt_status_poller import stop_task_polling

            task_snapshot = _task_store.snapshot(task_id)
            runtime_status = str(task_snapshot.get("status") or "").strip().lower()
            stop_reason = (
                "本地 Idea 任务已中断，已停止后续状态轮询"
                if runtime_status in {"stopped", "interrupted"}
                else "本地 Idea 任务已结束，已停止后续状态轮询"
            )
            stop_task_polling(task_id, reason=stop_reason)
        except Exception as stop_polling_exc:
            logger.warning("Idea 任务结束时停止后台轮询失败 task_id=%s: %s", task_id, stop_polling_exc)
        _clear_task_current(task_id)
        _task_store.cleanup()


def _run_chatgpt_oaipay_approval(task_id: str, account_ids: list[int], settings: dict[str, Any]):
    from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
    from datetime import datetime, timezone

    from services.chatgpt_account_state import mark_payment_pending
    from services.chatgpt_core.oaipay_client import (
        DEFAULT_BASE_URL as OAIPAY_DEFAULT_BASE_URL,
        DEFAULT_PROXY_POOL,
        OaiPayClient,
        extract_approval_url,
        sanitize_oaipay_result,
    )
    from services.chatgpt_core.paypal_binding_client import mask_proxy

    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    runtime_results: list[dict[str, Any]] = []
    approval_urls: list[dict[str, Any]] = []
    results_lock = threading.Lock()
    primary_email = ""

    base_url = str(settings.get("base_url") or OAIPAY_DEFAULT_BASE_URL).strip().rstrip("/") or OAIPAY_DEFAULT_BASE_URL
    proxy = str(settings.get("proxy") or "").strip()
    proxy_pool = str(settings.get("proxy_pool") or DEFAULT_PROXY_POOL).strip() or DEFAULT_PROXY_POOL
    submit_mode = str(settings.get("submit_mode") or "serial").strip().lower()
    if submit_mode not in {"serial", "batch"}:
        submit_mode = "serial"
    submit_delay_seconds = max(float(settings.get("submit_delay_seconds") or 0), 0.0)
    batch_max_workers = min(max(int(settings.get("batch_max_workers") or 50), 1), 200)
    timeout = max(float(settings.get("timeout") or 30), 5.0)
    event_timeout = max(float(settings.get("event_timeout") or 90), 10.0)
    account_interval_seconds = max(int(settings.get("account_interval_seconds") or 0), 0)
    failure_continue = bool(settings.get("failure_continue", True))
    precheck_token_info = bool(settings.get("precheck_token_info", True))
    billing_country = str(settings.get("billing_country") or "US").strip() or "US"
    payment_locale = str(settings.get("payment_locale") or "en").strip() or "en"
    checkout_ui_mode = str(settings.get("checkout_ui_mode") or "hosted").strip() or "hosted"

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")
    _log(
        task_id,
        "[OaiPay] approvalUrl 批量提取启动: "
        f"base_url={base_url} mode={submit_mode} accounts={len(account_ids)} "
        f"proxy={mask_proxy(proxy)} proxy_pool={proxy_pool} "
        f"delay={submit_delay_seconds}s precheck={'on' if precheck_token_info else 'off'}",
    )

    def sync_meta() -> None:
        with results_lock:
            results_snapshot = list(runtime_results)
            urls_snapshot = list(approval_urls)
            errors_snapshot = list(errors)
            success_snapshot = success_count
            skipped_snapshot = skipped_count
        _task_store.update_meta(
            task_id,
            {
                "runtime_results": results_snapshot,
                "approval_urls": urls_snapshot,
                "runtime_success": success_snapshot,
                "runtime_skipped": skipped_snapshot,
                "runtime_errors": errors_snapshot,
            },
        )

    def append_result(payload: dict[str, Any]) -> None:
        nonlocal success_count, skipped_count
        payload = {
            "finished_at": beijing_now_iso(),
            **dict(payload or {}),
        }
        with results_lock:
            runtime_results.append(payload)
            status_value = str(payload.get("status") or "").strip()
            if status_value == "success":
                success_count += 1
                approval_url = str(payload.get("approval_url") or "").strip()
                if approval_url:
                    approval_urls.append(
                        {
                            "account_id": payload.get("account_id"),
                            "email": payload.get("email"),
                            "approval_url": approval_url,
                            "cs_id": payload.get("cs_id", ""),
                            "payment_method_id": payload.get("payment_method_id", ""),
                            "checkout_amount": payload.get("checkout_amount", ""),
                        }
                    )
            elif status_value == "skipped":
                skipped_count += 1
        sync_meta()

    def persist_approval_snapshot(account_id: int, *, patch: dict[str, Any]) -> None:
        with Session(engine) as session:
            account = session.get(AccountModel, account_id)
            if account is None or account.platform != "chatgpt":
                return
            try:
                extra = account.get_extra()
            except Exception:
                extra = {}
            if not isinstance(extra, dict):
                extra = {}

            now_iso = datetime.now(timezone.utc).isoformat()
            paypal_url = str(
                patch.get("paypal_url")
                or patch.get("approval_url")
                or patch.get("provider_redirect_url")
                or patch.get("long_url")
                or ""
            ).strip()
            checkout_amount = str(patch.get("checkout_amount") or "").strip()
            currency = str(patch.get("currency") or ("USD" if "USD" in checkout_amount.upper() else "") or "").strip().upper()
            amount_normalized = checkout_amount.upper().replace(",", "").strip()
            checkout_amount_is_zero = (
                not checkout_amount
                or amount_normalized in {"0", "0.0", "0.00", "0 USD", "0.0 USD", "0.00 USD", "$0", "$0.00"}
                or amount_normalized.startswith("0 ")
            )
            current = extra.get("chatgpt_oaipay_approval") if isinstance(extra.get("chatgpt_oaipay_approval"), dict) else {}
            current.update(
                {
                    "updated_at": now_iso,
                    **dict(patch or {}),
                }
            )
            extra["chatgpt_oaipay_approval"] = current

            paypal_marker = extra.get("chatgpt_paypal_binding") if isinstance(extra.get("chatgpt_paypal_binding"), dict) else {}
            if str(patch.get("status") or "") == "success":
                paypal_url_payload = {
                    "updated_at": now_iso,
                    "created_at": str(patch.get("created_at") or now_iso),
                    "status": "paypal_url_created",
                    "stage": "paypal_url_created",
                    "source": str(patch.get("upstream") or "oaipay"),
                    "upstream": str(patch.get("upstream") or "oaipay"),
                    "url": paypal_url,
                    "paypal_url": paypal_url,
                    "approval_url": paypal_url,
                    "payment_link_format": "paypal_url",
                    "link_type": str(patch.get("link_type") or "paypal"),
                    "plan": "plus",
                    "country": str(patch.get("billing_country") or "US").strip().upper() or "US",
                    "billing_country": str(patch.get("billing_country") or "US").strip().upper() or "US",
                    "currency": currency or "USD",
                    "checkout_amount": checkout_amount,
                    "checkout_amount_is_zero": checkout_amount_is_zero,
                    "cs_id": str(patch.get("cs_id") or ""),
                    "payment_method_id": str(patch.get("payment_method_id") or ""),
                    "payment_method_type": str(patch.get("payment_method_type") or ""),
                    "processor_entity": str(patch.get("processor_entity") or ""),
                    "payment_locale": str(patch.get("payment_locale") or ""),
                    "provider_redirect_url": str(patch.get("provider_redirect_url") or ""),
                    "long_url": str(patch.get("long_url") or ""),
                    "stripe_redirect_url": str(patch.get("stripe_redirect_url") or ""),
                    "stripe_hosted_url": str(patch.get("stripe_hosted_url") or ""),
                    "proxy": str(patch.get("proxy") or ""),
                    "proxy_pool": str(patch.get("proxy_pool") or ""),
                }
                extra["chatgpt_paypal_url"] = paypal_url_payload
                last_payment_link = dict(paypal_url_payload)
                last_payment_link.update(
                    {
                        "source": str(patch.get("upstream") or "oaipay"),
                        "url": paypal_url,
                    }
                )
                extra["chatgpt_last_payment_link"] = last_payment_link
                account.cashier_url = paypal_url
                mark_payment_pending(account, reason="paypal_url_created")
                paypal_marker.update(
                    {
                        "updated_at": now_iso,
                        "status": "paypal_url_created",
                        "phase": "paypal_url_created",
                        "upstream": "oaipay",
                        "paypal_url": paypal_url,
                        "approval_url": paypal_url,
                        "cs_id": str(patch.get("cs_id") or ""),
                        "payment_method_id": str(patch.get("payment_method_id") or ""),
                        "checkout_amount": checkout_amount,
                    }
                )
            elif str(patch.get("status") or "") == "failed":
                paypal_marker.update(
                    {
                        "updated_at": now_iso,
                        "status": "paypal_url_failed",
                        "phase": "paypal_url_failed",
                        "upstream": "oaipay",
                        "error": str(patch.get("error") or ""),
                    }
                )
            if paypal_marker:
                extra["chatgpt_paypal_binding"] = paypal_marker

            account.set_extra(extra)
            account.updated_at = datetime.now(timezone.utc)
            session.add(account)
            session.commit()

    def load_account(account_id: int) -> tuple[str, str]:
        with Session(engine) as session:
            account = session.get(AccountModel, int(account_id or 0))
            if account is None or account.platform != "chatgpt":
                raise ValueError("ChatGPT 账号不存在")
            email = str(account.email or "")
            skip_reason = _paypal_bind_skip_reason(account)
            if skip_reason:
                raise SkipCurrentAttemptRequested(skip_reason)
            access_token = _chatgpt_account_access_token(account)
            if not access_token:
                raise ValueError("账号缺少 Access Token")
            return email, access_token

    def wait_seconds(seconds: float, *, attempt_id: int | None = None) -> None:
        remaining = max(float(seconds or 0), 0.0)
        while remaining > 0:
            control.checkpoint(attempt_id=attempt_id)
            chunk = min(0.5, remaining)
            time.sleep(chunk)
            remaining -= chunk

    def run_one(index: int, account_id: int, *, start_delay: float = 0.0) -> dict[str, Any]:
        nonlocal primary_email
        # A Future may have been accepted just before a graceful request but
        # not actually begun.  It is not an active account and must quietly
        # drain without escalating graceful stop into an immediate interrupt.
        attempt_id: int | None = None
        email = ""
        try:
            control.checkpoint()
            if start_delay > 0:
                _log(task_id, f"[OaiPay] {index}/{len(account_ids)} 延时 {start_delay:g}s 后提交")
                # Delay is queueing, not an already-started account.  It
                # remains interruptible for immediate stop only; graceful is
                # checked immediately before the upstream work is claimed.
                wait_seconds(start_delay)
            attempt_id = control.start_attempt()
            if attempt_id is None:
                if control.is_stop_requested():
                    raise StopTaskRequested()
                return {"account_id": account_id, "status": "not_started"}
            control.checkpoint(attempt_id=attempt_id)
            email, access_token = load_account(account_id)
            if not primary_email and email:
                primary_email = email
            control.checkpoint(attempt_id=attempt_id)

            _log(task_id, f"[OaiPay] -------- {index}/{len(account_ids)} | {email or account_id} --------")
            client = OaiPayClient(base_url=base_url, timeout=timeout, event_timeout=event_timeout)
            _log(task_id, f"[OaiPay] 请求浏览器: {client.browser_profile_label}")

            token_info: dict[str, Any] = {}
            if precheck_token_info:
                _log(task_id, f"[OaiPay] token-info 预检: {email or account_id}")
                token_info = client.token_info(
                    access_token=access_token,
                    proxy=proxy,
                    proxy_pool=proxy_pool,
                )
                _log(
                    task_id,
                    "[OaiPay] token-info: "
                    f"ok={bool(token_info.get('ok'))} "
                    f"plan={token_info.get('plan') or token_info.get('account_type') or '-'} "
                    f"proxy={token_info.get('proxy_source') or '-'}",
                )

            progress_steps: list[dict[str, Any]] = []
            final_result: dict[str, Any] | None = None
            final_error = ""
            _log(task_id, f"[OaiPay] 提交 approvalUrl 提取: {email or account_id}")
            for event in client.iter_long_link_events(
                access_token=access_token,
                proxy=proxy,
                proxy_pool=proxy_pool,
                billing_country=billing_country,
                checkout_ui_mode=checkout_ui_mode,
                payment_locale=payment_locale,
                mode=2,
                link_type="paypal",
            ):
                control.checkpoint(attempt_id=attempt_id)
                event_type = str(event.get("type") or event.get("event") or "").strip()
                if event_type == "progress":
                    step = event.get("step", "")
                    total_steps = event.get("total", "")
                    desc = str(event.get("desc") or "")
                    progress_steps.append(
                        {
                            "step": step,
                            "total": total_steps,
                            "desc": desc,
                        }
                    )
                    _log(task_id, f"[OaiPay] {email or account_id} 进度 {step}/{total_steps}: {desc}")
                    continue
                if event_type == "error":
                    final_error = str(event.get("detail") or event.get("error") or event.get("message") or "oaipay 上游返回失败")
                    break
                if event_type == "done":
                    result = event.get("result") if isinstance(event.get("result"), dict) else {}
                    final_result = dict(result)
                    break
                _log(task_id, f"[OaiPay] {email or account_id} 事件: {json.dumps(event, ensure_ascii=False)}", level="debug")

            if final_error:
                raise ValueError(final_error)
            if final_result is None:
                raise ValueError("上游事件流结束但未返回 done.result")

            approval_url = extract_approval_url(final_result)
            sanitized = sanitize_oaipay_result(final_result)
            if not approval_url:
                raise ValueError("上游成功返回但缺少 approvalUrl")
            if not bool(final_result.get("ok", False)):
                raise ValueError(str(final_result.get("provider_error") or "上游 result.ok != true"))
            if bool(final_result.get("fallback", False)):
                raise ValueError(str(final_result.get("provider_error") or "上游 fallback=true"))

            payload = {
                "account_id": account_id,
                "email": email,
                "status": "success",
                "upstream": "oaipay",
                "stage": "paypal_url_created",
                "paypal_url": approval_url,
                "approval_url": approval_url,
                "provider_redirect_url": str(final_result.get("provider_redirect_url") or ""),
                "long_url": str(final_result.get("long_url") or ""),
                "stripe_redirect_url": str(final_result.get("stripe_redirect_url") or ""),
                "stripe_hosted_url": str(final_result.get("stripe_hosted_url") or ""),
                "cs_id": str(final_result.get("cs_id") or ""),
                "payment_method_id": str(final_result.get("payment_method_id") or ""),
                "payment_method_type": str(final_result.get("payment_method_type") or ""),
                "checkout_amount": str(final_result.get("checkout_amount") or ""),
                "processor_entity": str(final_result.get("processor_entity") or ""),
                "billing_country": str(final_result.get("billing_country") or billing_country),
                "currency": str(final_result.get("currency") or ""),
                "payment_locale": str(final_result.get("payment_locale") or payment_locale),
                "link_type": str(final_result.get("link_type") or "paypal"),
                "fallback": bool(final_result.get("fallback", False)),
                "provider_error": str(final_result.get("provider_error") or ""),
                "proxy": mask_proxy(proxy),
                "proxy_pool": proxy_pool,
                "progress": progress_steps,
                "token_info": {
                    "ok": bool(token_info.get("ok", False)) if token_info else None,
                    "email": str(token_info.get("email") or "") if token_info else "",
                    "plan": str(token_info.get("plan") or token_info.get("account_type") or "") if token_info else "",
                    "proxy_source": str(token_info.get("proxy_source") or "") if token_info else "",
                    "proxy_route": str(token_info.get("proxy_route") or "") if token_info else "",
                },
                "result": sanitized,
            }
            persist_approval_snapshot(
                account_id,
                patch={
                    "status": "success",
                    "phase": "paypal_url_created",
                    **payload,
                },
            )
            _task_store.add_cashier_url(task_id, approval_url)
            append_result(payload)
            _log(task_id, f"[OK] approvalUrl 已返回: {email or account_id} amount={payload['checkout_amount'] or '-'}")
            return payload
        except SkipCurrentAttemptRequested as exc:
            payload = {
                "account_id": account_id,
                "email": email,
                "status": "skipped",
                "reason": str(exc),
            }
            append_result(payload)
            _log(task_id, f"[SKIP] {email or account_id} - {exc}")
            return payload
        except StopTaskRequested:
            raise
        except Exception as exc:
            error_text = str(exc or "oaipay approvalUrl 提取失败")
            payload = {
                "account_id": account_id,
                "email": email,
                "status": "failed",
                "stage": "error",
                "reason": error_text,
                "error": error_text,
                "proxy": mask_proxy(proxy),
                "proxy_pool": proxy_pool,
            }
            try:
                persist_approval_snapshot(
                    account_id,
                    patch={
                        "status": "failed",
                        "phase": "error",
                        "error": error_text,
                        "proxy": mask_proxy(proxy),
                        "proxy_pool": proxy_pool,
                    },
                )
            except Exception:
                pass
            append_result(payload)
            _log(task_id, f"[FAIL] approvalUrl 提取失败: {email or account_id} - {error_text}")
            return payload
        finally:
            control.finish_attempt(attempt_id)

    try:
        if submit_mode == "batch":
            _log(task_id, f"[OaiPay] 批量提交模式: max_workers={batch_max_workers} start_delay={submit_delay_seconds:g}s")
            completed = 0
            max_workers = min(batch_max_workers, max(len(account_ids), 1))
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                pending: dict[Any, tuple[int, int]] = {}
                next_index = 0
                while (
                    next_index < len(account_ids)
                    and len(pending) < max_workers
                    and not control.should_stop_starting_new_attempts()
                ):
                    index = next_index + 1
                    account_id = account_ids[next_index]
                    future = executor.submit(run_one, index, account_id, start_delay=(index - 1) * submit_delay_seconds)
                    pending[future] = (index, account_id)
                    next_index += 1
                while pending:
                    control.checkpoint(consume_skip=False)
                    done, _ = wait(pending, timeout=0.5, return_when=FIRST_COMPLETED)
                    for future in done:
                        index, account_id = pending.pop(future)
                        try:
                            result = future.result()
                            if str(result.get("status") or "") == "failed":
                                errors.append(f"{result.get('email') or account_id}: {result.get('error') or result.get('reason') or 'failed'}")
                        except StopTaskRequested:
                            raise
                        except Exception as exc:
                            errors.append(f"{account_id}: {exc}")
                            _log(task_id, f"[FAIL] 批量 worker 异常: {account_id} - {exc}")
                        completed += 1
                        _task_store.set_progress(task_id, f"{completed}/{total}")
                        if errors and not failure_continue:
                            _log(task_id, "[OaiPay] 已出现失败；批量模式下已派发的请求会等待结束")
                        if (
                            next_index < len(account_ids)
                            and not control.should_stop_starting_new_attempts()
                        ):
                            next_position = next_index + 1
                            next_account_id = account_ids[next_index]
                            next_future = executor.submit(
                                run_one,
                                next_position,
                                next_account_id,
                                start_delay=0,
                            )
                            pending[next_future] = (next_position, next_account_id)
                            next_index += 1
                    sync_meta()
        else:
            for index, account_id in enumerate(account_ids, start=1):
                if control.is_stop_after_current_requested():
                    _log(task_id, "[CONTROL] 已完成当前账号，停止后续 OaiPay 提交")
                    break
                control.checkpoint(consume_skip=False)
                result = run_one(index, account_id)
                if str(result.get("status") or "") == "failed":
                    errors.append(f"{result.get('email') or account_id}: {result.get('error') or result.get('reason') or 'failed'}")
                    if not failure_continue:
                        _log(task_id, "[OaiPay] 失败后继续已关闭，停止后续提交")
                        _task_store.set_progress(task_id, f"{index}/{total}")
                        break
                _task_store.set_progress(task_id, f"{index}/{total}")
                if index < len(account_ids) and account_interval_seconds > 0:
                    _log(task_id, f"[OaiPay] 等待账号间隔 {account_interval_seconds}s 后继续下一个账号")
                    wait_seconds(account_interval_seconds)
                sync_meta()

        sync_meta()
        summary_message = f"approvalUrl 提取完成: 成功 {success_count} 个，跳过 {skipped_count} 个，失败 {len(errors)} 个"
        if errors:
            summary_message = f"{summary_message}；首个失败: {errors[0]}"
        _log(task_id, f"[SUMMARY] {summary_message}")
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        log_status = "success" if success_count > 0 and not errors else "failed"
        _save_task_log(
            "chatgpt",
            primary_email,
            log_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "chatgpt_oaipay_approval_success" if log_status == "success" else "chatgpt_oaipay_approval_failed",
                    "source": "chatgpt_oaipay_approval",
                    "meta": latest_meta,
                    "runtime_results": list(runtime_results),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="done" if log_status == "success" else "failed",
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error="" if not errors else summary_message,
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        sync_meta()
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "chatgpt_oaipay_approval_stopped",
                    "source": "chatgpt_oaipay_approval",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                    "runtime_results": list(runtime_results),
                },
            ),
        )
        _task_store.finish(task_id, status="stopped", success=success_count, skipped=skipped_count, errors=errors, error=str(exc))
    except Exception as exc:
        error_text = str(exc or "approvalUrl 提取任务异常")
        _log(task_id, f"[FAIL] {error_text}")
        sync_meta()
        _save_task_log(
            "chatgpt",
            primary_email,
            "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "chatgpt_oaipay_approval_failed",
                    "source": "chatgpt_oaipay_approval",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                    "runtime_results": list(runtime_results),
                },
            ),
        )
        _task_store.finish(task_id, status="failed", success=success_count, skipped=skipped_count, errors=errors or [error_text], error=error_text)


def _run_chatgpt_paypal_bind(task_id: str, account_ids: list[int], settings: dict[str, Any]):
    import re
    from datetime import datetime, timezone

    from services.chatgpt_account_state import mark_payment_failed, mark_payment_pending
    from services.chatgpt_core.paypal_binding_client import (
        DEFAULT_BASE_URL,
        DEFAULT_OTP_SIGNAL,
        PlusIceaixClient,
        mask_proxy,
        mask_secret,
        sanitize_result,
    )
    from services.chatgpt_core.paypal_sms_api import (
        DEFAULT_POLL_INTERVAL_SECONDS,
        DEFAULT_STABILITY_SECONDS,
        format_sms_time,
        mask_sms_code,
        poll_paypal_sms_otp,
    )

    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    runtime_results: list[dict[str, Any]] = []
    primary_email = ""

    base_url = str(settings.get("base_url") or DEFAULT_BASE_URL).strip().rstrip("/") or DEFAULT_BASE_URL
    proxy = str(settings.get("proxy") or "").strip()
    proxy_jp = str(settings.get("proxy_jp") or "").strip()
    phone = str(settings.get("phone") or "").strip()
    paypal_email = str(settings.get("paypal_email") or "").strip()
    sms_api = str(settings.get("sms_api") or "").strip()
    sms_api_test_mode = bool(settings.get("sms_api_test_mode", False))
    otp_timeout = max(int(settings.get("otp_timeout") or 180), 30)
    pplink_retry = max(int(settings.get("pplink_retry") or 3), 1)
    timeout = max(float(settings.get("timeout") or 30), 5.0)
    event_timeout = max(float(settings.get("event_timeout") or 60), 10.0)
    account_interval_seconds = max(int(settings.get("account_interval_seconds") or 0), 0)
    failure_continue = bool(settings.get("failure_continue", True))
    otp_signal = str(settings.get("otp_signal") or DEFAULT_OTP_SIGNAL).strip() or DEFAULT_OTP_SIGNAL

    sms_used_codes: set[str] = set()
    sms_used_record_ids: set[str] = set()
    sms_used_lock = threading.Lock()
    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")
    _log(
        task_id,
        "[PayPal] 外部绑定任务启动: "
        f"base_url={base_url} phone={phone} proxy={mask_proxy(proxy)} "
        f"proxy_jp={mask_proxy(proxy_jp) or '-'} accounts={len(account_ids)} "
        f"sms_api={'local-test' if sms_api and sms_api_test_mode else 'local-auto' if sms_api else '-'}",
    )

    def sanitize_external_log(message: Any) -> str:
        text = str(message or "")
        text = re.sub(r"\b(?:BA|EC)-[A-Za-z0-9]+", lambda m: mask_secret(m.group(0)), text)
        text = re.sub(r"\bcs_live_[A-Za-z0-9_]+", lambda m: mask_secret(m.group(0)), text)
        text = re.sub(r"\bpk_live_[A-Za-z0-9_]+", lambda m: mask_secret(m.group(0)), text)
        if proxy:
            text = text.replace(proxy, mask_proxy(proxy))
        if proxy_jp:
            text = text.replace(proxy_jp, mask_proxy(proxy_jp))
        return text

    def sync_meta() -> None:
        _task_store.update_meta(
            task_id,
            {
                "runtime_results": list(runtime_results),
                "runtime_success": success_count,
                "runtime_skipped": skipped_count,
                "runtime_errors": list(errors),
            },
        )

    def append_result(**payload: Any) -> None:
        runtime_results.append(
            {
                "finished_at": beijing_now_iso(),
                **payload,
            }
        )
        sync_meta()

    def sms_exclude_snapshot() -> tuple[set[str], set[str]]:
        with sms_used_lock:
            return set(sms_used_codes), set(sms_used_record_ids)

    def remember_sms_otp(code: str = "", record_id: str = "") -> None:
        code_value = re.sub(r"\D", "", str(code or ""))
        record_value = str(record_id or "").strip()
        with sms_used_lock:
            if code_value:
                sms_used_codes.add(code_value)
            if record_value:
                sms_used_record_ids.add(record_value)

    def persist_binding_snapshot(
        account_id: int,
        *,
        patch: dict[str, Any],
        payment_status: str = "",
    ) -> None:
        with Session(engine) as session:
            account = session.get(AccountModel, account_id)
            if account is None or account.platform != "chatgpt":
                return
            try:
                extra = account.get_extra()
            except Exception:
                extra = {}
            current = extra.get("chatgpt_paypal_binding") if isinstance(extra.get("chatgpt_paypal_binding"), dict) else {}
            current.update(
                {
                    "updated_at": datetime.now(timezone.utc).isoformat(),
                    **patch,
                }
            )
            extra["chatgpt_paypal_binding"] = current
            account.set_extra(extra)
            if payment_status == "pending":
                mark_payment_pending(account, reason="paypal_bind_processing")
            elif payment_status == "failed":
                mark_payment_failed(account, reason="paypal_bind_failed")
            account.updated_at = datetime.now(timezone.utc)
            session.add(account)
            session.commit()

    def persist_external_state_discovery(
        account_id: int,
        *,
        state: str,
        message: str = "",
        job_id: str = "",
        stage: str = "",
    ) -> None:
        state_value = str(state or "").strip()
        if state_value != "already_paid":
            return
        with Session(engine) as session:
            account = session.get(AccountModel, account_id)
            if account is None or account.platform != "chatgpt":
                return
            try:
                extra = account.get_extra()
            except Exception:
                extra = {}
            if not isinstance(extra, dict):
                extra = {}

            now_iso = datetime.now(timezone.utc).isoformat()
            current = extra.get("chatgpt_paypal_binding") if isinstance(extra.get("chatgpt_paypal_binding"), dict) else {}
            current.update(
                {
                    "updated_at": now_iso,
                    "status": "status_updated",
                    "phase": state_value,
                    "job_id": str(job_id or ""),
                    "error": str(message or ""),
                    "external_discovered_state": state_value,
                    "external_discovered_stage": str(stage or ""),
                }
            )
            extra["chatgpt_paypal_binding"] = current
            account.set_extra(extra)
            account.updated_at = datetime.now(timezone.utc)
            session.add(account)
            session.commit()

    def refresh_account_local_status_after_paypal(
        account_id: int,
        *,
        reason: str,
        job_id: str = "",
        stage: str = "",
    ) -> dict[str, Any] | None:
        reason_value = str(reason or "").strip() or "paypal_bind"
        with Session(engine) as session:
            account = session.get(AccountModel, account_id)
            if account is None or account.platform != "chatgpt":
                return None
            refresh_result = _sync_payment_link_account_status(session, account)
            try:
                extra = account.get_extra()
            except Exception:
                extra = {}
            if not isinstance(extra, dict):
                extra = {}
            capabilities = refresh_result.get("capabilities") if isinstance(refresh_result.get("capabilities"), dict) else {}
            probe = refresh_result.get("probe") if isinstance(refresh_result.get("probe"), dict) else {}
            auth = probe.get("auth") if isinstance(probe.get("auth"), dict) else {}
            subscription = probe.get("subscription") if isinstance(probe.get("subscription"), dict) else {}
            codex = probe.get("codex") if isinstance(probe.get("codex"), dict) else {}
            summary = {
                "trigger": reason_value,
                "refreshed_at": datetime.now(timezone.utc).isoformat(),
                "status": str(refresh_result.get("status") or account.status or ""),
                "policy_reason": str(refresh_result.get("reason") or ""),
                "auth_state": str(auth.get("state") or ""),
                "subscription_plan": str(subscription.get("plan") or capabilities.get("subscription_plan") or ""),
                "codex_state": str(codex.get("state") or capabilities.get("codex_state") or ""),
                "upload_gate": str(capabilities.get("upload_gate") or ""),
                "job_id": str(job_id or ""),
                "stage": str(stage or ""),
            }
            current = extra.get("chatgpt_paypal_binding") if isinstance(extra.get("chatgpt_paypal_binding"), dict) else {}
            current.update(
                {
                    "updated_at": summary["refreshed_at"],
                    "local_status_refresh": summary,
                }
            )
            extra["chatgpt_paypal_binding"] = current
            account.set_extra(extra)
            account.updated_at = datetime.now(timezone.utc)
            session.add(account)
            session.commit()
            return summary

    def trigger_local_status_refresh(account_id: int, *, reason: str, job_id: str = "", stage: str = "") -> dict[str, Any] | None:
        try:
            summary = refresh_account_local_status_after_paypal(
                account_id,
                reason=reason,
                job_id=job_id,
                stage=stage,
            )
            if summary:
                _log(
                    task_id,
                    "[PayPal] 本地状态刷新完成: "
                    f"status={summary.get('status') or '-'} "
                    f"plan={summary.get('subscription_plan') or '-'} "
                    f"auth={summary.get('auth_state') or '-'} "
                    f"gate={summary.get('upload_gate') or '-'}",
                )
            return summary
        except Exception as exc:
            _log(task_id, f"[PayPal][WARN] 本地状态刷新失败: {exc}")
            return None

    def wait_before_next(index: int, attempt_id: int | None = None) -> None:
        if index >= len(account_ids) or account_interval_seconds <= 0:
            return
        _log(task_id, f"[PayPal] 等待账号间隔 {account_interval_seconds}s 后继续下一个账号")
        remaining = float(account_interval_seconds)
        while remaining > 0:
            control.checkpoint(attempt_id=attempt_id)
            chunk = min(1.0, remaining)
            time.sleep(chunk)
            remaining -= chunk

    def poll_local_sms_api(
        *,
        attempt_id: int | None,
        target_phone: str,
        wait_started_at: datetime,
        reveal_code_in_log: bool = False,
        stop_event: threading.Event | None = None,
        consume_task_control: bool = True,
    ):
        exclude_codes, exclude_record_ids = sms_exclude_snapshot()

        def sms_log(message: str) -> None:
            _log(task_id, f"[PayPal][SMS API] {message}")

        return poll_paypal_sms_otp(
            sms_api,
            wait_started_at=wait_started_at,
            expected_phone=target_phone or phone,
            exclude_codes=exclude_codes,
            exclude_record_ids=exclude_record_ids,
            timeout_seconds=otp_timeout,
            stability_seconds=DEFAULT_STABILITY_SECONDS,
            poll_interval_seconds=DEFAULT_POLL_INTERVAL_SECONDS,
            log=sms_log,
            stop_check=(lambda: control.checkpoint(attempt_id=attempt_id)) if consume_task_control else None,
            stop_event=stop_event,
            reveal_code_in_log=reveal_code_in_log,
        )

    def start_sms_test_poll_thread(
        *,
        attempt_id: int | None,
        target_phone: str,
        wait_started_at: datetime,
    ) -> tuple[threading.Event, threading.Thread]:
        stop_event = threading.Event()

        def worker() -> None:
            try:
                parsed = poll_local_sms_api(
                    attempt_id=attempt_id,
                    target_phone=target_phone,
                    wait_started_at=wait_started_at,
                    reveal_code_in_log=False,
                    stop_event=stop_event,
                    consume_task_control=False,
                )
                if parsed is None:
                    return
                remember_sms_otp(parsed.code, parsed.record_id)
                _log(
                    task_id,
                    "[PayPal][SMS API] "
                    f"测试模式已解析验证码: {parsed.code} "
                    f"recordId={parsed.record_id or '-'} received_at={format_sms_time(parsed.received_at)}；"
                    "未自动提交，请在任务面板手动输入",
                )
            except Exception as exc:
                if not stop_event.is_set():
                    _log(task_id, f"[PayPal][SMS API] 测试模式轮询异常: {exc}")

        thread = threading.Thread(target=worker, daemon=True)
        thread.start()
        return stop_event, thread

    try:
        for index, account_id in enumerate(account_ids, start=1):
            control.checkpoint(consume_skip=False)
            attempt_id = _claim_next_task_attempt(control)
            email = ""
            job_id = ""
            external_state_discovery = ""
            external_state_message = ""
            try:
                control.checkpoint(attempt_id=attempt_id)
                with Session(engine) as session:
                    account = session.get(AccountModel, int(account_id or 0))
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    email = str(account.email or "")
                    if not primary_email and email:
                        primary_email = email
                    skip_reason = _paypal_bind_skip_reason(account)
                    if skip_reason:
                        skipped_count += 1
                        _log(task_id, f"[SKIP] {email or account_id} - {skip_reason}")
                        append_result(account_id=account_id, email=email, status="skipped", reason=skip_reason)
                        continue
                    access_token = _chatgpt_account_access_token(account)

                client = PlusIceaixClient(base_url=base_url, timeout=timeout, event_timeout=event_timeout)
                _log(task_id, f"[PayPal] -------- {index}/{len(account_ids)} | {email or account_id} --------")
                _log(task_id, f"[PayPal] 外部请求浏览器: {client.browser_profile_label}")
                persist_binding_snapshot(
                    account_id,
                    patch={
                        "status": "processing",
                        "phase": "create_job",
                        "task_id": task_id,
                        "base_url": base_url,
                        "phone": phone,
                        "proxy": mask_proxy(proxy),
                        "proxy_jp": mask_proxy(proxy_jp),
                        "paypal_email": paypal_email,
                        "browser_profile": client.browser_profile_label,
                    },
                    payment_status="pending",
                )
                _log(task_id, f"[PayPal] 提交外部任务: {email or account_id}")
                if sms_api:
                    _log(task_id, "[PayPal][SMS API] 收码 API 将由本地解析，创建外部任务时不透传给外部服务")
                job_response = client.create_job(
                    input_token=access_token,
                    proxy=proxy,
                    proxy_jp=proxy_jp,
                    phone=phone,
                    email=paypal_email,
                    sms_api="",
                    otp_timeout=otp_timeout,
                    pplink_retry=pplink_retry,
                )
                job_id = str(job_response.get("job_id") or "").strip()
                if not job_id:
                    raise ValueError(f"外部服务未返回 job_id: {sanitize_result(job_response)}")
                _log(task_id, f"[PayPal] job_id={job_id} events={client.events_url(job_id)}")
                persist_binding_snapshot(
                    account_id,
                    patch={
                        "status": "processing",
                        "phase": "events",
                        "job_id": job_id,
                        "events_url": client.events_url(job_id),
                    },
                    payment_status="pending",
                )

                final_result: dict[str, Any] | None = None
                for event in client.iter_events(job_id):
                    control.checkpoint(attempt_id=attempt_id)
                    event_type = str(event.get("type") or event.get("event") or "").strip()
                    if event_type == "log":
                        raw_message = event.get("msg", "")
                        display_message = sanitize_external_log(raw_message)
                        _log(task_id, f"[PayPal] {display_message}")
                        discovered_state = _paypal_bind_detect_external_state(raw_message)
                        if discovered_state and not external_state_discovery:
                            external_state_discovery = discovered_state
                            external_state_message = display_message
                            persist_external_state_discovery(
                                account_id,
                                state=discovered_state,
                                message=display_message,
                                job_id=job_id,
                                stage="log",
                            )
                            if discovered_state == "already_paid":
                                _log(task_id, f"[PayPal] 外部反馈账号已付费，触发本地状态刷新: {email or account_id}")
                                trigger_local_status_refresh(
                                    account_id,
                                    reason="paypal_bind_already_paid_log",
                                    job_id=job_id,
                                    stage="log",
                                )
                        continue
                    if event_type == otp_signal:
                        target_phone = str(event.get("phone") or phone or "").strip()
                        # API timestamps are second-precision.  Floor the local
                        # wait-start marker so old messages from earlier seconds
                        # are rejected, while the current wait step has a stable
                        # comparison boundary.
                        otp_wait_started_at = datetime.now(timezone.utc).replace(microsecond=0)
                        _log(task_id, f"[PayPal] 等待 OTP: phone={target_phone or '-'} timeout={otp_timeout}s")
                        if sms_api and sms_api_test_mode:
                            stop_event, test_thread = start_sms_test_poll_thread(
                                attempt_id=attempt_id,
                                target_phone=target_phone,
                                wait_started_at=otp_wait_started_at,
                            )
                            try:
                                pin = control.wait_for_verification_code(
                                    attempt_id=attempt_id,
                                    phase="paypal_otp",
                                    phase_label="PayPal 短信 OTP",
                                    email=target_phone or phone or email,
                                    timeout_seconds=otp_timeout,
                                )
                            finally:
                                stop_event.set()
                                test_thread.join(timeout=0.2)
                            remember_sms_otp(pin)
                            otp_response = client.submit_otp(job_id, pin)
                            _log(task_id, f"[PayPal] OTP 已手动提交: ok={bool(otp_response.get('ok', True))}")
                            continue

                        if sms_api:
                            parsed_otp = poll_local_sms_api(
                                attempt_id=attempt_id,
                                target_phone=target_phone,
                                wait_started_at=otp_wait_started_at,
                                reveal_code_in_log=False,
                            )
                            if parsed_otp is not None:
                                remember_sms_otp(parsed_otp.code, parsed_otp.record_id)
                                otp_response = client.submit_otp(job_id, parsed_otp.code)
                                _log(
                                    task_id,
                                    "[PayPal] OTP 已由 SMS API 自动提交: "
                                    f"code={mask_sms_code(parsed_otp.code)} ok={bool(otp_response.get('ok', True))}",
                                )
                                continue
                            _log(task_id, "[PayPal][SMS API] 未取得可用验证码，切换为手动输入 OTP")

                        pin = control.wait_for_verification_code(
                            attempt_id=attempt_id,
                            phase="paypal_otp",
                            phase_label="PayPal 短信 OTP",
                            email=target_phone or phone or email,
                            timeout_seconds=otp_timeout,
                        )
                        remember_sms_otp(pin)
                        otp_response = client.submit_otp(job_id, pin)
                        _log(task_id, f"[PayPal] OTP 已提交: ok={bool(otp_response.get('ok', True))}")
                        continue
                    if event_type == "result":
                        result = event.get("result") if isinstance(event.get("result"), dict) else {}
                        final_result = dict(result)
                        _log(task_id, f"[PayPal] 外部结果: {json.dumps(sanitize_result(result), ensure_ascii=False)}")
                        break
                    if event_type == "done":
                        _log(task_id, "[PayPal] 外部事件流完成")
                        break
                    _log(task_id, f"[PayPal] 事件: {json.dumps(sanitize_result(event), ensure_ascii=False)}")

                if final_result is None:
                    raise ValueError("外部事件流结束但未返回 result")

                is_success = bool(final_result.get("success"))
                stage = str(final_result.get("stage") or "").strip()
                error_text = str(final_result.get("error") or "").strip()
                sanitized = sanitize_result(final_result)
                discovered_state = _paypal_bind_detect_external_state(final_result, error_text, stage)
                if discovered_state and not external_state_discovery:
                    external_state_discovery = discovered_state
                    external_state_message = error_text or json.dumps(sanitized, ensure_ascii=False)
                    persist_external_state_discovery(
                        account_id,
                        state=discovered_state,
                        message=external_state_message,
                        job_id=job_id,
                        stage=stage or "result",
                    )
                    if discovered_state == "already_paid":
                        _log(task_id, f"[PayPal] 外部结果提示账号已付费，触发本地状态刷新: {email or account_id}")
                        trigger_local_status_refresh(
                            account_id,
                            reason="paypal_bind_already_paid_result",
                            job_id=job_id,
                            stage=stage or "result",
                        )
                binding_status = "success" if is_success else "status_updated" if external_state_discovery == "already_paid" else "failed"
                binding_phase = stage or ("done" if is_success else external_state_discovery or "failed")
                persist_binding_snapshot(
                    account_id,
                    patch={
                        "status": binding_status,
                        "phase": binding_phase,
                        "job_id": job_id,
                        "result": sanitized,
                        "ba_token": str(final_result.get("ba_token") or ""),
                        "ec_token": str(final_result.get("ec_token") or ""),
                        "paypal_email": str(final_result.get("email") or paypal_email or ""),
                        "paypal_password": str(final_result.get("password") or ""),
                        "error": error_text,
                    },
                    payment_status="" if is_success or external_state_discovery == "already_paid" else "failed",
                )
                if external_state_discovery == "already_paid" and not is_success:
                    skipped_count += 1
                    message = "外部反馈 User is already paid，已触发本地状态刷新"
                    append_result(
                        account_id=account_id,
                        email=email,
                        job_id=job_id,
                        status="skipped",
                        stage=stage or external_state_discovery,
                        reason=message,
                        result=sanitized,
                    )
                    _log(task_id, f"[SKIP] {email or account_id} - {message}")
                    wait_before_next(index, attempt_id)
                    continue
                append_result(
                    account_id=account_id,
                    email=email,
                    job_id=job_id,
                    status="success" if is_success else "failed",
                    stage=stage,
                    error=error_text,
                    result=sanitized,
                )
                if is_success:
                    trigger_local_status_refresh(
                        account_id,
                        reason="paypal_bind_success",
                        job_id=job_id,
                        stage=stage or "done",
                    )
                    success_count += 1
                    _log(task_id, f"[OK] PayPal 绑定成功: {email or account_id}")
                else:
                    message = error_text or stage or "PayPal 绑定失败"
                    errors.append(f"{email or account_id}: {message}")
                    _log(task_id, f"[FAIL] PayPal 绑定失败: {email or account_id} stage={stage or '-'} error={error_text or '-'}")
                    if not failure_continue:
                        _log(task_id, "[PayPal] 失败后继续已关闭，停止后续提交")
                        break
                wait_before_next(index, attempt_id)
            except SkipCurrentAttemptRequested as exc:
                skipped_count += 1
                _log(task_id, f"[SKIP] 已跳过当前 PayPal 绑定: {email or account_id} - {exc}")
                append_result(account_id=account_id, email=email, job_id=job_id, status="skipped", reason=str(exc))
            except StopTaskRequested:
                raise
            except Exception as exc:
                error_text = str(exc or "PayPal 绑定失败")
                if external_state_discovery == "already_paid":
                    skipped_count += 1
                    persist_binding_snapshot(
                        account_id,
                        patch={
                            "status": "status_updated",
                            "phase": external_state_discovery,
                            "job_id": job_id,
                            "error": external_state_message or error_text,
                        },
                        payment_status="",
                    )
                    trigger_local_status_refresh(
                        account_id,
                        reason="paypal_bind_already_paid_exception",
                        job_id=job_id,
                        stage=external_state_discovery,
                    )
                    message = "外部反馈 User is already paid，已触发本地状态刷新"
                    append_result(account_id=account_id, email=email, job_id=job_id, status="skipped", reason=message)
                    _log(task_id, f"[SKIP] {email or account_id} - {message}")
                    wait_before_next(index, attempt_id)
                    continue
                errors.append(f"{email or account_id}: {error_text}")
                persist_binding_snapshot(
                    account_id,
                    patch={
                        "status": "failed",
                        "phase": "error",
                        "job_id": job_id,
                        "error": error_text,
                    },
                    payment_status="failed",
                )
                append_result(account_id=account_id, email=email, job_id=job_id, status="failed", reason=error_text)
                _log(task_id, f"[FAIL] PayPal 绑定异常: {email or account_id} - {error_text}")
                if not failure_continue:
                    _log(task_id, "[PayPal] 失败后继续已关闭，停止后续提交")
                    break
            finally:
                control.finish_attempt(attempt_id)
                _task_store.set_progress(task_id, f"{index}/{total}")

        summary_message = f"PayPal 绑定完成: 成功 {success_count} 个，跳过 {skipped_count} 个，失败 {len(errors)} 个"
        if errors:
            summary_message = f"{summary_message}；首个失败: {errors[0]}"
        _log(task_id, f"[SUMMARY] {summary_message}")
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        log_status = "success" if success_count > 0 and not errors else "failed"
        _save_task_log(
            "chatgpt",
            primary_email,
            log_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "chatgpt_paypal_bind_success" if log_status == "success" else "chatgpt_paypal_bind_failed",
                    "source": "chatgpt_paypal_bind",
                    "meta": latest_meta,
                    "runtime_results": list(runtime_results),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="done" if log_status == "success" else "failed",
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error="" if not errors else summary_message,
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        sync_meta()
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "chatgpt_paypal_bind_stopped",
                    "source": "chatgpt_paypal_bind",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                    "runtime_results": list(runtime_results),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error=str(exc),
        )
    finally:
        _task_store.cleanup()



def _run_local_short_payment_links(task_id: str, account_ids: list[int]):
    """Generate login-bound ChatGPT checkout links without the long-link service."""

    from api.actions import _apply_action_result, _to_platform_account
    from core.base_platform import RegisterConfig
    from core.config_store import config_store
    from services.chatgpt_core import ChatGPTPlatform

    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    primary_email = ""

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    skipped_items = list(meta.get("skipped_items") or [])
    missing_ids = list(meta.get("missing_ids") or [])
    request_params = _filtered_payment_link_request_params(dict(meta.get("params") or {}))
    skip_existing = bool(meta.get("skip_existing", True))
    force_refresh = bool(meta.get("force_refresh", False))
    instance = ChatGPTPlatform(config=RegisterConfig(extra=config_store.get_all()))
    instance_id = str(os.getenv("APP_INSTANCE_ID") or "auto-gpt").strip() or "auto-gpt"

    local_profile = {
        "link_type": "chatgpt",
        "plan": "plus",
        "country": str(request_params.get("country") or "US").strip().upper(),
        "currency": str(request_params.get("currency") or "USD").strip().upper(),
        "checkout_ui_mode": "custom",
        "payment_source": PAYMENT_SOURCE_CHATGPT_HOSTED,
        "payment_link_format": PAYMENT_LINK_FORMAT_SHORT,
        "login_required": True,
        "effective_concurrency": 1,
        "variant_key": payment_link_variant_key(request_params),
    }
    _task_store.update_meta(
        task_id,
        {
            "payment_link_profile": local_profile,
            "payment_link_state": "preparing",
            "params": dict(request_params),
        },
    )

    try:
        for missing_id in missing_ids:
            _log(task_id, f"[MISS] 账号不存在: account_id={missing_id}")
            errors.append(f"account_id={missing_id}: 账号不存在")

        for item in skipped_items:
            if not primary_email:
                primary_email = str(item.get("email") or "")
            _log(
                task_id,
                f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - "
                f"{item.get('reason') or '已跳过'}",
            )

        for index, account_id in enumerate(account_ids, start=1):
            control.checkpoint(consume_skip=False)
            email = ""
            request_id = f"{instance_id}:{task_id}:{int(account_id or 0)}"
            pending: dict[str, Any] = {}
            attempt_id = _claim_next_task_attempt(control)
            try:
                control.checkpoint(attempt_id=attempt_id)
                with Session(engine) as session:
                    account = session.get(AccountModel, int(account_id or 0))
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    email = str(account.email or "")
                    if not primary_email:
                        primary_email = email

                    params = _build_batch_payment_link_params(account, request_params)
                    params["request_id"] = request_id
                    params["reuse_cached_link"] = not force_refresh and request_params.get("reuse_cached_link") is not False
                    skip_reason = _payment_link_skip_reason(
                        account,
                        force_refresh=force_refresh,
                        session=session,
                        exclude_request_id=request_id,
                        variant_params=params,
                    )
                    if skip_reason:
                        skipped_count += 1
                        _log(task_id, f"[SKIP] 登录态短链生成跳过: {email or account_id} - {skip_reason}")
                        continue

                    extra = account.get_extra()
                    cached = payment_link_cache_for_params(extra, params)
                    cached_url = _payment_link_current_cache_url(cached)
                    if (
                        skip_existing
                        and not force_refresh
                        and cached_url
                        and payment_link_cache_matches(cached, params)
                    ):
                        if str(account.cashier_url or "").strip() != cached_url:
                            account.cashier_url = cached_url
                            account.updated_at = datetime.now(timezone.utc)
                            session.add(account)
                            upsert_account_list_state_for_account_ids(
                                session,
                                [account.id],
                                commit=False,
                            )
                            session.commit()
                        _task_store.add_cashier_url(task_id, cached_url)
                        skipped_count += 1
                        _log(task_id, f"[SKIP] 已有可复用登录态短链: {email or account_id}")
                        continue

                    pending = {
                        "account_id": int(account_id),
                        "email": email,
                        "account_email": str(account.email or "").strip().lower(),
                        "account_created_at": _payment_link_account_created_at_text(account.created_at),
                        "account_identity": _payment_link_account_identity(account),
                    }
                    _upsert_payment_link_generation(
                        session,
                        account_id=int(account_id),
                        **_payment_link_pending_identity_kwargs(pending),
                        task_id=task_id,
                        request_id=request_id,
                        status="submitting",
                        link_type="chatgpt",
                        generation_kind="plus_checkout",
                        variant_key=payment_link_variant_key(params),
                        submitted_at=datetime.now(timezone.utc).isoformat(),
                        result=params,
                    )
                    platform_account = _to_platform_account(account)
                    session.commit()

                _log(
                    task_id,
                    f"[短链] {index}/{total} {email or account_id} "
                    f"country={params.get('country')} currency={params.get('currency')} session=ready",
                )
                result = instance.execute_action("payment_link", platform_account, params)
                data = result.get("data") if isinstance(result.get("data"), dict) else {}
                checkout_url = _validated_payment_link_url(
                    data.get("url") or data.get("checkout_url") or data.get("cashier_url")
                )
                if not result.get("ok") or not checkout_url:
                    raise ValueError(str(result.get("error") or data.get("message") or "登录态短链生成失败"))

                with Session(engine) as session:
                    account = session.get(AccountModel, int(account_id or 0))
                    if not _payment_link_pending_matches_account(account, pending):
                        _delete_payment_link_generation_by_request_id(session, request_id)
                        session.commit()
                        raise ValueError("账号已被删除或替换，短链结果未写入")
                    _apply_action_result(
                        "chatgpt",
                        "payment_link",
                        account,
                        {"ok": True, "data": data},
                        session,
                    )
                    _upsert_payment_link_generation(
                        session,
                        account_id=int(account_id),
                        **_payment_link_pending_identity_kwargs(pending),
                        task_id=task_id,
                        request_id=request_id,
                        status="succeeded",
                        link_type="chatgpt",
                        generation_kind="plus_checkout",
                        variant_key=str(data.get("variant_key") or payment_link_variant_key(params)),
                        generated_at=str(data.get("generated_at") or datetime.now(timezone.utc).isoformat()),
                        url=checkout_url,
                        result=data,
                    )
                    upsert_account_list_state_for_account_ids(
                        session,
                        [account.id],
                        commit=False,
                    )
                    session.commit()
                _task_store.add_cashier_url(task_id, checkout_url)
                success_count += 1
                _log(task_id, f"[OK] 登录态短链已生成并保存: {email or account_id}")
            except SkipCurrentAttemptRequested as exc:
                skipped_count += 1
                _log(task_id, f"[SKIP] 已跳过登录态短链生成: {email or account_id} - {exc}")
            except StopTaskRequested:
                raise
            except Exception as exc:
                error_text = sanitize_error_message(exc)[:1600]
                errors.append(f"{email or account_id}: {error_text}")
                if pending:
                    with Session(engine) as failure_session:
                        account = failure_session.get(AccountModel, int(account_id or 0))
                        if _payment_link_pending_matches_account(account, pending):
                            _upsert_payment_link_generation(
                                failure_session,
                                account_id=int(account_id),
                                **_payment_link_pending_identity_kwargs(pending),
                                task_id=task_id,
                                request_id=request_id,
                                status="failed",
                                link_type="chatgpt",
                                generation_kind="plus_checkout",
                                variant_key=payment_link_variant_key(request_params),
                                error=error_text,
                            )
                        else:
                            _delete_payment_link_generation_by_request_id(failure_session, request_id)
                        failure_session.commit()
                _log(task_id, f"[FAIL] 登录态短链生成失败: {email or account_id} - {error_text}")
            finally:
                control.finish_attempt(attempt_id)
                _task_store.set_progress(task_id, f"{index}/{total}")

        if errors and success_count:
            final_status = "partial"
            aggregate = "partial_failure"
        elif errors:
            final_status = "failed"
            aggregate = "total_failure"
        else:
            final_status = "done"
            aggregate = "completed_success"
        total_skipped = skipped_count + len(skipped_items)
        summary_message = (
            f"批量登录态短链生成完成: 成功 {success_count} 个，跳过 {total_skipped} 个，"
            f"失败 {len(errors)} 个"
        )
        _task_store.update_meta(
            task_id,
            {
                "payment_link_state": aggregate,
                "payment_link_aggregate_status": aggregate,
                "runtime_success": success_count,
                "runtime_skipped": skipped_count,
                "runtime_errors": list(errors),
                "runtime_interrupted": 0,
            },
        )
        _log(task_id, f"[SUMMARY] {summary_message}")
        _save_task_log(
            "chatgpt",
            primary_email,
            final_status,
            error="" if final_status == "done" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": f"batch_payment_link_{aggregate}",
                    "source": "batch_payment_link",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status=final_status,
            success=success_count,
            skipped=total_skipped,
            errors=errors,
            error="" if final_status == "done" else summary_message,
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_payment_link_stopped",
                    "source": "batch_payment_link",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors,
            error=str(exc),
        )
    except Exception as exc:
        error_text = sanitize_error_message(exc)[:1600]
        _log(task_id, f"[FAIL] 批量登录态短链生成失败: {error_text}")
        _save_task_log(
            "chatgpt",
            primary_email,
            "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_payment_link_failed",
                    "source": "batch_payment_link",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="failed",
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors or [error_text],
            error=error_text,
        )
    finally:
        _task_store.cleanup()


def _run_batch_payment_links(task_id: str, account_ids: list[int]):
    """Submit all eligible accounts once, then poll long-link batches in bulk."""

    initial_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    initial_params = _filtered_payment_link_request_params(dict(initial_meta.get("params") or {}))
    if is_local_short_payment_link_params(initial_params):
        return _run_local_short_payment_links(task_id, account_ids)

    from api.actions import _apply_action_result
    from services.chatgpt_core.long_link_payment_client import (
        LongLinkPaymentClient,
        LongLinkPaymentError,
        payment_link_from_remote_job,
    )

    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    success_count = 0
    skipped_count = 0
    remote_interrupted_count = 0
    errors: list[str] = []
    primary_email = ""
    prepared: list[dict[str, Any]] = []
    submitted_request_ids: set[str] = set()
    terminal_request_ids: set[str] = set()
    stop_after_submit_noted = False

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    skipped_items = list(meta.get("skipped_items") or [])
    missing_ids = list(meta.get("missing_ids") or [])
    request_params = _filtered_payment_link_request_params(dict(meta.get("params") or {}))
    profile_overrides = dict(request_params)
    is_team_task = str(request_params.get("plan") or "plus").strip().lower() == PAYMENT_LINK_PLAN_TEAM
    generation_label = "Team checkout 长链接" if is_team_task else "支付链接"
    skip_existing = bool(meta.get("skip_existing", True))
    force_refresh = bool(meta.get("force_refresh", False))
    profile: dict[str, Any] = {}

    def _remote_time(value: Any) -> str:
        try:
            timestamp = float(value)
        except (TypeError, ValueError):
            return ""
        if timestamp <= 0:
            return ""
        try:
            return datetime.fromtimestamp(timestamp, timezone.utc).isoformat()
        except (OverflowError, OSError, ValueError):
            return ""

    def _account_access_token(account: AccountModel) -> str:
        extra = account.get_extra()
        return str(extra.get("access_token") or account.token or "").strip()

    def _record_remote_items(items: list[dict[str, Any]]) -> None:
        nonlocal success_count, remote_interrupted_count
        item_by_request = {
            str(item.get("request_id") or "").strip(): item
            for item in items
            if isinstance(item, dict) and str(item.get("request_id") or "").strip()
        }
        if not item_by_request:
            return
        committed_errors: list[str] = []
        committed_terminal_request_ids: list[str] = []
        committed_cashier_urls: list[str] = []
        committed_logs: list[str] = []
        committed_success_count = 0
        committed_interrupted_count = 0
        changed_account_ids: list[int] = []
        with Session(engine) as session:
            changed = False
            for pending in prepared:
                request_id = str(pending["request_id"])
                remote = item_by_request.get(request_id)
                if remote is None:
                    continue
                if request_id in terminal_request_ids:
                    continue
                remote_status = str(remote.get("status") or "unknown").strip().lower()
                remote_batch_id = str(remote.get("batch_id") or "").strip()
                remote_job_id = str(remote.get("job_id") or "").strip()
                submitted_at = _remote_time(remote.get("created_at"))
                started_at = _remote_time(remote.get("started_at"))
                email = str(pending.get("email") or pending.get("account_id") or "")
                account = session.get(AccountModel, int(pending["account_id"]))
                if not _payment_link_pending_matches_account(account, pending):
                    _delete_payment_link_generation_by_request_id(session, request_id)
                    error_text = "账号已被删除或替换，支付链接结果未写入"
                    committed_errors.append(f"{email}: {error_text}")
                    committed_terminal_request_ids.append(request_id)
                    committed_logs.append(f"[SKIP] {error_text}: {email}")
                    changed = True
                    continue
                existing_history = session.exec(
                    select(PaymentLinkGenerationModel).where(
                        PaymentLinkGenerationModel.request_id == request_id
                    )
                ).first()
                if existing_history is not None and not _payment_link_generation_matches_pending(
                    existing_history, pending
                ):
                    error_text = "支付链接历史请求身份不匹配，结果未写入"
                    committed_errors.append(f"{email}: {error_text}")
                    committed_terminal_request_ids.append(request_id)
                    committed_logs.append(f"[SKIP] {error_text}: {email}")
                    continue
                if remote_status in {"queued", "running"}:
                    _upsert_payment_link_generation(
                        session,
                        account_id=int(pending["account_id"]),
                        **_payment_link_pending_identity_kwargs(pending),
                        task_id=task_id,
                        request_id=request_id,
                        status=remote_status,
                        profile_hash=str(profile.get("profile_hash") or ""),
                        link_type=str(profile.get("link_type") or ""),
                        generation_kind=payment_link_generation_kind(request_params),
                        variant_key=payment_link_variant_key(request_params),
                        remote_batch_id=remote_batch_id,
                        remote_job_id=remote_job_id,
                        submitted_at=submitted_at,
                        started_at=started_at,
                    )
                    changed = True
                    continue
                if remote_status == "done":
                    try:
                        data = payment_link_from_remote_job(remote, profile=profile)
                    except Exception as exc:
                        error_text = sanitize_error_message(exc)[:1600]
                        committed_errors.append(f"{email}: {error_text}")
                        _upsert_payment_link_generation(
                            session,
                            account_id=int(pending["account_id"]),
                            **_payment_link_pending_identity_kwargs(pending),
                            task_id=task_id,
                            request_id=request_id,
                            status="failed",
                            profile_hash=str(profile.get("profile_hash") or ""),
                            link_type=str(profile.get("link_type") or ""),
                            generation_kind=payment_link_generation_kind(request_params),
                            variant_key=payment_link_variant_key(request_params),
                            remote_batch_id=remote_batch_id,
                            remote_job_id=remote_job_id,
                            submitted_at=submitted_at,
                            started_at=started_at,
                            generated_at=_remote_time(remote.get("completed_at")),
                            error=error_text,
                        )
                        committed_logs.append(
                            f"[FAIL] {generation_label}保存失败: {email} - {error_text}"
                        )
                    else:
                        _apply_action_result(
                            "chatgpt",
                            "payment_link",
                            account,
                            {"ok": True, "data": data},
                            session,
                        )
                        _upsert_payment_link_generation(
                            session,
                            account_id=int(pending["account_id"]),
                            **_payment_link_pending_identity_kwargs(pending),
                            task_id=task_id,
                            request_id=request_id,
                            status="succeeded",
                            profile_hash=str(data.get("profile_hash") or profile.get("profile_hash") or ""),
                            link_type=str(data.get("link_type") or profile.get("link_type") or ""),
                            generation_kind=str(data.get("generation_kind") or payment_link_generation_kind(request_params)),
                            variant_key=str(data.get("variant_key") or payment_link_variant_key(request_params)),
                            remote_batch_id=str(data.get("remote_batch_id") or remote_batch_id),
                            remote_job_id=str(data.get("remote_job_id") or remote_job_id),
                            submitted_at=submitted_at,
                            started_at=started_at,
                            generated_at=str(data.get("generated_at") or _remote_time(remote.get("completed_at"))),
                            url=str(data.get("url") or ""),
                            result=data,
                        )
                        changed_account_ids.append(int(pending["account_id"]))
                        committed_cashier_urls.append(str(data.get("url") or ""))
                        committed_success_count += 1
                        committed_logs.append(
                            f"[OK] {generation_label}已生成并保存: {email}"
                        )
                else:
                    interruption = remote_status == "interrupted"
                    error_text = sanitize_error_message(remote.get("error") or "支付链接生成失败")[:1600]
                    committed_errors.append(f"{email}: {error_text}")
                    if interruption:
                        committed_interrupted_count += 1
                    _upsert_payment_link_generation(
                        session,
                        account_id=int(pending["account_id"]),
                        **_payment_link_pending_identity_kwargs(pending),
                        task_id=task_id,
                        request_id=request_id,
                        status="interrupted" if interruption else "failed",
                        profile_hash=str(profile.get("profile_hash") or ""),
                        link_type=str(profile.get("link_type") or ""),
                        generation_kind=payment_link_generation_kind(request_params),
                        variant_key=payment_link_variant_key(request_params),
                        remote_batch_id=remote_batch_id,
                        remote_job_id=remote_job_id,
                        submitted_at=submitted_at,
                        started_at=started_at,
                        generated_at=_remote_time(remote.get("completed_at")),
                        error=error_text,
                    )
                    label = "远端任务中断" if interruption else f"{generation_label}生成失败"
                    committed_logs.append(f"[FAIL] {label}: {email} - {error_text}")
                committed_terminal_request_ids.append(request_id)
                changed = True
            if changed:
                if changed_account_ids:
                    upsert_account_list_state_for_account_ids(
                        session,
                        changed_account_ids,
                        commit=False,
                    )
                session.commit()

        errors.extend(committed_errors)
        terminal_request_ids.update(committed_terminal_request_ids)
        success_count += committed_success_count
        remote_interrupted_count += committed_interrupted_count
        for cashier_url in committed_cashier_urls:
            _task_store.add_cashier_url(task_id, cashier_url)
        for message in committed_logs:
            _log(task_id, message)

    def _mark_unresolved_interrupted(reason: str) -> None:
        nonlocal remote_interrupted_count
        with Session(engine) as session:
            changed = False
            for pending in prepared:
                request_id = str(pending["request_id"])
                if request_id in terminal_request_ids:
                    continue
                account = session.get(AccountModel, int(pending["account_id"]))
                if _payment_link_pending_matches_account(account, pending):
                    _upsert_payment_link_generation(
                        session,
                        account_id=int(pending["account_id"]),
                        **_payment_link_pending_identity_kwargs(pending),
                        task_id=task_id,
                        request_id=request_id,
                        status="interrupted",
                        profile_hash=str(profile.get("profile_hash") or ""),
                        link_type=str(profile.get("link_type") or ""),
                        generation_kind=payment_link_generation_kind(request_params),
                        variant_key=payment_link_variant_key(request_params),
                        error=reason,
                    )
                    item_reason = reason
                else:
                    _delete_payment_link_generation_by_request_id(session, request_id)
                    item_reason = "账号已被删除或替换，未保留中断记录"
                errors.append(f"{pending.get('email') or pending.get('account_id')}: {item_reason}")
                terminal_request_ids.add(request_id)
                remote_interrupted_count += 1
                changed = True
            if changed:
                session.commit()

    try:
        client = LongLinkPaymentClient.from_env()
        profile = (
            client.get_profile(overrides=profile_overrides, force_refresh=True)
            if is_team_task
            else client.get_profile(force_refresh=True)
        )
        profile_hash = str(profile.get("profile_hash") or "").strip()
        if not profile_hash:
            raise LongLinkPaymentError("支付链接生成服务未返回配置哈希")
        request_params = _payment_link_params_from_profile(request_params, profile)
        generation_kind = payment_link_generation_kind(request_params)
        variant_key = payment_link_variant_key(request_params)
        team_data = request_params.get("team_plan_data") if isinstance(request_params.get("team_plan_data"), dict) else {}
        _task_store.update_meta(
            task_id,
            {
                "payment_link_profile": {
                    "link_type": str(profile.get("link_type") or ""),
                    "country": request_params["country"],
                    "billing_country": str(request_params.get("billing_country") or request_params["country"]),
                    "currency": request_params["currency"],
                    "profile_hash": profile_hash,
                    "effective_concurrency": int(profile.get("effective_concurrency") or 0),
                    "generation_kind": generation_kind,
                    "variant_key": variant_key,
                    "plan": request_params.get("plan") or "plus",
                    "team_plan_data": dict(team_data),
                    "promo_code_digest": str(request_params.get("promo_code_digest") or ""),
                    "checkout_proxy_region": str(request_params.get("checkout_proxy_region") or ""),
                    "checkout_ui_mode": str(request_params.get("checkout_ui_mode") or ""),
                },
                "payment_link_state": "preparing",
                "params": dict(request_params),
            },
        )
        _log(
            task_id,
            f"[{generation_label}] 已冻结 long-link 管理端配置 "
            f"type={profile.get('link_type') or '-'} profile={profile_hash[:12]} "
            f"country={request_params['country'] or '-'} currency={request_params['currency'] or '-'} "
            f"concurrency={profile.get('effective_concurrency') or '-'}"
            + (
                f" workspace={team_data.get('workspace_name') or '-'}"
                f" interval={team_data.get('price_interval') or '-'}"
                f" seats={team_data.get('seat_quantity') or '-'}"
                f" billing_country={request_params.get('billing_country') or '-'}"
                f" proxy_country={request_params.get('checkout_proxy_region') or '-'}"
                f" checkout_mode={request_params.get('checkout_ui_mode') or '-'}"
                if is_team_task
                else ""
            ),
        )

        for missing_id in missing_ids:
            _log(task_id, f"[MISS] 账号不存在: account_id={missing_id}")
            errors.append(f"account_id={missing_id}: 账号不存在")
        for item in skipped_items:
            _log(task_id, f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - {item.get('reason') or '已跳过'}")

        instance_id = str(os.getenv("APP_INSTANCE_ID") or "auto-gpt").strip() or "auto-gpt"
        with Session(engine) as session:
            for index, account_id in enumerate(account_ids, start=1):
                control.checkpoint(consume_skip=False)
                email = ""
                attempt_id = _claim_next_task_attempt(control)
                try:
                    control.checkpoint(attempt_id=attempt_id)
                    account = session.get(AccountModel, int(account_id or 0))
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    email = str(account.email or "")
                    if not primary_email:
                        primary_email = email
                    extra = account.get_extra()
                    params = _build_batch_payment_link_params(account, request_params)
                    cached = payment_link_cache_for_params(extra, params)
                    legacy_cached = (
                        extra.get("chatgpt_paypal_url")
                        if not is_team_task and isinstance(extra.get("chatgpt_paypal_url"), dict)
                        else {}
                    )
                    current_cached_url = _payment_link_current_cache_url(cached) or _payment_link_current_cache_url(legacy_cached)
                    skip_reason = _payment_link_skip_reason(
                        account,
                        force_refresh=force_refresh,
                        session=session,
                        exclude_request_id=f"{instance_id}:{task_id}:{int(account_id or 0)}",
                        variant_params=params,
                    )
                    if skip_reason:
                        # Preserve the existing already-paid reconciliation
                        # path: it is a terminal generation guard, but the
                        # local subscription state still needs one refresh.
                        cached_for_status = (
                            cached
                            if str(cached.get("link_status") or "").strip().lower() == "already_paid"
                            else legacy_cached
                            if str(legacy_cached.get("link_status") or "").strip().lower() == "already_paid"
                            else {}
                        )
                        if cached_for_status:
                            status_label = payment_link_status_label(cached_for_status.get("link_status"))
                            _log(task_id, f"[SYNC] {status_label}，开始同步账号状态: {email or account_id}")
                            _sync_payment_link_account_status(session, account)
                            skipped_count += 1
                            _log(task_id, f"[SYNC] 账号状态同步完成: {email or account_id}")
                            continue
                        if current_cached_url and "已有当前支付链接" in skip_reason:
                            if str(account.cashier_url or "").strip() != current_cached_url:
                                account.cashier_url = current_cached_url
                                account.updated_at = datetime.now(timezone.utc)
                                session.add(account)
                            _task_store.add_cashier_url(task_id, current_cached_url)
                            skipped_count += 1
                            _log(task_id, f"[SKIP] 已有当前支付链接: {email or account_id}")
                            continue
                        skipped_count += 1
                        _log(task_id, f"[SKIP] 支付链接生成跳过: {email or account_id} - {skip_reason}")
                        continue

                    raw_cached_url = str(cached.get("url") or "").strip()
                    cached_format = str(cached.get("payment_link_format") or "long_hosted").strip()
                    cached_url = _validated_payment_link_url(
                        normalize_payment_link_url(raw_cached_url, cached_format)
                    )
                    if cached_url and cached_url != raw_cached_url:
                        cached = {**cached, "url": cached_url}
                        store_payment_link_variant(extra, cached, make_current=True)
                        account.set_extra(extra)
                        session.add(account)
                    if cached_url and not force_refresh and payment_link_requires_status_sync(cached):
                        status_label = payment_link_status_label(cached.get("link_status"))
                        _log(task_id, f"[SYNC] {status_label}，开始同步账号状态: {email or account_id}")
                        _sync_payment_link_account_status(session, account)
                        skipped_count += 1
                        _log(task_id, f"[SYNC] 账号状态同步完成: {email or account_id}")
                        continue
                    if cached_url and not force_refresh and payment_link_expires_soon(cached):
                        _log(task_id, f"[REGEN] 缓存 PIX 支付链接已过期或将于 60 秒内到期，重新生成: {email or account_id}")
                    elif cached_url and not force_refresh and payment_link_requires_regeneration(cached):
                        status_label = payment_link_status_label(cached.get("link_status"))
                        _log(task_id, f"[REGEN] 缓存支付链接{status_label}，重新生成: {email or account_id}")
                    if skip_existing and not force_refresh and payment_link_cache_matches(cached, params):
                        if str(account.cashier_url or "").strip() != cached_url:
                            account.cashier_url = cached_url
                            account.updated_at = datetime.now(timezone.utc)
                            session.add(account)
                        _task_store.add_cashier_url(task_id, cached_url)
                        skipped_count += 1
                        _log(task_id, f"[SKIP] 已有可复用支付链接: {email or account_id}")
                        continue

                    token = _account_access_token(account)
                    if not token:
                        raise ValueError("账号缺少 Access Token")
                    request_id = f"{instance_id}:{task_id}:{int(account_id or 0)}"
                    prepared.append(
                        {
                            "account_id": int(account_id),
                            "email": email,
                            "account_email": str(account.email or "").strip().lower(),
                            "account_created_at": _payment_link_account_created_at_text(account.created_at),
                            "request_id": request_id,
                            "access_token": token,
                            "account_identity": _payment_link_account_identity(account),
                        }
                    )
                    _log(task_id, f"[SUBMIT] 已准备 {index}/{total}: {email or account_id}")
                except SkipCurrentAttemptRequested as exc:
                    skipped_count += 1
                    _log(task_id, f"[SKIP] 已跳过支付链接生成: {email or account_id} - {exc}")
                except StopTaskRequested:
                    raise
                except Exception as exc:
                    error_text = sanitize_error_message(exc)[:1600]
                    errors.append(f"{email or account_id}: {error_text}")
                    _log(task_id, f"[FAIL] 支付链接准备失败: {email or account_id} - {error_text}")
                finally:
                    control.finish_attempt(attempt_id)
                    _task_store.set_progress(task_id, f"{index}/{total}")
            session.commit()

        if prepared:
            # The account list was resolved before the worker started.  A
            # second task (or a cleanup/status refresh) may have changed one
            # of those accounts in the meantime.  Serialize the final local
            # claim so only the winner reaches the remote batch endpoint.
            guarded_prepared: list[dict[str, Any]] = []
            guarded_skipped: list[tuple[dict[str, Any], str]] = []
            with Session(engine) as guard_session:
                guard_session.exec(text("BEGIN IMMEDIATE"))
                for pending in prepared:
                    account_id = int(pending.get("account_id") or 0)
                    request_id = str(pending.get("request_id") or "").strip()
                    account = guard_session.get(AccountModel, account_id)
                    reason = "账号不存在"
                    if account is not None and not _payment_link_pending_matches_account(account, pending):
                        reason = "账号已被删除或替换"
                    elif account is not None:
                        reason = _payment_link_skip_reason(
                            account,
                            force_refresh=force_refresh,
                            session=guard_session,
                            exclude_request_id=request_id,
                            variant_params=_build_batch_payment_link_params(account, request_params),
                        )
                        if not reason and skip_existing and not force_refresh:
                            params = _build_batch_payment_link_params(account, request_params)
                            extra = account.get_extra()
                            cached = payment_link_cache_for_params(extra, params)
                            cached_format = str(cached.get("payment_link_format") or "long_hosted").strip()
                            cached_url = _validated_payment_link_url(
                                normalize_payment_link_url(
                                    str(cached.get("url") or "").strip(),
                                    cached_format,
                                )
                            )
                            if cached_url and payment_link_cache_matches(cached, params):
                                reason = "已有可复用支付链接"
                    if reason:
                        guarded_skipped.append((pending, reason))
                    else:
                        _upsert_payment_link_generation(
                            guard_session,
                            account_id=account_id,
                            **_payment_link_pending_identity_kwargs(pending),
                            task_id=task_id,
                            request_id=request_id,
                            status="submitting",
                            profile_hash=profile_hash,
                            link_type=str(profile.get("link_type") or ""),
                            generation_kind=payment_link_generation_kind(request_params),
                            variant_key=payment_link_variant_key(request_params),
                        )
                        guarded_prepared.append(pending)
                guard_session.commit()

            prepared = guarded_prepared
            for pending, reason in guarded_skipped:
                skipped_count += 1
                _log(
                    task_id,
                    f"[SKIP] 提交前重新检查跳过: {pending.get('email') or pending.get('account_id') or '-'} - {reason}",
                )

        if prepared:
            control.checkpoint(consume_skip=False)
            _task_store.update_meta(task_id, {"payment_link_state": "submitting", "payment_link_submitted": 0})
            submission_items = [
                {
                    "account_id": item["account_id"],
                    "email": item["email"],
                    "request_id": item["request_id"],
                    "access_token": item["access_token"],
                }
                for item in prepared
            ]
            response = (
                client.submit_batch(
                    items=submission_items,
                    expected_profile_hash=profile_hash,
                    profile_overrides=profile_overrides,
                )
                if is_team_task
                else client.submit_batch(
                    items=submission_items,
                    expected_profile_hash=profile_hash,
                )
            )
            remote_items = response.get("items") if isinstance(response.get("items"), list) else []
            submitted_request_ids = {str(item["request_id"]) for item in prepared}
            _record_remote_items([item for item in remote_items if isinstance(item, dict)])
            batch_ids = sorted(
                {
                    str(candidate or "").strip()
                    for candidate in [
                        response.get("batch_id"),
                        *(response.get("batch_ids") if isinstance(response.get("batch_ids"), list) else []),
                        *[
                            item.get("batch_id")
                            for item in remote_items
                            if isinstance(item, dict)
                        ],
                    ]
                    if str(candidate or "").strip()
                }
            )
            if submitted_request_ids - terminal_request_ids and not batch_ids:
                raise LongLinkPaymentError("支付链接生成服务未返回可轮询的远端批次 ID")
            _task_store.update_meta(
                task_id,
                {
                    "payment_link_state": "queued",
                    "payment_link_submitted": len(prepared),
                    "payment_link_batch_ids": batch_ids,
                    "payment_link_remote_summary": dict(response.get("summary") or {}),
                },
            )
            _log(task_id, f"[SUBMIT] 已批量提交 {len(prepared)} 个账号生成{generation_label}，开始统一轮询 {len(batch_ids)} 个远端批次")

            poll_interval = max(float(os.getenv("OPENAI_PAY_LONG_LINK_POLL_INTERVAL_SECONDS") or 2.0), 0.2)
            job_timeout = max(float(os.getenv("OPENAI_PAY_LONG_LINK_JOB_TIMEOUT_SECONDS") or 1800.0), 5.0)
            deadline = time.monotonic() + job_timeout
            last_poll_error = ""
            while submitted_request_ids - terminal_request_ids:
                if control.should_stop_starting_new_attempts() and not stop_after_submit_noted:
                    stop_after_submit_noted = True
                    _log(task_id, "[STOP] 远端批次已全部受理，停止请求不会取消远端任务；继续轮询并保存终态")
                if time.monotonic() >= deadline:
                    _mark_unresolved_interrupted("远端批次轮询超时，结果状态未知")
                    _log(task_id, "[INTERRUPTED] 远端批次轮询超时，未完成项已标记为中断")
                    break
                poll_failed = False
                for batch_id in batch_ids:
                    try:
                        batch = client.get_batch(batch_id)
                        batch_items = batch.get("items") if isinstance(batch.get("items"), list) else []
                        _record_remote_items([item for item in batch_items if isinstance(item, dict)])
                        _task_store.update_meta(
                            task_id,
                            {
                                "payment_link_state": str(batch.get("status") or "running"),
                                "payment_link_remote_summary": dict(batch.get("summary") or {}),
                            },
                        )
                    except LongLinkPaymentError as exc:
                        poll_failed = True
                        error_text = sanitize_error_message(exc)[:600]
                        if error_text != last_poll_error:
                            _log(task_id, f"[WARN] 远端批次查询失败，将重试: {error_text}")
                            last_poll_error = error_text
                completed_count = len(terminal_request_ids) + skipped_count + len(skipped_items)
                _task_store.set_progress(task_id, f"{min(completed_count, total)}/{total}")
                if submitted_request_ids - terminal_request_ids:
                    if poll_failed:
                        time.sleep(min(max(poll_interval, 1.0), 5.0))
                    else:
                        time.sleep(poll_interval)

        if remote_interrupted_count:
            final_status = "interrupted"
            aggregate = "remote_interrupted"
        elif errors and success_count:
            final_status = "partial"
            aggregate = "partial_failure"
        elif errors:
            final_status = "failed"
            aggregate = "total_failure"
        else:
            final_status = "done"
            aggregate = "completed_success"
        total_skipped = skipped_count + len(skipped_items)
        summary_message = (
            f"批量{generation_label}生成完成: 成功 {success_count} 个，跳过 {total_skipped} 个，"
            f"失败 {len(errors)} 个，中断 {remote_interrupted_count} 个"
        )
        _task_store.update_meta(
            task_id,
            {
                "payment_link_state": aggregate,
                "payment_link_aggregate_status": aggregate,
                "runtime_success": success_count,
                "runtime_skipped": skipped_count,
                "runtime_errors": list(errors),
                "runtime_interrupted": remote_interrupted_count,
            },
        )
        _log(task_id, f"[SUMMARY] {summary_message}")
        _save_task_log(
            "chatgpt",
            primary_email,
            final_status,
            error="" if final_status == "done" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": f"batch_payment_link_{aggregate}",
                    "source": "batch_payment_link",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status=final_status,
            success=success_count,
            skipped=total_skipped,
            errors=errors,
            error="" if final_status == "done" else summary_message,
        )
    except StopTaskRequested as exc:
        _mark_unresolved_interrupted("任务在远端批次提交前停止")
        _log(task_id, f"[STOP] {exc}")
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_payment_link_stopped",
                    "source": "batch_payment_link",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors,
            error=str(exc),
        )
    except Exception as exc:
        error_text = sanitize_error_message(exc)[:1600]
        _mark_unresolved_interrupted(error_text)
        _log(task_id, f"[FAIL] 批量{generation_label}生成失败: {error_text}")
        _save_task_log(
            "chatgpt",
            primary_email,
            "interrupted" if prepared else "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_payment_link_remote_interrupted" if prepared else "batch_payment_link_failed",
                    "source": "batch_payment_link",
                    "meta": dict(_task_store.snapshot(task_id).get("meta") or {}),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="interrupted" if prepared else "failed",
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors or [error_text],
            error=error_text,
        )
    finally:
        _task_store.cleanup()


def _run_batch_resume_subscription_auth(
    task_id: str,
    account_ids: list[int],
    allow_phone_verification: bool = False,
):
    from api.actions import (
        _apply_chatgpt_resume_auth_result,
        _execute_chatgpt_resume_subscription_auth,
    )
    from core.config_store import config_store
    from services.chatgpt_core.phone_service import SharedPhoneGatewayService, create_phone_service

    control = _task_store.control_for(task_id)

    def stop_checker() -> None:
        control.checkpoint(consume_skip=False)

    def task_log(message: str) -> None:
        stop_checker()
        _log(task_id, message)

    total = max(len(account_ids), 1)
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    primary_email = ""

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    skipped_items = list(meta.get("skipped_items") or [])
    missing_ids = list(meta.get("missing_ids") or [])
    phone_modes = _resolve_resume_auth_phone_modes(allow_phone_verification)
    shared_phone_service = None
    if phone_modes.get("allow_add_phone_verification"):
        phone_config = config_store.get_all().copy()
        provider = str(
            phone_config.get("chatgpt_phone_verification_provider")
            or phone_config.get("phone_verification_provider")
            or "smstome"
        ).strip().lower()
        if provider in {"local_gateway", "gateway", "local"}:
            phone_config["_task_stop_checker"] = stop_checker
            phone_config["_current_task_id"] = task_id
            base_phone_service = create_phone_service(phone_config, log_fn=task_log)
            shared_phone_service = SharedPhoneGatewayService(
                base_phone_service,
                log_fn=task_log,
                stop_checker=stop_checker,
            )
            _log(task_id, "[补抓] 本地接码网关已启用全局串行通道，所有补抓请求会排队复用同一个手机号")

    try:
        for missing_id in missing_ids:
            _log(task_id, f"[MISS] 账号不存在: account_id={missing_id}")
            errors.append(f"account_id={missing_id}: 账号不存在")

        for index, account_id in enumerate(account_ids, start=1):
            control.checkpoint(consume_skip=False)
            email = ""
            attempt_id = _claim_next_task_attempt(control)
            try:
                with Session(engine) as session:
                    account = session.get(AccountModel, int(account_id or 0))
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    email = str(account.email or "")
                    if not primary_email:
                        primary_email = email

                _task_timeline_log(
                    task_id,
                    task="补抓Auth",
                    email=email,
                    account_id=account_id,
                    item_index=index,
                    item_total=total,
                    phase="prepare",
                    phase_label="准备补抓 Auth",
                    stage_index=1,
                    stage_total=5,
                    message=f"开始：手机验证策略={_format_phone_modes_for_log(phone_modes)}",
                    next_step="恢复邮箱状态并进入 OAuth 登录",
                    reset_started_at=True,
                )
                control.checkpoint(attempt_id=attempt_id)
                with Session(engine) as session:
                    account = session.get(AccountModel, int(account_id or 0))
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    result = _execute_chatgpt_resume_subscription_auth(
                        account,
                        allow_phone_verification=bool(allow_phone_verification),
                        log_fn=task_log,
                        shared_phone_service=shared_phone_service,
                        stop_checker=lambda: control.checkpoint(attempt_id=attempt_id),
                    )
                    session.refresh(account)
                    _apply_chatgpt_resume_auth_result(account, result, session)
                    if not bool(result.get("ok")):
                        data = result.get("data") if isinstance(result.get("data"), dict) else {}
                        raise ValueError(str(result.get("error") or data.get("message") or "补抓Auth失败"))
                pipeline_continuation = _resume_registration_pipeline_after_auth(
                    account_id,
                    log_fn=lambda message: _log(task_id, message),
                )
                if bool(pipeline_continuation.get("resumed")):
                    continuation_results = meta.get("registration_pipeline_continuations")
                    if not isinstance(continuation_results, list):
                        continuation_results = []
                    continuation_results.append(
                        {
                            "account_id": int(account_id or 0),
                            "email": email,
                            **pipeline_continuation,
                        }
                    )
                    meta["registration_pipeline_continuations"] = continuation_results[-500:]
                    _task_store.update_meta(
                        task_id,
                        {
                            "registration_pipeline_continuations": continuation_results[-500:]
                        },
                    )
                success_count += 1
                _task_timeline_log(
                    task_id,
                    task="补抓Auth",
                    email=email,
                    account_id=account_id,
                    item_index=index,
                    item_total=total,
                    phase="done",
                    phase_label="补抓结果",
                    stage_index=5,
                    stage_total=5,
                    message="结果：refresh_token 已保存",
                    next_step="处理下一个账号",
                    reset_started_at=True,
                )
            except SkipCurrentAttemptRequested as exc:
                skipped_count += 1
                _task_timeline_log(
                    task_id,
                    task="补抓Auth",
                    email=email,
                    account_id=account_id,
                    item_index=index,
                    item_total=total,
                    phase="skipped",
                    phase_label="已跳过",
                    stage_index=5,
                    stage_total=5,
                    message=str(exc),
                    next_step="处理下一个账号",
                    reset_started_at=True,
                )
            except StopTaskRequested:
                raise
            except Exception as exc:
                error_text = str(exc or "补抓Auth失败")
                errors.append(f"{email or account_id}: {error_text}")
                _task_timeline_log(
                    task_id,
                    task="补抓Auth",
                    email=email,
                    account_id=account_id,
                    item_index=index,
                    item_total=total,
                    phase="failed",
                    phase_label="补抓失败",
                    stage_index=5,
                    stage_total=5,
                    message=error_text,
                    next_step="查看 Debug 详情",
                    reset_started_at=True,
                )
            finally:
                control.finish_attempt(attempt_id)
                _task_store.set_progress(task_id, f"{index}/{total}")

        final_status = "done"
        summary_message = (
            f"批量补抓Auth完成: 成功 {success_count} 个，跳过 {skipped_count + len(skipped_items)} 个，失败 {len(errors)} 个"
        )
        _log(task_id, f"[SUMMARY] {summary_message}")
        log_status = "success" if not errors else "failed"
        _save_task_log(
            "chatgpt",
            primary_email,
            log_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_resume_subscription_auth_success" if log_status == "success" else "batch_resume_subscription_auth_failed",
                    "source": "batch_resume_subscription_auth",
                    "meta": {
                        **meta,
                        "runtime_success": success_count,
                        "runtime_skipped": skipped_count,
                        "runtime_errors": errors,
                        "allow_phone_verification": bool(allow_phone_verification),
                    },
                },
            ),
        )
        _task_store.finish(
            task_id,
            status=final_status,
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors,
            error="" if not errors else summary_message,
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        _task_timeline_log(
            task_id,
            task="补抓Auth",
            item_index=total if total > 0 else None,
            item_total=total if total > 0 else None,
            phase="stopped",
            phase_label="已停止",
            stage_index=5,
            stage_total=5,
            message=str(exc),
            next_step="任务停止",
            reset_started_at=True,
        )
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "batch_resume_subscription_auth_stopped",
                    "source": "batch_resume_subscription_auth",
                    "meta": {
                        **meta,
                        "runtime_success": success_count,
                        "runtime_skipped": skipped_count,
                        "runtime_errors": errors,
                    },
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count + len(skipped_items),
            errors=errors,
            error=str(exc),
        )
    finally:
        if shared_phone_service is not None:
            try:
                shared_phone_service.release_current(reason="batch resume auth finished", terminal=False)
            except Exception as exc:
                _log(task_id, f"[补抓] 释放共享手机号失败: {exc}")
        _clear_task_current(task_id)
        _task_store.cleanup()


def _phone_binding_prefix4(value: Any) -> str:
    from services.chatgpt_core.phone_pool_repository import _phone_effective_digits

    digits = _phone_effective_digits(str(value or ""))
    return digits[:4] if len(digits) >= 4 else ""


def _build_phone_prefix_sample_summary(
    phone_items: list[dict[str, Any]],
    runtime_results: list[dict[str, Any]],
    *,
    phone_signup: bool = False,
) -> dict[str, Any]:
    selected_by_prefix: dict[str, list[str]] = {}
    selected_phones: set[str] = set()
    for item in phone_items:
        phone = str(item.get("phone") or "").strip()
        prefix = str(item.get("prefix4") or _phone_binding_prefix4(phone)).strip()
        if not phone or not prefix or phone in selected_phones:
            continue
        selected_phones.add(phone)
        selected_by_prefix.setdefault(prefix, []).append(phone)

    outcomes: dict[str, str] = {}
    unavailable_statuses = {
        "openai_rejected",
        "openai_phone_limit",
        "api_no_code",
        "api_error",
        "rate_limited",
    }
    for result in runtime_results:
        phone = str(result.get("phone") or "").strip()
        if phone not in selected_phones:
            continue
        status = str(result.get("status") or "").strip()
        if status in {"bound", "sms_probe_received", "registered_phone_signup", "phone_already_used"}:
            outcomes[phone] = "available"
        elif outcomes.get(phone) != "available":
            if phone_signup:
                try:
                    from services.chatgpt_core.phone_pool_repository import is_phone_signup_prefix_unavailable_signal

                    reason = str(result.get("reason") or result.get("error") or result.get("message") or "")
                    if is_phone_signup_prefix_unavailable_signal(status, reason):
                        outcomes[phone] = "unavailable"
                except Exception:
                    pass
            elif status in unavailable_statuses:
                outcomes[phone] = "unavailable"

    assessment_counts = {
        "positive_sample": 0,
        "negative_sample": 0,
        "mixed_sample": 0,
        "untested": 0,
    }
    items: list[dict[str, Any]] = []
    negative_sample_prefixes: list[str] = []
    for prefix in sorted(selected_by_prefix):
        phones = selected_by_prefix[prefix]
        available_count = sum(1 for phone in phones if outcomes.get(phone) == "available")
        unavailable_count = sum(1 for phone in phones if outcomes.get(phone) == "unavailable")
        untested_count = max(len(phones) - available_count - unavailable_count, 0)
        if available_count > 0 and unavailable_count > 0:
            assessment = "mixed_sample"
        elif available_count > 0:
            assessment = "positive_sample"
        elif unavailable_count > 0:
            assessment = "negative_sample"
            negative_sample_prefixes.append(prefix)
        else:
            assessment = "untested"
        assessment_counts[assessment] += 1
        items.append(
            {
                "prefix": prefix,
                "status": assessment,
                "assessment": assessment,
                "sample_only": True,
                "selected_count": len(phones),
                "tested_count": available_count + unavailable_count,
                "available_count": available_count,
                "unavailable_count": unavailable_count,
                "untested_count": untested_count,
                "phones": list(phones),
            }
        )

    positive_count = assessment_counts["positive_sample"]
    negative_count = assessment_counts["negative_sample"]
    mixed_count = assessment_counts["mixed_sample"]
    return {
        "sample_only": True,
        "prefix_count": len(items),
        "selected_phone_count": len(selected_phones),
        "tested_phone_count": sum(1 for phone in selected_phones if phone in outcomes),
        "positive_sample_prefix_count": positive_count,
        "negative_sample_prefix_count": negative_count,
        "mixed_sample_prefix_count": mixed_count,
        "untested_prefix_count": assessment_counts["untested"],
        "negative_sample_prefixes": negative_sample_prefixes,
        # Compatibility aliases for historical task-detail readers. These are
        # sample outcomes, not authoritative prefix eligibility decisions.
        "available_prefix_count": positive_count,
        "unavailable_prefix_count": negative_count,
        "partial_prefix_count": mixed_count,
        "unavailable_prefixes": negative_sample_prefixes,
        "items": items,
    }


def _phone_binding_error_status(error_text: str) -> str:
    lowered = str(error_text or "").strip().lower()
    if not lowered:
        return "unknown"
    if any(
        marker in lowered
        for marker in (
            "api_forward_error",
            "手机号 api relay",
            "手机号 api 转发",
            "route_not_registered",
            "host_not_registered",
            "redirect_blocked",
            "response_too_large",
            "upstream_unavailable",
            "relay_unavailable",
            "relay_request_failed",
        )
    ):
        return "api_forward_error"
    if any(
        marker in lowered
        for marker in (
            "phone number already in use",
            "phone_number_in_use",
            "手机号已被使用",
            "号码已被使用",
            "手机号已使用",
            "号码已使用",
        )
    ):
        return "phone_already_used"
    if any(
        marker in lowered
        for marker in (
            "already linked to the maximum",
            "maximum number of accounts",
            "phone_number_already_linked",
            "phone_number_max",
            "phone_max",
            "账号绑定上限",
            "绑定上限",
        )
    ):
        return "openai_phone_limit"
    if any(
        marker in lowered
        for marker in (
            "phone number is invalid",
            "invalid phone number",
            "invalid phone",
            "unable to send sms",
            "not a valid mobile number",
            "unsupported phone number",
            "phone number not supported",
            "carrier not supported",
            "detected suspicious behavior from phone numbers",
            "suspicious behavior from phone numbers",
            "电话号码无效",
            "手机号无效",
            "发送短信验证失败",
            "号码无效",
            "号码不支持",
            "手机号不支持",
        )
    ):
        return "openai_rejected"
    if any(marker in lowered for marker in ("未收到短信验证码", "no verification code", "达到同号重发上限")):
        return "api_no_code"
    if any(marker in lowered for marker in ("收码 api", "api 请求失败", "api 响应不是 json", "api 返回失败")):
        return "api_error"
    if "429" in lowered and any(
        marker in lowered
        for marker in (
            "提交邮箱失败",
            "authorize_continue",
            "/authorize/continue",
            "oauth",
            "login_session",
        )
    ):
        return "account_auth_error"
    if any(marker in lowered for marker in ("rate limit", "429", "too many verification requests", "验证请求过多")):
        return "rate_limited"
    if any(marker in lowered for marker in ("timeout", "timed out", "network", "connection", "proxy", "ssl", "tls")):
        return "browser_error"
    if any(
        marker in lowered
        for marker in (
            "mailbox_state 缺失",
            "账号邮箱为空",
            "auth",
            "oauth 登录失败",
            "refresh_token",
            "提交邮箱失败",
            "sign-in session is no longer valid",
            "invalid_request_error",
            "invalid_state",
        )
    ):
        return "account_auth_error"
    return "unknown"


def _phone_binding_status_label(status: str) -> str:
    return {
        "bound": "绑定成功",
        "sms_probe_received": "已收码，未提交",
        "account_phone_bound": "账号已绑定手机号码",
        "openai_rejected": "OpenAI 拒绝号码",
        "openai_phone_limit": "号码达到 OpenAI 绑定上限",
        "phone_already_used": "手机号已被使用",
        "api_no_code": "OpenAI 已发码但 API 未收到",
        "api_error": "收码 API 异常",
        "api_forward_error": "API 转发暂时不可用",
        "rate_limited": "OpenAI 限流",
        "browser_error": "浏览器/网络异常",
        "account_auth_error": "账号 Auth 异常",
        "account_missing": "账号不存在",
        "not_tested": "未测试",
        "unknown": "未知",
    }.get(str(status or ""), str(status or "unknown"))


def _phone_binding_effective_api_fields(
    item: dict[str, Any],
    phone_service: Any = None,
) -> tuple[str, str, str]:
    """Return request URL, supplier URL, and request raw line for a result."""
    phone = str((item or {}).get("phone") or "").strip()
    candidates: list[Any] = []
    if phone_service is not None:
        candidates.extend(list(getattr(phone_service, "completed_entries", None) or []))
        current = getattr(phone_service, "current_entry", None)
        if current is not None:
            candidates.append(current)
        for cancelled in list(getattr(phone_service, "cancelled_entries", None) or []):
            candidate = cancelled[0] if isinstance(cancelled, (tuple, list)) and cancelled else cancelled
            if candidate is not None:
                candidates.append(candidate)
    effective_entry = None
    for candidate in reversed(candidates):
        if str(getattr(candidate, "phone", "") or "").strip() == phone:
            effective_entry = candidate
            break
    request_api_url = str(
        getattr(effective_entry, "api_url", "")
        or (item or {}).get("api_url")
        or ""
    ).strip()
    source_api_url = str(
        getattr(effective_entry, "source_api_url", "")
        or (item or {}).get("source_api_url")
        or request_api_url
    ).strip()
    raw_line = str(
        getattr(effective_entry, "raw_line", "")
        or (item or {}).get("raw_line")
        or (f"{phone}----{request_api_url}" if request_api_url else phone)
    ).strip()
    return request_api_url, source_api_url, raw_line


def _persist_phone_binding_result(
    account: AccountModel,
    phone_result: dict[str, Any],
    *,
    task_id: str,
    raw_line: str = "",
) -> None:
    phone = str(phone_result.get("phone") or "").strip()
    api_url = str(phone_result.get("api_url") or "").strip()
    source_api_url = str(phone_result.get("source_api_url") or api_url).strip()
    if not phone and not api_url:
        return

    try:
        extra = account.get_extra()
    except Exception:
        extra = {}
    if not isinstance(extra, dict):
        extra = {}

    binding = {
        "phone": phone,
        "api_url": api_url,
        "source_api_url": source_api_url,
        "raw_line": str(raw_line or phone_result.get("raw_line") or "").strip(),
        "account_id": int(phone_result.get("account_id") or getattr(account, "id", 0) or 0),
        "email": str(phone_result.get("email") or getattr(account, "email", "") or "").strip(),
        "task_id": str(task_id or "").strip(),
        "source": "phone_binding_test",
        "status": "bound",
        "status_label": _phone_binding_status_label("bound"),
        "api_expired_date": str(phone_result.get("api_expired_date") or "").strip(),
        "code_time": str(phone_result.get("code_time") or "").strip(),
        "code_extracted": bool(phone_result.get("code_extracted")),
        "bound_at": str(phone_result.get("finished_at") or beijing_now_iso()),
    }
    extra["chatgpt_phone_binding"] = binding
    if phone:
        extra["chatgpt_bound_phone"] = {
            "phone": phone,
            "phone_number": phone,
            "api_url": api_url,
            "source_api_url": source_api_url,
            "source": "phone_binding_test",
            "updated_at": binding["bound_at"],
            "status": "bound",
        }
        extra["chatgpt_bound_phone_number"] = phone
    history = extra.get("chatgpt_phone_binding_history")
    if not isinstance(history, list):
        history = []
    history.append(binding)
    extra["chatgpt_phone_binding_history"] = history[-20:]
    account.set_extra(extra)
    try:
        from datetime import datetime, timezone

        account.updated_at = datetime.now(timezone.utc)
    except Exception:
        pass


def _run_phone_binding_test_concurrent(
    task_id: str,
    account_ids: list[int],
    phone_items: list[dict[str, Any]],
    settings: dict[str, Any],
):
    """Concurrent phone-binding runner.

    The legacy runner below stays the source of truth for serial mode.  This
    path only runs when the task explicitly requests concurrency > 1, and keeps
    all mutable task state behind locks so multiple account workers cannot reuse
    the same phone item or overwrite each other's result snapshots.
    """
    from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait

    from api.actions import (
        _apply_chatgpt_resume_auth_result,
        _execute_chatgpt_resume_subscription_auth,
    )
    from core.proxy_utils import is_proxy_error_text
    from services.chatgpt_core.phone_service import UploadedPhoneEntry, UploadedPhoneService

    control = _task_store.control_for(task_id)
    use_pool = _is_truthy(settings.get("use_pool"))
    total_accounts = max(len(account_ids), 1)
    requested_concurrency = _parse_positive_int(settings.get("requested_concurrency") or settings.get("concurrency"), 1)
    effective_concurrency = max(1, min(_parse_positive_int(settings.get("concurrency"), 1), total_accounts))
    account_interval_seconds = max(_parse_positive_int(settings.get("account_interval_seconds"), 60), 0)
    prefix_bind_enabled = _is_truthy(settings.get("prefix_bind_enabled"))
    prefix_sample_enabled = _is_truthy(settings.get("prefix_sample_enabled"))
    runtime_pool_mode = _normalize_phone_binding_pool_mode(
        settings.get("phone_pool_mode"),
        prefix_bind_enabled=prefix_bind_enabled,
        prefix_sample_enabled=prefix_sample_enabled,
        unavailable_number_test_enabled=_is_truthy(settings.get("unavailable_number_test_enabled")),
    )
    unavailable_number_test_enabled = runtime_pool_mode == "unavailable_numbers"
    phone_number_filter = _normalize_phone_binding_number_filter(
        settings.get("prefix_number_filter") or settings.get("phone_number_filter")
    )
    if unavailable_number_test_enabled:
        phone_number_filter = "unavailable"
    elif not prefix_bind_enabled:
        phone_number_filter = "available"
    prefix_sample_filter = str(settings.get("prefix_sample_filter") or "all").strip().lower()
    if prefix_sample_filter not in {"all", "available", "rejected"}:
        prefix_sample_filter = "all"
    prefix_sms_probe_only = _is_truthy(settings.get("prefix_sms_probe_only"))
    if unavailable_number_test_enabled or (prefix_bind_enabled and phone_number_filter != "available"):
        use_pool = False
    selected_prefixes = [
        str(prefix or "").strip()
        for prefix in (settings.get("selected_prefixes") or [])
        if str(prefix or "").strip()
    ]

    state_lock = threading.RLock()
    allocation_lock = threading.RLock()
    runtime_results: list[dict[str, Any]] = []
    account_results: list[dict[str, Any]] = []
    bound_phone_lines: list[str] = []
    bound_phone_results: list[dict[str, Any]] = []
    errors: list[str] = []
    success_count = 0
    skipped_count = 0
    completed_accounts = 0
    primary_email = ""
    no_phone_available = False

    phone_cursor = 0
    dynamic_phone_attempts = 0
    claimed_phones_this_run: set[str] = set()
    terminal_phones_this_run: set[str] = set()
    successful_phones_this_run: set[str] = set()

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total_accounts}")
    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    missing_ids = list(meta.get("missing_ids") or [])
    parse_errors = list(meta.get("parse_errors") or [])

    pool_repo = None
    if use_pool or any(bool(item.get("pool_managed")) for item in phone_items):
        from services.chatgpt_core.phone_pool_repository import PhonePoolRepository

        pool_repo = PhonePoolRepository()

    def _safe_int(value: Any, default: int = 0) -> int:
        try:
            return int(value or 0)
        except Exception:
            return int(default or 0)

    def _build_phone_binding_candidate_proxies() -> list[tuple[str, object | None, str]]:
        from core.proxy_utils import resolve_task_proxy_candidates

        return resolve_task_proxy_candidates(
            dict(settings or {}),
            fallback_proxy=None,
            default_mode="global",
            target="chatgpt",
        )

    def _report_phone_proxy_success(proxy_pool: Any, proxy_url: str, phone_service: Any, result: dict[str, Any] | None = None) -> None:
        if proxy_pool is None or not proxy_url:
            return
        if phone_was_touched(phone_service) or bool((result or {}).get("ok")):
            try:
                proxy_pool.report_success(proxy_url)
            except Exception:
                pass

    def _report_phone_proxy_fail(proxy_pool: Any, proxy_url: str, error_text: str) -> None:
        if proxy_pool is None or not proxy_url or not is_proxy_error_text(error_text):
            return
        try:
            proxy_pool.report_fail(proxy_url)
        except Exception:
            pass

    def phone_was_touched(phone_service: Any) -> bool:
        return bool(
            getattr(phone_service, "last_sms_sent", False)
            or getattr(phone_service, "completed_entries", None)
            or getattr(phone_service, "cancelled_entries", None)
            or getattr(phone_service, "last_expired_date", "")
            or getattr(phone_service, "last_code_time", "")
        )

    def result_for_phone(
        item: dict[str, Any],
        status: str,
        *,
        account_id: int = 0,
        email: str = "",
        reason: str = "",
        code_received: bool = False,
        phone_service: Any = None,
    ) -> dict[str, Any]:
        api_url, source_api_url, result_raw_line = _phone_binding_effective_api_fields(item, phone_service)
        return {
            "line_no": _safe_int(item.get("line_no")),
            "phone": str(item.get("phone") or ""),
            "prefix4": str(item.get("prefix4") or _phone_binding_prefix4(item.get("phone"))),
            "api_url": api_url,
            "source_api_url": source_api_url,
            "raw_line": result_raw_line,
            "status": status,
            "status_label": _phone_binding_status_label(status),
            "account_id": int(account_id or 0),
            "email": str(email or ""),
            "reason": str(reason or ""),
            "code_received": bool(code_received),
            "api_expired_date": str(getattr(phone_service, "last_expired_date", "") or ""),
            "code_time": str(getattr(phone_service, "last_code_time", "") or ""),
            "code_extracted": bool(getattr(phone_service, "last_code_was_extracted", False)),
            "finished_at": beijing_now_iso(),
        }

    def sync_meta() -> None:
        with state_lock:
            safe_runtime_results = [sanitize_phone_result(item) for item in runtime_results]
            safe_bound_phone_results = [sanitize_phone_result(item) for item in bound_phone_results]
            updates = {
                "runtime_results": safe_runtime_results,
                "account_results": sanitize_task_detail(account_results),
                "bound_phone_lines": [redact_raw_phone_line(line) for line in bound_phone_lines],
                "bound_phone_results": safe_bound_phone_results,
                "runtime_success": success_count,
                "runtime_skipped": skipped_count,
                "runtime_errors": [sanitize_error_message(err) for err in errors],
                "no_phone_available": no_phone_available,
                "completed_accounts": completed_accounts,
                "requested_concurrency": requested_concurrency,
                "effective_concurrency": effective_concurrency,
            }
            if prefix_sample_enabled:
                updates["prefix_summary"] = _build_phone_prefix_sample_summary(phone_items, runtime_results)
        _task_store.update_meta(task_id, updates)

    def record_pool_result(item: dict[str, Any], status: str, *, reason: str = "", email: str = "", api_expired_date: str = "") -> None:
        if pool_repo is None or not bool(item.get("pool_managed")):
            return
        phone = str(item.get("phone") or "")
        try:
            pool_repo.record_task_status(phone, status, reason=reason, email=email)
            expired = str(api_expired_date or "").strip()
            if expired and hasattr(pool_repo, "update_api_expired_date"):
                pool_repo.update_api_expired_date(phone, expired)
        except Exception as exc:
            _log(task_id, f"[手机号绑定][号码池] 回写失败｜手机号={phone or '-'}｜原因={exc}")

    def pool_record_to_item(record: Any, line_no: int) -> dict[str, Any]:
        phone_value = str(getattr(record, "phone_e164", "") or "")
        api_url_value = str(getattr(record, "api_url", "") or "")
        return {
            "id": _safe_int(getattr(record, "id", 0)),
            "pool_id": _safe_int(getattr(record, "id", 0)),
            "line_no": int(line_no or 0),
            "phone": phone_value,
            "api_url": api_url_value,
            "source_api_url": api_url_value,
            "raw_line": f"{phone_value}----{api_url_value}",
            "pool_managed": True,
            "prefix4": _phone_binding_prefix4(phone_value),
        }

    def claim_phone_item() -> tuple[dict[str, Any], int, str] | None:
        nonlocal phone_cursor, dynamic_phone_attempts, no_phone_available
        with allocation_lock:
            excluded_phones = set(terminal_phones_this_run) | set(successful_phones_this_run) | set(claimed_phones_this_run)
            if use_pool:
                if pool_repo is None:
                    no_phone_available = True
                    return None
                available_candidates = (
                    pool_repo.list_available_by_prefixes(selected_prefixes)
                    if prefix_bind_enabled and selected_prefixes and hasattr(pool_repo, "list_available_by_prefixes")
                    else pool_repo.list_available()
                )
                selected = None
                for candidate in available_candidates:
                    phone_value = str(getattr(candidate, "phone_e164", "") or "")
                    if not phone_value or phone_value in excluded_phones:
                        continue
                    if not str(getattr(candidate, "api_url", "") or ""):
                        continue
                    selected = candidate
                    break
                if selected is None:
                    no_phone_available = True
                    return None
                dynamic_phone_attempts += 1
                item = pool_record_to_item(selected, dynamic_phone_attempts)
                claimed_phones_this_run.add(str(item.get("phone") or ""))
                return item, dynamic_phone_attempts, "动态"

            total_phones = len(phone_items)
            while phone_cursor < total_phones:
                item = dict(phone_items[phone_cursor] or {})
                phone_index = phone_cursor + 1
                phone_cursor += 1
                phone = str(item.get("phone") or "").strip()
                if phone and phone in excluded_phones:
                    _log(task_id, f"[手机号绑定][跳过] 重复号码｜号码={phone_index}/{total_phones}｜手机号={phone}｜原因=已在本轮被占用或判定不可继续使用")
                    continue
                if phone:
                    claimed_phones_this_run.add(phone)
                return item, phone_index, str(total_phones)
            no_phone_available = True
            return None

    def release_phone(item: dict[str, Any], *, terminal: bool = False, successful: bool = False, reusable: bool = False) -> None:
        phone = str((item or {}).get("phone") or "").strip()
        if not phone:
            return
        with allocation_lock:
            claimed_phones_this_run.discard(phone)
            if terminal:
                terminal_phones_this_run.add(phone)
            elif successful:
                successful_phones_this_run.add(phone)
            elif reusable:
                successful_phones_this_run.discard(phone)
                terminal_phones_this_run.discard(phone)

    def result_error_text(result: dict[str, Any], default: str = "手机号绑定失败") -> str:
        data = result.get("data") if isinstance(result.get("data"), dict) else {}
        return str(result.get("error") or data.get("message") or default)

    def should_keep_phone_for_next_account(status: str, phone_service: Any) -> bool:
        return status in {"account_auth_error", "browser_error", "unknown"} and not phone_was_touched(phone_service)

    def is_account_rate_limit_error(status: str, error_text: str) -> bool:
        if status != "account_auth_error":
            return False
        lowered = str(error_text or "").strip().lower()
        if not any(marker in lowered for marker in ("429", "rate limit", "too many request", "请求过快", "限流")):
            return False
        return any(
            marker in lowered
            for marker in (
                "提交邮箱失败",
                "authorize_continue",
                "/authorize/continue",
                "oauth",
                "login_session",
                "rate limit",
                "too many request",
                "请求过快",
                "限流",
            )
        )

    def mark_account_rate_limited_for_recovery(account_id: int, email: str, error_text: str) -> str:
        if account_id <= 0:
            return ""
        try:
            with Session(engine) as rate_session:
                account = rate_session.get(AccountModel, account_id)
                if account is None or account.platform != "chatgpt":
                    return ""
                mark_account_rate_limited(account)
                recover_at = str(account_rate_limit_payload(account).get("recover_at") or "")
                rate_session.add(account)
                rate_session.commit()
            _log(task_id, f"[限流] 账号已标记限流，预计恢复: {email or account_id} -> {recover_at or '1小时后'}")
            return recover_at
        except Exception as exc:
            _log(task_id, f"[限流] 账号限流状态写入失败: {email or account_id} - {exc}")
            return ""

    def parse_auth_retry_delays(value: Any) -> list[int]:
        default_delays = [5, 10, 20]
        if value in (None, ""):
            return default_delays
        if isinstance(value, str):
            candidates = value.replace("，", ",").replace(";", ",").split(",")
        elif isinstance(value, (list, tuple, set)):
            candidates = list(value)
        else:
            candidates = [value]
        delays: list[int] = []
        for item in candidates:
            try:
                delay = int(float(str(item).strip()))
            except Exception:
                continue
            if delay < 0:
                continue
            delays.append(min(delay, 120))
            if len(delays) >= 3:
                break
        return delays or default_delays

    auth_retry_delays_seconds = parse_auth_retry_delays(
        settings.get("phone_binding_auth_retry_delays_seconds")
        if settings.get("phone_binding_auth_retry_delays_seconds") not in (None, "")
        else settings.get("auth_retry_delays_seconds")
    )

    def wait_seconds(seconds: float, *, attempt_id: int | None = None) -> None:
        remaining = max(float(seconds or 0), 0.0)
        if remaining <= 0:
            control.checkpoint(attempt_id=attempt_id)
            return
        while remaining > 0:
            control.checkpoint(attempt_id=attempt_id)
            chunk = min(1.0, remaining)
            time.sleep(chunk)
            remaining -= chunk

    def retry_auth_capture_after_phone_completed(
        *,
        account: AccountModel,
        session: Session,
        first_result: dict[str, Any],
        email: str,
        account_position: int,
        attempt_id: int | None,
        proxy_url: str = "",
    ) -> tuple[dict[str, Any], int, bool]:
        latest_result = dict(first_result or {})
        retry_count = 0
        for retry_index, delay_seconds in enumerate(auth_retry_delays_seconds, start=1):
            retry_count = retry_index
            last_error = result_error_text(latest_result, "Auth/RT 获取失败")
            _log(
                task_id,
                f"[手机号绑定][账号 {account_position}/{total_accounts}][补抓Auth] "
                f"手机号已提交成功，但 Auth/RT 获取失败：{last_error[:180]}；"
                f"{'等待 ' + str(delay_seconds) + 's 后' if delay_seconds > 0 else '立即'}重试 {retry_index}/{len(auth_retry_delays_seconds)}",
            )
            wait_seconds(delay_seconds, attempt_id=attempt_id)
            try:
                control.checkpoint(attempt_id=attempt_id)
                retry_kwargs = {
                    "allow_phone_verification": False,
                    "log_fn": lambda message, _pos=account_position: _log(task_id, f"[手机号绑定][账号 {_pos}/{total_accounts}][补抓Auth] {message}"),
                    "stop_checker": lambda: control.checkpoint(attempt_id=attempt_id),
                    "retry_delays_seconds": [],
                }
                if proxy_url:
                    retry_kwargs["proxy_url"] = proxy_url
                retry_result = _execute_chatgpt_resume_subscription_auth(account, **retry_kwargs)
                session.refresh(account)
                _apply_chatgpt_resume_auth_result(account, retry_result, session)
                latest_result = retry_result
            except (SkipCurrentAttemptRequested, StopTaskRequested):
                raise
            except Exception as exc:
                latest_result = {
                    "ok": False,
                    "error": str(exc or "Auth/RT 重试失败"),
                    "data": {"message": str(exc or "Auth/RT 重试失败")},
                }
                _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}][补抓Auth] 重试异常｜次数={retry_index}/{len(auth_retry_delays_seconds)}｜原因={latest_result['error']}")
            if bool(latest_result.get("ok")):
                _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}][补抓Auth] 手机绑定后 Auth/RT 重试成功｜账号={email or getattr(account, 'id', '')}｜次数={retry_index}/{len(auth_retry_delays_seconds)}")
                return latest_result, retry_count, True
        return latest_result, retry_count, False

    def clean_upstream_message(message: str) -> str:
        text = str(message or "").strip()
        while True:
            cleaned = re.sub(
                r"^\s*\[(?:验证码|手机号验证|号码测试|代理|邮箱|登录|阶段|主链路|注册|结果|TempMailLocal|DEBUG)\]\s*",
                "",
                text,
                flags=re.I,
            )
            if cleaned == text:
                return text
            text = cleaned

    def append_error(error_text: str) -> None:
        with state_lock:
            errors.append(str(error_text or ""))

    def append_account_result(payload: dict[str, Any]) -> None:
        with state_lock:
            account_results.append(dict(payload or {}))

    def append_runtime_result(payload: dict[str, Any]) -> None:
        with state_lock:
            runtime_results.append(dict(payload or {}))

    def increment_success() -> None:
        nonlocal success_count
        with state_lock:
            success_count += 1

    def increment_skipped(value: int = 1) -> None:
        nonlocal skipped_count
        with state_lock:
            skipped_count += int(value or 0)

    def mark_account_completed() -> None:
        nonlocal completed_accounts
        with state_lock:
            completed_accounts += 1
            completed_snapshot = completed_accounts
        _task_store.set_progress(task_id, f"{completed_snapshot}/{total_accounts}")

    def set_primary_email_once(email: str) -> None:
        nonlocal primary_email
        value = str(email or "").strip()
        if not value:
            return
        with state_lock:
            if not primary_email:
                primary_email = value

    def task_log_for_attempt(*, account_position: int, account_id: int, email_getter, phone: str, phone_index: int, phone_total_label: str, attempt_id: int | None = None):
        def _task_log(message: str, level: str = "info") -> None:
            control.checkpoint(attempt_id=attempt_id)
            raw = str(message or "")
            effective_level = classify_task_log_level(raw, level, flow="phone_binding")
            cleaned = clean_upstream_message(raw)
            if effective_level != "debug":
                cleaned = restore_known_identity_for_log(
                    cleaned,
                    email=email_getter(),
                    phone=phone,
                )
            _log(
                task_id,
                "[手机号绑定]"
                f"[账号 {account_position}/{total_accounts}]"
                f"[号码 {phone_index}/{phone_total_label}] "
                f"{cleaned}",
                level="debug" if effective_level == "debug" else "info",
            )
        return _task_log

    def process_account(account_position: int, account_id_raw: int, *, start_delay: float = 0.0) -> dict[str, Any]:
        account_id = int(account_id_raw or 0)
        email = ""
        if control.should_stop_starting_new_attempts():
            return {"status": "not_started", "account_id": account_id, "email": email}
        if start_delay > 0:
            _log(task_id, f"[手机号绑定][并发] 账号 {account_position}/{total_accounts} 延时 {start_delay:g}s 后启动｜原因=错峰降低 OpenAI 风控")
            wait_seconds(start_delay)
        account_attempt_id = control.start_attempt()
        if account_attempt_id is None:
            return {"status": "not_started", "account_id": account_id, "email": email}
        account_attempts = 0
        while True:
            control.resume_attempt(account_attempt_id)
            control.checkpoint(consume_skip=False)
            next_item = claim_phone_item()
            if next_item is None:
                increment_skipped()
                append_account_result({"account_id": account_id, "email": email, "status": "not_tested", "reason": "手机号池/列表当前没有可用号码，未完成绑定"})
                sync_meta()
                control.finish_attempt(account_attempt_id)
                return {"status": "not_tested", "account_id": account_id, "email": email}
            item, phone_index, phone_total_label = next_item
            phone = str(item.get("phone") or "").strip()
            raw_line = str(item.get("raw_line") or "").strip()
            account_attempts += 1
            # One account may try more than one phone.  It remains the same
            # already-started account under graceful mode; do not re-claim a
            # new attempt between phone candidates.
            attempt_id = account_attempt_id
            task_log = task_log_for_attempt(
                account_position=account_position,
                account_id=account_id,
                email_getter=lambda: email,
                phone=phone,
                phone_index=phone_index,
                phone_total_label=phone_total_label,
                attempt_id=attempt_id,
            )
            service_entry = UploadedPhoneEntry(
                country_slug="uploaded",
                phone=phone,
                detail_url=str(item.get("api_url") or ""),
                api_url=str(item.get("api_url") or ""),
                raw_line=raw_line,
                line_no=_safe_int(item.get("line_no")),
                source_api_url=str(item.get("source_api_url") or item.get("api_url") or ""),
            )
            phone_service = UploadedPhoneService(
                [service_entry],
                {
                    "_task_stop_checker": lambda _attempt_id=attempt_id: control.checkpoint(attempt_id=_attempt_id),
                    "uploaded_phone_timeout_seconds": int(settings.get("timeout_seconds") or 180),
                    "uploaded_phone_poll_interval_seconds": int(settings.get("poll_interval_seconds") or 5),
                    "uploaded_phone_max_resend_attempts": int(settings.get("max_resend_attempts") or 0),
                    "uploaded_phone_resend_interval_seconds": int(settings.get("resend_interval_seconds") or 30),
                },
                log_fn=task_log,
            )
            phone_service.bind_entry(service_entry)
            try:
                with Session(engine) as session:
                    account = session.get(AccountModel, account_id)
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    email = str(account.email or "")
                    set_primary_email_once(email)

                _log(
                    task_id,
                    "[手机号绑定]"
                    f"[账号 {account_position}/{total_accounts}]"
                    f"[号码 {phone_index}/{phone_total_label}] "
                    f"开始｜账号={email or account_id}｜手机号={phone}｜尝试={account_attempts}｜并发={effective_concurrency}",
                )
                candidate_proxies = _build_phone_binding_candidate_proxies()
                with Session(engine) as session:
                    account = session.get(AccountModel, account_id)
                    if account is None or account.platform != "chatgpt":
                        raise ValueError("ChatGPT 账号不存在")
                    result: dict[str, Any] = {}
                    selected_proxy_url = ""
                    for proxy_index, (candidate_proxy, candidate_proxy_pool, candidate_proxy_source) in enumerate(candidate_proxies, start=1):
                        selected_proxy_url = candidate_proxy
                        proxy_label = redact_proxy_url(candidate_proxy) if candidate_proxy else "direct"
                        _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}][号码 {phone_index}/{phone_total_label}] 使用代理 {proxy_index}/{len(candidate_proxies)}｜source={candidate_proxy_source}｜proxy={proxy_label}")
                        try:
                            resume_kwargs = {
                                "allow_phone_verification": True,
                                "log_fn": task_log,
                                "shared_phone_service": phone_service,
                                "stop_checker": lambda _attempt_id=attempt_id: control.checkpoint(attempt_id=_attempt_id),
                                "retry_delays_seconds": [],
                            }
                            if prefix_sms_probe_only:
                                resume_kwargs["phone_sms_probe_only"] = True
                            if candidate_proxy:
                                resume_kwargs["proxy_url"] = candidate_proxy
                            result = _execute_chatgpt_resume_subscription_auth(account, **resume_kwargs)
                            proxy_error_text = result_error_text(result, "") if not bool(result.get("ok")) else ""
                            if (
                                proxy_error_text
                                and is_proxy_error_text(proxy_error_text)
                                and not phone_was_touched(phone_service)
                                and proxy_index < len(candidate_proxies)
                            ):
                                _report_phone_proxy_fail(candidate_proxy_pool, candidate_proxy, proxy_error_text)
                                _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 当前代理疑似不可用且手机号未触碰，切换下一个代理：{proxy_error_text[:180]}")
                                continue
                            _report_phone_proxy_success(candidate_proxy_pool, candidate_proxy, phone_service, result)
                            break
                        except (SkipCurrentAttemptRequested, StopTaskRequested):
                            raise
                        except Exception as proxy_exc:
                            proxy_error_text = str(proxy_exc or "手机号绑定失败")
                            if (
                                is_proxy_error_text(proxy_error_text)
                                and not phone_was_touched(phone_service)
                                and proxy_index < len(candidate_proxies)
                            ):
                                _report_phone_proxy_fail(candidate_proxy_pool, candidate_proxy, proxy_error_text)
                                _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 当前代理异常且手机号未触碰，切换下一个代理：{proxy_error_text[:180]}")
                                continue
                            _report_phone_proxy_fail(candidate_proxy_pool, candidate_proxy, proxy_error_text)
                            raise

                    session.refresh(account)
                    ok = bool(result.get("ok"))
                    auth_retry_attempts = 0

                    if prefix_sms_probe_only and phone_service.completed_entries:
                        success_reason = "OpenAI 已发码，收码 API 已收到验证码；按设置未提交验证码，未完成手机号绑定"
                        phone_result = result_for_phone(
                            item,
                            "sms_probe_received",
                            account_id=account_id,
                            email=email,
                            reason=success_reason,
                            code_received=True,
                            phone_service=phone_service,
                        )
                        phone_result["verification_submitted"] = False
                        phone_result["sms_probe_only"] = True
                        record_pool_result(item, "sms_probe_received", reason=success_reason, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                        release_phone(item, successful=True)
                        increment_success()
                        with state_lock:
                            runtime_results.append(phone_result)
                            bound_phone_results.append(dict(phone_result))
                            account_results.append({"account_id": account_id, "email": email, "status": "sms_probe_received", "phone": phone, "reason": success_reason})
                        _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 已收码未提交｜手机号={phone}｜结果=短信探测完成")
                        sync_meta()
                        return {"status": "sms_probe_received", "account_id": account_id, "email": email}

                    try:
                        session.commit()
                    except Exception:
                        session.rollback()
                    try:
                        session.refresh(account)
                    except Exception:
                        pass
                    _apply_chatgpt_resume_auth_result(account, result, session)

                    if (not ok) and phone_service.completed_entries:
                        result, auth_retry_attempts, _ = retry_auth_capture_after_phone_completed(
                            account=account,
                            session=session,
                            first_result=result,
                            email=email,
                            account_position=account_position,
                            attempt_id=attempt_id,
                            proxy_url=selected_proxy_url,
                        )
                        ok = bool(result.get("ok"))

                    if phone_service.completed_entries:
                        auth_error_text = "" if ok else result_error_text(result, "Auth/RT 获取失败")
                        success_reason = "验证码已提交 OpenAI，手机号绑定完成"
                        if ok:
                            success_reason = (
                                f"{success_reason}，Auth/RT 已获取"
                                if auth_retry_attempts <= 0
                                else f"{success_reason}，Auth/RT 重试 {auth_retry_attempts} 次后已获取"
                            )
                        else:
                            success_reason = f"{success_reason}；但 Auth/RT 重试 {auth_retry_attempts} 次仍失败: {auth_error_text[:180]}"
                        phone_result = result_for_phone(
                            item,
                            "bound",
                            account_id=account_id,
                            email=email,
                            reason=success_reason,
                            code_received=True,
                            phone_service=phone_service,
                        )
                        raw_result_line = str(phone_result.get("raw_line") or raw_line or f"{phone}----{item.get('api_url') or ''}")
                        phone_result["auth_capture_ok"] = bool(ok)
                        phone_result["auth_retry_attempts"] = int(auth_retry_attempts or 0)
                        if auth_error_text:
                            phone_result["auth_error"] = auth_error_text
                            _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 手机号已绑定完成，但 Auth/RT 获取失败：{auth_error_text[:180]}")
                        try:
                            session.commit()
                        except Exception:
                            session.rollback()
                        try:
                            session.refresh(account)
                        except Exception:
                            pass
                        _persist_phone_binding_result(account, phone_result, task_id=task_id, raw_line=raw_result_line)
                        session.add(account)
                        session.commit()
                        from services.account_filters import upsert_account_list_state_for_account_ids

                        upsert_account_list_state_for_account_ids(session, [account.id], commit=True)
                        record_pool_result(item, "bound", reason=success_reason, email=email, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                        release_phone(item, successful=True)
                        increment_success()
                        with state_lock:
                            bound_phone_lines.append(raw_result_line)
                            runtime_results.append(phone_result)
                            bound_phone_results.append({**phone_result, "raw_line": raw_result_line})
                            if ok:
                                account_results.append({"account_id": account_id, "email": email, "status": "used_for_binding", "phone": phone})
                            else:
                                account_results.append({"account_id": account_id, "email": email, "status": "used_for_binding_auth_failed", "phone": phone, "reason": auth_error_text})
                                errors.append(f"{email or account_id}: 手机号已绑定，但 Auth/RT 获取失败: {auth_error_text}")
                        _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 绑定完成｜手机号={phone}｜AuthRT={'ok' if ok else 'failed'}")
                        sync_meta()
                        return {"status": "bound", "account_id": account_id, "email": email}

                    if ok and not phone_service.completed_entries:
                        try:
                            session.commit()
                        except Exception:
                            session.rollback()
                        release_phone(item, reusable=True)
                        increment_skipped()
                        skip_reason = "账号已完成 Auth，未进入 add_phone；当前手机号未提交 OpenAI，留给其他账号继续测试"
                        with state_lock:
                            runtime_results.append(result_for_phone(item, "account_phone_bound", account_id=account_id, email=email, reason=skip_reason, phone_service=phone_service))
                            account_results.append({"account_id": account_id, "email": email, "status": "account_phone_bound", "reason": skip_reason})
                        _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 无需绑定｜账号已完成 Auth，当前手机号未消耗")
                        sync_meta()
                        return {"status": "account_phone_bound", "account_id": account_id, "email": email}

                    error_text = result_error_text(result)
                    status = _phone_binding_error_status(error_text)
                    if status in {"openai_rejected", "openai_phone_limit", "phone_already_used", "api_no_code", "api_error", "rate_limited"}:
                        increment_skipped()
                        release_phone(item, terminal=True)
                        phone_result = result_for_phone(item, status, account_id=account_id, email=email, reason=error_text, phone_service=phone_service)
                        record_pool_result(item, status, reason=error_text, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                        append_runtime_result(phone_result)
                        _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 当前手机号不可继续｜状态={_phone_binding_status_label(status)}｜原因={error_text[:180]}")
                        sync_meta()
                        continue

                    if should_keep_phone_for_next_account(status, phone_service):
                        release_phone(item, reusable=True)
                        recover_at = mark_account_rate_limited_for_recovery(account_id, email, error_text) if is_account_rate_limit_error(status, error_text) else ""
                        account_result_status = "rate_limited" if recover_at else status
                        account_reason = f"{error_text}；账号限流预计恢复: {recover_at}" if recover_at else error_text
                        append_error(f"{email or account_id}: {account_reason}")
                        append_account_result({"account_id": account_id, "email": email, "status": account_result_status, "reason": account_reason})
                        _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 账号前置失败，手机号未被触碰｜原因={account_reason[:180]}")
                        sync_meta()
                        return {"status": account_result_status, "account_id": account_id, "email": email}

                    release_phone(item, successful=phone_was_touched(phone_service), reusable=not phone_was_touched(phone_service))
                    phone_result = result_for_phone(item, status, account_id=account_id, email=email, reason=error_text, phone_service=phone_service)
                    record_pool_result(item, status, reason=error_text, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                    append_runtime_result(phone_result)
                    append_account_result({"account_id": account_id, "email": email, "status": status, "reason": error_text})
                    append_error(f"{email or account_id}: {error_text}")
                    _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 绑定失败｜状态={_phone_binding_status_label(status)}｜原因={error_text[:180]}")
                    sync_meta()
                    return {"status": status, "account_id": account_id, "email": email}
            except SkipCurrentAttemptRequested as exc:
                release_phone(item, reusable=not phone_was_touched(phone_service), successful=phone_was_touched(phone_service))
                increment_skipped()
                append_runtime_result(result_for_phone(item, "not_tested", account_id=account_id, email=email, reason=str(exc), phone_service=phone_service))
                append_account_result({"account_id": account_id, "email": email, "status": "skipped", "reason": str(exc)})
                _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 已跳过｜原因={exc}")
                sync_meta()
                return {"status": "skipped", "account_id": account_id, "email": email}
            except StopTaskRequested:
                release_phone(item, reusable=not phone_was_touched(phone_service), successful=phone_was_touched(phone_service))
                raise
            except Exception as exc:
                error_text = str(exc or "手机号绑定失败")
                status = _phone_binding_error_status(error_text)
                if status in {"openai_rejected", "openai_phone_limit", "phone_already_used", "api_no_code", "api_error", "rate_limited"}:
                    increment_skipped()
                    release_phone(item, terminal=True)
                    phone_result = result_for_phone(item, status, account_id=account_id, email=email, reason=error_text, phone_service=phone_service)
                    record_pool_result(item, status, reason=error_text, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                    append_runtime_result(phone_result)
                    _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 当前手机号不可继续｜状态={_phone_binding_status_label(status)}｜原因={error_text[:180]}")
                    sync_meta()
                    continue
                if should_keep_phone_for_next_account(status, phone_service):
                    release_phone(item, reusable=True)
                    recover_at = mark_account_rate_limited_for_recovery(account_id, email, error_text) if is_account_rate_limit_error(status, error_text) else ""
                    account_result_status = "rate_limited" if recover_at else status
                    account_reason = f"{error_text}；账号限流预计恢复: {recover_at}" if recover_at else error_text
                    append_error(f"{email or account_id}: {account_reason}")
                    append_account_result({"account_id": account_id, "email": email, "status": account_result_status, "reason": account_reason})
                    _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 账号前置失败，手机号未被触碰｜原因={account_reason[:180]}")
                    sync_meta()
                    return {"status": account_result_status, "account_id": account_id, "email": email}
                release_phone(item, successful=phone_was_touched(phone_service), reusable=not phone_was_touched(phone_service))
                phone_result = result_for_phone(item, status, account_id=account_id, email=email, reason=error_text, phone_service=phone_service)
                record_pool_result(item, status, reason=error_text, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                append_runtime_result(phone_result)
                append_account_result({"account_id": account_id, "email": email, "status": status, "reason": error_text})
                append_error(f"{email or account_id}: {error_text}")
                _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 绑定异常｜状态={_phone_binding_status_label(status)}｜原因={error_text[:180]}")
                sync_meta()
                return {"status": status, "account_id": account_id, "email": email}
            finally:
                control.finish_attempt(attempt_id)

    try:
        for parse_error in parse_errors:
            _log(task_id, f"[手机号绑定][解析] 跳过｜行={parse_error.get('line')}｜原因={parse_error.get('reason') or ''}")
        for missing_id in missing_ids:
            message = f"account_id={missing_id}: 账号不存在"
            _log(task_id, f"[MISS] {message}")
            append_error(message)
            append_account_result({"account_id": int(missing_id or 0), "email": "", "status": "account_missing", "reason": "账号不存在"})

        _log(
            task_id,
            "[手机号绑定][配置] 并发已开启"
            f"｜请求={requested_concurrency}｜实际={effective_concurrency}"
            f"｜启动错峰={account_interval_seconds}s｜账号数={len(account_ids)}",
        )
        if prefix_sms_probe_only:
            _log(task_id, "[手机号绑定][配置] 短信探测模式已开启｜验证=OpenAI发码+收码API收码｜提交验证码=否｜完成绑定=否")
        if prefix_bind_enabled:
            _log(
                task_id,
                f"[手机号绑定][限定号段] 已开启｜号段={','.join(selected_prefixes) or '-'}"
                f"｜号码范围={phone_number_filter}｜并发取号=任务内互斥",
            )
        if prefix_sample_enabled:
            _log(task_id, f"[手机号绑定][号段抽样] 已开启｜范围={prefix_sample_filter}｜选中号码={len(phone_items)}｜并发取号=任务内互斥")
        if unavailable_number_test_enabled:
            _log(
                task_id,
                f"[手机号绑定][不可用号码复测] 已开启｜选中号码={len(phone_items)}"
                "｜每个号码只测试一次",
            )

        next_account_index = 0
        in_flight: dict[Any, tuple[int, int]] = {}
        launch_count = 0
        ordered_accounts = [int(value or 0) for value in account_ids]
        with ThreadPoolExecutor(max_workers=effective_concurrency) as pool:
            while (
                next_account_index < len(ordered_accounts)
                and len(in_flight) < effective_concurrency
                and not control.should_stop_starting_new_attempts()
            ):
                account_position = next_account_index + 1
                account_id = ordered_accounts[next_account_index]
                start_delay = account_interval_seconds * min(launch_count, max(effective_concurrency - 1, 0))
                future = pool.submit(process_account, account_position, account_id, start_delay=start_delay)
                in_flight[future] = (account_position, account_id)
                next_account_index += 1
                launch_count += 1

            while in_flight:
                control.checkpoint(consume_skip=False)
                done, _ = wait(tuple(in_flight.keys()), timeout=0.5, return_when=FIRST_COMPLETED)
                if not done:
                    continue
                for future in done:
                    account_position, account_id = in_flight.pop(future)
                    try:
                        future.result()
                    except StopTaskRequested:
                        control.request_stop()
                        raise
                    except Exception as exc:
                        error_text = str(exc or "手机号绑定并发任务异常")
                        append_error(f"{account_id}: {error_text}")
                        append_account_result({"account_id": account_id, "email": "", "status": "unknown", "reason": error_text})
                        _log(task_id, f"[手机号绑定][账号 {account_position}/{total_accounts}] 并发任务异常｜原因={error_text}")
                    finally:
                        mark_account_completed()
                        sync_meta()

                    if (
                        next_account_index < len(ordered_accounts)
                        and not control.should_stop_starting_new_attempts()
                    ):
                        next_position = next_account_index + 1
                        next_account_id = ordered_accounts[next_account_index]
                        future = pool.submit(process_account, next_position, next_account_id, start_delay=0)
                        in_flight[future] = (next_position, next_account_id)
                        next_account_index += 1

        final_status = "done"
        try:
            from collections import Counter

            with state_lock:
                runtime_status_counts = Counter(str(item.get("status") or "unknown") for item in runtime_results)
                account_status_counts = Counter(str(item.get("status") or "unknown") for item in account_results)
                success_snapshot = success_count
                skipped_snapshot = skipped_count
                errors_snapshot = list(errors)
                runtime_results_snapshot = list(runtime_results)
                account_results_snapshot = list(account_results)
                bound_phone_lines_snapshot = list(bound_phone_lines)
                bound_phone_results_snapshot = list(bound_phone_results)
                primary_email_snapshot = primary_email
        except Exception:
            runtime_status_counts = {}
            account_status_counts = {}
            success_snapshot = success_count
            skipped_snapshot = skipped_count
            errors_snapshot = list(errors)
            runtime_results_snapshot = list(runtime_results)
            account_results_snapshot = list(account_results)
            bound_phone_lines_snapshot = list(bound_phone_lines)
            bound_phone_results_snapshot = list(bound_phone_results)
            primary_email_snapshot = primary_email
        phone_issue_count = sum(
            int(runtime_status_counts.get(status, 0))
            for status in (
                "openai_rejected",
                "openai_phone_limit",
                "phone_already_used",
                "api_no_code",
                "api_error",
                "rate_limited",
            )
        )
        forward_issue_count = int(runtime_status_counts.get("api_forward_error", 0))
        account_issue_count = sum(int(account_status_counts.get(status, 0)) for status in ("account_auth_error", "unknown", "rate_limited"))
        summary_message = (
            f"OpenAI 手机号绑定完成：成功 {success_snapshot}/{len(account_ids)}，"
            f"手机号问题 {phone_issue_count}，转发问题 {forward_issue_count}，"
            f"账号问题 {account_issue_count}，跳过 {skipped_snapshot}，并发 {effective_concurrency}"
        )
        _log(
            task_id,
            "[手机号绑定][汇总] 完成"
            f"｜成功={success_snapshot}/{len(account_ids)}"
            f"｜手机号问题={phone_issue_count}"
            f"｜转发问题={forward_issue_count}"
            f"｜账号问题={account_issue_count}"
            f"｜跳过={skipped_snapshot}"
            f"｜并发={effective_concurrency}",
        )
        if runtime_results_snapshot:
            _log(task_id, f"[手机号绑定][汇总] 结果表已生成｜总数={len(runtime_results_snapshot)}｜成功绑定={len(bound_phone_results_snapshot)}")
        else:
            _log(task_id, "[手机号绑定][汇总] 结果表已生成｜总数=0｜成功绑定=0")
        sync_meta()
        log_status = "success" if success_snapshot > 0 and not errors_snapshot else "failed"
        attempt_outcome = "phone_binding_test_success" if log_status == "success" else "phone_binding_test_failed"
        if log_status != "success" and no_phone_available:
            attempt_outcome = "phone_binding_test_no_phone_available"
        _task_store.finish(
            task_id,
            status=final_status,
            success=success_snapshot,
            skipped=skipped_snapshot,
            errors=errors_snapshot,
            error="" if not errors_snapshot else summary_message,
        )
        terminal_status = str(_task_store.snapshot(task_id).get("status") or log_status)
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        _save_task_log(
            "chatgpt",
            primary_email_snapshot,
            terminal_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email_snapshot,
                    "attempt_outcome": attempt_outcome,
                    "source": "phone_binding_test",
                    "meta": latest_meta,
                    "bound_phone_lines": [redact_raw_phone_line(line) for line in bound_phone_lines_snapshot],
                    "bound_phone_results": [sanitize_phone_result(item) for item in bound_phone_results_snapshot],
                    "runtime_results": [sanitize_phone_result(item) for item in runtime_results_snapshot],
                    "account_results": sanitize_task_detail(account_results_snapshot),
                },
            ),
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        sync_meta()
        with state_lock:
            success_snapshot = success_count
            skipped_snapshot = skipped_count
            errors_snapshot = list(errors)
            primary_email_snapshot = primary_email
            bound_phone_lines_snapshot = list(bound_phone_lines)
            bound_phone_results_snapshot = list(bound_phone_results)
            runtime_results_snapshot = list(runtime_results)
            account_results_snapshot = list(account_results)
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_snapshot,
            skipped=skipped_snapshot,
            errors=errors_snapshot,
            error=str(exc),
        )
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        _save_task_log(
            "chatgpt",
            primary_email_snapshot,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email_snapshot,
                    "attempt_outcome": "phone_binding_test_stopped",
                    "source": "phone_binding_test",
                    "meta": latest_meta,
                    "bound_phone_lines": [redact_raw_phone_line(line) for line in bound_phone_lines_snapshot],
                    "bound_phone_results": [sanitize_phone_result(item) for item in bound_phone_results_snapshot],
                    "runtime_results": [sanitize_phone_result(item) for item in runtime_results_snapshot],
                    "account_results": sanitize_task_detail(account_results_snapshot),
                },
            ),
        )
    except Exception as exc:
        error_text = str(exc or "手机号绑定并发任务异常退出")
        append_error(error_text)
        _log(task_id, f"[ERROR] 手机号绑定并发任务异常退出: {error_text}")
        try:
            sync_meta()
        except Exception as sync_exc:
            _log(task_id, f"[ERROR] 手机号绑定并发任务异常状态同步失败: {sync_exc}")
        with state_lock:
            success_snapshot = success_count
            skipped_snapshot = skipped_count
            errors_snapshot = list(errors)
            primary_email_snapshot = primary_email
            bound_phone_lines_snapshot = list(bound_phone_lines)
            bound_phone_results_snapshot = list(bound_phone_results)
            runtime_results_snapshot = list(runtime_results)
            account_results_snapshot = list(account_results)
        _task_store.finish(task_id, status="failed", success=success_snapshot, skipped=skipped_snapshot, errors=errors_snapshot, error=error_text)
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        _save_task_log(
            "chatgpt",
            primary_email_snapshot,
            "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email_snapshot,
                    "attempt_outcome": "phone_binding_test_exception",
                    "source": "phone_binding_test",
                    "meta": latest_meta,
                    "bound_phone_lines": [redact_raw_phone_line(line) for line in bound_phone_lines_snapshot],
                    "bound_phone_results": [sanitize_phone_result(item) for item in bound_phone_results_snapshot],
                    "runtime_results": [sanitize_phone_result(item) for item in runtime_results_snapshot],
                    "account_results": sanitize_task_detail(account_results_snapshot),
                },
            ),
        )
    finally:
        _task_store.cleanup()

def _run_phone_binding_test(
    task_id: str,
    account_ids: list[int],
    phone_items: list[dict[str, Any]],
    settings: dict[str, Any],
):
    if _parse_positive_int((settings or {}).get("concurrency"), 1) > 1:
        return _run_phone_binding_test_concurrent(task_id, account_ids, phone_items, settings)

    from api.actions import (
        _apply_chatgpt_resume_auth_result,
        _execute_chatgpt_resume_subscription_auth,
    )
    from services.chatgpt_core.phone_service import UploadedPhoneEntry, UploadedPhoneService
    from core.proxy_utils import is_proxy_error_text, normalize_proxy_url

    control = _task_store.control_for(task_id)
    phone_log_context: dict[str, Any] = {
        "account_index": 0,
        "account_total": len(account_ids),
        "stage_index": 1,
        "stage_label": "准备",
        "email": "",
        "account_id": 0,
        "phone": "",
        "phone_index": 0,
        "phone_total": len(phone_items),
        "attempt": 0,
    }
    PHONE_BINDING_STAGE_TOTAL = 12
    PHONE_BINDING_STAGE_LABELS: dict[int, str] = {
        1: "准备",
        2: "选择代理",
        3: "OAuth登录",
        4: "邮箱验证",
        5: "进入绑定",
        6: "发送短信",
        7: "接收短信",
        8: "提交短信",
        9: "确认绑定",
        10: "补抓Auth",
        11: "保存账号",
        12: "回写号码池",
    }

    def set_phone_log_context(**updates: Any) -> None:
        phone_log_context.update({key: value for key, value in updates.items() if value is not None})

    def _phone_stage_label(stage_index: int | None = None, phase_label: str = "") -> str:
        index = int(stage_index or phone_log_context.get("stage_index") or 1)
        return str(phase_label or PHONE_BINDING_STAGE_LABELS.get(index) or "").strip()

    def _phone_binding_log_line(
        message: str,
        *,
        stage_index: int | None = None,
        phase_label: str = "",
        debug: bool = False,
    ) -> str:
        index = int(stage_index or phone_log_context.get("stage_index") or 1)
        label = _phone_stage_label(index, phase_label)
        return format_task_timeline_log(
            "手机绑定",
            str(message or ""),
            item_index=int(phone_log_context.get("account_index") or 0),
            item_total=int(phone_log_context.get("account_total") or len(account_ids) or 0),
            email=str(phone_log_context.get("email") or ""),
            account_id=phone_log_context.get("account_id") or None,
            phone=str(phone_log_context.get("phone") or ""),
            phone_index=phone_log_context.get("phone_index") or None,
            phone_total=phone_log_context.get("phone_total_label") or phone_log_context.get("phone_total") or None,
            stage_index=index,
            stage_total=PHONE_BINDING_STAGE_TOTAL,
            phase_label=label,
            debug=debug,
        )

    def clean_phone_binding_message(message: str) -> str:
        text = str(message or "").strip()
        # 上游组件经常自带 [验证码] / [号码测试] 这类模块标签。
        # 手机绑定日志前缀已经有步骤名，正文里再重复这些标签只会干扰排版。
        while True:
            cleaned = re.sub(
                r"^\s*\[(?:验证码|手机号验证|号码测试|代理|邮箱|登录|阶段|主链路|注册|结果|TempMailLocal|DEBUG)\]\s*",
                "",
                text,
                flags=re.I,
            )
            if cleaned == text:
                break
            text = cleaned
        return text

    def phone_log(
        message: str,
        *,
        level: str = "info",
        stage_index: int | None = None,
        phase_label: str = "",
    ) -> None:
        index = int(stage_index or phone_log_context.get("stage_index") or 1)
        label = _phone_stage_label(index, phase_label)
        set_phone_log_context(stage_index=index, stage_label=label)
        _log(
            task_id,
            _phone_binding_log_line(
                clean_phone_binding_message(message),
                stage_index=index,
                phase_label=label,
                debug=str(level or "info").strip().lower() == "debug",
            ),
            level,
        )

    def phone_attempt_header(*, account_position: int, account_total: int, phone_index: int, phone_total_label: str, phone: str) -> None:
        _log(
            task_id,
            (
                "[手机号绑定]"
                f"[账号 {account_position}/{account_total}]"
                f"[号码 {phone_index}/{phone_total_label}] "
                f"开始｜手机号={phone}"
            ),
        )

    def infer_phone_binding_stage(message: str) -> tuple[int | None, str]:
        text = str(message or "")
        lowered = text.lower()
        if "绑定手机号 otp 验证通过" in lowered or "otp 验证通过" in lowered:
            return 9, "确认绑定"
        if "准备提交绑定手机号验证码" in text or "validate_phone" in lowered:
            return 8, "提交短信"
        if "收到验证码" in text or "暂无验证码" in text or "收码 api" in text or "接码" in text:
            return 7, "接收短信"
        if "已请求绑定手机号短信验证码" in text or "openai 已接受并发送验证码" in lowered or "add-phone/send" in lowered:
            return 6, "发送短信"
        if "add_phone" in lowered or "手机号验证" in text:
            return 5, "进入绑定"
        if "邮箱验证码" in text or "email otp" in lowered:
            return 4, "邮箱验证"
        if "oauth" in lowered or "登录" in text or "authorize" in lowered:
            return 3, "OAuth登录"
        if "代理" in text or "proxy" in lowered:
            return 2, "选择代理"
        return None, ""

    def task_log_info_from_upstream(message: str, stage_index: int, phase_label: str) -> None:
        text = str(message or "")
        if "已请求绑定手机号短信验证码" in text or "OpenAI 已接受并发送验证码" in text:
            phone_log("OpenAI 已接受手机号，等待短信验证码", stage_index=6, phase_label="发送短信")
            return
        if "收到验证码" in text:
            phone_log(text, stage_index=7, phase_label="接收短信")
            return
        if "准备提交绑定手机号验证码" in text:
            phone_log(text, stage_index=8, phase_label="提交短信")
            return
        if "绑定手机号 OTP 验证通过" in text:
            phone_log("手机号验证码验证通过", stage_index=9, phase_label="确认绑定")
            return
        if "等待邮箱验证码" in text:
            phone_log(text, stage_index=4, phase_label="邮箱验证")
            return
        if "验证码已获取" in text and "邮箱" in text:
            phone_log(text, stage_index=4, phase_label="邮箱验证")

    def stop_checker() -> None:
        control.checkpoint(consume_skip=False)

    def task_log(message: str, level: str = "info") -> None:
        stop_checker()
        raw = str(message or "")
        stage_index, phase_label = infer_phone_binding_stage(raw)
        if stage_index:
            set_phone_log_context(stage_index=stage_index, stage_label=phase_label)
        task_log_info_from_upstream(
            raw,
            int(stage_index or phone_log_context.get("stage_index") or 1),
            phase_label or str(phone_log_context.get("stage_label") or ""),
        )
        effective_level = classify_task_log_level(raw, level, flow="phone_binding")
        phone_log(
            raw,
            level="debug" if effective_level == "debug" else "info",
            stage_index=int(stage_index or phone_log_context.get("stage_index") or 1),
            phase_label=phase_label or str(phone_log_context.get("stage_label") or ""),
        )

    use_pool = _is_truthy(settings.get("use_pool"))
    total = max(len(account_ids) if use_pool else min(len(account_ids), len(phone_items)), 1)
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    primary_email = ""
    runtime_results: list[dict[str, Any]] = []
    account_results: list[dict[str, Any]] = []
    bound_phone_lines: list[str] = []
    bound_phone_results: list[dict[str, Any]] = []
    account_index = 0
    accounts_with_phone_terminal_result: set[int] = set()
    terminal_phones_this_run: set[str] = set()
    account_interval_seconds = _parse_positive_int(settings.get("account_interval_seconds"), 60)
    reuse_phone_until_unusable = _is_truthy(settings.get("reuse_phone_until_unusable"))
    prefix_bind_enabled = _is_truthy(settings.get("prefix_bind_enabled"))
    prefix_sample_enabled = _is_truthy(settings.get("prefix_sample_enabled"))
    runtime_pool_mode = _normalize_phone_binding_pool_mode(
        settings.get("phone_pool_mode"),
        prefix_bind_enabled=prefix_bind_enabled,
        prefix_sample_enabled=prefix_sample_enabled,
        unavailable_number_test_enabled=_is_truthy(settings.get("unavailable_number_test_enabled")),
    )
    unavailable_number_test_enabled = runtime_pool_mode == "unavailable_numbers"
    phone_number_filter = _normalize_phone_binding_number_filter(
        settings.get("prefix_number_filter") or settings.get("phone_number_filter")
    )
    if unavailable_number_test_enabled:
        phone_number_filter = "unavailable"
    elif not prefix_bind_enabled:
        phone_number_filter = "available"
    prefix_sample_size = 2 if int(settings.get("prefix_sample_size") or 1) == 2 else 1
    prefix_sample_filter = str(settings.get("prefix_sample_filter") or "all").strip().lower()
    if prefix_sample_filter not in {"all", "available", "rejected"}:
        prefix_sample_filter = "all"
    prefix_sms_probe_only = _is_truthy(settings.get("prefix_sms_probe_only"))
    if (
        prefix_sample_enabled
        or prefix_sms_probe_only
        or unavailable_number_test_enabled
        or (prefix_bind_enabled and phone_number_filter != "available")
    ):
        reuse_phone_until_unusable = False
    if unavailable_number_test_enabled or (prefix_bind_enabled and phone_number_filter != "available"):
        use_pool = False
    selected_prefixes = [
        str(prefix or "").strip()
        for prefix in (settings.get("selected_prefixes") or [])
        if str(prefix or "").strip()
    ]
    last_account_attempt_finished_at = 0.0
    no_phone_available = False

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    missing_ids = list(meta.get("missing_ids") or [])
    parse_errors = list(meta.get("parse_errors") or [])

    def timeline(
        *,
        email: str = "",
        account_id: int | str | None = None,
        phone: str = "",
        phase: str = "",
        phase_label: str = "",
        stage_index: int | None = None,
        stage_total: int | None = None,
        message: str = "",
        next_step: str = "",
        resource_touched: bool | None = None,
        reset_started_at: bool = False,
    ) -> None:
        normalized_stage_index = int(stage_index or phone_log_context.get("stage_index") or 1)
        normalized_phase_label = _phone_stage_label(normalized_stage_index, phase_label)
        set_phone_log_context(
            email=email or phone_log_context.get("email") or "",
            account_id=account_id or phone_log_context.get("account_id") or 0,
            phone=phone or phone_log_context.get("phone") or "",
            account_index=account_index if account_index > 0 else phone_log_context.get("account_index") or 0,
            account_total=len(account_ids) if account_ids else phone_log_context.get("account_total") or 0,
            stage_index=normalized_stage_index,
            stage_label=normalized_phase_label,
        )
        _task_timeline_log(
            task_id,
            task="手机绑定",
            email=email,
            account_id=account_id,
            phone=phone,
            phone_index=phone_log_context.get("phone_index") or None,
            phone_total=phone_log_context.get("phone_total_label") or phone_log_context.get("phone_total") or None,
            item_index=account_index if account_index > 0 else None,
            item_total=len(account_ids) if account_ids else None,
            phase=phase,
            phase_label=normalized_phase_label,
            stage_index=normalized_stage_index,
            stage_total=PHONE_BINDING_STAGE_TOTAL,
            message=message,
            next_step=next_step,
            resource_touched=resource_touched,
            reset_started_at=reset_started_at,
        )

    def sync_meta() -> None:
        safe_runtime_results = [sanitize_phone_result(item) for item in runtime_results]
        safe_bound_phone_results = [sanitize_phone_result(item) for item in bound_phone_results]
        updates = {
            "runtime_results": safe_runtime_results,
            "account_results": sanitize_task_detail(account_results),
            "bound_phone_lines": [redact_raw_phone_line(line) for line in bound_phone_lines],
            "bound_phone_results": safe_bound_phone_results,
            "runtime_success": success_count,
            "runtime_skipped": skipped_count,
            "runtime_errors": [sanitize_error_message(err) for err in errors],
            "no_phone_available": no_phone_available,
        }
        if prefix_sample_enabled:
            updates["prefix_summary"] = _build_phone_prefix_sample_summary(phone_items, runtime_results)
        _task_store.update_meta(task_id, updates)

    pool_repo = None
    if use_pool or any(bool(item.get("pool_managed")) for item in phone_items):
        from services.chatgpt_core.phone_pool_repository import PhonePoolRepository

        pool_repo = PhonePoolRepository()

    def record_pool_result(item: dict[str, Any], status: str, *, reason: str = "", email: str = "", api_expired_date: str = "") -> None:
        if pool_repo is None or not bool(item.get("pool_managed")):
            return
        phone = str(item.get("phone") or "")
        try:
            pool_repo.record_task_status(phone, status, reason=reason, email=email)
            expired = str(api_expired_date or "").strip()
            if expired and hasattr(pool_repo, "update_api_expired_date"):
                pool_repo.update_api_expired_date(phone, expired)
        except Exception as exc:
            _log(task_id, f"[手机号绑定][号码池] 回写失败｜手机号={item.get('phone') or '-'}｜原因={exc}")

    def result_for_phone(
        item: dict[str, Any],
        status: str,
        *,
        account_id: int = 0,
        email: str = "",
        reason: str = "",
        code_received: bool = False,
        phone_service: Any = None,
    ) -> dict[str, Any]:
        api_url, source_api_url, result_raw_line = _phone_binding_effective_api_fields(item, phone_service)
        return {
            "line_no": int(item.get("line_no") or 0),
            "phone": str(item.get("phone") or ""),
            "prefix4": str(item.get("prefix4") or _phone_binding_prefix4(item.get("phone"))),
            "api_url": api_url,
            "source_api_url": source_api_url,
            "raw_line": result_raw_line,
            "status": status,
            "status_label": _phone_binding_status_label(status),
            "account_id": int(account_id or 0),
            "email": str(email or ""),
            "reason": str(reason or ""),
            "code_received": bool(code_received),
            "api_expired_date": str(getattr(phone_service, "last_expired_date", "") or ""),
            "code_time": str(getattr(phone_service, "last_code_time", "") or ""),
            "code_extracted": bool(getattr(phone_service, "last_code_was_extracted", False)),
            "finished_at": beijing_now_iso(),
        }

    def format_result_log_line(result: dict[str, Any]) -> str:
        parts = [
            f"手机号: {mask_phone_for_log(result.get('phone')) if result.get('phone') else '-'}",
            f"状态: {result.get('status_label') or result.get('status') or '-'}",
        ]
        email = str(result.get("email") or "").strip()
        if email:
            parts.append(f"账号: {email}")
        expired_date = str(result.get("api_expired_date") or "").strip()
        if expired_date:
            parts.append(f"接口有效期: {expired_date}")
        code_time = str(result.get("code_time") or "").strip()
        if code_time:
            parts.append(f"验证码时间: {code_time}")
        reason = sanitize_error_message(str(result.get("reason") or "").strip())
        if reason:
            parts.append(f"原因: {reason[:160]}")
        return " | ".join(parts)

    def phone_was_touched(phone_service: Any) -> bool:
        return bool(
            getattr(phone_service, "last_sms_sent", False)
            or getattr(phone_service, "completed_entries", None)
            or getattr(phone_service, "cancelled_entries", None)
            or getattr(phone_service, "last_expired_date", "")
            or getattr(phone_service, "last_code_time", "")
        )

    def _positive_int(value: Any, default: int, minimum: int = 1, maximum: int = 20) -> int:
        try:
            parsed = int(float(str(value or "").strip()))
        except Exception:
            parsed = default
        return max(minimum, min(maximum, parsed))

    def _positive_float(value: Any, default: float, minimum: float = 0, maximum: float = 100) -> float:
        try:
            parsed = float(str(value or "").strip())
        except Exception:
            parsed = default
        return max(minimum, min(maximum, parsed))

    def _build_phone_binding_candidate_proxies() -> list[tuple[str, object | None, str]]:
        from core.proxy_utils import resolve_task_proxy_candidates

        return resolve_task_proxy_candidates(
            dict(settings or {}),
            fallback_proxy=None,
            default_mode="global",
            target="chatgpt",
        )

    def _log_phone_binding_proxy_choice(proxy_url: str, source: str, index: int, total_count: int) -> None:
        if proxy_url:
            phone_log(
                f"使用代理 {index}/{total_count}：source={source} proxy={redact_proxy_url(proxy_url)}",
                stage_index=2,
                phase_label="选择代理",
            )
        else:
            phone_log(
                f"使用代理 {index}/{total_count}：direct",
                stage_index=2,
                phase_label="选择代理",
            )

    def _report_phone_proxy_success(proxy_pool: Any, proxy_url: str, phone_service: Any, result: dict[str, Any] | None = None) -> None:
        if proxy_pool is None or not proxy_url:
            return
        if phone_was_touched(phone_service) or bool((result or {}).get("ok")):
            try:
                proxy_pool.report_success(proxy_url)
            except Exception:
                pass

    def _report_phone_proxy_fail(proxy_pool: Any, proxy_url: str, error_text: str) -> None:
        if proxy_pool is None or not proxy_url or not is_proxy_error_text(error_text):
            return
        try:
            proxy_pool.report_fail(proxy_url)
        except Exception:
            pass

    def should_keep_phone_for_next_account(status: str, phone_service: Any) -> bool:
        return status in {"account_auth_error", "browser_error", "unknown"} and not phone_was_touched(phone_service)

    def is_account_rate_limit_error(status: str, error_text: str) -> bool:
        if status != "account_auth_error":
            return False
        lowered = str(error_text or "").strip().lower()
        if not any(marker in lowered for marker in ("429", "rate limit", "too many request", "请求过快", "限流")):
            return False
        return any(
            marker in lowered
            for marker in (
                "提交邮箱失败",
                "authorize_continue",
                "/authorize/continue",
                "oauth",
                "login_session",
                "rate limit",
                "too many request",
                "请求过快",
                "限流",
            )
        )

    def mark_account_rate_limited_for_recovery(account_id: int, email: str, error_text: str) -> str:
        if account_id <= 0:
            return ""
        try:
            with Session(engine) as rate_session:
                account = rate_session.get(AccountModel, account_id)
                if account is None or account.platform != "chatgpt":
                    return ""
                mark_account_rate_limited(account)
                recover_at = str(account_rate_limit_payload(account).get("recover_at") or "")
                rate_session.add(account)
                rate_session.commit()
            _log(task_id, f"[限流] 账号已标记限流，预计恢复: {email or account_id} -> {recover_at or '1小时后'}")
            return recover_at
        except Exception as exc:
            _log(task_id, f"[限流] 账号限流状态写入失败: {email or account_id} - {exc}")
            return ""

    def wait_before_next_account_attempt(attempt_id: int | None = None) -> None:
        if last_account_attempt_finished_at <= 0 or account_interval_seconds <= 0:
            return
        remaining = (last_account_attempt_finished_at + account_interval_seconds) - time.monotonic()
        if remaining > 0:
            _log(task_id, f"[手机号绑定][等待] 账号/号码间隔｜剩余={remaining:.0f}s｜原因=降低 OpenAI too many request 风险")
        while remaining > 0:
            control.checkpoint(attempt_id=attempt_id)
            chunk = min(1.0, remaining)
            time.sleep(chunk)
            remaining = (last_account_attempt_finished_at + account_interval_seconds) - time.monotonic()

    def result_error_text(result: dict[str, Any], default: str = "手机号绑定失败") -> str:
        data = result.get("data") if isinstance(result.get("data"), dict) else {}
        return str(result.get("error") or data.get("message") or default)

    def parse_auth_retry_delays(value: Any) -> list[int]:
        default_delays = [5, 10, 20]
        if value in (None, ""):
            return default_delays
        if isinstance(value, str):
            candidates = value.replace("，", ",").replace(";", ",").split(",")
        elif isinstance(value, (list, tuple, set)):
            candidates = list(value)
        else:
            candidates = [value]

        delays: list[int] = []
        for item in candidates:
            try:
                delay = int(float(str(item).strip()))
            except Exception:
                continue
            if delay < 0:
                continue
            delays.append(min(delay, 120))
            if len(delays) >= 3:
                break
        return delays or default_delays

    auth_retry_delays_seconds = parse_auth_retry_delays(
        settings.get("phone_binding_auth_retry_delays_seconds")
        if settings.get("phone_binding_auth_retry_delays_seconds") not in (None, "")
        else settings.get("auth_retry_delays_seconds")
    )

    def sleep_before_auth_retry(delay_seconds: int, attempt_id: int | None) -> None:
        delay_seconds = max(int(delay_seconds or 0), 0)
        if delay_seconds <= 0:
            control.checkpoint(attempt_id=attempt_id)
            return
        deadline = time.monotonic() + delay_seconds
        while True:
            control.checkpoint(attempt_id=attempt_id)
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            time.sleep(min(1.0, remaining))

    def retry_auth_capture_after_phone_completed(
        *,
        account: AccountModel,
        session: Session,
        first_result: dict[str, Any],
        email: str,
        attempt_id: int | None,
        proxy_url: str = "",
    ) -> tuple[dict[str, Any], int, bool]:
        latest_result = dict(first_result or {})
        retry_count = 0
        for retry_index, delay_seconds in enumerate(auth_retry_delays_seconds, start=1):
            retry_count = retry_index
            last_error = result_error_text(latest_result, "Auth/RT 获取失败")
            if delay_seconds > 0:
                _log(
                    task_id,
                    f"[手机号绑定] 手机号已提交成功，但 Auth/RT 获取失败：{last_error[:180]}；"
                    f"等待 {delay_seconds}s 后重试 {retry_index}/{len(auth_retry_delays_seconds)}",
                )
            else:
                _log(
                    task_id,
                    f"[手机号绑定] 手机号已提交成功，但 Auth/RT 获取失败：{last_error[:180]}；"
                    f"立即重试 {retry_index}/{len(auth_retry_delays_seconds)}",
                )
            sleep_before_auth_retry(delay_seconds, attempt_id)
            try:
                control.checkpoint(attempt_id=attempt_id)
                retry_kwargs = {
                    "allow_phone_verification": False,
                    "log_fn": task_log,
                    "stop_checker": lambda: control.checkpoint(attempt_id=attempt_id),
                    "retry_delays_seconds": [],
                }
                if proxy_url:
                    retry_kwargs["proxy_url"] = proxy_url
                retry_result = _execute_chatgpt_resume_subscription_auth(
                    account,
                    **retry_kwargs,
                )
                session.refresh(account)
                _apply_chatgpt_resume_auth_result(account, retry_result, session)
                latest_result = retry_result
            except (SkipCurrentAttemptRequested, StopTaskRequested):
                raise
            except Exception as exc:
                latest_result = {
                    "ok": False,
                    "error": str(exc or "Auth/RT 重试失败"),
                    "data": {"message": str(exc or "Auth/RT 重试失败")},
                }
                _log(task_id, f"[手机号绑定][补抓Auth] 重试异常｜次数={retry_index}/{len(auth_retry_delays_seconds)}｜原因={latest_result['error']}")

            if bool(latest_result.get("ok")):
                _log(task_id, f"[手机号绑定][补抓Auth] 手机绑定后 Auth/RT 重试成功｜账号={email or getattr(account, 'id', '')}｜次数={retry_index}/{len(auth_retry_delays_seconds)}")
                return latest_result, retry_count, True

        return latest_result, retry_count, False

    try:
        for parse_error in parse_errors:
            _log(task_id, f"[手机号绑定][解析] 跳过｜行={parse_error.get('line')}｜原因={parse_error.get('reason') or ''}")

        phone_pool_import_meta = meta.get("phone_pool_import") if isinstance(meta.get("phone_pool_import"), dict) else {}
        imported_count = int((phone_pool_import_meta or {}).get("imported") or 0)
        existing_count = int((phone_pool_import_meta or {}).get("existing") or 0)
        skipped_import_count = int((phone_pool_import_meta or {}).get("skipped") or 0)
        if imported_count or existing_count or skipped_import_count:
            _log(
                task_id,
                "[手机号绑定][手机号池] 导入完成"
                f"｜新增={imported_count}｜更新={existing_count}｜跳过={skipped_import_count}｜结果回写=启用",
            )

        for missing_id in missing_ids:
            message = f"account_id={missing_id}: 账号不存在"
            _log(task_id, f"[MISS] {message}")
            errors.append(message)
            account_results.append({"account_id": int(missing_id or 0), "email": "", "status": "account_missing", "reason": "账号不存在"})

        if reuse_phone_until_unusable:
            _log(task_id, "[手机号绑定][配置] 同号连续绑定已开启｜规则=复用到 OpenAI 或收码接口判定不可继续使用")
        if prefix_sms_probe_only:
            _log(task_id, "[手机号绑定][配置] 短信探测模式已开启｜验证=OpenAI发码+收码API收码｜提交验证码=否｜完成绑定=否")
        if prefix_sample_enabled:
            prefix_count = int((meta.get("prefix_sample") or {}).get("prefix_count") or 0)
            sample_filter_label = (
                f"指定号段 {','.join(selected_prefixes)}"
                if selected_prefixes
                else "抽样号码自身可用候选"
                if prefix_sample_filter == "available"
                else "仅复测 OpenAI 拒绝号码"
                if prefix_sample_filter == "rejected"
                else "全部号段"
            )
            _log(
                task_id,
                f"[手机号绑定][号段抽样] 已开启｜范围={sample_filter_label}｜分组=手机号前4位"
                f"｜每号段最多={prefix_sample_size}｜选中号段={prefix_count}｜选中号码={len(phone_items)}",
            )
        if prefix_bind_enabled:
            prefix_bind_meta = meta.get("prefix_bind") if isinstance(meta.get("prefix_bind"), dict) else {}
            slot_count = int((prefix_bind_meta or {}).get("available_slot_count") or 0)
            phone_count = int((prefix_bind_meta or {}).get("candidate_phone_count") or (prefix_bind_meta or {}).get("available_phone_count") or 0)
            _log(
                task_id,
                f"[手机号绑定][限定号段] 已开启｜号段={','.join(selected_prefixes) or '-'}"
                f"｜号码范围={phone_number_filter}｜候选号码={phone_count}"
                f"｜可覆盖账号={slot_count}｜兜底其他号段=否",
            )
        if unavailable_number_test_enabled:
            _log(
                task_id,
                f"[手机号绑定][不可用号码复测] 已开启｜选中号码={len(phone_items)}"
                "｜每个号码只测试一次",
            )
        phone_cursor = 0
        total_phones = len(phone_items)
        dynamic_phone_attempts = 0
        preferred_phone_item: dict[str, Any] | None = None
        preferred_pool_phone = ""
        successful_phones_this_run: set[str] = set()

        def pool_record_to_item(record: Any, line_no: int) -> dict[str, Any]:
            phone_value = str(getattr(record, "phone_e164", "") or "")
            api_url_value = str(getattr(record, "api_url", "") or "")
            return {
                "id": int(getattr(record, "id", 0) or 0),
                "pool_id": int(getattr(record, "id", 0) or 0),
                "line_no": int(line_no or 0),
                "phone": phone_value,
                "api_url": api_url_value,
                "source_api_url": api_url_value,
                "raw_line": f"{phone_value}----{api_url_value}",
                "pool_managed": True,
                "prefix4": _phone_binding_prefix4(phone_value),
            }

        def next_pool_item() -> tuple[dict[str, Any], int, str] | None:
            nonlocal dynamic_phone_attempts, preferred_pool_phone
            if pool_repo is None:
                return None
            excluded_phones = set(terminal_phones_this_run)
            if not reuse_phone_until_unusable:
                excluded_phones.update(successful_phones_this_run)
            selected = None
            preferred = str(preferred_pool_phone or "").strip()
            if preferred and preferred not in excluded_phones:
                get_record = getattr(pool_repo, "get", None)
                if callable(get_record):
                    candidate = get_record(preferred)
                    if candidate is not None and getattr(candidate, "available", False) and str(getattr(candidate, "api_url", "") or ""):
                        selected = candidate
            if selected is None:
                preferred_pool_phone = ""
                available_candidates = (
                    pool_repo.list_available_by_prefixes(selected_prefixes)
                    if prefix_bind_enabled and selected_prefixes and hasattr(pool_repo, "list_available_by_prefixes")
                    else pool_repo.list_available()
                )
                for candidate in available_candidates:
                    phone_value = str(getattr(candidate, "phone_e164", "") or "")
                    if not phone_value or phone_value in excluded_phones:
                        continue
                    if not str(getattr(candidate, "api_url", "") or ""):
                        continue
                    selected = candidate
                    break
            if selected is None:
                return None
            dynamic_phone_attempts += 1
            item = pool_record_to_item(selected, dynamic_phone_attempts)
            if preferred and item.get("phone") == preferred:
                _log(task_id, f"[手机号绑定][号码复用] 同号连续绑定继续｜手机号={preferred}")
            return item, dynamic_phone_attempts, "动态"

        def next_manual_item() -> tuple[dict[str, Any], int, str] | None:
            nonlocal phone_cursor, dynamic_phone_attempts, preferred_phone_item
            if reuse_phone_until_unusable and preferred_phone_item is not None:
                dynamic_phone_attempts += 1
                _log(task_id, f"[手机号绑定][号码复用] 同号连续绑定继续｜手机号={preferred_phone_item.get('phone') or '-'}")
                return dict(preferred_phone_item), dynamic_phone_attempts, "动态"
            while phone_cursor < total_phones:
                item = phone_items[phone_cursor]
                phone_index = phone_cursor + 1
                phone_cursor += 1
                phone = str(item.get("phone") or "").strip()
                if phone and phone in terminal_phones_this_run:
                    _log(task_id, f"[手机号绑定][跳过] 重复号码｜号码={phone_index}/{total}｜手机号={phone}｜原因=已在本轮判定不可继续使用，跳过重复 slot")
                    _task_store.set_progress(task_id, f"{min(phone_cursor, total)}/{total}")
                    continue
                return item, phone_index, str(total)
            return None

        def next_phone_item() -> tuple[dict[str, Any], int, str] | None:
            return next_pool_item() if use_pool else next_manual_item()

        for account_position, account_id_raw in enumerate(account_ids, start=1):
            control.checkpoint(consume_skip=False)
            account_id = int(account_id_raw or 0)
            # The execution unit is one account, not one candidate phone.  A
            # graceful request after this claim lets the account exhaust its
            # normal retry/OTP path, but blocks the next account at this gate.
            account_attempt_id = _claim_next_task_attempt(control)
            email = ""
            account_done = False
            account_attempts = 0

            while not account_done:
                control.checkpoint(consume_skip=False)
                control.resume_attempt(account_attempt_id)
                next_item = next_phone_item()
                if next_item is None:
                    no_phone_available = True
                    control.finish_attempt(account_attempt_id)
                    break
                item, phone_index, phone_total_label = next_item
                phone = str(item.get("phone") or "").strip()

                raw_line = str(item.get("raw_line") or "").strip()
                account_attempts += 1
                account_index = account_position
                set_phone_log_context(
                    account_index=account_position,
                    account_total=len(account_ids),
                    account_id=account_id,
                    email=email,
                    phone=phone,
                    phone_index=phone_index,
                    phone_total=total_phones,
                    phone_total_label=phone_total_label,
                    attempt=account_attempts,
                    stage_index=1,
                    stage_label="准备",
                )
                phone_attempt_header(
                    account_position=account_position,
                    account_total=len(account_ids),
                    phone_index=phone_index,
                    phone_total_label=phone_total_label,
                    phone=phone,
                )
                timeline(
                    email=email,
                    account_id=account_id,
                    phone=phone,
                    phase="prepare",
                    phase_label="准备",
                    stage_index=1,
                    message=(
                        f"账号ID={account_id}，手机号={phone}，手机号序号={phone_index}/{phone_total_label}，"
                        f"尝试={account_attempts}，来源={'号码池' if use_pool else '上传列表'}"
                    ),
                    next_step="选择代理",
                    resource_touched=False,
                    reset_started_at=True,
                )
                if use_pool:
                    _task_store.set_progress(task_id, f"{max(account_position - 1, 0)}/{total}")
                else:
                    _task_store.set_progress(task_id, f"{max(phone_index - 1, 0)}/{total}")

                attempt_id = account_attempt_id
                service_entry = UploadedPhoneEntry(
                    country_slug="uploaded",
                    phone=phone,
                    detail_url=str(item.get("api_url") or ""),
                    api_url=str(item.get("api_url") or ""),
                    raw_line=raw_line,
                    line_no=int(item.get("line_no") or 0),
                    source_api_url=str(item.get("source_api_url") or item.get("api_url") or ""),
                )
                phone_service = UploadedPhoneService(
                    [service_entry],
                    {
                        "_task_stop_checker": lambda: control.checkpoint(attempt_id=attempt_id),
                        "uploaded_phone_timeout_seconds": int(settings.get("timeout_seconds") or 180),
                        "uploaded_phone_poll_interval_seconds": int(settings.get("poll_interval_seconds") or 5),
                        "uploaded_phone_max_resend_attempts": int(settings.get("max_resend_attempts") or 0),
                        "uploaded_phone_resend_interval_seconds": int(settings.get("resend_interval_seconds") or 30),
                    },
                    log_fn=task_log,
                )
                phone_service.bind_entry(service_entry)

                try:
                    wait_before_next_account_attempt(attempt_id)
                    with Session(engine) as session:
                        account = session.get(AccountModel, account_id)
                        if account is None or account.platform != "chatgpt":
                            raise ValueError("ChatGPT 账号不存在")
                        email = str(account.email or "")
                        if not primary_email:
                            primary_email = email
                        set_phone_log_context(email=email)

                    candidate_proxies = _build_phone_binding_candidate_proxies()
                    phone_log(
                        f"邮箱={email or '-'}，账号ID={account_id}，手机号={phone}",
                        stage_index=1,
                        phase_label="准备",
                    )
                    control.checkpoint(attempt_id=attempt_id)
                    with Session(engine) as session:
                        account = session.get(AccountModel, account_id)
                        if account is None or account.platform != "chatgpt":
                            raise ValueError("ChatGPT 账号不存在")
                        result: dict[str, Any] = {}
                        selected_proxy_url = ""
                        for proxy_index, (candidate_proxy, candidate_proxy_pool, candidate_proxy_source) in enumerate(candidate_proxies, start=1):
                            selected_proxy_url = candidate_proxy
                            _log_phone_binding_proxy_choice(candidate_proxy, candidate_proxy_source, proxy_index, len(candidate_proxies))
                            try:
                                timeline(
                                    email=email,
                                    account_id=account_id,
                                    phone=phone,
                                    phase="oauth_login",
                                    phase_label="OAuth登录",
                                    stage_index=3,
                                    message=f"开始 OAuth 登录；代理 {proxy_index}/{len(candidate_proxies)}",
                                    next_step="邮箱验证或进入手机号绑定",
                                    resource_touched=False,
                                    reset_started_at=(proxy_index == 1),
                                )
                                resume_kwargs = {
                                    "allow_phone_verification": True,
                                    "log_fn": task_log,
                                    "shared_phone_service": phone_service,
                                    "stop_checker": lambda: control.checkpoint(attempt_id=attempt_id),
                                    "retry_delays_seconds": [],
                                }
                                if prefix_sms_probe_only:
                                    resume_kwargs["phone_sms_probe_only"] = True
                                if candidate_proxy:
                                    resume_kwargs["proxy_url"] = candidate_proxy
                                result = _execute_chatgpt_resume_subscription_auth(
                                    account,
                                    **resume_kwargs,
                                )
                                proxy_error_text = result_error_text(result, "") if not bool(result.get("ok")) else ""
                                if (
                                    proxy_error_text
                                    and is_proxy_error_text(proxy_error_text)
                                    and not phone_was_touched(phone_service)
                                    and proxy_index < len(candidate_proxies)
                                ):
                                    _report_phone_proxy_fail(candidate_proxy_pool, candidate_proxy, proxy_error_text)
                                    phone_log(
                                        f"当前代理疑似不可用且手机号未触碰，切换下一个代理：{proxy_error_text[:180]}",
                                        stage_index=2,
                                        phase_label="选择代理",
                                    )
                                    continue
                                _report_phone_proxy_success(candidate_proxy_pool, candidate_proxy, phone_service, result)
                                break
                            except (SkipCurrentAttemptRequested, StopTaskRequested):
                                raise
                            except Exception as proxy_exc:
                                proxy_error_text = str(proxy_exc or "手机号绑定失败")
                                if (
                                    is_proxy_error_text(proxy_error_text)
                                    and not phone_was_touched(phone_service)
                                    and proxy_index < len(candidate_proxies)
                                ):
                                    _report_phone_proxy_fail(candidate_proxy_pool, candidate_proxy, proxy_error_text)
                                    phone_log(
                                        f"当前代理异常且手机号未触碰，切换下一个代理：{proxy_error_text[:180]}",
                                        stage_index=2,
                                        phase_label="选择代理",
                                    )
                                    continue
                                _report_phone_proxy_fail(candidate_proxy_pool, candidate_proxy, proxy_error_text)
                                raise
                        session.refresh(account)
                        ok = bool(result.get("ok"))
                        data = result.get("data") if isinstance(result.get("data"), dict) else {}
                        auth_retry_attempts = 0

                        if prefix_sms_probe_only and phone_service.completed_entries:
                            success_count += 1
                            success_reason = "OpenAI 已发码，收码 API 已收到验证码；按设置未提交验证码，未完成手机号绑定"
                            phone_result = result_for_phone(
                                item,
                                "sms_probe_received",
                                account_id=account_id,
                                email=email,
                                reason=success_reason,
                                code_received=True,
                                phone_service=phone_service,
                            )
                            phone_result["verification_submitted"] = False
                            phone_result["sms_probe_only"] = True
                            raw_result_line = str(phone_result.get("raw_line") or raw_line or f"{phone}----{item.get('api_url') or ''}")
                            session.commit()
                            runtime_results.append(phone_result)
                            record_pool_result(item, "sms_probe_received", reason=success_reason, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                            if phone:
                                successful_phones_this_run.add(phone)
                                preferred_pool_phone = ""
                                preferred_phone_item = None
                            bound_phone_results.append({**phone_result, "raw_line": raw_result_line})
                            account_index = account_position
                            account_results.append({"account_id": account_id, "email": email, "status": "sms_probe_received", "phone": phone, "reason": success_reason})
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="phone_sms_wait",
                                phase_label="接收短信",
                                stage_index=7,
                                message="已收码未提交：短信探测完成，不执行绑定",
                                next_step="回写号码池",
                                resource_touched=True,
                                reset_started_at=True,
                            )
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="pool_writeback",
                                phase_label="回写号码池",
                                stage_index=12,
                                message="已回写号码池：短信探测成功",
                                next_step="处理下一个账号",
                                resource_touched=True,
                                reset_started_at=True,
                            )
                            account_done = True
                            sync_meta()
                            break
                        try:
                            session.commit()
                        except Exception:
                            session.rollback()
                        try:
                            session.refresh(account)
                        except Exception:
                            pass
                        _apply_chatgpt_resume_auth_result(account, result, session)

                        if (not ok) and phone_service.completed_entries:
                            result, auth_retry_attempts, _ = retry_auth_capture_after_phone_completed(
                                account=account,
                                session=session,
                                first_result=result,
                                email=email,
                                attempt_id=attempt_id,
                                proxy_url=selected_proxy_url,
                            )
                            ok = bool(result.get("ok"))
                            data = result.get("data") if isinstance(result.get("data"), dict) else {}

                        if phone_service.completed_entries:
                            success_count += 1
                            auth_error_text = "" if ok else result_error_text(result, "Auth/RT 获取失败")
                            success_reason = "验证码已提交 OpenAI，手机号绑定完成"
                            if ok:
                                success_reason = (
                                    f"{success_reason}，Auth/RT 已获取"
                                    if auth_retry_attempts <= 0
                                    else f"{success_reason}，Auth/RT 重试 {auth_retry_attempts} 次后已获取"
                                )
                            else:
                                success_reason = (
                                    f"{success_reason}；但 Auth/RT 重试 {auth_retry_attempts} 次仍失败: "
                                    f"{auth_error_text[:180]}"
                                )
                            phone_result = result_for_phone(
                                item,
                                "bound",
                                account_id=account_id,
                                email=email,
                                reason=success_reason,
                                code_received=True,
                                phone_service=phone_service,
                            )
                            raw_result_line = str(phone_result.get("raw_line") or raw_line or f"{phone}----{item.get('api_url') or ''}")
                            bound_phone_lines.append(raw_result_line)
                            phone_result["auth_capture_ok"] = bool(ok)
                            phone_result["auth_retry_attempts"] = int(auth_retry_attempts or 0)
                            if auth_error_text:
                                phone_result["auth_error"] = auth_error_text
                                _log(
                                    task_id,
                                    f"[手机号绑定] 手机号已绑定完成，但 Auth/RT 获取失败：{auth_error_text[:180]}",
                                )
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="phone_bound_confirmed",
                                phase_label="确认绑定",
                                stage_index=9,
                                message="手机号验证码已通过，OpenAI 侧绑定完成",
                                next_step="补抓 Auth/RT",
                                resource_touched=True,
                                reset_started_at=True,
                            )
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="auth_capture_after_phone",
                                phase_label="补抓Auth",
                                stage_index=10,
                                message=(
                                    "Auth/RT 获取成功"
                                    if ok
                                    else f"Auth/RT 获取失败：{auth_error_text[:180]}"
                                ),
                                next_step="保存账号绑定状态",
                                resource_touched=True,
                                reset_started_at=True,
                            )
                            try:
                                session.commit()
                            except Exception:
                                session.rollback()
                            try:
                                session.refresh(account)
                            except Exception:
                                pass
                            _persist_phone_binding_result(
                                account,
                                phone_result,
                                task_id=task_id,
                                raw_line=raw_result_line,
                            )
                            session.add(account)
                            session.commit()
                            from services.account_filters import upsert_account_list_state_for_account_ids
                            upsert_account_list_state_for_account_ids(session, [account.id], commit=True)
                            try:
                                session.refresh(account)
                            except Exception:
                                pass
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="save_account",
                                phase_label="保存账号",
                                stage_index=11,
                                message="已写入账号绑定状态 chatgpt_phone_binding",
                                next_step="回写号码池",
                                resource_touched=True,
                                reset_started_at=True,
                            )
                            runtime_results.append(phone_result)
                            record_pool_result(item, "bound", reason=success_reason, email=email, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="pool_writeback",
                                phase_label="回写号码池",
                                stage_index=12,
                                message="已回写号码池：绑定成功",
                                next_step="处理下一个账号",
                                resource_touched=True,
                                reset_started_at=True,
                            )
                            if phone:
                                successful_phones_this_run.add(phone)
                                if reuse_phone_until_unusable:
                                    if use_pool and pool_repo is not None:
                                        get_record = getattr(pool_repo, "get", None)
                                        latest_record = get_record(phone) if callable(get_record) else None
                                        preferred_pool_phone = phone if latest_record is not None and latest_record.available else ""
                                    else:
                                        preferred_phone_item = dict(item)
                                else:
                                    preferred_pool_phone = ""
                                    preferred_phone_item = None
                            bound_phone_results.append({**phone_result, "raw_line": raw_result_line})
                            account_index = account_position
                            if ok:
                                account_results.append({"account_id": account_id, "email": email, "status": "used_for_binding", "phone": phone})
                            else:
                                account_results.append(
                                    {
                                        "account_id": account_id,
                                        "email": email,
                                        "status": "used_for_binding_auth_failed",
                                        "phone": phone,
                                        "reason": auth_error_text,
                                    }
                                )
                                errors.append(f"{email or account_id}: 手机号已绑定，但 Auth/RT 获取失败: {auth_error_text}")
                            account_done = True
                            sync_meta()
                            break

                        if ok and not phone_service.completed_entries:
                            session.commit()
                            skipped_count += 1
                            # 账号未进入 add_phone，当前手机号未提交 OpenAI，不消耗该手机号，留给下一个账号。
                            if not use_pool and preferred_phone_item is None:
                                phone_cursor = max(phone_cursor - 1, 0)
                            skip_reason = "账号已完成 Auth，未进入 add_phone；当前手机号未提交 OpenAI，留给下一个账号继续测试"
                            runtime_results.append(
                                result_for_phone(
                                    item,
                                    "account_phone_bound",
                                    account_id=account_id,
                                    email=email,
                                    reason=skip_reason,
                                    phone_service=phone_service,
                                )
                            )
                            account_index = account_position
                            account_results.append({"account_id": account_id, "email": email, "status": "account_phone_bound", "reason": "账号已完成 Auth，未进入 add_phone 或未消耗上传号码"})
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="skipped",
                                phase_label="进入绑定",
                                stage_index=5,
                                message="账号已完成 Auth，未进入 add_phone；当前手机号未消耗",
                                next_step="处理下一个账号",
                                resource_touched=False,
                                reset_started_at=True,
                            )
                            account_done = True
                            sync_meta()
                            break

                        error_text = result_error_text(result)
                        status = _phone_binding_error_status(error_text)
                        if status in {"openai_rejected", "openai_phone_limit", "phone_already_used", "api_no_code", "api_error", "rate_limited"}:
                            skipped_count += 1
                            accounts_with_phone_terminal_result.add(account_id)
                            if phone:
                                terminal_phones_this_run.add(phone)
                                if phone == preferred_pool_phone:
                                    preferred_pool_phone = ""
                                if preferred_phone_item is not None and str(preferred_phone_item.get("phone") or "") == phone:
                                    preferred_phone_item = None
                            phone_result = result_for_phone(item, status, account_id=account_id, email=email, reason=error_text, phone_service=phone_service)
                            runtime_results.append(phone_result)
                            record_pool_result(item, status, reason=error_text, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                            failure_stage = 7 if status in {"api_no_code", "api_error"} else 6
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="phone_failed",
                                phase_label=PHONE_BINDING_STAGE_LABELS.get(failure_stage, "发送短信"),
                                stage_index=failure_stage,
                                message=f"{_phone_binding_status_label(status)}：{error_text}",
                                next_step="回写号码池",
                                resource_touched=phone_was_touched(phone_service),
                                reset_started_at=True,
                            )
                            writeback_message = "已回写号码池：当前手机号不可继续使用"
                            if status == "phone_already_used":
                                writeback_message = "已回写号码池：手机号已被使用；号段记为可用信号"
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="pool_writeback",
                                phase_label="回写号码池",
                                stage_index=12,
                                message=writeback_message,
                                next_step="继续尝试下一个手机号",
                                resource_touched=phone_was_touched(phone_service),
                                reset_started_at=True,
                            )
                            _log(task_id, "[手机号绑定][号码] 不可继续｜处理=账号将继续尝试下一个手机号")
                            sync_meta()
                            continue

                        if should_keep_phone_for_next_account(status, phone_service):
                            # 账号前置失败，手机号没有被 OpenAI 触碰：账号消耗，手机号回退给下一个账号。
                            if not use_pool and preferred_phone_item is None:
                                phone_cursor = max(phone_cursor - 1, 0)
                            recover_at = (
                                mark_account_rate_limited_for_recovery(account_id, email, error_text)
                                if is_account_rate_limit_error(status, error_text)
                                else ""
                            )
                            account_result_status = "rate_limited" if recover_at else status
                            account_reason = (
                                f"{error_text}；账号限流预计恢复: {recover_at}"
                                if recover_at
                                else error_text
                            )
                            account_index = account_position
                            account_results.append({"account_id": account_id, "email": email, "status": account_result_status, "reason": account_reason})
                            errors.append(f"{email or account_id}: {account_reason}")
                            timeline(
                                email=email,
                                account_id=account_id,
                                phone=phone,
                                phase="account_failed",
                                phase_label="OAuth登录",
                                stage_index=3,
                                message=f"账号前置失败，手机号未被触碰：{account_reason}",
                                next_step="继续用下一个账号测试当前手机号",
                                resource_touched=False,
                                reset_started_at=True,
                            )
                            account_done = True
                            sync_meta()
                            break

                        account_index = account_position
                        phone_result = result_for_phone(item, status, account_id=account_id, email=email, reason=error_text, phone_service=phone_service)
                        runtime_results.append(phone_result)
                        record_pool_result(item, status, reason=error_text, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                        account_results.append({"account_id": account_id, "email": email, "status": status, "reason": error_text})
                        errors.append(f"{email or account_id}: {error_text}")
                        timeline(
                            email=email,
                            account_id=account_id,
                            phone=phone,
                            phase="failed",
                            phase_label="确认绑定",
                            stage_index=9,
                            message=error_text,
                            next_step="查看 Debug 或处理下一个账号",
                            resource_touched=phone_was_touched(phone_service),
                            reset_started_at=True,
                        )
                        account_done = True
                        sync_meta()
                        break

                except SkipCurrentAttemptRequested as exc:
                    account_index = account_position
                    skipped_count += 1
                    runtime_results.append(result_for_phone(item, "not_tested", account_id=account_id, email=email, reason=str(exc), phone_service=phone_service))
                    account_results.append({"account_id": account_id, "email": email, "status": "skipped", "reason": str(exc)})
                    timeline(
                        email=email,
                        account_id=account_id,
                        phone=phone,
                        phase="skipped",
                        phase_label="已跳过当前账号",
                        stage_index=9,
                        message=str(exc),
                        next_step="处理下一个账号",
                        resource_touched=phone_was_touched(phone_service),
                        reset_started_at=True,
                    )
                    account_done = True
                    sync_meta()
                    break
                except StopTaskRequested:
                    raise
                except Exception as exc:
                    error_text = str(exc or "手机号绑定失败")
                    status = _phone_binding_error_status(error_text)
                    if status in {"openai_rejected", "openai_phone_limit", "phone_already_used", "api_no_code", "api_error", "rate_limited"}:
                        skipped_count += 1
                        accounts_with_phone_terminal_result.add(account_id)
                        if phone:
                            terminal_phones_this_run.add(phone)
                            if phone == preferred_pool_phone:
                                preferred_pool_phone = ""
                            if preferred_phone_item is not None and str(preferred_phone_item.get("phone") or "") == phone:
                                preferred_phone_item = None
                        phone_result = result_for_phone(item, status, account_id=account_id, email=email, reason=error_text, phone_service=phone_service)
                        runtime_results.append(phone_result)
                        record_pool_result(item, status, reason=error_text, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                        failure_stage = 7 if status in {"api_no_code", "api_error"} else 6
                        timeline(
                            email=email,
                            account_id=account_id,
                            phone=phone,
                            phase="phone_failed",
                            phase_label=PHONE_BINDING_STAGE_LABELS.get(failure_stage, "发送短信"),
                            stage_index=failure_stage,
                            message=f"{_phone_binding_status_label(status)}：{error_text}",
                            next_step="回写号码池",
                            resource_touched=phone_was_touched(phone_service),
                            reset_started_at=True,
                        )
                        writeback_message = "已回写号码池：当前手机号不可继续使用"
                        if status == "phone_already_used":
                            writeback_message = "已回写号码池：手机号已被使用；号段记为可用信号"
                        timeline(
                            email=email,
                            account_id=account_id,
                            phone=phone,
                            phase="pool_writeback",
                            phase_label="回写号码池",
                            stage_index=12,
                            message=writeback_message,
                            next_step="继续尝试下一个手机号",
                            resource_touched=phone_was_touched(phone_service),
                            reset_started_at=True,
                        )
                        _log(task_id, "[手机号绑定][号码] 不可继续｜处理=账号将继续尝试下一个手机号")
                        sync_meta()
                        continue
                    if should_keep_phone_for_next_account(status, phone_service):
                        if not use_pool and preferred_phone_item is None:
                            phone_cursor = max(phone_cursor - 1, 0)
                        recover_at = (
                            mark_account_rate_limited_for_recovery(account_id, email, error_text)
                            if is_account_rate_limit_error(status, error_text)
                            else ""
                        )
                        account_result_status = "rate_limited" if recover_at else status
                        account_reason = (
                            f"{error_text}；账号限流预计恢复: {recover_at}"
                            if recover_at
                            else error_text
                        )
                        account_index = account_position
                        errors.append(f"{email or account_id}: {account_reason}")
                        account_results.append({"account_id": account_id, "email": email, "status": account_result_status, "reason": account_reason})
                        timeline(
                            email=email,
                            account_id=account_id,
                            phone=phone,
                            phase="account_failed",
                            phase_label="OAuth登录",
                            stage_index=3,
                            message=f"账号前置失败，手机号未被触碰：{account_reason}",
                            next_step="继续用下一个账号测试当前手机号",
                            resource_touched=False,
                            reset_started_at=True,
                        )
                        account_done = True
                        sync_meta()
                        break

                    account_index = account_position
                    errors.append(f"{email or account_id}: {error_text}")
                    phone_result = result_for_phone(item, status, account_id=account_id, email=email, reason=error_text, phone_service=phone_service)
                    runtime_results.append(phone_result)
                    record_pool_result(item, status, reason=error_text, api_expired_date=str(phone_result.get("api_expired_date") or ""))
                    account_results.append({"account_id": account_id, "email": email, "status": status, "reason": error_text})
                    timeline(
                        email=email,
                        account_id=account_id,
                        phone=phone,
                        phase="failed",
                        phase_label="确认绑定",
                        stage_index=9,
                        message=error_text,
                        next_step="查看 Debug 或处理下一个账号",
                        resource_touched=phone_was_touched(phone_service),
                        reset_started_at=True,
                    )
                    account_done = True
                    sync_meta()
                    break
                finally:
                    control.finish_attempt(attempt_id)
                    last_account_attempt_finished_at = time.monotonic()

            control.finish_attempt(account_attempt_id)
            if not account_done:
                remaining_start = account_position if account_id in accounts_with_phone_terminal_result else account_position - 1
                remaining_account_ids = [int(value or 0) for value in account_ids[remaining_start:] if int(value or 0) > 0]
                if remaining_account_ids:
                    skipped_count += len(remaining_account_ids)
                    empty_label = (
                        "手机号池当前没有可用号码"
                        if use_pool
                        else "号段抽样号码已耗尽"
                        if prefix_sample_enabled
                        else "手机号列表已耗尽"
                    )
                    empty_reason = f"{empty_label}，未完成绑定"
                    if remaining_start == account_position:
                        empty_message = f"[手机号绑定] {empty_label}，剩余 {len(remaining_account_ids)} 个账号未完成绑定"
                    else:
                        empty_message = (
                            f"[手机号绑定] {empty_label}，当前账号 {account_id} "
                            f"及剩余 {max(len(remaining_account_ids) - 1, 0)} 个账号未完成绑定"
                        )
                    _log(
                        task_id,
                        empty_message,
                    )
                    for remaining_id in remaining_account_ids:
                        account_results.append(
                            {
                                "account_id": remaining_id,
                                "email": "",
                                "status": "not_tested",
                                "reason": empty_reason,
                            }
                        )
                    sync_meta()
                break

            if use_pool:
                _task_store.set_progress(task_id, f"{min(account_position, total)}/{total}")
            else:
                _task_store.set_progress(task_id, f"{min(phone_cursor, total)}/{total}")

        final_status = "done"
        try:
            from collections import Counter

            runtime_status_counts = Counter(str(item.get("status") or "unknown") for item in runtime_results)
            account_status_counts = Counter(str(item.get("status") or "unknown") for item in account_results)
        except Exception:
            runtime_status_counts = {}
            account_status_counts = {}
        phone_issue_count = sum(
            int(runtime_status_counts.get(status, 0))
            for status in (
                "openai_rejected",
                "openai_phone_limit",
                "phone_already_used",
                "api_no_code",
                "api_error",
                "rate_limited",
            )
        )
        forward_issue_count = int(runtime_status_counts.get("api_forward_error", 0))
        account_issue_count = sum(
            int(account_status_counts.get(status, 0))
            for status in ("account_auth_error", "unknown", "rate_limited")
        )
        summary_message = (
            f"OpenAI 手机号绑定完成：成功 {success_count}/{len(account_ids)}，"
            f"手机号问题 {phone_issue_count}，转发问题 {forward_issue_count}，"
            f"账号问题 {account_issue_count}，跳过 {skipped_count}"
        )
        _log(
            task_id,
            "[手机号绑定][汇总] 完成"
            f"｜成功={success_count}/{len(account_ids)}"
            f"｜手机号问题={phone_issue_count}"
            f"｜转发问题={forward_issue_count}"
            f"｜账号问题={account_issue_count}"
            f"｜跳过={skipped_count}",
        )
        if runtime_results:
            phone_bucket_labels = {
                "openai_rejected": "OpenAI 拒绝",
                "openai_phone_limit": "绑定上限",
                "phone_already_used": "手机号已被使用",
                "api_no_code": "已发码但未收码",
                "api_error": "收码 API 异常",
                "api_forward_error": "API 转发暂时不可用",
                "rate_limited": "OpenAI 限流",
                "bound": "绑定成功",
                "sms_probe_received": "已收码未提交",
            }
            phone_parts = [
                f"{label}={int(runtime_status_counts.get(status, 0))}"
                for status, label in phone_bucket_labels.items()
                if int(runtime_status_counts.get(status, 0))
            ]
            if phone_parts:
                _log(task_id, f"[手机号绑定][汇总] 手机号结果｜{'｜'.join(phone_parts)}")
        if account_results:
            account_bucket_labels = {
                "used_for_binding": "完成绑定",
                "used_for_binding_auth_failed": "已绑定但补Auth失败",
                "account_auth_error": "账号Auth异常",
                "rate_limited": "账号限流",
                "unknown": "未知/OTP冷却",
                "account_phone_bound": "无需绑定",
                "skipped": "手动跳过",
                "not_tested": "未测试",
            }
            account_parts = [
                f"{label}={int(account_status_counts.get(status, 0))}"
                for status, label in account_bucket_labels.items()
                if int(account_status_counts.get(status, 0))
            ]
            if account_parts:
                _log(task_id, f"[手机号绑定][汇总] 账号结果｜{'｜'.join(account_parts)}")
        if prefix_sample_enabled:
            prefix_summary = _build_phone_prefix_sample_summary(phone_items, runtime_results)
            _log(
                task_id,
                "[手机号绑定][号段抽样] 汇总"
                f"｜成功样本={prefix_summary['positive_sample_prefix_count']}"
                f"｜失败样本={prefix_summary['negative_sample_prefix_count']}"
                f"｜结果混合={prefix_summary['mixed_sample_prefix_count']}"
                f"｜未测试={prefix_summary['untested_prefix_count']}",
            )
            assessment_labels = {
                "positive_sample": "样本成功",
                "negative_sample": "样本失败",
                "mixed_sample": "样本混合",
                "untested": "未测试",
            }
            for prefix_item in prefix_summary["items"]:
                assessment = str(prefix_item.get("assessment") or prefix_item.get("status") or "untested")
                _log(
                    task_id,
                    "[手机号绑定][号段抽样] 样本结果"
                    f"｜号段={prefix_item['prefix']}"
                    f"｜状态={assessment_labels.get(assessment, assessment)}"
                    f"｜成功={prefix_item['available_count']}"
                    f"｜失败={prefix_item['unavailable_count']}"
                    f"｜未测试={prefix_item['untested_count']}",
                )
            if prefix_summary["negative_sample_prefixes"]:
                _log(
                    task_id,
                    "[手机号绑定][号段抽样] 失败样本号段"
                    f"｜号段={','.join(prefix_summary['negative_sample_prefixes'])}"
                    "｜结论=仅代表本次抽样号码",
                )
        if runtime_results:
            _log(task_id, f"[手机号绑定][汇总] 结果表已生成｜总数={len(runtime_results)}｜成功绑定={len(bound_phone_results)}")
        else:
            _log(task_id, "[手机号绑定][汇总] 结果表已生成｜总数=0｜成功绑定=0")
        sync_meta()
        log_status = "success" if success_count > 0 and not errors else "failed"
        attempt_outcome = "phone_binding_test_success" if log_status == "success" else "phone_binding_test_failed"
        if log_status != "success" and no_phone_available:
            attempt_outcome = "phone_binding_test_no_phone_available"
        _task_store.finish(
            task_id,
            status=final_status,
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error="" if not errors else summary_message,
        )
        terminal_status = str(_task_store.snapshot(task_id).get("status") or log_status)
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        _save_task_log(
            "chatgpt",
            primary_email,
            terminal_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": attempt_outcome,
                    "source": "phone_binding_test",
                    "meta": latest_meta,
                    "bound_phone_lines": [redact_raw_phone_line(line) for line in bound_phone_lines],
                    "bound_phone_results": [sanitize_phone_result(item) for item in bound_phone_results],
                    "runtime_results": [sanitize_phone_result(item) for item in runtime_results],
                    "account_results": sanitize_task_detail(account_results),
                },
            ),
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        sync_meta()
        _task_store.finish(
            task_id,
            status="stopped",
            success=success_count,
            skipped=skipped_count,
            errors=list(errors),
            error=str(exc),
        )
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        _save_task_log(
            "chatgpt",
            primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "phone_binding_test_stopped",
                    "source": "phone_binding_test",
                    "meta": latest_meta,
                    "bound_phone_lines": [redact_raw_phone_line(line) for line in bound_phone_lines],
                    "bound_phone_results": [sanitize_phone_result(item) for item in bound_phone_results],
                    "runtime_results": [sanitize_phone_result(item) for item in runtime_results],
                    "account_results": sanitize_task_detail(account_results),
                },
            ),
        )
    except Exception as exc:
        error_text = str(exc or "手机号绑定测试异常退出")
        errors.append(error_text)
        _log(task_id, f"[ERROR] 手机号绑定测试异常退出: {error_text}")
        try:
            sync_meta()
        except Exception as sync_exc:
            _log(task_id, f"[ERROR] 手机号绑定测试异常状态同步失败: {sync_exc}")
        _task_store.finish(
            task_id,
            status="failed",
            success=success_count,
            skipped=skipped_count,
            errors=errors,
            error=error_text,
        )
        latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
        _save_task_log(
            "chatgpt",
            primary_email,
            "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": primary_email,
                    "attempt_outcome": "phone_binding_test_exception",
                    "source": "phone_binding_test",
                    "meta": latest_meta,
                    "bound_phone_lines": [redact_raw_phone_line(line) for line in bound_phone_lines],
                    "bound_phone_results": [sanitize_phone_result(item) for item in bound_phone_results],
                    "runtime_results": [sanitize_phone_result(item) for item in runtime_results],
                    "account_results": sanitize_task_detail(account_results),
                },
            ),
        )
    finally:
        _task_store.cleanup()


def _run_batch_web_session_login(
    task_id: str,
    account_ids: list[int],
    settings: dict[str, Any] | None = None,
):
    from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait

    runtime_settings = dict(settings or {})
    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    requested_concurrency = _invalid_recheck_requested_concurrency(
        runtime_settings.get("requested_concurrency") or runtime_settings.get("concurrency"),
        default=1,
    )
    effective_concurrency = min(
        _invalid_recheck_requested_concurrency(runtime_settings.get("concurrency"), default=requested_concurrency),
        total,
    )
    proxy_settings = {
        key: runtime_settings.get(key)
        for key in _TASK_PROXY_RUNTIME_KEYS
        if key in runtime_settings
    }

    state_lock = threading.RLock()
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    results: list[dict[str, Any]] = []
    primary_email = ""

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    skipped_items = list(meta.get("skipped_items") or [])
    missing_ids = list(meta.get("missing_ids") or [])
    meta_emails = meta.get("emails")
    if isinstance(meta_emails, list) and meta_emails:
        primary_email = str(meta_emails[0] or "")

    def task_log(
        message: str,
        *,
        attempt_id: int | None = None,
        check_stop: bool = True,
    ) -> None:
        if check_stop:
            control.checkpoint(consume_skip=False, attempt_id=attempt_id)
        _log(task_id, message)

    def current_runtime_meta() -> dict[str, Any]:
        latest = dict(_task_store.snapshot(task_id).get("meta") or meta)
        with state_lock:
            ordered_results = sorted(results, key=lambda item: int(item.get("position") or 0))
            latest.update(
                {
                    "requested_concurrency": requested_concurrency,
                    "effective_concurrency": effective_concurrency,
                    "runtime_success": success_count,
                    "runtime_skipped": skipped_count,
                    "runtime_errors": list(errors),
                    "results": sanitize_task_detail(ordered_results),
                }
            )
        return latest

    def sync_runtime_meta() -> None:
        try:
            _task_store.update_meta(task_id, current_runtime_meta())
        except Exception:
            pass

    def process_account(account_position: int, account_id: int, attempt_id: int) -> dict[str, Any]:
        nonlocal primary_email
        email = ""
        try:
            control.checkpoint(attempt_id=attempt_id)
            with Session(engine) as session:
                account = session.get(AccountModel, int(account_id or 0))
                if account is None or account.platform != "chatgpt":
                    raise ValueError("ChatGPT 账号不存在")
                email = str(account.email or "")
                skip_reason = _web_session_login_skip_reason(account)

            with state_lock:
                if not primary_email:
                    primary_email = email

            if skip_reason:
                task_log(
                    f"[执行登录态][账号 {account_position}/{total}] 跳过｜账号={email or account_id}｜原因={skip_reason}",
                    attempt_id=attempt_id,
                )
                return {
                    "position": account_position,
                    "account_id": account_id,
                    "email": email,
                    "status": "skipped",
                    "message": skip_reason,
                }

            task_log(
                f"[执行登录态][账号 {account_position}/{total}] 开始｜账号={email or account_id}｜并发={effective_concurrency}",
                attempt_id=attempt_id,
            )
            result, email = _execute_web_session_login_with_proxy_candidates(
                task_id=task_id,
                account_id=account_id,
                proxy_settings=proxy_settings,
                control=control,
                attempt_id=attempt_id,
                log_fn=lambda message: task_log(
                    f"[账号 {account_position}/{total}] {message}",
                    attempt_id=attempt_id,
                ),
            )

            data = result.get("data") if isinstance(result.get("data"), dict) else {}
            if not bool(result.get("ok")):
                error_text = sanitize_error_message(
                    str(result.get("error") or data.get("message") or "执行登录态失败")
                )
                if str(data.get("error_code") or "").strip().lower() == "browser_lease_released":
                    task_log(
                        f"[执行登录态][账号 {account_position}/{total}] 已释放｜账号={email or account_id}｜登录尚未就绪，未改写原认证材料",
                        attempt_id=attempt_id,
                        check_stop=False,
                    )
                    return {
                        "position": account_position,
                        "account_id": account_id,
                        "email": email,
                        "status": "released",
                        "message": error_text,
                    }
                task_log(
                    f"[执行登录态][账号 {account_position}/{total}] 失败｜账号={email or account_id}｜原因={error_text}",
                    attempt_id=attempt_id,
                    check_stop=False,
                )
                return {
                    "position": account_position,
                    "account_id": account_id,
                    "email": email,
                    "status": "failed",
                    "error": error_text,
                }

            task_log(
                f"[执行登录态][账号 {account_position}/{total}] 成功｜账号={email or account_id}｜结果=完整Web Session已写回",
                attempt_id=attempt_id,
                check_stop=False,
            )
            return {
                "position": account_position,
                "account_id": account_id,
                "email": email,
                "status": "success",
                "message": "完整 Web Session 已写回",
                "local_status_refresh_scheduled": bool(data.get("local_status_refresh_scheduled")),
            }
        except SkipCurrentAttemptRequested as exc:
            task_log(
                f"[执行登录态][账号 {account_position}/{total}] 已跳过｜账号={email or account_id}｜原因={exc}",
                check_stop=False,
            )
            return {
                "position": account_position,
                "account_id": account_id,
                "email": email,
                "status": "skipped",
                "message": str(exc),
            }
        except StopTaskRequested:
            raise
        except Exception as exc:
            error_text = sanitize_error_message(str(exc or "执行登录态失败"))
            task_log(
                f"[执行登录态][账号 {account_position}/{total}] 异常｜账号={email or account_id}｜原因={error_text}",
                check_stop=False,
            )
            return {
                "position": account_position,
                "account_id": account_id,
                "email": email,
                "status": "failed",
                "error": error_text,
            }
        finally:
            control.finish_attempt(attempt_id)

    def apply_result(result: dict[str, Any]) -> None:
        nonlocal success_count, skipped_count
        status = str(result.get("status") or "failed")
        account_label = str(result.get("email") or result.get("account_id") or "-")
        with state_lock:
            results.append(dict(result))
            if status == "success":
                success_count += 1
            elif status in {"skipped", "released"}:
                skipped_count += 1
            else:
                errors.append(f"{account_label}: {result.get('error') or '执行登录态失败'}")
        sync_runtime_meta()

    try:
        control.checkpoint(consume_skip=False)
        for missing_id in missing_ids:
            task_log(f"[MISS] 账号不存在: account_id={missing_id}", check_stop=False)
            with state_lock:
                errors.append(f"account_id={missing_id}: 账号不存在")

        for item in skipped_items:
            task_log(
                f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - {item.get('reason') or '已跳过'}",
                check_stop=False,
            )

        task_log(
            f"[执行登录态][配置] 并发已开启｜请求={requested_concurrency}｜实际={effective_concurrency}",
            check_stop=False,
        )

        ordered_account_ids = [int(account_id or 0) for account_id in account_ids if int(account_id or 0) > 0]
        next_account_index = 0
        completed_count = 0
        in_flight: dict[Any, tuple[int, int]] = {}

        def should_stop_starting_new_attempts() -> bool:
            value = control.should_stop_starting_new_attempts()
            return value if isinstance(value, bool) else False

        def launch_next_account(pool: ThreadPoolExecutor) -> bool:
            nonlocal next_account_index
            if next_account_index >= len(ordered_account_ids) or should_stop_starting_new_attempts():
                return False
            account_position = next_account_index + 1
            account_id = ordered_account_ids[next_account_index]
            attempt_id = _claim_next_task_attempt(control)
            future = pool.submit(process_account, account_position, account_id, attempt_id)
            in_flight[future] = (account_position, account_id)
            next_account_index += 1
            return True

        with ThreadPoolExecutor(max_workers=effective_concurrency) as pool:
            while len(in_flight) < effective_concurrency and launch_next_account(pool):
                pass

            while in_flight:
                control.checkpoint(consume_skip=False)
                done, _ = wait(tuple(in_flight.keys()), timeout=0.5, return_when=FIRST_COMPLETED)
                if not done:
                    continue
                for future in done:
                    account_position, account_id = in_flight.pop(future)
                    try:
                        result = future.result()
                    except StopTaskRequested:
                        raise
                    except Exception as exc:
                        result = {
                            "position": account_position,
                            "account_id": account_id,
                            "email": "",
                            "status": "failed",
                            "error": sanitize_error_message(str(exc) or "并发 worker 异常"),
                        }
                    apply_result(result)
                    completed_count += 1
                    _task_store.set_progress(task_id, f"{completed_count}/{total}")
                    while len(in_flight) < effective_concurrency and launch_next_account(pool):
                        pass

        with state_lock:
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors)
            final_primary_email = primary_email
        graceful_stop = control.is_stop_after_current_requested()
        summary_message = (
            f"批量执行登录态{'已完成当前执行单元后停止' if graceful_stop else '完成'}: "
            f"成功 {runtime_success} 个，跳过 {runtime_skipped + len(skipped_items)} 个，"
            f"失败 {len(runtime_errors)} 个，并发 {effective_concurrency}"
        )
        task_log(f"[SUMMARY] {summary_message}", check_stop=False)
        final_status = "stopped" if graceful_stop else "done"
        log_status = "stopped" if graceful_stop else ("success" if not runtime_errors else "failed")
        final_meta = current_runtime_meta()
        _save_task_log(
            "chatgpt",
            final_primary_email,
            log_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": (
                        "batch_web_session_login_stopped"
                        if graceful_stop
                        else "batch_web_session_login_success"
                        if log_status == "success"
                        else "batch_web_session_login_failed"
                    ),
                    "source": "batch_web_session_login",
                    "meta": final_meta,
                },
            ),
        )
        _task_store.finish(
            task_id,
            status=final_status,
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error="" if not runtime_errors and not graceful_stop else summary_message,
        )
    except StopTaskRequested as exc:
        task_log(f"[STOP] {exc}", check_stop=False)
        final_meta = current_runtime_meta()
        with state_lock:
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors)
            final_primary_email = primary_email
        _save_task_log(
            "chatgpt",
            final_primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": "batch_web_session_login_stopped",
                    "source": "batch_web_session_login",
                    "meta": final_meta,
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error=str(exc),
        )
    except Exception as exc:
        error_text = sanitize_error_message(str(exc or "批量执行登录态异常退出"))
        task_log(f"[ERROR] 批量执行登录态异常退出: {error_text}", check_stop=False)
        with state_lock:
            errors.append(error_text)
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors)
            final_primary_email = primary_email
        final_meta = current_runtime_meta()
        _save_task_log(
            "chatgpt",
            final_primary_email,
            "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": "batch_web_session_login_exception",
                    "source": "batch_web_session_login",
                    "meta": final_meta,
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="failed",
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error=error_text,
        )
    finally:
        _clear_task_current(task_id)
        _task_store.cleanup()


def _run_batch_invalid_recheck(
    task_id: str,
    account_ids: list[int],
    settings: dict[str, Any] | None = None,
):
    from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait

    from api.actions import _apply_chatgpt_invalid_recheck_result

    runtime_settings = dict(settings or {})
    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    filter_invalid = _coerce_invalid_recheck_filter(
        runtime_settings.get("filter_invalid"),
        default=False,
    )
    requested_concurrency = _invalid_recheck_requested_concurrency(
        runtime_settings.get("requested_concurrency") or runtime_settings.get("concurrency"),
        default=1,
    )
    effective_concurrency = min(
        _invalid_recheck_requested_concurrency(runtime_settings.get("concurrency"), default=requested_concurrency),
        total,
    )
    proxy_settings = {
        key: runtime_settings.get(key)
        for key in _TASK_PROXY_RUNTIME_KEYS
        if key in runtime_settings
    }

    state_lock = threading.RLock()
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    results: list[dict[str, Any]] = []
    primary_email = ""

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")

    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    skipped_items = list(meta.get("skipped_items") or [])
    missing_ids = list(meta.get("missing_ids") or [])
    meta_emails = meta.get("emails")
    if isinstance(meta_emails, list) and meta_emails:
        primary_email = str(meta_emails[0] or "")

    def task_log(
        message: str,
        *,
        attempt_id: int | None = None,
        check_stop: bool = True,
    ) -> None:
        if check_stop:
            control.checkpoint(consume_skip=False, attempt_id=attempt_id)
        _log(task_id, message)

    def current_runtime_meta() -> dict[str, Any]:
        latest = dict(_task_store.snapshot(task_id).get("meta") or meta)
        with state_lock:
            ordered_results = sorted(results, key=lambda item: int(item.get("position") or 0))
            latest.update(
                {
                    "requested_concurrency": requested_concurrency,
                    "effective_concurrency": effective_concurrency,
                    "filter_invalid": filter_invalid,
                    "runtime_success": success_count,
                    "runtime_skipped": skipped_count,
                    "runtime_errors": list(errors),
                    "results": sanitize_task_detail(ordered_results),
                }
            )
        return latest

    def sync_runtime_meta() -> None:
        try:
            _task_store.update_meta(task_id, current_runtime_meta())
        except Exception:
            pass

    def process_account(account_position: int, account_id: int, attempt_id: int) -> dict[str, Any]:
        nonlocal primary_email
        email = ""
        try:
            control.checkpoint(attempt_id=attempt_id)
            with Session(engine) as session:
                account = session.get(AccountModel, int(account_id or 0))
                if account is None or account.platform != "chatgpt":
                    raise ValueError("ChatGPT 账号不存在")
                email = str(account.email or "")
                status_skip_reason = _invalid_recheck_status_skip_reason(
                    account,
                    filter_invalid=filter_invalid,
                )
                material_skip_reason = _web_session_login_skip_reason(account)
                skip_reason = status_skip_reason or material_skip_reason

            with state_lock:
                if not primary_email:
                    primary_email = email

            if skip_reason:
                reason = skip_reason
                task_log(
                    f"[失效测活][账号 {account_position}/{total}] 跳过｜账号={email or account_id}｜原因={reason}",
                    attempt_id=attempt_id,
                )
                return {
                    "position": account_position,
                    "account_id": account_id,
                    "email": email,
                    "status": "skipped",
                    "message": reason,
                }

            task_log(
                f"[失效测活][账号 {account_position}/{total}] 开始｜账号={email or account_id}｜并发={effective_concurrency}",
                attempt_id=attempt_id,
            )
            result, email = _execute_invalid_recheck_with_proxy_candidates(
                task_id=task_id,
                account_id=account_id,
                proxy_settings=proxy_settings,
                control=control,
                attempt_id=attempt_id,
                log_fn=lambda message: task_log(
                    f"[账号 {account_position}/{total}] {message}",
                    attempt_id=attempt_id,
                ),
            )

            with Session(engine) as session:
                account = session.get(AccountModel, int(account_id or 0))
                if account is None or account.platform != "chatgpt":
                    raise ValueError("ChatGPT 账号不存在")
                _apply_chatgpt_invalid_recheck_result(account, result, session)
                session.commit()

            if not bool(result.get("ok")):
                data = result.get("data") if isinstance(result.get("data"), dict) else {}
                error_text = sanitize_error_message(
                    str(result.get("error") or data.get("message") or "失效测活失败")
                )
                task_log(
                    f"[失效测活][账号 {account_position}/{total}] 失败｜账号={email or account_id}｜原因={error_text}",
                    attempt_id=attempt_id,
                    check_stop=False,
                )
                return {
                    "position": account_position,
                    "account_id": account_id,
                    "email": email,
                    "status": "failed",
                    "error": error_text,
                }

            task_log(
                f"[失效测活][账号 {account_position}/{total}] 成功｜账号={email or account_id}｜结果=Web Session已刷新",
                attempt_id=attempt_id,
                check_stop=False,
            )
            return {
                "position": account_position,
                "account_id": account_id,
                "email": email,
                "status": "success",
                "message": "Web Session 已刷新",
            }
        except SkipCurrentAttemptRequested as exc:
            task_log(
                f"[失效测活][账号 {account_position}/{total}] 已跳过｜账号={email or account_id}｜原因={exc}",
                check_stop=False,
            )
            return {
                "position": account_position,
                "account_id": account_id,
                "email": email,
                "status": "skipped",
                "message": str(exc),
            }
        except StopTaskRequested:
            raise
        except Exception as exc:
            error_text = sanitize_error_message(str(exc or "失效测活失败"))
            task_log(
                f"[失效测活][账号 {account_position}/{total}] 异常｜账号={email or account_id}｜原因={error_text}",
                check_stop=False,
            )
            return {
                "position": account_position,
                "account_id": account_id,
                "email": email,
                "status": "failed",
                "error": error_text,
            }
        finally:
            control.finish_attempt(attempt_id)

    def apply_result(result: dict[str, Any]) -> None:
        nonlocal success_count, skipped_count
        status = str(result.get("status") or "failed")
        account_label = str(result.get("email") or result.get("account_id") or "-")
        with state_lock:
            results.append(dict(result))
            if status == "success":
                success_count += 1
            elif status == "skipped":
                skipped_count += 1
            else:
                errors.append(f"{account_label}: {result.get('error') or '失效测活失败'}")
        sync_runtime_meta()

    try:
        for missing_id in missing_ids:
            task_log(f"[MISS] 账号不存在: account_id={missing_id}", check_stop=False)
            with state_lock:
                errors.append(f"account_id={missing_id}: 账号不存在")

        for item in skipped_items:
            task_log(
                f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - {item.get('reason') or '已跳过'}",
                check_stop=False,
            )

        task_log(
            f"[失效测活][配置] 并发已开启｜请求={requested_concurrency}｜实际={effective_concurrency}"
            f"｜范围={'仅 status=invalid' if filter_invalid else '全部账号'}",
            check_stop=False,
        )

        ordered_account_ids = [int(account_id or 0) for account_id in account_ids if int(account_id or 0) > 0]
        next_account_index = 0
        completed_count = 0
        in_flight: dict[Any, tuple[int, int]] = {}

        def should_stop_starting_new_attempts() -> bool:
            value = control.should_stop_starting_new_attempts()
            return value if isinstance(value, bool) else False

        def launch_next_account(pool: ThreadPoolExecutor) -> bool:
            nonlocal next_account_index
            if next_account_index >= len(ordered_account_ids):
                return False
            if should_stop_starting_new_attempts():
                return False
            account_position = next_account_index + 1
            account_id = ordered_account_ids[next_account_index]
            attempt_id = _claim_next_task_attempt(control)
            future = pool.submit(process_account, account_position, account_id, attempt_id)
            in_flight[future] = (account_position, account_id)
            next_account_index += 1
            return True

        with ThreadPoolExecutor(max_workers=effective_concurrency) as pool:
            while len(in_flight) < effective_concurrency and launch_next_account(pool):
                pass

            while in_flight:
                control.checkpoint(consume_skip=False)
                done, _ = wait(tuple(in_flight.keys()), timeout=0.5, return_when=FIRST_COMPLETED)
                if not done:
                    continue
                for future in done:
                    account_position, account_id = in_flight.pop(future)
                    try:
                        result = future.result()
                    except StopTaskRequested:
                        raise
                    except Exception as exc:
                        result = {
                            "position": account_position,
                            "account_id": account_id,
                            "email": "",
                            "status": "failed",
                            "error": sanitize_error_message(str(exc) or "并发 worker 异常"),
                        }
                    apply_result(result)
                    completed_count += 1
                    _task_store.set_progress(task_id, f"{completed_count}/{total}")

                    while len(in_flight) < effective_concurrency and launch_next_account(pool):
                        pass

        with state_lock:
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors)
            final_primary_email = primary_email
        graceful_stop = control.is_stop_after_current_requested()
        summary_message = (
            f"批量失效测活{'已完成当前执行单元后停止' if graceful_stop else '完成'}: "
            f"恢复 {runtime_success} 个，跳过 {runtime_skipped + len(skipped_items)} 个，"
            f"失败 {len(runtime_errors)} 个，并发 {effective_concurrency}"
        )
        task_log(f"[SUMMARY] {summary_message}", check_stop=False)
        final_status = "stopped" if graceful_stop else "done"
        log_status = "stopped" if graceful_stop else ("success" if not runtime_errors else "failed")
        final_meta = current_runtime_meta()
        _save_task_log(
            "chatgpt",
            final_primary_email,
            log_status,
            error="" if log_status == "success" else summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": (
                        "batch_invalid_recheck_stopped"
                        if graceful_stop
                        else "batch_invalid_recheck_success"
                        if log_status == "success"
                        else "batch_invalid_recheck_failed"
                    ),
                    "source": "batch_invalid_recheck",
                    "meta": final_meta,
                },
            ),
        )
        _task_store.finish(
            task_id,
            status=final_status,
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error="" if not runtime_errors and not graceful_stop else summary_message,
        )
    except StopTaskRequested as exc:
        task_log(f"[STOP] {exc}", check_stop=False)
        final_meta = current_runtime_meta()
        with state_lock:
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors)
            final_primary_email = primary_email
        _save_task_log(
            "chatgpt",
            final_primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": "batch_invalid_recheck_stopped",
                    "source": "batch_invalid_recheck",
                    "meta": final_meta,
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error=str(exc),
        )
    except Exception as exc:
        error_text = sanitize_error_message(str(exc or "批量失效测活异常退出"))
        task_log(f"[ERROR] 批量失效测活异常退出: {error_text}", check_stop=False)
        with state_lock:
            errors.append(error_text)
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors)
            final_primary_email = primary_email
        final_meta = current_runtime_meta()
        _save_task_log(
            "chatgpt",
            final_primary_email,
            "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": "batch_invalid_recheck_exception",
                    "source": "batch_invalid_recheck",
                    "meta": final_meta,
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="failed",
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error=error_text,
        )
    finally:
        _task_store.cleanup()


def _run_batch_probe_local_status(task_id: str, account_ids: list[int], params: dict[str, Any]):
    from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
    from core.db import AccountModel, engine
    from core.proxy_utils import resolve_probe_candidate_proxies
    from services.chatgpt_core.account_fingerprint import (
        fingerprint_signature,
        resolve_account_browser_fingerprint,
    )
    from services.chatgpt_core.local_status_refresh import (
        build_chatgpt_local_status_probe_account,
        probe_chatgpt_account_local_status,
        refresh_local_status_concurrency_from_store,
        sync_chatgpt_account_local_status_by_id,
    )
    from services.chatgpt_account_state import (
        is_paid_subscription_plan,
        normalize_subscription_plan,
    )
    from services.chatgpt_core.local_status_proxy import (
        is_local_status_proxy_configuration_error,
        is_local_status_proxy_transport_error,
        local_status_probe_proxy_failure,
    )

    runtime_params = dict(params or {}) if isinstance(params, dict) else {}
    control = _task_store.control_for(task_id)
    total = max(len(account_ids), 1)
    requested_concurrency = _coerce_batch_probe_positive_int(
        runtime_params.get("requested_concurrency") or runtime_params.get("concurrency"),
        default=1,
        maximum=LOCAL_STATUS_PROBE_MAX_CONCURRENCY,
    )
    global_concurrency_limit = refresh_local_status_concurrency_from_store()
    task_concurrency = _coerce_batch_probe_positive_int(
        runtime_params.get("concurrency"),
        default=min(requested_concurrency, global_concurrency_limit),
        maximum=LOCAL_STATUS_PROBE_MAX_CONCURRENCY,
    )
    effective_concurrency = min(task_concurrency, global_concurrency_limit, total)
    unique_exit_ip_enabled = _coerce_batch_probe_bool(
        runtime_params.get("unique_exit_ip_enabled"),
        default=False,
    ) and len(account_ids) > 1
    proxy_mode = str(runtime_params.get("proxy_mode") or "global").strip().lower()
    proxy_failover_enabled = _coerce_batch_probe_bool(
        runtime_params.get("proxy_failover"),
        default=False,
    )
    dynamic_proxy_attempt_budget = (
        _coerce_batch_probe_positive_int(
            runtime_params.get("dynamic_proxy_max_attempts"),
            default=1,
            maximum=100,
        )
        if proxy_mode == "dynamic" and proxy_failover_enabled
        else 1
    )

    def _coerce_delay(value: Any) -> float:
        try:
            parsed = float(value or 0)
        except (TypeError, ValueError):
            return 0.0
        if not math.isfinite(parsed):
            return 0.0
        return max(min(parsed, LOCAL_STATUS_PROBE_MAX_DELAY_SECONDS), 0.0)

    delay_min = _coerce_delay(runtime_params.get("delay_seconds") or runtime_params.get("probe_delay_seconds"))
    delay_max = _coerce_delay(runtime_params.get("delay_max_seconds") or runtime_params.get("probe_delay_max_seconds"))
    delay_low, delay_high = min(delay_min, delay_max), max(delay_min, delay_max)

    state_lock = threading.RLock()
    unique_exit_ip_lock = threading.Lock()
    fingerprint_state_lock = threading.Lock()
    shared_proxy_lock = threading.Lock()
    start_gate_lock = threading.Lock()
    next_start_at = time.monotonic()
    unique_exit_ips: set[str] = set()
    unique_exit_events: list[dict[str, Any]] = []
    fingerprint_seen: set[str] = set()
    fingerprint_stats = {
        "account_profile_count": 0,
        "legacy_fallback_count": 0,
        "shared_profile_serialized_count": 0,
    }
    shared_proxy_candidates: dict[str, tuple[str, Any, str]] = {}
    failed_proxy_candidates: set[str] = set()
    shared_proxy_uses: dict[str, int] = {}
    success_count = 0
    skipped_count = 0
    errors: list[str] = []
    subscription_counts = {"plus": 0, "free": 0, "unknown": 0}
    primary_email = ""
    fatal_configuration_errors: list[str] = []

    _task_store.mark_running(task_id)
    _task_store.set_progress(task_id, f"0/{total}")
    meta = dict(_task_store.snapshot(task_id).get("meta") or {})
    skipped_items = list(meta.get("skipped_items") or [])
    missing_ids = list(meta.get("missing_ids") or [])
    meta_emails = meta.get("emails")
    if isinstance(meta_emails, list) and meta_emails:
        primary_email = str(meta_emails[0] or "")

    def task_log(message: str, *, attempt_id: int | None = None, check_stop: bool = True) -> None:
        if check_stop:
            control.checkpoint(consume_skip=False, attempt_id=attempt_id)
        _log(task_id, message)

    def current_runtime_meta() -> dict[str, Any]:
        latest = dict(_task_store.snapshot(task_id).get("meta") or meta)
        with state_lock:
            latest.update(
                {
                    "runtime_success": success_count,
                    "runtime_skipped": skipped_count,
                    "runtime_errors": list(errors),
                    "subscription_counts": dict(subscription_counts),
                    "subscription_classified_count": sum(subscription_counts.values()),
                }
            )
        return latest

    def subscription_bucket(refresh_result: dict[str, Any]) -> str:
        probe = refresh_result.get("probe") if isinstance(refresh_result.get("probe"), dict) else {}
        subscription = probe.get("subscription") if isinstance(probe.get("subscription"), dict) else {}
        capabilities = refresh_result.get("capabilities") if isinstance(refresh_result.get("capabilities"), dict) else {}
        plan = normalize_subscription_plan(
            subscription.get("plan") or capabilities.get("subscription_plan")
        )
        if plan == "free":
            return "free"
        if is_paid_subscription_plan(plan):
            return "plus"
        return "unknown"

    def incomplete_refresh_error(refresh_result: dict[str, Any]) -> str:
        probe = refresh_result.get("probe") if isinstance(refresh_result.get("probe"), dict) else {}
        for section_name, label in (("auth", "认证"), ("codex", "Codex")):
            section = probe.get(section_name) if isinstance(probe.get(section_name), dict) else {}
            if str(section.get("state") or "").strip().lower() != "probe_failed":
                continue
            detail = sanitize_error_message(
                section.get("message")
                or section.get("error_code")
                or (f"HTTP {section.get('http_status')}" if section.get("http_status") else "")
                or "远端探测未完成"
            )[:240]
            return f"{label}探测失败: {detail}"
        refresh_outcome = str(refresh_result.get("refresh_outcome") or "").strip().lower()
        if refresh_outcome in {"unknown_plan", "probe_incomplete"}:
            return "订阅套餐探测未完成"
        capabilities = refresh_result.get("capabilities") if isinstance(refresh_result.get("capabilities"), dict) else {}
        if str(capabilities.get("subscription_refresh_state") or "").strip().lower() == "refresh_failed":
            return "订阅状态探测失败"
        return ""

    def record_unique_exit_ip_event(event: dict[str, Any]) -> None:
        if not unique_exit_ip_enabled:
            return
        clean_event = sanitize_task_detail(event)
        with unique_exit_ip_lock:
            unique_exit_events.append(clean_event)
            assigned_count = sum(1 for item in unique_exit_events if item.get("status") == "assigned")
            collision_count = sum(1 for item in unique_exit_events if item.get("status") == "collision")
            failed_count = sum(1 for item in unique_exit_events if item.get("status") == "failed")
            runtime_meta = {
                "enabled": True,
                "assigned_count": assigned_count,
                "collision_count": collision_count,
                "failed_count": failed_count,
                "assigned_exit_ips": sorted(unique_exit_ips)[-100:],
                "events": list(unique_exit_events[-100:]),
            }
        try:
            _task_store.update_meta(task_id, {"unique_exit_ip": runtime_meta})
        except Exception:
            pass

    def record_fingerprint_state(*, source: str, shared: bool) -> None:
        with state_lock:
            if source == "account":
                fingerprint_stats["account_profile_count"] += 1
            else:
                fingerprint_stats["legacy_fallback_count"] += 1
            if shared:
                fingerprint_stats["shared_profile_serialized_count"] += 1
            runtime_meta = {
                "policy": "reuse_account_profile; serialize_shared_or_missing",
                **dict(fingerprint_stats),
            }
        try:
            _task_store.update_meta(task_id, {"fingerprint_isolation": runtime_meta})
        except Exception:
            pass

    def source_exit_ip(source: Any) -> str:
        text = str(source or "")
        for pattern in (
            r"\bexit_ip\s*[:=]\s*([^｜\s,，;；)）]+)",
            r"出口IP\s*[:：]\s*([^｜\s,，;；)）]+)",
        ):
            match = re.search(pattern, text, flags=re.I)
            if match:
                return str(match.group(1) or "").strip()
        return ""

    def candidate_network_label(proxy_url: str, source: Any) -> str:
        """Return a log-safe transport label without retaining proxy endpoint data."""
        if not str(proxy_url or "").strip():
            return "直连"
        source_text = str(source or "").strip().lower()
        if source_text.startswith("dynamic"):
            return "动态代理"
        if source_text.startswith("pool"):
            return "代理池"
        if source_text.startswith("specified"):
            return "指定代理"
        return "已配置代理"

    def proxy_candidate_key(candidate: tuple[str, Any, str]) -> str:
        return str(candidate[0] or "").strip()

    def remember_shared_proxy(candidate: tuple[str, Any, str]) -> None:
        if unique_exit_ip_enabled:
            return
        key = proxy_candidate_key(candidate)
        if not key:
            return
        with shared_proxy_lock:
            if key in failed_proxy_candidates:
                return
            shared_proxy_candidates[key] = candidate
            shared_proxy_uses.setdefault(key, 0)

    def mark_shared_proxy_failed(candidate: tuple[str, Any, str]) -> None:
        key = proxy_candidate_key(candidate)
        if not key:
            return
        with shared_proxy_lock:
            failed_proxy_candidates.add(key)
            shared_proxy_candidates.pop(key, None)
            shared_proxy_uses.pop(key, None)

    def is_shared_proxy_failed(candidate: tuple[str, Any, str]) -> bool:
        key = proxy_candidate_key(candidate)
        if not key:
            return False
        with shared_proxy_lock:
            return key in failed_proxy_candidates

    def select_shared_proxy(excluded: set[str]) -> tuple[str, Any, str] | None:
        if unique_exit_ip_enabled:
            return None
        with shared_proxy_lock:
            available = [
                (shared_proxy_uses.get(key, 0), key, candidate)
                for key, candidate in shared_proxy_candidates.items()
                if key not in excluded and key not in failed_proxy_candidates
            ]
            if not available:
                return None
            _uses, key, candidate = min(available, key=lambda item: (item[0], item[1]))
            shared_proxy_uses[key] = shared_proxy_uses.get(key, 0) + 1
            return candidate

    def resolve_fresh_dynamic_proxy() -> tuple[str, Any, str]:
        single_candidate_params = dict(runtime_params)
        single_candidate_params["proxy_failover"] = False
        single_candidate_params["dynamic_proxy_max_attempts"] = 1
        candidates = resolve_probe_candidate_proxies(
            single_candidate_params,
            fallback_proxy="",
            default_mode="global",
        )
        if not candidates:
            raise RuntimeError("动态代理没有可用候选")
        return candidates[0]

    def probe_exit_ip(proxy_url: str, source: str) -> tuple[str, str]:
        source_ip = source_exit_ip(source)
        source_text = str(source or "").strip().lower()
        source_is_fresh_dynamic_probe = bool(
            source_ip
            and source_text.startswith("dynamic")
            and ("probe=ok" in source_text or "probe=geo_unavailable" in source_text)
        )
        if not proxy_url:
            return "", "直连模式没有可隔离的代理出口"
        try:
            from services.proxy_scanner import probe_basic

            result = probe_basic(proxy_url, timeout_seconds=8)
            if result.get("ok") and result.get("exit_ip"):
                return str(result.get("exit_ip") or "").strip(), "probe"
            if source_is_fresh_dynamic_probe:
                return source_ip, "dynamic_source_after_probe_failed"
            return "", "probe_failed"
        except Exception:
            if source_is_fresh_dynamic_probe:
                return source_ip, "dynamic_source_after_probe_exception"
            return "", "probe_exception"

    def claim_unique_exit_ip(
        *,
        account_position: int,
        account_id: int,
        candidate_index: int,
        candidate_total: int,
        proxy_url: str,
        source: str,
    ) -> tuple[bool, str, str]:
        exit_ip, probe_source = probe_exit_ip(proxy_url, source)
        source_label = candidate_network_label(proxy_url, source)
        if not exit_ip:
            reason = f"无法确认候选代理出口 IP（{source_label}）"
            record_unique_exit_ip_event(
                {
                    "account_position": account_position,
                    "account_id": account_id,
                    "candidate": candidate_index,
                    "total": candidate_total,
                    "status": "failed",
                    "source": source_label,
                    "reason": reason,
                }
            )
            return False, "", reason

        with unique_exit_ip_lock:
            if exit_ip in unique_exit_ips:
                collision = True
            else:
                unique_exit_ips.add(exit_ip)
                collision = False
        if collision:
            reason = f"出口 IP 已在本批量任务内分配: {exit_ip}"
            record_unique_exit_ip_event(
                {
                    "account_position": account_position,
                    "account_id": account_id,
                    "candidate": candidate_index,
                    "total": candidate_total,
                    "status": "collision",
                    "exit_ip": exit_ip,
                    "source": source_label,
                    "probe_source": probe_source,
                    "reason": reason,
                }
            )
            return False, exit_ip, reason

        record_unique_exit_ip_event(
            {
                "account_position": account_position,
                "account_id": account_id,
                "candidate": candidate_index,
                "total": candidate_total,
                "status": "assigned",
                "exit_ip": exit_ip,
                "source": source_label,
                "probe_source": probe_source,
            }
        )
        return True, exit_ip, ""

    def fingerprint_state_for_account(account: Any) -> tuple[str, bool]:
        try:
            extra = account.get_extra() if hasattr(account, "get_extra") else getattr(account, "extra", {})
        except Exception:
            extra = getattr(account, "extra", {})
        fingerprint = resolve_account_browser_fingerprint(extra)
        signature = fingerprint_signature(fingerprint, include_device=True) if fingerprint else ""
        source = "account" if signature else "legacy_default"
        gate_key = f"account:{signature}" if signature else "legacy_default"
        with fingerprint_state_lock:
            shared = gate_key in fingerprint_seen
            fingerprint_seen.add(gate_key)
        record_fingerprint_state(source=source, shared=shared)
        return source, shared

    def reserve_start_delay(position: int) -> float:
        nonlocal next_start_at
        if position <= 1 or delay_high <= 0:
            return 0.0
        interval = random.uniform(delay_low, delay_high) if delay_high > delay_low else delay_low
        if interval <= 0:
            return 0.0
        with start_gate_lock:
            now = time.monotonic()
            next_start_at = max(next_start_at, now) + interval
            return max(next_start_at - now, 0.0)

    def process_account(
        account_position: int,
        account_id: int,
        attempt_id: int,
        start_delay: float,
    ) -> dict[str, Any]:
        email = ""
        try:
            if start_delay > 0:
                task_log(
                    f"[{account_position}/{total}] 等候启动错峰 {start_delay:.1f} 秒",
                    attempt_id=attempt_id,
                )
                _sleep_with_task_control(control, start_delay, attempt_id=attempt_id)
            control.checkpoint(attempt_id=attempt_id)

            with Session(engine) as session:
                account = session.get(AccountModel, account_id)
                if account is None:
                    task_log(
                        f"[{account_position}/{total}] 账号不存在 ID={account_id}，已跳过",
                        attempt_id=attempt_id,
                    )
                    return {"status": "skipped", "account_id": account_id, "email": ""}
                email = str(account.email or "")
                prepared_account = build_chatgpt_local_status_probe_account(account)

            fingerprint_source, fingerprint_shared = fingerprint_state_for_account(prepared_account)
            if fingerprint_source == "legacy_default":
                task_log(
                    f"[{account_position}/{total}] 账号未保存浏览器指纹，已按兼容指纹串行化",
                    attempt_id=attempt_id,
                )
            elif fingerprint_shared:
                task_log(
                    f"[{account_position}/{total}] 检测到重复账号浏览器指纹，已串行化该身份",
                    attempt_id=attempt_id,
                )

            reusable_account_candidate: tuple[str, Any, str] | None = None
            reusable_account_exit_ip = ""

            def run_network_probe(probe_account: Any) -> dict[str, Any]:
                nonlocal reusable_account_candidate, reusable_account_exit_ip
                if (
                    reusable_account_candidate is not None
                    and is_shared_proxy_failed(reusable_account_candidate)
                ):
                    reusable_account_candidate = None
                    reusable_account_exit_ip = ""
                try:
                    static_candidates = (
                        []
                        if proxy_mode == "dynamic"
                        else resolve_probe_candidate_proxies(
                            runtime_params,
                            fallback_proxy="",
                            default_mode="global",
                        )
                    )
                    if reusable_account_candidate is not None and proxy_mode != "dynamic":
                        reusable_key = proxy_candidate_key(reusable_account_candidate)
                        static_candidates = [reusable_account_candidate] + [
                            candidate
                            for candidate in static_candidates
                            if proxy_candidate_key(candidate) != reusable_key
                        ]
                except Exception as exc:
                    raise RuntimeError(
                        sanitize_error_message(str(exc) or "代理配置解析失败")
                    ) from exc

                candidate_total = (
                    dynamic_proxy_attempt_budget
                    if proxy_mode == "dynamic"
                    else max(len(static_candidates), 1)
                )
                attempted_proxy_keys: set[str] = set()
                last_error = ""

                for candidate_index in range(1, candidate_total + 1):
                    control.checkpoint(attempt_id=attempt_id)
                    candidate_origin = ""
                    reused_account_candidate = False
                    if proxy_mode == "dynamic":
                        candidate = None
                        if candidate_index == 1 and reusable_account_candidate is not None:
                            candidate = reusable_account_candidate
                            reused_account_candidate = True
                            candidate_origin = "复用账号上一轮已到达上游 SID"
                        elif candidate_index > 1:
                            candidate = select_shared_proxy(attempted_proxy_keys)
                            if candidate is not None:
                                candidate_origin = "复用任务内已验证健康 SID"
                        if candidate is None:
                            candidate_origin = "新主线路" if candidate_index == 1 else "新补位线路"
                            try:
                                candidate = resolve_fresh_dynamic_proxy()
                            except Exception as exc:
                                last_error = sanitize_error_message(str(exc) or "动态代理线路准备失败")
                                task_log(
                                    f" -> [代理 {candidate_index}/{candidate_total}] {candidate_origin} 准备失败: {last_error}",
                                    attempt_id=attempt_id,
                                )
                                if is_local_status_proxy_configuration_error(last_error):
                                    raise RuntimeError(last_error) from exc
                                continue
                    else:
                        if candidate_index > len(static_candidates):
                            break
                        candidate = static_candidates[candidate_index - 1]
                        reused_account_candidate = (
                            reusable_account_candidate is not None
                            and proxy_candidate_key(candidate)
                            == proxy_candidate_key(reusable_account_candidate)
                        )

                    proxy_url, proxy_pool, source = candidate
                    candidate_key = proxy_candidate_key(candidate)
                    if candidate_key and candidate_key in attempted_proxy_keys:
                        last_error = "动态代理返回了本账号已尝试的 SID"
                        task_log(
                            f" -> [跳过候选] {last_error}",
                            attempt_id=attempt_id,
                        )
                        continue
                    if candidate_key:
                        attempted_proxy_keys.add(candidate_key)

                    network_label = candidate_network_label(proxy_url, source)
                    exit_ip = ""
                    if unique_exit_ip_enabled:
                        if reused_account_candidate and reusable_account_exit_ip:
                            claimed = True
                            exit_ip = reusable_account_exit_ip
                            claim_error = ""
                            record_unique_exit_ip_event(
                                {
                                    "account_position": account_position,
                                    "account_id": account_id,
                                    "candidate": candidate_index,
                                    "total": candidate_total,
                                    "status": "reused",
                                    "exit_ip": exit_ip,
                                    "source": candidate_network_label(proxy_url, source),
                                    "reason": "auth_revision_retry",
                                }
                            )
                        else:
                            claimed, exit_ip, claim_error = claim_unique_exit_ip(
                                account_position=account_position,
                                account_id=account_id,
                                candidate_index=candidate_index,
                                candidate_total=candidate_total,
                                proxy_url=proxy_url,
                                source=source,
                            )
                        if not claimed:
                            last_error = claim_error
                            task_log(
                                f" -> [跳过候选] {claim_error}",
                                attempt_id=attempt_id,
                            )
                            continue

                    origin_note = f"｜SID={candidate_origin}" if candidate_origin else ""
                    exit_note = f"｜出口IP: {exit_ip}" if exit_ip else ""
                    task_log(
                        f" -> [尝试 {candidate_index}/{candidate_total}] 网络方式: {network_label}{origin_note}{exit_note}",
                        attempt_id=attempt_id,
                    )
                    try:
                        probe = probe_chatgpt_account_local_status(
                            probe_account,
                            proxy=proxy_url,
                            use_default_proxy=False,
                        )
                    except Exception as exc:
                        error_text = sanitize_error_message(str(exc) or "探测失败")
                        if not is_local_status_proxy_transport_error(error_text):
                            raise RuntimeError(error_text) from exc
                        proxy_error = error_text
                        probe = None
                    else:
                        proxy_error = local_status_probe_proxy_failure(probe)
                        if not proxy_error:
                            if proxy_pool is not None and proxy_url:
                                try:
                                    proxy_pool.report_success(proxy_url)
                                except Exception:
                                    pass
                            if proxy_mode == "dynamic":
                                remember_shared_proxy(candidate)
                            reusable_account_candidate = candidate
                            reusable_account_exit_ip = exit_ip
                            return probe

                    last_error = sanitize_error_message(proxy_error or "代理探测失败")
                    if proxy_mode == "dynamic":
                        mark_shared_proxy_failed(candidate)
                    if (
                        reusable_account_candidate is not None
                        and proxy_candidate_key(candidate)
                        == proxy_candidate_key(reusable_account_candidate)
                    ):
                        reusable_account_candidate = None
                        reusable_account_exit_ip = ""
                    if proxy_pool is not None and proxy_url:
                        try:
                            proxy_pool.report_fail(proxy_url)
                        except Exception:
                            pass
                    task_log(
                        f" -> [代理失败] {network_label}: {last_error}"
                        + ("，按需切换下一条线路" if candidate_index < candidate_total else ""),
                        attempt_id=attempt_id,
                    )

                raise RuntimeError(last_error or "代理候选全部失败")

            stop_check = lambda: control.checkpoint(attempt_id=attempt_id)
            def on_probe_start(_probe_account: Any, _probe_attempt: int) -> None:
                if _probe_attempt <= 1:
                    task_log(
                        f"[{account_position}/{total}] 开始同步本地状态 账号ID：{account_id}｜邮箱：{email}",
                        attempt_id=attempt_id,
                    )
                else:
                    task_log(
                        f"[{account_position}/{total}] 认证材料已更新，重新同步账号 "
                        f"账号ID：{account_id}｜邮箱：{email}｜探测轮次={_probe_attempt}",
                        attempt_id=attempt_id,
                    )

            result = sync_chatgpt_account_local_status_by_id(
                account_id,
                prepared_account=prepared_account,
                probe_runner=run_network_probe,
                on_probe_start=on_probe_start,
                stop_check=stop_check,
            )

            final_proxy_error = local_status_probe_proxy_failure(result.get("probe") or {})
            if final_proxy_error:
                error_text = sanitize_error_message(final_proxy_error)
                task_log(
                    f" -> [异常] 账号 {email or account_id} 本地状态全部失败: {error_text}",
                    attempt_id=attempt_id,
                )
                return {"status": "failed", "account_id": account_id, "email": email, "error": error_text}

            plan = result.get("probe", {}).get("subscription", {}).get("plan", "unknown")
            bucket = subscription_bucket(result)
            incomplete_error = incomplete_refresh_error(result)
            if incomplete_error:
                task_log(
                    f" -> [失败] 账号 {email or account_id} 本地状态已写入，但刷新不完整: {incomplete_error}",
                    attempt_id=attempt_id,
                )
                return {
                    "status": "failed",
                    "account_id": account_id,
                    "email": email,
                    "error": incomplete_error,
                    "subscription_bucket": bucket,
                }
            task_log(
                f" -> [成功] 账号 {email} 本地状态同步完成｜当前订阅计划: {plan}",
                attempt_id=attempt_id,
            )
            return {
                "status": "success",
                "account_id": account_id,
                "email": email,
                "subscription_bucket": bucket,
            }
        except SkipCurrentAttemptRequested as exc:
            task_log(
                f"[{account_position}/{total}] 已跳过 {email or account_id}: {exc}",
                attempt_id=attempt_id,
                check_stop=False,
            )
            return {"status": "skipped", "account_id": account_id, "email": email, "error": str(exc)}
        except StopTaskRequested:
            raise
        except Exception as exc:
            error_text = sanitize_error_message(str(exc) or exc.__class__.__name__)
            task_log(
                f"[{account_position}/{total}] 本地状态同步异常: {email or account_id} - {error_text}",
                attempt_id=attempt_id,
                check_stop=False,
            )
            return {
                "status": "failed",
                "account_id": account_id,
                "email": email,
                "error": error_text,
                "fatal_configuration": is_local_status_proxy_configuration_error(error_text),
            }
        finally:
            control.finish_attempt(attempt_id)

    def apply_result(result: dict[str, Any]) -> None:
        nonlocal success_count, skipped_count, primary_email
        status = str(result.get("status") or "failed")
        email = str(result.get("email") or "")
        error_text = str(result.get("error") or "").strip()
        bucket = str(result.get("subscription_bucket") or "").strip().lower()
        with state_lock:
            if email and not primary_email:
                primary_email = email
            if bucket in subscription_counts:
                subscription_counts[bucket] += 1
            if status == "success":
                success_count += 1
            elif status == "skipped":
                skipped_count += 1
            else:
                errors.append(f"{email or result.get('account_id') or '-'}: {error_text or '探测失败'}")
                if result.get("fatal_configuration"):
                    fatal_configuration_errors.append(error_text or "代理配置解析失败")
            runtime_subscription_counts = dict(subscription_counts)
        try:
            _task_store.update_meta(
                task_id,
                {
                    "subscription_counts": runtime_subscription_counts,
                    "subscription_classified_count": sum(runtime_subscription_counts.values()),
                },
            )
        except Exception:
            pass

    try:
        for missing_id in missing_ids:
            task_log(f"[MISS] 账号不存在: account_id={missing_id}")
            errors.append(f"account_id={missing_id}: 账号不存在")
        for item in skipped_items:
            task_log(f"[SKIP] {item.get('email') or item.get('account_id') or '-'} - {item.get('reason') or '已跳过'}")

        _task_store.update_meta(
            task_id,
            {
                "subscription_counts": dict(subscription_counts),
                "subscription_classified_count": 0,
                "settings": {
                    **dict(meta.get("settings") or {}),
                    "requested_concurrency": requested_concurrency,
                    "effective_concurrency": effective_concurrency,
                    "global_concurrency_limit": global_concurrency_limit,
                    "unique_exit_ip_enabled": unique_exit_ip_enabled,
                    "fingerprint_policy": "reuse_account_profile; serialize_shared_or_missing",
                },
                "fingerprint_isolation": {
                    "policy": "reuse_account_profile; serialize_shared_or_missing",
                    **dict(fingerprint_stats),
                },
            },
        )
        if unique_exit_ip_enabled:
            _task_store.update_meta(
                task_id,
                {
                    "unique_exit_ip": {
                        "enabled": True,
                        "assigned_count": 0,
                        "collision_count": 0,
                        "failed_count": 0,
                        "assigned_exit_ips": [],
                        "events": [],
                    }
                },
            )
            task_log("[代理] 已启用任务内强制独立出口 IP：撞 IP 时会换候选，候选不足会明确失败")
        task_log(
            "[配置] 批量本地状态同步"
            f"｜请求并发={requested_concurrency}｜实际并发={effective_concurrency}"
            f"｜进程全局上限={global_concurrency_limit}"
            f"｜独立出口IP={'开启' if unique_exit_ip_enabled else '关闭'}"
            "｜指纹=复用账号已保存指纹，缺失或重复时串行化",
        )

        ordered_account_ids = [int(account_id or 0) for account_id in account_ids if int(account_id or 0) > 0]
        next_account_index = 0
        completed_count = 0
        in_flight: dict[Any, tuple[int, int]] = {}

        def should_stop_starting_new_attempts() -> bool:
            value = control.should_stop_starting_new_attempts()
            # The real task control always returns bool.  Treat foreign/legacy
            # control stubs as "continue" instead of letting a truthy mock
            # silently prevent all workers from being scheduled.
            return value if isinstance(value, bool) else False

        def launch_next_account(pool: ThreadPoolExecutor) -> bool:
            nonlocal next_account_index
            if next_account_index >= len(ordered_account_ids):
                return False
            if should_stop_starting_new_attempts():
                return False
            account_position = next_account_index + 1
            account_id = ordered_account_ids[next_account_index]
            try:
                attempt_id = _claim_next_task_attempt(control)
            except StopTaskRequested:
                if control.is_stop_requested():
                    raise
                return False
            start_delay = reserve_start_delay(account_position)
            future = pool.submit(process_account, account_position, account_id, attempt_id, start_delay)
            in_flight[future] = (account_position, account_id)
            next_account_index += 1
            return True

        with ThreadPoolExecutor(max_workers=effective_concurrency) as pool:
            while len(in_flight) < effective_concurrency and launch_next_account(pool):
                pass

            while in_flight:
                control.checkpoint(consume_skip=False)
                done, _ = wait(tuple(in_flight.keys()), timeout=0.5, return_when=FIRST_COMPLETED)
                if not done:
                    continue
                for future in done:
                    account_position, account_id = in_flight.pop(future)
                    try:
                        result = future.result()
                    except StopTaskRequested:
                        raise
                    except Exception as exc:
                        result = {
                            "status": "failed",
                            "account_id": account_id,
                            "email": "",
                            "error": sanitize_error_message(str(exc) or "并发 worker 异常"),
                        }
                        task_log(
                            f"[{account_position}/{total}] 并发 worker 异常: {result['error']}",
                            check_stop=False,
                        )
                    apply_result(result)
                    completed_count += 1
                    _task_store.set_progress(task_id, f"{completed_count}/{total}")

                    while len(in_flight) < effective_concurrency and launch_next_account(pool):
                        pass

        with state_lock:
            summary_message = (
                f"批量同步本地状态完成: 成功 {success_count} 个，"
                f"跳过 {skipped_count + len(skipped_items)} 个，失败 {len(errors)} 个，"
                f"订阅 Plus {subscription_counts['plus']} 个 / Free {subscription_counts['free']} 个 / Unknown {subscription_counts['unknown']} 个，"
                f"并发 {effective_concurrency}"
            )
            if control.is_stop_after_current_requested():
                summary_message = (
                    f"批量同步本地状态已完成当前执行单元后停止: 成功 {success_count} 个，"
                    f"跳过 {skipped_count + len(skipped_items)} 个，失败 {len(errors)} 个，"
                    f"订阅 Plus {subscription_counts['plus']} 个 / Free {subscription_counts['free']} 个 / Unknown {subscription_counts['unknown']} 个"
                )
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors)
            final_primary_email = primary_email

        task_log(f"[SUMMARY] {summary_message}", check_stop=not control.is_stop_after_current_requested())
        final_status = "failed" if fatal_configuration_errors and runtime_success == 0 else "done"
        log_status = "success" if final_status == "done" and not runtime_errors else "failed"
        final_error = (
            fatal_configuration_errors[0]
            if final_status == "failed" and fatal_configuration_errors
            else "" if not runtime_errors else summary_message
        )
        final_meta = current_runtime_meta()
        _save_task_log(
            "chatgpt",
            final_primary_email,
            log_status,
            error="" if log_status == "success" else final_error or summary_message,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": "batch_probe_local_status_success" if log_status == "success" else "batch_probe_local_status_failed",
                    "source": "batch_probe_local_status",
                    "meta": final_meta,
                },
            ),
        )
        _task_store.finish(
            task_id,
            status=final_status,
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error=final_error,
        )
    except StopTaskRequested as exc:
        _log(task_id, f"[STOP] {exc}")
        with state_lock:
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors)
            final_primary_email = primary_email
        _save_task_log(
            "chatgpt",
            final_primary_email,
            "stopped",
            error=str(exc),
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": "batch_probe_local_status_stopped",
                    "source": "batch_probe_local_status",
                    "meta": current_runtime_meta(),
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="stopped",
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error=str(exc),
        )
    except Exception as exc:
        error_text = sanitize_error_message(str(exc) or exc.__class__.__name__)
        logger.exception("批量同步本地状态任务异常 task_id=%s error=%s", task_id, error_text)
        _log(task_id, f"[FAIL] 批量同步本地状态异常: {error_text}")
        with state_lock:
            runtime_success = success_count
            runtime_skipped = skipped_count
            runtime_errors = list(errors) + [error_text]
            final_primary_email = primary_email
        _save_task_log(
            "chatgpt",
            final_primary_email,
            "failed",
            error=error_text,
            detail=_build_task_log_detail(
                task_id,
                {
                    "email": final_primary_email,
                    "attempt_outcome": "batch_probe_local_status_failed",
                    "source": "batch_probe_local_status",
                    "meta": {
                        **current_runtime_meta(),
                        "runtime_errors": runtime_errors,
                    },
                },
            ),
        )
        _task_store.finish(
            task_id,
            status="failed",
            success=runtime_success,
            skipped=runtime_skipped + len(skipped_items),
            errors=runtime_errors,
            error=error_text,
        )
    finally:
        _task_store.cleanup()


def _is_fatal_registration_infrastructure_error(message: Any) -> bool:
    text = str(message or "").strip().lower()
    return any(
        marker in text
        for marker in (
            "sentinel_browser_unavailable",
            "auth_browser_finalize_unavailable",
            "browser_registration_unavailable",
            "代理池没有可用候选",
            "动态代理没有可用候选",
            "dynamic proxy",
            "no available proxy",
            "已选择动态代理模式，但动态节点地址为空",
            "动态代理模式必须填写出口国家",
        )
    )


def _run_register(task_id: str, req: RegisterTaskRequest):

    from core.base_platform import RegisterConfig
    from core.db import save_account
    from core.base_mailbox import create_mailbox
    from core.proxy_utils import normalize_proxy_url
    from services.chatgpt_account_state import classify_chatgpt_capabilities
    from services.chatgpt_core import ChatGPTPlatform

    control = _task_store.control_for(task_id)
    _task_store.mark_running(task_id)
    success = 0
    target_successes = max(int(req.count or 1), 1)
    # ``success`` is updated by the dispatcher while registration workers emit
    # logs concurrently.  Each worker freezes its next-success slot once it
    # actually starts so one account's prefix cannot change mid-attempt.
    success_lock = threading.Lock()
    skipped = 0
    errors = []
    fatal_registration_error = ""
    registration_eligibility_coordinator: Any | None = None
    registration_paypal_payment_coordinator: Any | None = None
    start_gate_lock = threading.Lock()
    task_meta_update_lock = threading.Lock()
    post_registration_refresh_lock = threading.Lock()
    post_registration_refresh_proxies: dict[int, str] = {}
    next_start_time = time.monotonic()
    registration_stage_total = 9
    from services.chatgpt_core.registration_diagnostics import (
        create_registration_diagnostic_session,
        record_registration_diagnostic_log,
        registration_diagnostics_summary,
    )

    def _registration_task_log(
        message: str,
        level: str = "info",
        *,
        stage_index: int | None = None,
        phase_label: str = "",
        success_slot: int | None = None,
    ) -> None:
        inferred_index, inferred_label = infer_registration_timeline_stage(message)
        resolved_index = int(stage_index or inferred_index)
        resolved_label = str(phase_label or inferred_label).strip()
        if success_slot is None:
            with success_lock:
                resolved_success_slot = min(success + 1, target_successes)
        else:
            resolved_success_slot = int(success_slot or 1)
        is_debug = str(level or "info").strip().lower() == "debug" or str(message or "").lstrip().upper().startswith("[DEBUG]")
        if is_debug:
            debug_text = str(message or "")
            if "[HTTP]" not in debug_text.upper():
                return
        _log(
            task_id,
            format_task_timeline_log(
                "ChatGPT注册",
                message,
                success_slot=resolved_success_slot,
                success_total=target_successes,
                stage_index=resolved_index,
                stage_total=registration_stage_total,
                phase_label=resolved_label,
                debug=is_debug,
            ),
            level,
        )

    def _sleep_with_control(
        wait_seconds: float,
        *,
        attempt_id: int | None = None,
        stop_before_start: bool = False,
    ) -> bool:
        remaining = max(float(wait_seconds or 0), 0.0)
        while remaining > 0:
            control.checkpoint(attempt_id=attempt_id)
            if stop_before_start:
                should_stop = control.should_stop_starting_new_attempts()
                if isinstance(should_stop, bool) and should_stop:
                    return False
            chunk = min(0.25, remaining)
            time.sleep(chunk)
            remaining -= chunk
        return True

    try:
        if req.platform != "chatgpt":
            raise RuntimeError(f"不支持的平台: {req.platform}")
        PlatformCls = ChatGPTPlatform

        initial_merged_extra = _build_effective_register_extra(req)
        register_control = dict(getattr(req, "_register_control", {}) or {})
        browser_executor = str(req.executor_type or "protocol").strip().lower() in {
            "headless",
            "headed",
        }
        chatgpt_zero_amount_stop_enabled = (
            req.platform == "chatgpt"
            and _is_truthy(initial_merged_extra.get("chatgpt_access_token_only_zero_amount_stop_enabled"))
        )
        chatgpt_zero_amount_stop_threshold = _parse_positive_int(
            initial_merged_extra.get("chatgpt_access_token_only_zero_amount_stop_threshold"),
            default=1,
        )
        chatgpt_checkout_amount_zero = 0
        chatgpt_checkout_amount_nonzero = 0
        chatgpt_zero_amount_stop_triggered = False
        chatgpt_checkout_amount_lock = threading.Lock()
        unique_exit_ip_lock = threading.Lock()
        unique_exit_ip_meta_lock = threading.Lock()
        unique_exit_ip_assigned: set[str] = set()
        unique_exit_ip_assigned_keys: set[str] = set()
        unique_exit_ip_events: list[dict[str, Any]] = []
        browser_fingerprint_lock = threading.Lock()
        browser_fingerprint_signatures: set[str] = set()
        registration_zero_amount_enabled = bool(
            getattr(req, "registration_zero_amount_eligibility_enabled", False)
        )
        registration_paypal_payment_enabled = bool(
            getattr(req, "registration_paypal_payment_enabled", False)
        )
        raw_registration_paypal_link_enabled = getattr(
            req,
            "registration_paypal_link_enabled",
            None,
        )
        registration_paypal_link_enabled = (
            registration_paypal_payment_enabled
            if raw_registration_paypal_link_enabled is None
            else bool(raw_registration_paypal_link_enabled)
        )
        registration_pipeline_legacy_combined = bool(
            getattr(req, "_registration_pipeline_legacy_combined", False)
        ) or raw_registration_paypal_link_enabled is None

        frozen_paypal_payment: dict[str, Any] = {}
        if registration_paypal_link_enabled:
            frozen_paypal_payment = dict(
                getattr(req, "_registration_paypal_payment_runtime", {})
                or _registration_paypal_payment_settings(
                    include_payment=registration_paypal_payment_enabled
                )
            )
            frozen_paypal_payment["submit_payment"] = registration_paypal_payment_enabled
            from services.chatgpt_core.registration_paypal_payment import (
                RegistrationPaypalPaymentCoordinator,
                run_registration_paypal_payment_for_account,
            )

            registration_paypal_payment_coordinator = (
                RegistrationPaypalPaymentCoordinator(
                    task_id=task_id,
                    settings=frozen_paypal_payment,
                    run_account=run_registration_paypal_payment_for_account,
                    update_meta=lambda value: _task_store.update_meta(
                        task_id,
                        {"registration_paypal_payment": value},
                    ),
                    log=lambda message, level="info": _log(
                        task_id,
                        message,
                        level,
                    ),
                    concurrency=REGISTRATION_PAYPAL_PAYMENT_CONCURRENCY,
                )
            )

        def _handle_registration_eligibility_result(result: dict[str, Any]) -> None:
            _apply_registration_eligibility_pipeline_result(
                result,
                task_id=task_id,
                payment_link_enabled=registration_paypal_link_enabled,
                payment_enabled=registration_paypal_payment_enabled,
                legacy_combined=registration_pipeline_legacy_combined,
                submit_payment_link=(
                    registration_paypal_payment_coordinator.submit
                    if registration_paypal_payment_coordinator is not None
                    else None
                ),
            )

        if registration_zero_amount_enabled:
            frozen_registration_eligibility = dict(
                getattr(req, "_registration_eligibility_runtime", {})
                or _safe_registration_zero_amount_eligibility_settings(
                    getattr(req, "registration_zero_amount_checkout_country", "VN")
                )
            )
            try:
                registration_eligibility_max_attempts = int(
                    frozen_registration_eligibility.get("max_attempts") or 2
                )
            except (TypeError, ValueError):
                registration_eligibility_max_attempts = 2
            registration_eligibility_max_attempts = max(
                1,
                min(registration_eligibility_max_attempts, 4),
            )
            registration_checkout_country = str(
                frozen_registration_eligibility.get("checkout_country_code")
                or frozen_registration_eligibility.get("promotion_proxy_country_code")
                or "VN"
            ).strip().upper()
            if not (
                len(registration_checkout_country) == 2
                and registration_checkout_country.isascii()
                and registration_checkout_country.isalpha()
            ):
                registration_checkout_country = "VN"
            registration_eligibility_settings: dict[str, Any] = {
                **frozen_registration_eligibility,
                "checkout_country_code": registration_checkout_country,
                "promotion_proxy_country_code": registration_checkout_country,
                "max_attempts": registration_eligibility_max_attempts,
            }
            from services.chatgpt_core.registration_eligibility import (
                RegistrationEligibilityCoordinator,
            )

            registration_eligibility_coordinator = RegistrationEligibilityCoordinator(
                task_id=task_id,
                settings=registration_eligibility_settings,
                run_account=_run_payment_eligibility_for_account,
                update_meta=lambda value: _task_store.update_meta(
                    task_id,
                    {"registration_zero_amount_eligibility": value},
                ),
                log=lambda message, level="info": _log(task_id, message, level),
                on_result=_handle_registration_eligibility_result,
                concurrency=REGISTRATION_ZERO_AMOUNT_ELIGIBILITY_CONCURRENCY,
            )

        def _schedule_post_registration_refreshes() -> None:
            with post_registration_refresh_lock:
                account_refreshes = sorted(post_registration_refresh_proxies.items())
                post_registration_refresh_proxies.clear()
            for account_id, successful_proxy in account_refreshes:
                if registration_paypal_link_enabled:
                    # A submitted PayPal handoff owns the next login/refresh.  Do
                    # not let the legacy registration completion refresh race it
                    # and write a stale local snapshot over the payment marker.
                    try:
                        with Session(engine) as session:
                            account = session.get(AccountModel, int(account_id))
                            marker = (
                                account.get_extra().get("chatgpt_paypal_auto_payment")
                                if account is not None
                                else None
                            )
                        marker_state = str(marker.get("status") or "").strip().lower() if isinstance(marker, dict) else ""
                        if marker_state in {
                            "submitted",
                            "payment_pending",
                            "payment_authorized",
                            "relogin_pending",
                            "local_refresh_pending",
                            "subscription_confirmed",
                        }:
                            continue
                    except Exception:
                        # A failed marker read should not suppress the ordinary
                        # post-registration refresh for an account that never
                        # reached the payment handoff.
                        pass
                schedule_chatgpt_local_status_refresh_for_account_id(
                    account_id,
                    proxy=successful_proxy or None,
                    use_default_proxy=False if successful_proxy else True,
                    reason="registration_task_completed",
                    delay_seconds=2.0,
                )

        def _build_mailbox(proxy: Optional[str], runtime_extra: dict | None = None):
            merged_extra = dict(runtime_extra or _build_effective_register_extra(req))
            return create_mailbox(
                provider=merged_extra.get("mail_provider", "luckmail"),
                extra=merged_extra,
                proxy=proxy,
            )

        def _redact_proxy_for_log(proxy: Optional[str]) -> str:
            return redact_proxy_url(proxy) or "direct"

        def _log_register_proxy_choice(
            proxy: str,
            source: str,
            index: int,
            total: int,
            *,
            attempt_index: int,
            exit_ip: str = "",
            log_fn=None,
        ) -> None:
            label = str(source or "direct").strip() or "direct"
            ip_info = ""
            if exit_ip:
                ip_info = f" (出口IP: {exit_ip})"
            elif proxy:
                try:
                    from services.proxy_scanner import probe_basic
                    res = probe_basic(proxy, timeout_seconds=6)
                    if res.get("ok") and res.get("exit_ip"):
                        ip_info = f" (出口IP: {res['exit_ip']})"
                except Exception:
                    pass
            message = (
                f"[代理] candidate={index}/{total} "
                f"source={label} proxy={_redact_proxy_for_log(proxy)}"
                f"{'' if 'exit_ip=' in label.lower() or '出口ip' in label.lower() else ip_info}"
            )
            if callable(log_fn):
                log_fn(message)
            else:
                _registration_task_log(message, stage_index=2, phase_label="选择代理")

        def _truthy(value, default: bool = False) -> bool:
            if value is None:
                return default
            text = str(value).strip().lower()
            if text in {"1", "true", "yes", "on"}:
                return True
            if text in {"0", "false", "no", "off"}:
                return False
            return default

        def _positive_int(value, default: int, minimum: int = 1, maximum: int = 50) -> int:
            try:
                parsed = int(float(str(value or "").strip()))
            except Exception:
                parsed = default
            return max(minimum, min(maximum, parsed))

        def _positive_float(value, default: float, minimum: float = 0, maximum: float = 100) -> float:
            try:
                parsed = float(str(value or "").strip())
            except Exception:
                parsed = default
            return max(minimum, min(maximum, parsed))

        def _nonnegative_int(value, default: int, maximum: int) -> int:
            try:
                parsed = int(float(str(value).strip()))
            except (TypeError, ValueError):
                parsed = default
            return max(0, min(maximum, parsed))

        unique_exit_ip_enabled = (
            req.platform == "chatgpt"
            and _truthy(initial_merged_extra.get("chatgpt_register_unique_exit_ip_enabled"), default=False)
        )
        unique_exit_ip_policy = str(
            initial_merged_extra.get("chatgpt_register_unique_exit_ip_policy") or "off"
        ).strip().lower()
        unique_exit_ip_refresh_budget_default = (
            REGISTER_UNIQUE_EXIT_IP_MAX_REFRESH_ATTEMPTS_DEFAULT
        )
        unique_exit_ip_max_refresh_attempts = _positive_int(
            initial_merged_extra.get("chatgpt_register_unique_exit_ip_max_refresh_attempts")
            or initial_merged_extra.get("register_unique_exit_ip_max_refresh_attempts")
            or unique_exit_ip_refresh_budget_default,
            default=unique_exit_ip_refresh_budget_default,
            minimum=1,
            maximum=12,
        )
        unique_exit_ip_probe_timeout_seconds = _positive_int(
            initial_merged_extra.get("chatgpt_register_unique_exit_ip_probe_timeout_seconds")
            or initial_merged_extra.get("dynamic_proxy_probe_timeout_seconds")
            or REGISTER_UNIQUE_EXIT_IP_PROBE_TIMEOUT_SECONDS_DEFAULT,
            default=REGISTER_UNIQUE_EXIT_IP_PROBE_TIMEOUT_SECONDS_DEFAULT,
            minimum=2,
            maximum=60,
        )
        unique_exit_ip_active_ttl_seconds = _positive_int(
            initial_merged_extra.get("chatgpt_register_unique_exit_ip_active_ttl_seconds")
            or 1800,
            default=1800,
            minimum=900,
            maximum=7200,
        )
        unique_exit_ip_cooldown_seconds = _nonnegative_int(
            initial_merged_extra.get("chatgpt_register_unique_exit_ip_cooldown_seconds")
            if initial_merged_extra.get("chatgpt_register_unique_exit_ip_cooldown_seconds") not in (None, "")
            else 900,
            default=900,
            maximum=7200,
        )
        from core.chatgpt_register_exit_ip_registry import (
            normalize_register_exit_ip,
            register_exit_ip_registry,
        )

        if unique_exit_ip_enabled:
            _task_store.update_meta(
                task_id,
                {
                    "register_unique_exit_ip": {
                        "enabled": True,
                        "policy": unique_exit_ip_policy,
                        "scope": "process",
                        "assigned_count": 0,
                        "collision_count": 0,
                        "max_refresh_attempts": unique_exit_ip_max_refresh_attempts,
                        "probe_timeout_seconds": unique_exit_ip_probe_timeout_seconds,
                        "active_ttl_seconds": unique_exit_ip_active_ttl_seconds,
                        "cooldown_seconds": unique_exit_ip_cooldown_seconds,
                        "events": [],
                    }
                },
            )
            _registration_task_log(
                "[代理] 已启用进程内跨任务独立出口 IP：每个尝试会先探测并原子锁定出口，结束后进入冷却",
                stage_index=2,
                phase_label="选择代理",
            )

        def _proxy_source_exit_ip(source: Any) -> str:
            text = str(source or "")
            for pattern in (
                r"\bexit_ip\s*[:=]\s*([^｜\s,，;；)）]+)",
                r"出口IP\s*[:：]\s*([^｜\s,，;；)）]+)",
            ):
                match = re.search(pattern, text, flags=re.I)
                if match:
                    return str(match.group(1) or "").strip()
            return ""

        def _record_unique_exit_ip_event(event: dict[str, Any]) -> None:
            if not unique_exit_ip_enabled:
                return
            clean_event = sanitize_task_detail(event)
            # Keep snapshot construction and publication ordered. Without the
            # outer lock an older one-event snapshot can overwrite a newer
            # two-event snapshot when concurrent attempts publish out of order.
            with unique_exit_ip_meta_lock:
                with unique_exit_ip_lock:
                    unique_exit_ip_events.append(clean_event)
                    recent_events = list(unique_exit_ip_events[-100:])
                    assigned_count = sum(1 for item in unique_exit_ip_events if str(item.get("status") or "") == "assigned")
                    collision_count = sum(1 for item in unique_exit_ip_events if str(item.get("status") or "") == "collision")
                    failed_count = sum(1 for item in unique_exit_ip_events if str(item.get("status") or "") == "failed")
                    assigned_ips = sorted(unique_exit_ip_assigned)
                try:
                    _task_store.update_meta(
                        task_id,
                        {
                            "register_unique_exit_ip": {
                                "enabled": True,
                                "policy": unique_exit_ip_policy,
                                "scope": "process",
                                "assigned_count": assigned_count,
                                "collision_count": collision_count,
                                "failed_count": failed_count,
                                "max_refresh_attempts": unique_exit_ip_max_refresh_attempts,
                                "probe_timeout_seconds": unique_exit_ip_probe_timeout_seconds,
                                "active_ttl_seconds": unique_exit_ip_active_ttl_seconds,
                                "cooldown_seconds": unique_exit_ip_cooldown_seconds,
                                "assigned_exit_ips": assigned_ips[-100:],
                                "events": recent_events,
                            }
                        },
                    )
                except Exception:
                    pass

        def _probe_unique_exit_ip(
            proxy: str,
            source: str,
            *,
            reuse_source_probe: bool,
        ) -> tuple[str, str]:
            source_exit_ip = _proxy_source_exit_ip(source)
            source_text = str(source or "").strip().lower()
            fresh_source_probe = bool(
                source_exit_ip
                and source_text.startswith("dynamic")
                and ("probe=ok" in source_text or "probe=geo_unavailable" in source_text)
            )
            if not proxy:
                return "", "直连模式没有可隔离的代理出口；请改用动态代理或代理池"
            if fresh_source_probe and reuse_source_probe:
                return source_exit_ip, "dynamic_source_probe"
            try:
                from services.proxy_scanner import probe_basic

                probe = probe_basic(proxy, timeout_seconds=unique_exit_ip_probe_timeout_seconds)
                if probe.get("ok") and probe.get("exit_ip"):
                    return str(probe.get("exit_ip") or "").strip(), "probe"
                error = str(probe.get("error") or probe.get("error_code") or "出口 IP 探测失败").strip()
                return "", error
            except Exception as exc:
                return "", str(exc or "出口 IP 探测异常")

        def _claim_unique_register_exit_ip(
            *,
            attempt_index: int,
            owner: str,
            proxy: str,
            source: str,
            candidate_index: int,
            candidate_total: int,
        ) -> tuple[bool, str, str]:
            exit_ip, probe_source = _probe_unique_exit_ip(
                proxy,
                source,
                reuse_source_probe=candidate_index == 1,
            )
            source_label = str(source or "direct").strip() or "direct"
            if not exit_ip:
                reason = f"无法确认候选代理出口 IP: {probe_source or source_label}"
                _record_unique_exit_ip_event(
                    {
                        "attempt": attempt_index + 1,
                        "candidate": candidate_index,
                        "total": candidate_total,
                        "status": "failed",
                        "source": source_label,
                        "reason": reason,
                    }
                )
                return False, "", reason

            normalized_exit_ip = normalize_register_exit_ip(exit_ip)
            with unique_exit_ip_lock:
                task_collision = normalized_exit_ip in unique_exit_ip_assigned_keys
                claim = (
                    None
                    if task_collision
                    else register_exit_ip_registry.claim(
                        exit_ip,
                        owner=owner,
                        active_ttl_seconds=unique_exit_ip_active_ttl_seconds,
                    )
                )
                if claim is not None and claim.claimed:
                    unique_exit_ip_assigned_keys.add(claim.key)
                    unique_exit_ip_assigned.add(exit_ip)
            if task_collision:
                reason = f"出口 IP 已在本注册任务内分配: {exit_ip}"
                _record_unique_exit_ip_event(
                    {
                        "attempt": attempt_index + 1,
                        "candidate": candidate_index,
                        "total": candidate_total,
                        "status": "collision",
                        "exit_ip": exit_ip,
                        "source": source_label,
                        "probe_source": probe_source,
                        "reason": reason,
                    }
                )
                return False, exit_ip, reason
            if claim is None or not claim.claimed:
                wait_seconds = int(math.ceil(claim.expires_in_seconds)) if claim else 0
                reason = (
                    f"出口 IP 已被同进程其他注册任务占用: {exit_ip} "
                    f"state={claim.state if claim else 'unknown'} retry_after={wait_seconds}s"
                )
                _record_unique_exit_ip_event(
                    {
                        "attempt": attempt_index + 1,
                        "candidate": candidate_index,
                        "total": candidate_total,
                        "status": "collision",
                        "exit_ip": exit_ip,
                        "source": source_label,
                        "probe_source": probe_source,
                        "collision_scope": "process",
                        "lease_state": claim.state if claim else "unknown",
                        "retry_after_seconds": wait_seconds,
                        "reason": reason,
                    }
                )
                return False, exit_ip, reason

            _record_unique_exit_ip_event(
                {
                    "attempt": attempt_index + 1,
                    "candidate": candidate_index,
                    "total": candidate_total,
                    "status": "assigned",
                    "exit_ip": exit_ip,
                    "source": source_label,
                    "probe_source": probe_source,
                }
            )
            return True, exit_ip, ""

        def _fingerprint_payload(fingerprint: Any) -> dict[str, Any]:
            from services.chatgpt_core.account_fingerprint import (
                build_browser_fingerprint_payload,
            )

            return build_browser_fingerprint_payload(fingerprint)

        def _fingerprint_signature(payload: dict[str, Any], *, include_device: bool = False) -> str:
            from services.chatgpt_core.account_fingerprint import fingerprint_signature

            return fingerprint_signature(payload, include_device=include_device)

        def _build_register_attempt_fingerprint(attempt_index: int) -> tuple[dict[str, Any], str, str]:
            from services.chatgpt_core.browser_identity import (
                generate_browser_fingerprint,
                select_protocol_browser_family,
            )

            selected_payload: dict[str, Any] = {}
            selected_signature = ""
            family = (
                "firefox"
                if browser_executor
                else select_protocol_browser_family(
                    getattr(req, "browser_family", "random")
                )
            )
            for _ in range(40):
                payload = _fingerprint_payload(
                    generate_browser_fingerprint(
                        browser_family=family,
                        deep_context=browser_executor,
                    )
                )
                signature = _fingerprint_signature(payload)
                with browser_fingerprint_lock:
                    if signature not in browser_fingerprint_signatures:
                        browser_fingerprint_signatures.add(signature)
                        selected_payload = payload
                        selected_signature = signature
                        break
                selected_payload = payload
                selected_signature = _fingerprint_signature(payload, include_device=True)
            if not selected_payload:
                payload = _fingerprint_payload(
                    generate_browser_fingerprint(
                        browser_family=family,
                        deep_context=browser_executor,
                    )
                )
                selected_payload = payload
                selected_signature = _fingerprint_signature(payload, include_device=True)
            summary = (
                f"device=*{str(selected_payload.get('device_id') or '')[-8:]} "
                f"browser={selected_payload.get('browser_family') or family}/"
                f"{selected_payload.get('browser_version') or selected_payload.get('chrome_full_version')} "
                f"transport={selected_payload.get('impersonate') or '-'} "
                f"viewport={selected_payload.get('viewport_width')}x{selected_payload.get('viewport_height')} "
                f"lang={selected_payload.get('accept_language')} sig={selected_signature}"
            )
            return selected_payload, selected_signature, summary

        def _build_register_candidate_proxies(
            *,
            preflight: bool = False,
            dynamic_on_demand: bool = False,
        ) -> list[tuple[str, object | None, str]]:
            from core.proxy_utils import resolve_task_proxy_candidates

            params = dict(req.extra or {}) if isinstance(req.extra, dict) else {}
            params.update(dict(getattr(req, "_dynamic_proxy_runtime", {}) or {}))
            params["proxy"] = str(req.proxy or params.get("proxy") or params.get("dynamic_proxy_template") or "")
            params["proxy_mode"] = str(req.proxy_mode or params.get("proxy_mode") or "")
            if req.dynamic_proxy_provider:
                params["dynamic_proxy_provider"] = str(req.dynamic_proxy_provider)
            params["proxy_country_code"] = str(req.proxy_country_code or params.get("proxy_country_code") or "")
            params["proxy_failover"] = bool(req.proxy_failover) if req.proxy_failover is not None else params.get("proxy_failover")
            if req.dynamic_proxy_ip_retention_minutes:
                params["dynamic_proxy_ip_retention_minutes"] = req.dynamic_proxy_ip_retention_minutes
            if req.proxy_max_candidates:
                params["proxy_max_candidates"] = req.proxy_max_candidates
            elif params.get("proxy_max_candidates") is None:
                params.pop("proxy_max_candidates", None)
            if req.proxy_min_score:
                params["proxy_min_score"] = req.proxy_min_score
            elif params.get("proxy_min_score") is None:
                params.pop("proxy_min_score", None)
            mode = str(params.get("proxy_mode") or "").strip().lower()
            if preflight:
                if mode == "dynamic":
                    params["proxy_failover"] = False
                    params["dynamic_proxy_max_attempts"] = 1
                elif mode == "pool":
                    params["proxy_max_candidates"] = 1
                elif mode in {"specified", "manual", "explicit"}:
                    params["proxy_failover"] = False
            elif unique_exit_ip_enabled:
                if mode == "dynamic":
                    params["proxy_failover"] = not dynamic_on_demand
                    params["dynamic_proxy_max_attempts"] = (
                        1
                        if dynamic_on_demand
                        else unique_exit_ip_max_refresh_attempts
                    )
                elif mode == "pool" or (mode in {"specified", "manual", "explicit"} and _truthy(params.get("proxy_failover"))):
                    params["proxy_max_candidates"] = max(
                        _positive_int(params.get("proxy_max_candidates") or 0, default=0, minimum=0, maximum=100),
                        min(100, max(unique_exit_ip_max_refresh_attempts, int(req.count or 1) * 2)),
                    )

            return resolve_task_proxy_candidates(
                params,
                fallback_proxy=None,
                default_mode="global",
                target="chatgpt",
            )

        def _register_candidate_stream():
            mode = str(req.proxy_mode or "").strip().lower()
            if unique_exit_ip_enabled and mode == "dynamic":
                budget = unique_exit_ip_max_refresh_attempts

                def _generate_on_demand():
                    produced = 0
                    calls = 0
                    last_error: Exception | None = None
                    while produced < budget and calls < budget:
                        control.checkpoint()
                        calls += 1
                        try:
                            candidates = _build_register_candidate_proxies(
                                dynamic_on_demand=True,
                            )
                        except Exception as exc:
                            last_error = exc
                            continue
                        for candidate in candidates:
                            yield candidate
                            produced += 1
                            if produced >= budget:
                                return
                    if produced == 0 and last_error is not None:
                        raise last_error

                return _generate_on_demand(), budget

            candidates = _build_register_candidate_proxies()
            return iter(candidates), len(candidates)

        def _select_phone_signup_lines_for_attempt(raw_lines: Any, attempt_index: int) -> str:
            lines = [
                str(line or "").strip()
                for line in str(raw_lines or "").splitlines()
                if str(line or "").strip()
            ]
            if not lines:
                return ""
            if attempt_index >= len(lines):
                raise RuntimeError(
                    f"手机号注册可用号码行不足：当前尝试 {attempt_index + 1}，有效号码 {len(lines)} 条"
                )
            return lines[attempt_index]

        def _do_one(i: int):
            nonlocal next_start_time
            nonlocal chatgpt_checkout_amount_zero, chatgpt_checkout_amount_nonzero
            nonlocal chatgpt_zero_amount_stop_triggered
            current_email = req.email or ""
            attempt_id: int | None = None
            success_slot = 0
            success_at_start = 0
            browser_register_invoked = False
            phone_signup_entry = False
            exit_ip_lease_owner = f"{task_id}:{i + 1}"
            exit_ip_heartbeat_stop: threading.Event | None = None
            exit_ip_heartbeat_thread: threading.Thread | None = None
            diagnostic_session = None
            attempt_log_context: dict[str, Any] = {
                "attempt": i + 1,
                "email": current_email,
            }

            def _contextualize_attempt_log(message: str) -> str:
                text = str(message or "").strip()
                attempt_label = f"attempt={i + 1}"
                masked_email = mask_email_for_log(
                    attempt_log_context.get("email") or current_email
                )
                context = (
                    f"{attempt_label} email={masked_email}"
                    if masked_email
                    else attempt_label
                )
                if text.upper().startswith("[DEBUG]"):
                    remainder = text[len("[DEBUG]") :].strip()
                    return f"[DEBUG][{context}] {remainder}".rstrip()
                tag_match = re.match(r"^(\[[^\]]+\])\s*(.*)$", text)
                if tag_match:
                    tag, remainder = tag_match.groups()
                    return f"{tag} {context} {remainder}".rstrip()
                return f"[{context}] {text}".rstrip()

            def _format_attempt_timeline_log(message: str, *, debug: bool = False) -> str:
                stage_index, phase_label = infer_registration_timeline_stage(message)
                return format_task_timeline_log(
                    "ChatGPT注册",
                    str(message or ""),
                    success_slot=success_slot or 1,
                    success_total=target_successes,
                    stage_index=stage_index,
                    stage_total=registration_stage_total,
                    phase_label=phase_label,
                    debug=debug,
                )

            def _attempt_log(message: str, level: str = "info") -> None:
                normalized_level = str(level or "info").strip().lower() or "info"
                record_registration_diagnostic_log(message, normalized_level)
                if phone_signup_entry:
                    _log(task_id, _contextualize_attempt_log(message), normalized_level)
                    return
                if normalized_level == "debug" or str(message or "").lstrip().upper().startswith("[DEBUG]"):
                    if "[HTTP]" not in str(message or "").upper():
                        return
                    _log(task_id, _format_attempt_timeline_log(message, debug=True), "debug")
                    return
                _log(task_id, _format_attempt_timeline_log(message), normalized_level)

            def _attempt_result_metadata(**fields: Any) -> dict[str, Any]:
                metadata = {
                    "registration_success_slot": int(success_slot or 1),
                    "email": str(
                        attempt_log_context.get("email")
                        or current_email
                        or req.email
                        or ""
                    ).strip(),
                }
                metadata.update(fields)
                return metadata

            def _finalize_attempt_diagnostics(
                *,
                outcome: str,
                error: str = "",
                email: str = "",
                reason_code: str = "",
            ) -> dict[str, Any] | None:
                if diagnostic_session is None:
                    return None
                try:
                    artifact = diagnostic_session.finalize(
                        outcome=outcome,
                        error=error,
                        email=email,
                        reason_code=reason_code,
                    )
                    summary = registration_diagnostics_summary(task_id)
                    _task_store.update_meta(
                        task_id,
                        {
                            "registration_diagnostics": {
                                "mode": req.registration_diagnostics_mode,
                                "enabled": req.registration_diagnostics_mode != "off",
                                **summary,
                                "last_artifact": artifact,
                            }
                        },
                    )
                    return artifact
                except Exception as exc:
                    _log(
                        task_id,
                        f"[DEBUG] 注册诊断包收口失败: {type(exc).__name__}: {exc}",
                        "debug",
                    )
                    return None

            def _finish_attempt_result(result: AttemptResult) -> AttemptResult:
                result_meta = (
                    dict(result.metadata)
                    if isinstance(result.metadata, dict)
                    else {}
                )
                _finalize_attempt_diagnostics(
                    outcome=result.outcome.value,
                    error=result.message,
                    email=str(
                        result_meta.get("email")
                        or attempt_log_context.get("email")
                        or current_email
                        or ""
                    ),
                    reason_code=str(result_meta.get("reason_code") or ""),
                )
                return result

            try:
                from core.proxy_utils import (
                    is_proxy_error_text,
                )

                control.checkpoint()
                if req.register_delay_seconds > 0 or req.register_delay_max_seconds > 0:
                    with start_gate_lock:
                        # A future waiting for the shared start interval has
                        # not started an account yet.  Check immediate stop
                        # here, then claim only after the delay to ensure a
                        # graceful request cannot leak a queued registration.
                        control.checkpoint()
                        should_stop = control.should_stop_starting_new_attempts()
                        if isinstance(should_stop, bool) and should_stop:
                            return AttemptResult.not_started()
                        now = time.monotonic()
                        wait_seconds = max(0.0, next_start_time - now)
                        if wait_seconds > 0:
                            _attempt_log(
                                f"第 {i + 1} 个账号启动前延迟 {wait_seconds:g} 秒",
                            )
                            if not _sleep_with_control(
                                wait_seconds,
                                stop_before_start=True,
                            ):
                                return AttemptResult.not_started()
                        
                        delay_min = req.register_delay_seconds
                        delay_max = req.register_delay_max_seconds
                        if delay_max > delay_min:
                            chosen_delay = random.uniform(delay_min, delay_max)
                        else:
                            chosen_delay = delay_min
                            
                        next_start_time = time.monotonic() + chosen_delay
                with success_lock:
                    # Claiming the execution unit and freezing its next
                    # success slot are one atomic dispatcher observation.
                    # This prevents a concurrent completion from changing the
                    # prefix between ``start_attempt`` and the snapshot.
                    if success >= target_successes:
                        return AttemptResult.not_started()
                    attempt_id = control.start_attempt()
                    if attempt_id is not None:
                        success_at_start = success
                        success_slot = success_at_start + 1
                if attempt_id is None:
                    if control.is_stop_requested():
                        raise StopTaskRequested()
                    return AttemptResult.not_started()
                control.checkpoint(attempt_id=attempt_id)
                attempt_log_context["registration_success_slot"] = success_slot
                if req.registration_diagnostics_mode != "off":
                    try:
                        diagnostic_session = create_registration_diagnostic_session(
                            task_id=task_id,
                            attempt_id=attempt_id,
                            attempt_number=i + 1,
                            mode=req.registration_diagnostics_mode,
                            metadata={
                                "platform": req.platform,
                                "executor_type": req.executor_type,
                                "captcha_solver": req.captcha_solver,
                                "success_slot": success_slot,
                                "target_successes": target_successes,
                                "mail_provider": initial_merged_extra.get("mail_provider"),
                                "registration_entry": initial_merged_extra.get(
                                    "chatgpt_registration_entry"
                                ),
                            },
                        )
                        if diagnostic_session is not None:
                            _task_store.update_meta(
                                task_id,
                                {
                                    "registration_diagnostics": {
                                        "mode": req.registration_diagnostics_mode,
                                        "enabled": True,
                                        **registration_diagnostics_summary(task_id),
                                    }
                                },
                            )
                    except Exception as exc:
                        diagnostic_session = None
                        _log(
                            task_id,
                            f"[DEBUG] 注册诊断初始化失败，注册继续: {type(exc).__name__}: {exc}",
                            "debug",
                        )
                candidate_proxies, candidate_total = _register_candidate_stream()

                merged_extra = _build_effective_register_extra(req)
                phone_signup_entry = (
                    req.platform == "chatgpt"
                    and str(
                        merged_extra.get("chatgpt_registration_entry")
                        or merged_extra.get("registration_entry")
                        or ""
                    ).strip().lower().replace("-", "_")
                    in {"phone", "phone_signup", "sms", "sms_signup"}
                )
                if phone_signup_entry:
                    merged_extra["chatgpt_registration_entry"] = "phone_signup"
                    merged_extra["chatgpt_registration_mode"] = "access_token_only"
                    merged_extra["chatgpt_has_refresh_token_solution"] = False
                    merged_extra["_target_success_count"] = target_successes

                def _register_task_log(message: str, level: str = "info", *_args: Any) -> None:
                    raw_message = str(message or "")
                    record_registration_diagnostic_log(raw_message, level)
                    # Mailbox implementations may still emit a low-level
                    # "code hit" line containing the plaintext OTP. The
                    # adapter emits the canonical length/wait/source summary;
                    # discard the raw duplicate before it reaches task logs.
                    if any(
                        marker in raw_message
                        for marker in ("命中验证码:", "解析到验证码", "成功获取验证码:")
                    ) and "长度=" not in raw_message:
                        return
                    if raw_message.startswith("[邮箱] mail_provider=") or "Helper 已领取别名:" in raw_message:
                        return
                    flow = "phone_signup" if phone_signup_entry else "access_token_register"
                    effective_level = classify_task_log_level(message, level, flow=flow)
                    if (
                        not phone_signup_entry
                        and effective_level == "debug"
                        and "[HTTP]" not in raw_message.upper()
                    ):
                        # Registration Debug is reserved for network
                        # transactions.  OAuth/state-machine chatter remains
                        # available in the engine's internal diagnostics but
                        # does not inflate the operator-facing task log.
                        return
                    if phone_signup_entry:
                        display_message = _contextualize_attempt_log(str(message or ""))
                    elif effective_level == "debug":
                        display_message = _format_attempt_timeline_log(str(message or ""), debug=True)
                    else:
                        display_message = _format_attempt_timeline_log(str(message or ""))
                    _log(
                        task_id,
                        display_message,
                        effective_level,
                    )

                _task_store.set_progress(task_id, f"{success_at_start}/{target_successes}")
                _attempt_log(
                    f"[账号] target={target_successes} current_success={success_at_start} "
                    f"executor={req.executor_type or 'protocol'} status=started"
                )
                attempt_fingerprint_payload: dict[str, Any] = {}
                attempt_fingerprint_signature = ""
                if req.platform == "chatgpt":
                    (
                        attempt_fingerprint_payload,
                        attempt_fingerprint_signature,
                        attempt_fingerprint_summary,
                    ) = _build_register_attempt_fingerprint(i)
                    _attempt_log(
                        f"[指纹] 已分配独立浏览器指纹：{attempt_fingerprint_summary}"
                    )

                last_proxy_error = ""
                last_proxy_error_email = current_email
                selected_exit_ip = ""
                selected_proxy_source = ""
                for proxy_index, (candidate_proxy, candidate_proxy_pool, candidate_proxy_source) in enumerate(candidate_proxies, start=1):
                    _proxy = candidate_proxy
                    proxy_pool = candidate_proxy_pool
                    proxy_source = candidate_proxy_source

                    try:
                        allocated_exit_ip = ""
                        if unique_exit_ip_enabled:
                            allocation_ok, allocated_exit_ip, allocation_reason = _claim_unique_register_exit_ip(
                                attempt_index=i,
                                owner=exit_ip_lease_owner,
                                proxy=_proxy,
                                source=proxy_source,
                                candidate_index=proxy_index,
                                candidate_total=candidate_total,
                            )
                            if not allocation_ok:
                                last_proxy_error = allocation_reason
                                _attempt_log(
                                    f"[代理] 独立出口 IP 检查未通过，跳过候选 {proxy_index}/{candidate_total}：{allocation_reason}",
                                )
                                continue
                            if exit_ip_heartbeat_thread is None:
                                exit_ip_heartbeat_stop = threading.Event()
                                heartbeat_interval = max(
                                    5.0,
                                    min(
                                        float(unique_exit_ip_active_ttl_seconds) / 3.0,
                                        300.0,
                                    ),
                                )

                                def _refresh_exit_ip_lease() -> None:
                                    while not exit_ip_heartbeat_stop.wait(heartbeat_interval):
                                        refreshed = register_exit_ip_registry.refresh_owner(
                                            exit_ip_lease_owner,
                                            active_ttl_seconds=unique_exit_ip_active_ttl_seconds,
                                        )
                                        if refreshed <= 0:
                                            return

                                exit_ip_heartbeat_thread = threading.Thread(
                                    target=_refresh_exit_ip_lease,
                                    name=f"register-exit-ip-{i + 1}",
                                    daemon=True,
                                )
                                exit_ip_heartbeat_thread.start()
                            _attempt_log(
                                f"[代理] 独立出口 IP 已锁定: {allocated_exit_ip} candidate={proxy_index}/{candidate_total}",
                            )
                        _log_register_proxy_choice(
                            _proxy,
                            proxy_source,
                            proxy_index,
                            candidate_total,
                            attempt_index=i + 1,
                            exit_ip=allocated_exit_ip,
                            log_fn=_attempt_log,
                        )
                        runtime_extra = dict(merged_extra or {})
                        runtime_extra["__register_task_log_context"] = attempt_log_context
                        if not _proxy and str(proxy_source or "").strip().lower() == "direct":
                            runtime_extra["__register_proxy_mode"] = "direct"
                        runtime_extra["_current_task_id"] = task_id
                        if attempt_fingerprint_payload:
                            runtime_extra["chatgpt_browser_fingerprint"] = dict(attempt_fingerprint_payload)
                            runtime_extra["chatgpt_browser_fingerprint_isolated"] = True
                            runtime_extra["chatgpt_browser_fingerprint_isolation_mode"] = str(
                                attempt_fingerprint_payload.get("isolation_mode") or ""
                            )
                            runtime_extra["chatgpt_browser_fingerprint_signature"] = attempt_fingerprint_signature
                        if unique_exit_ip_enabled:
                            runtime_extra["chatgpt_register_unique_exit_ip_enabled"] = True
                        if allocated_exit_ip:
                            runtime_extra["chatgpt_register_exit_ip"] = allocated_exit_ip
                        if phone_signup_entry:
                            phone_lines_for_signup = str(runtime_extra.get("chatgpt_phone_signup_phone_lines") or "").strip()
                            if phone_lines_for_signup:
                                runtime_extra["chatgpt_phone_signup_phone_lines"] = _select_phone_signup_lines_for_attempt(
                                    phone_lines_for_signup,
                                    i,
                                )
                        _config = RegisterConfig(
                            executor_type=req.executor_type,
                            captcha_solver=req.captcha_solver,
                            proxy=_proxy,
                            extra=runtime_extra,
                        )
                        if str(runtime_extra.get("mail_provider") or "").strip().lower() in {"email_api", "api_email", "email_otp_api", "mail_api_otp"}:
                            runtime_extra["mail_provider"] = "email_api"
                            runtime_extra["email_api_pool_key"] = task_id
                        _mailbox = None if phone_signup_entry else _build_mailbox(_proxy, runtime_extra)
                        _platform = PlatformCls(config=_config, mailbox=_mailbox)
                        _platform._task_attempt_token = attempt_id
                        _platform._log_fn = _register_task_log
                        _platform.bind_task_control(control)
                        if getattr(_platform, "mailbox", None) is not None:
                            _platform.mailbox._task_attempt_token = attempt_id
                            # Keep the parent task id distinct from the attempt
                            # idempotency token.  HME Helper persists it at
                            # checkout time, so a client-side prepare timeout is
                            # still attributable and recoverable.
                            _platform.mailbox._registration_task_id = task_id
                            _platform.mailbox._log_fn = _platform._log_fn
                        if browser_executor:
                            browser_register_invoked = True
                            _attempt_log(
                                "[控制] browser_identity_started=yes "
                                "same_attempt_proxy_failover=disabled"
                            )
                        account = _platform.register(
                            email=req.email or None,
                            password=req.password,
                        )
                        selected_exit_ip = allocated_exit_ip
                        selected_proxy_source = str(proxy_source or "")
                        break
                    except SkipCurrentAttemptRequested:
                        raise
                    except StopTaskRequested:
                        raise
                    except Exception as proxy_exc:
                        current_email = str(
                            attempt_log_context.get("email")
                            or current_email
                            or req.email
                            or ""
                        ).strip()
                        error_text = str(proxy_exc or "").strip()
                        if _proxy and proxy_pool is not None and str(proxy_source or "").startswith("pool"):
                            proxy_pool.report_fail(_proxy)
                            if (
                                "status=403" in error_text
                                or "HTTP 403" in error_text
                                or "预授权被拦截" in error_text
                                or "访问首页失败" in error_text
                            ):
                                proxy_pool.report_homepage_fail(
                                    _proxy,
                                    error_message=error_text,
                                    status_code=403 if ("403" in error_text or "访问首页失败" in error_text or "预授权被拦截" in error_text) else 0,
                                )
                        if browser_executor and browser_register_invoked:
                            last_proxy_error = error_text
                            last_proxy_error_email = current_email
                            _attempt_log(
                                "[控制] browser_identity_started=yes "
                                "same_attempt_proxy_failover=disabled "
                                f"reason={sanitize_error_message(error_text)[:300]}",
                                "debug",
                            )
                            raise
                        if is_proxy_error_text(error_text) and proxy_index < candidate_total:
                            last_proxy_error = error_text
                            last_proxy_error_email = current_email
                            _attempt_log(
                                f"[代理] 当前代理失败，保留当前尝试重试下一个代理: {error_text}"
                            )
                            continue
                        raise
                else:
                    final_error = last_proxy_error or "所有代理尝试失败"
                    raise RuntimeError(final_error)

                current_email = account.email or current_email
                attempt_log_context["email"] = current_email
                if isinstance(account.extra, dict):
                    persist_attempt_fingerprint = (
                        req.platform == "chatgpt"
                        and str(req.executor_type or "protocol").strip().lower()
                        == "protocol"
                    )
                    if attempt_fingerprint_payload and persist_attempt_fingerprint:
                        from services.chatgpt_core.account_fingerprint import persist_account_browser_fingerprint

                        account.extra = persist_account_browser_fingerprint(
                            account.extra,
                            attempt_fingerprint_payload,
                            source="registration",
                            overwrite=False,
                        )
                    if attempt_fingerprint_signature and persist_attempt_fingerprint:
                        account.extra.setdefault("chatgpt_browser_fingerprint_isolated", True)
                        account.extra.setdefault("chatgpt_browser_fingerprint_signature", attempt_fingerprint_signature)
                    if unique_exit_ip_enabled:
                        account.extra.setdefault("chatgpt_register_unique_exit_ip_enabled", True)
                    if selected_exit_ip:
                        account.extra.setdefault("chatgpt_register_exit_ip", selected_exit_ip)
                    if selected_proxy_source:
                        account.extra.setdefault("chatgpt_register_proxy_source", selected_proxy_source)
                    mail_provider = merged_extra.get("mail_provider", "")
                    if mail_provider:
                        account.extra.setdefault("mail_provider", mail_provider)
                    if req.platform == "chatgpt":
                        for key in (
                            "chatgpt_existing_account_capture",
                            "chatgpt_existing_account_login_route_enabled",
                            "chatgpt_register_unique_exit_ip_enabled",
                        ):
                            if key in merged_extra:
                                account.extra[key] = merged_extra.get(key)
                    if mail_provider == "luckmail" and req.platform == "chatgpt":
                        mailbox_token = getattr(_mailbox, "_token", "") or ""
                        if mailbox_token:
                            account.extra.setdefault("mailbox_token", mailbox_token)
                        if merged_extra.get("luckmail_project_code"):
                            account.extra.setdefault(
                                "luckmail_project_code",
                                merged_extra.get("luckmail_project_code"),
                            )
                        if merged_extra.get("luckmail_email_type"):
                            account.extra.setdefault(
                                "luckmail_email_type",
                                merged_extra.get("luckmail_email_type"),
                            )
                        if merged_extra.get("luckmail_domain"):
                            account.extra.setdefault(
                                "luckmail_domain", merged_extra.get("luckmail_domain")
                            )
                        if merged_extra.get("luckmail_base_url"):
                            account.extra.setdefault(
                                "luckmail_base_url",
                                merged_extra.get("luckmail_base_url"),
                            )
                account_extra = account.extra if isinstance(account.extra, dict) else {}
                account_extra = _cache_chatgpt_checkout_link(
                    account_extra,
                    source="registration_checkout_probe",
                )
                if isinstance(account.extra, dict):
                    account.extra = account_extra
                if req.platform == "chatgpt" and isinstance(account.extra, dict):
                    account.extra["chatgpt_capabilities"] = classify_chatgpt_capabilities(account)
                registered_auth_pending = bool(
                    req.platform == "chatgpt"
                    and isinstance(account.extra, dict)
                    and account.extra.get("registered_auth_pending")
                    and not str(
                        account.token
                        or account.extra.get("access_token")
                        or ""
                    ).strip()
                )
                existing_account_route_event = {}
                if req.platform == "chatgpt" and isinstance(account_extra, dict):
                    existing_account_route_event = _coerce_existing_account_login_route_event(
                        account_extra.get(LOGIN_ROUTE_EVENT_KEY),
                        fallback_email=str(account.email or current_email or ""),
                    )
                    if existing_account_route_event:
                        _record_existing_account_login_route(task_id, existing_account_route_event)
                        action_label = (
                            "已跳过"
                            if existing_account_route_event.get("blocked")
                            else "已路由到登录恢复"
                        )
                        _attempt_log(
                            f"[已有账号] {action_label}: {existing_account_route_event.get('email') or account.email or '-'}",
                        )
                skip_save_account = req.platform == "chatgpt" and _is_truthy(account_extra.get("chatgpt_skip_save_account"))
                checkout_amount_seen = "chatgpt_checkout_amount_is_zero" in account_extra
                checkout_amount_is_zero = bool(account_extra.get("chatgpt_checkout_amount_is_zero"))
                should_stop_after_current_account = False
                zero_amount_stop_reason = ""
                if req.platform == "chatgpt" and checkout_amount_seen:
                    with chatgpt_checkout_amount_lock:
                        if checkout_amount_is_zero:
                            chatgpt_checkout_amount_zero += 1
                            if (
                                chatgpt_zero_amount_stop_enabled
                                and not chatgpt_zero_amount_stop_triggered
                                and chatgpt_checkout_amount_zero >= chatgpt_zero_amount_stop_threshold
                            ):
                                chatgpt_zero_amount_stop_triggered = True
                                should_stop_after_current_account = True
                                zero_amount_stop_reason = (
                                    "Plus checkout amount=0 命中阈值 "
                                    f"{chatgpt_checkout_amount_zero}/{chatgpt_zero_amount_stop_threshold}，"
                                    "已停止后续注册"
                                )
                        else:
                            chatgpt_checkout_amount_nonzero += 1
                if skip_save_account:
                    skip_reason = str(account_extra.get("chatgpt_skip_save_reason") or "Plus checkout amount != 0").strip()
                    skip_save_is_failure = True
                    amount_text = str(account_extra.get("chatgpt_checkout_amount") or account_extra.get("chatgpt_checkout_amount_raw") or "").strip()
                    currency_text = str(account_extra.get("chatgpt_checkout_currency") or "").strip()
                    checkout_url = str(account_extra.get("chatgpt_checkout_url") or account_extra.get("cashier_url") or "").strip()
                    _attempt_log(
                        f"[SKIP_SAVE] 注册未计成功且不保存账号: {account.email} reason={skip_reason}",
                    )
                    if amount_text or currency_text:
                        _attempt_log(
                            f"[SKIP_SAVE] Plus checkout amount={amount_text or 'unknown'} currency={currency_text or 'unknown'}"
                        )
                    if checkout_url:
                        _attempt_log(f"[升级链接] {checkout_url}")
                        _task_store.add_cashier_url(task_id, checkout_url)
                    if should_stop_after_current_account and zero_amount_stop_reason:
                        control.request_stop()
                        _attempt_log(f"[STOP] {zero_amount_stop_reason}")
                    _save_task_log(
                        req.platform,
                        account.email,
                        "failed" if skip_save_is_failure else "success",
                        error=skip_reason if skip_save_is_failure else "",
                        detail=_build_task_log_detail(
                            task_id,
                            {
                                "attempt_outcome": "failed_skip_save",
                                "email": account.email,
                                "skip_save_reason": skip_reason,
                                "skip_save_is_failure": skip_save_is_failure,
                                "chatgpt_checkout_error_code": str(account_extra.get("chatgpt_checkout_error_code") or ""),
                                "chatgpt_checkout_amount": amount_text,
                                "chatgpt_checkout_currency": currency_text,
                                "chatgpt_checkout_amount_is_zero": checkout_amount_is_zero,
                                "chatgpt_checkout_url": checkout_url,
                                "existing_account_login_route": existing_account_route_event,
                                "chatgpt_zero_amount_stop_enabled": chatgpt_zero_amount_stop_enabled,
                                "chatgpt_zero_amount_stop_threshold": chatgpt_zero_amount_stop_threshold,
                                "chatgpt_zero_amount_stop_triggered": should_stop_after_current_account,
                                "chatgpt_zero_amount_stop_reason": zero_amount_stop_reason,
                            },
                        ),
                    )
                    return _finish_attempt_result(AttemptResult.failed(
                        skip_reason,
                        metadata=_attempt_result_metadata(
                            email=str(account.email or current_email or ""),
                            reason_code="failed_skip_save",
                            mailbox_action="success",
                            backfill=True,
                        ),
                    ))
                saved_account = save_account(account)
                if req.platform == "chatgpt" and saved_account is not None:
                    try:
                        with task_meta_update_lock:
                            latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
                            registered_accounts = latest_meta.get("registered_accounts")
                            if not isinstance(registered_accounts, list):
                                registered_accounts = []
                            saved_account_id = int(getattr(saved_account, "id", 0) or 0)
                            saved_email = str(getattr(saved_account, "email", "") or account.email or "").strip()
                            if saved_account_id > 0 or saved_email:
                                existing_keys = {
                                    (
                                        int(item.get("account_id") or 0),
                                        str(item.get("email") or "").strip().lower(),
                                    )
                                    for item in registered_accounts
                                    if isinstance(item, dict)
                                }
                                key = (saved_account_id, saved_email.lower())
                                if key not in existing_keys:
                                    created_at = getattr(saved_account, "created_at", None)
                                    updated_at = getattr(saved_account, "updated_at", None)
                                    registered_accounts.append(
                                        {
                                            "account_id": saved_account_id,
                                            "email": saved_email,
                                            "created_at": created_at.isoformat() if hasattr(created_at, "isoformat") else "",
                                            "updated_at": updated_at.isoformat() if hasattr(updated_at, "isoformat") else "",
                                        }
                                    )
                                    _task_store.update_meta(task_id, {"registered_accounts": registered_accounts[-500:]})
                    except Exception as meta_exc:
                        _attempt_log(f"[WARN] 注册账号结果写入任务快照失败: {meta_exc}", "warning")
                    if registered_auth_pending:
                        try:
                            with task_meta_update_lock:
                                latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
                                pending_accounts = latest_meta.get("auth_pending_accounts")
                                if not isinstance(pending_accounts, list):
                                    pending_accounts = []
                                pending_item = {
                                    "account_id": int(getattr(saved_account, "id", 0) or 0),
                                    "email": str(getattr(saved_account, "email", "") or account.email or ""),
                                    "reason": str(
                                        account.extra.get("registration_full_auth_error")
                                        or "浏览器注册完成但认证材料待补抓"
                                    ),
                                    "requested_executor_type": str(
                                        account.extra.get("requested_executor_type") or req.executor_type or ""
                                    ),
                                    "effective_executor_type": str(
                                        account.extra.get("effective_executor_type") or req.executor_type or ""
                                    ),
                                }
                                pending_key = (
                                    pending_item["account_id"],
                                    pending_item["email"].strip().lower(),
                                )
                                pending_accounts = [
                                    item
                                    for item in pending_accounts
                                    if not isinstance(item, dict)
                                    or (
                                        int(item.get("account_id") or 0),
                                        str(item.get("email") or "").strip().lower(),
                                    )
                                    != pending_key
                                ]
                                pending_accounts.append(pending_item)
                                _task_store.update_meta(
                                    task_id,
                                    {
                                        "auth_pending_accounts": pending_accounts[-500:],
                                        "auth_pending_count": len(pending_accounts[-500:]),
                                    },
                                )
                        except Exception as meta_exc:
                            _attempt_log(
                                f"[WARN] 认证待补抓结果写入任务快照失败: {meta_exc}",
                                "warning",
                            )
                    else:
                        saved_account_id = int(getattr(saved_account, "id", 0) or 0)
                        if saved_account_id > 0:
                            with post_registration_refresh_lock:
                                post_registration_refresh_proxies[saved_account_id] = str(_proxy or "").strip()
                            # The PayPal coordinator writes the payment marker and
                            # link audit after this block.  Defer the refresh until
                            # coordinator.finish() so a stale full-extra snapshot
                            # cannot overwrite that marker in the 2-second queue.
                            if not registration_paypal_link_enabled:
                                schedule_chatgpt_local_status_refresh_for_account_id(
                                    saved_account_id,
                                    proxy=str(_proxy or "").strip() or None,
                                    use_default_proxy=False if str(_proxy or "").strip() else True,
                                    reason="registration_account_saved",
                                    delay_seconds=2.0,
                                )
                if req.platform == "chatgpt" and isinstance(account.extra, dict) and account.extra.get("chatgpt_registration_entry") == "phone_signup":
                    try:
                        phone_result = account.extra.get("chatgpt_phone_signup_result")
                        phone_results = account.extra.get("chatgpt_phone_signup_results")
                        if not isinstance(phone_results, list):
                            phone_results = [phone_result] if isinstance(phone_result, dict) else []
                        phone_results = [dict(item) for item in phone_results if isinstance(item, dict)]
                        if phone_results:
                            saved_account_id = int(getattr(saved_account, "id", 0) or 0) if saved_account is not None else 0
                            saved_email = str(getattr(saved_account, "email", "") or account.email or "")
                            latest_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
                            runtime_results = list(latest_meta.get("runtime_results") or [])
                            registered_phone_lines = list(latest_meta.get("registered_phone_lines") or [])
                            last_phone = ""
                            for item in phone_results:
                                if str(item.get("status") or "") == "registered_phone_signup":
                                    item["account_id"] = saved_account_id
                                    item["email"] = saved_email or str(item.get("email") or "")
                                    raw_line = str(item.get("raw_line") or "").strip()
                                    if raw_line:
                                        registered_phone_lines.append(redact_raw_phone_line(raw_line))
                                    last_phone = str(item.get("phone") or last_phone or "")
                                runtime_results.append(sanitize_phone_result(item))
                            phone_prefix_items = [
                                {
                                    "phone": str(item.get("phone") or ""),
                                    "prefix4": str(item.get("prefix4") or _phone_binding_prefix4(item.get("phone"))),
                                }
                                for item in runtime_results
                                if str(item.get("phone") or "").strip()
                            ]
                            _task_store.update_meta(
                                task_id,
                                {
                                    "runtime_results": [sanitize_phone_result(item) for item in runtime_results],
                                    "registered_phone_lines": [redact_raw_phone_line(line) for line in registered_phone_lines],
                                    "prefix_summary": _build_phone_prefix_sample_summary(phone_prefix_items, runtime_results, phone_signup=True),
                                    "phone_signup": {
                                        "enabled": True,
                                        "last_phone": last_phone,
                                        "last_phone_masked": mask_phone_for_log(last_phone),
                                    },
                                },
                            )
                    except Exception as meta_exc:
                        _log(task_id, f"[手机号注册] 结果写入任务快照失败: {meta_exc}")
                if req.platform == "chatgpt" and isinstance(account.extra, dict):
                    try:
                        from core.db import sync_icloud_hme_rerun_result

                        mailbox_state = account.extra.get("chatgpt_mailbox_state")
                        mailbox_state = mailbox_state if isinstance(mailbox_state, dict) else {}
                        mailbox_account = mailbox_state.get("account") if isinstance(mailbox_state.get("account"), dict) else {}
                        mailbox_extra = mailbox_account.get("extra") if isinstance(mailbox_account.get("extra"), dict) else {}
                        provider = str(mailbox_state.get("provider") or account.extra.get("mail_provider") or "").strip()
                        raw_provider = provider.lower()
                        from services.chatgpt_core.mailbox_state import normalize_mailbox_provider

                        if normalize_mailbox_provider(provider) == "hme_ready_api":
                            legacy_source = str(
                                mailbox_extra.get("source")
                                or mailbox_extra.get("record_source")
                                or ""
                            ).strip().lower()
                            anonymous_id = str(mailbox_extra.get("anonymous_id") or "").strip()
                            lease_id = str(
                                mailbox_extra.get("lease_id")
                                or mailbox_extra.get("checkout_id")
                                or ""
                            ).strip()
                            if anonymous_id and (
                                legacy_source in {"legacy-icloud-hme", "icloud-hme-legacy"}
                                or (raw_provider == "icloud_hme" and not lease_id)
                            ):
                                token_value = str(account.token or account.extra.get("access_token") or "").strip()
                                sync_icloud_hme_rerun_result(
                                    anonymous_id=anonymous_id,
                                    hme=str(mailbox_extra.get("hme") or mailbox_state.get("email") or account.email or ""),
                                    task_id=task_id,
                                    success=True,
                                    saved_account_id=int(getattr(saved_account, "id", 0) or 0) if saved_account is not None else 0,
                                    access_token_saved=bool(token_value),
                                    mailbox_state=mailbox_state,
                                    result_code=(
                                        "registered_auth_pending"
                                        if registered_auth_pending
                                        else "login_alive"
                                    ),
                                )
                    except Exception as sync_exc:
                        _attempt_log(f"[HME Ready] 重跑结果写回失败: {sync_exc}", "warning")
                saved_inventory_id = int(getattr(saved_account, "id", 0) or 0) if saved_account is not None else 0
                openai_account_id = str(
                    account_extra.get("account_id")
                    or account_extra.get("user_id")
                    or "-"
                ).strip()
                _attempt_log(
                    f"[保存] 账号已保存｜邮箱={mask_email_for_log(str(account.email or current_email or ''))} "
                    f"｜库存ID={saved_inventory_id or '-'}｜OpenAI账号={openai_account_id} "
                    f"｜AT={'是' if account.token or account_extra.get('access_token') else '否'} "
                    f"｜Session={'是' if account_extra.get('session_token') or account_extra.get('sessionToken') else '否'} "
                    f"｜Cookie状态={'已获取' if account_extra.get('cookie_header') or account_extra.get('cookies') else '缺失'}"
                )
                if _proxy and proxy_pool is not None and str(proxy_source or "").startswith("pool"):
                    proxy_pool.report_success(_proxy)
                if should_stop_after_current_account and zero_amount_stop_reason:
                    control.request_stop()
                    _attempt_log(f"[STOP] {zero_amount_stop_reason}")
                if registered_auth_pending:
                    _attempt_log(
                        "[阶段] stage=auth_capture result=pending saved=yes"
                    )
                    _attempt_log(
                        "[Auto Upload] 认证材料待补抓，已跳过外部同步"
                    )
                else:
                    _auto_upload_integrations(
                        task_id,
                        saved_account or account,
                        log_fn=_attempt_log,
                    )
                saved_account_id = int(
                    getattr(saved_account, "id", 0)
                    or getattr(account, "id", 0)
                    or 0
                )
                saved_account_email = str(
                    getattr(saved_account, "email", "")
                    or getattr(account, "email", "")
                    or ""
                )
                saved_account_created_at = getattr(saved_account, "created_at", None)
                saved_account_created_at_text = (
                    saved_account_created_at.replace(tzinfo=None).isoformat(sep=" ")
                    if isinstance(saved_account_created_at, datetime)
                    else str(saved_account_created_at or "").strip()
                )
                try:
                    from services.chatgpt_core.registration_pipeline import (
                        initialize_registration_pipeline,
                    )

                    initialize_registration_pipeline(
                        saved_account_id,
                        email=saved_account_email,
                        created_at=saved_account_created_at_text,
                        task_id=task_id,
                        zero_amount_enabled=registration_zero_amount_enabled,
                        payment_link_enabled=registration_paypal_link_enabled,
                        payment_enabled=registration_paypal_payment_enabled,
                        auth_pending=registered_auth_pending,
                        legacy_combined=registration_pipeline_legacy_combined,
                        zero_amount_checkout_country=str(
                            getattr(
                                req,
                                "registration_zero_amount_checkout_country",
                                "VN",
                            )
                            or "VN"
                        ),
                        payment_link_profile_hash=str(
                            frozen_paypal_payment.get("profile_hash") or ""
                        ),
                        payment_link_type=str(
                            frozen_paypal_payment.get("link_type") or "paypal"
                        ),
                    )
                except Exception as pipeline_exc:
                    _attempt_log(
                        f"[注册链路] 账号阶段初始化失败，不影响注册结果: {sanitize_error_message(str(pipeline_exc))}",
                        "warning",
                    )
                if registration_eligibility_coordinator is not None:
                    try:
                        registration_eligibility_coordinator.submit(
                            int(getattr(saved_account, "id", 0) or 0),
                            str(getattr(saved_account, "email", "") or account.email or ""),
                        )
                    except Exception as eligibility_submit_exc:
                        _attempt_log(
                            "[0 元试用资格] 后处理入队失败，不影响注册结果: "
                            f"{sanitize_error_message(str(eligibility_submit_exc or '未知错误'))}",
                            "warning",
                        )
                if (
                    registration_paypal_payment_coordinator is not None
                    and (
                        registration_pipeline_legacy_combined
                        or registration_eligibility_coordinator is None
                    )
                ):
                    try:
                        registration_paypal_payment_coordinator.submit(
                            saved_account_id,
                            saved_account_email,
                        )
                    except Exception as paypal_submit_exc:
                        from services.chatgpt_core.paypal_agreement_auto_client import (
                            sanitize_paypal_agreement_error,
                        )

                        _attempt_log(
                            "[PayPal 自动支付] 后处理入队失败，不影响注册结果: "
                            f"{sanitize_paypal_agreement_error(paypal_submit_exc) or '未知错误'}",
                            "warning",
                        )
                cashier_url = (account.extra or {}).get("cashier_url", "")
                if cashier_url:
                    _attempt_log(f"[升级链接] {cashier_url}")
                    _task_store.add_cashier_url(task_id, cashier_url)
                _save_task_log(
                    req.platform,
                    account.email,
                    "success",
                    detail=_build_task_log_detail(
                        task_id,
                        {
                            "attempt_outcome": (
                                "registered_auth_pending"
                                if registered_auth_pending
                                else "success"
                            ),
                            "email": account.email,
                            "registered_auth_pending": registered_auth_pending,
                            "registration_full_auth_error": str(
                                account_extra.get("registration_full_auth_error") or ""
                            ),
                            "existing_account_login_route": existing_account_route_event,
                            "chatgpt_zero_amount_stop_enabled": chatgpt_zero_amount_stop_enabled,
                            "chatgpt_zero_amount_stop_threshold": chatgpt_zero_amount_stop_threshold,
                            "chatgpt_zero_amount_stop_triggered": should_stop_after_current_account,
                            "chatgpt_zero_amount_stop_reason": zero_amount_stop_reason,
                        },
                    ),
                )
                return _finish_attempt_result(AttemptResult.success(
                    metadata=_attempt_result_metadata(
                        email=str(account.email or current_email or ""),
                        reason_code=(
                            "registered_auth_pending"
                            if registered_auth_pending
                            else "success"
                        ),
                        mailbox_action="success",
                        registered_auth_pending=registered_auth_pending,
                        backfill=False,
                    )
                ))
            except SkipCurrentAttemptRequested as e:
                current_email = str(
                    attempt_log_context.get("email")
                    or getattr(e, "email", "")
                    or current_email
                    or ""
                ).strip()
                route_event = _coerce_existing_account_login_route_event(
                    getattr(e, "route_event", None),
                    fallback_email=current_email,
                    default_blocked=bool(getattr(e, "route_event", None)),
                )
                if route_event:
                    current_email = str(route_event.get("email") or current_email or "").strip()
                    attempt_log_context["email"] = current_email
                    _record_existing_account_login_route(task_id, route_event)
                skip_reason_code = (
                    "existing_account"
                    if route_event
                    else str(getattr(e, "code", "") or "skipped")
                )
                _save_task_log(
                    req.platform,
                    current_email,
                    "skipped",
                    error=str(e),
                    detail=_build_task_log_detail(
                        task_id,
                        {
                            "attempt_outcome": "existing_account_login_route_blocked" if route_event else "skipped",
                            "email": current_email,
                            "existing_account_login_route": route_event,
                        },
                    ),
                )
                return _finish_attempt_result(AttemptResult.skipped(
                    str(e),
                    metadata=_attempt_result_metadata(
                        email=current_email,
                        reason_code=skip_reason_code,
                        mailbox_action="keep" if route_event else "finalized",
                        backfill=True,
                        existing_account_login_route=route_event,
                    ),
                ))
            except StopTaskRequested as e:
                _attempt_log(f"[STOP] {e}")
                return _finish_attempt_result(AttemptResult.stopped(str(e)))
            except Exception as e:
                error_text = str(e)
                registration_failure_metadata = getattr(
                    e, "registration_metadata", None
                )
                registration_failure_metadata = (
                    dict(registration_failure_metadata)
                    if isinstance(registration_failure_metadata, dict)
                    else {}
                )
                mailbox_finalize_outcome = str(
                    registration_failure_metadata.get("mailbox_finalize_outcome")
                    or ""
                ).strip().lower()
                current_email = str(
                    attempt_log_context.get("email")
                    or current_email
                    or ""
                ).strip()
                deterministic_existing = is_existing_account_detected_message(
                    error_text
                )
                route_enabled = parse_route_bool(
                    (
                        merged_extra.get(
                            "chatgpt_existing_account_login_route_enabled"
                        )
                        if "merged_extra" in locals()
                        else None
                    ),
                    default=True,
                )
                if deterministic_existing and not route_enabled:
                    route_event = _coerce_existing_account_login_route_event(
                        getattr(e, "route_event", None),
                        fallback_email=current_email,
                        default_blocked=True,
                    )
                    if not route_event:
                        route_event = build_existing_account_login_route_event(
                            email=current_email,
                            reason=error_text,
                            stage="task_fallback",
                            enabled=False,
                            routed=False,
                            blocked=True,
                            action="skip_save",
                            source="registration_task",
                            deterministic=True,
                        )
                    _record_existing_account_login_route(task_id, route_event)
                    _save_task_log(
                        req.platform,
                        current_email,
                        "skipped",
                        error=error_text,
                        detail=_build_task_log_detail(
                            task_id,
                            {
                                "attempt_outcome": "existing_account_login_route_blocked",
                                "email": current_email,
                                "existing_account_login_route": route_event,
                            },
                        ),
                    )
                    return _finish_attempt_result(AttemptResult.skipped(
                        error_text,
                        metadata=_attempt_result_metadata(
                            email=current_email,
                            reason_code="existing_account",
                            mailbox_action="keep",
                            backfill=True,
                            existing_account_login_route=route_event,
                        ),
                    ))

                safe_early_failure = bool(
                    browser_executor
                    and browser_register_invoked
                    and mailbox_finalize_outcome == "early_failure"
                )
                consumes_target_slot = bool(
                    browser_executor
                    and browser_register_invoked
                    and not deterministic_existing
                    and not safe_early_failure
                )
                if deterministic_existing:
                    failure_reason_code = "existing_account_login_recovery_failed"
                elif safe_early_failure:
                    failure_reason_code = "registration_early_failure"
                else:
                    failure_reason_code = "registration_failed"
                _save_task_log(
                    req.platform,
                    current_email,
                    "failed",
                    error=error_text,
                    detail=_build_task_log_detail(
                        task_id,
                        {
                            "attempt_outcome": "failed",
                            "email": current_email,
                            "mailbox_finalize_outcome": mailbox_finalize_outcome,
                        },
                    ),
                )
                return _finish_attempt_result(AttemptResult.failed(
                    error_text,
                    consumes_target_slot=consumes_target_slot,
                    metadata=_attempt_result_metadata(
                        email=current_email,
                        reason_code=failure_reason_code,
                        mailbox_action=mailbox_finalize_outcome or "finalized",
                        backfill=not consumes_target_slot,
                        mailbox_finalize_outcome=mailbox_finalize_outcome,
                    ),
                ))
            finally:
                if unique_exit_ip_enabled:
                    if exit_ip_heartbeat_stop is not None:
                        exit_ip_heartbeat_stop.set()
                    if exit_ip_heartbeat_thread is not None:
                        exit_ip_heartbeat_thread.join(timeout=1.0)
                    register_exit_ip_registry.release_owner(
                        exit_ip_lease_owner,
                        cooldown_seconds=unique_exit_ip_cooldown_seconds,
                    )
                if diagnostic_session is not None:
                    _finalize_attempt_diagnostics(
                        outcome="interrupted",
                        error="attempt exited before a terminal result",
                        email=str(
                            attempt_log_context.get("email")
                            or current_email
                            or ""
                        ),
                        reason_code="attempt_interrupted",
                    )
                control.finish_attempt(attempt_id)

        from concurrent.futures import FIRST_COMPLETED, CancelledError, ThreadPoolExecutor, wait

        initial_registration_entry = str(
            initial_merged_extra.get("chatgpt_registration_entry")
            or initial_merged_extra.get("registration_entry")
            or ""
        ).strip().lower().replace("-", "_")
        initial_phone_signup_entry = initial_registration_entry in {"phone", "phone_signup", "sms", "sms_signup"}
        initial_phone_signup_lines = [
            str(line or "").strip()
            for line in str(initial_merged_extra.get("chatgpt_phone_signup_phone_lines") or "").splitlines()
            if str(line or "").strip()
        ]
        initial_mail_provider = str(initial_merged_extra.get("mail_provider") or "").strip().lower()
        initial_email_api_entry = initial_mail_provider in {"email_api", "api_email", "email_otp_api", "mail_api_otp"}
        initial_email_api_candidates = []
        if initial_email_api_entry:
            try:
                if isinstance(initial_merged_extra.get("email_api_candidates"), list):
                    initial_email_api_candidates = [
                        dict(item)
                        for item in initial_merged_extra.get("email_api_candidates") or []
                        if isinstance(item, dict)
                    ]
                else:
                    from core.base_mailbox import parse_email_api_lines

                    initial_email_api_candidates, _initial_email_api_errors = parse_email_api_lines(
                        initial_merged_extra.get("email_api_lines") or initial_merged_extra.get("email_api_accounts") or "",
                        gmail_dot_variant_enabled=_truthy(initial_merged_extra.get("email_api_gmail_dot_variant_enabled", True), default=True),
                        gmail_variant_count=initial_merged_extra.get("email_api_gmail_variant_count", 2),
                        gmail_variant_rules=initial_merged_extra.get("email_api_gmail_variant_rules", "all"),
                        gmail_plus_tag_template=initial_merged_extra.get("email_api_gmail_plus_tag_template", "r{rand}"),
                        gmail_variant_random_seed=initial_merged_extra.get("email_api_gmail_variant_random_seed", ""),
                        default_scheme=str(initial_merged_extra.get("email_api_default_scheme") or "https"),
                    )
            except Exception:
                initial_email_api_candidates = []
        configured_max_attempts = 0
        if isinstance(req.extra, dict):
            configured_max_attempts = _positive_int(
                req.extra.get("register_max_attempts")
                or req.extra.get("max_register_attempts")
                or 0,
                default=0,
                minimum=0,
                maximum=500,
            )
        if initial_phone_signup_entry:
            if initial_phone_signup_lines:
                attempt_cap = len(initial_phone_signup_lines)
                if configured_max_attempts > 0:
                    attempt_cap = min(attempt_cap, max(target_successes, configured_max_attempts))
            else:
                attempt_cap = max(target_successes, configured_max_attempts) if configured_max_attempts > 0 else target_successes
        elif initial_email_api_entry:
            attempt_cap = len(initial_email_api_candidates) or target_successes
            if configured_max_attempts > 0:
                attempt_cap = min(attempt_cap, max(target_successes, configured_max_attempts))
        else:
            if configured_max_attempts > 0:
                attempt_cap = max(target_successes, configured_max_attempts)
            else:
                # 默认有限补尝试：避免代理池空/基础设施错误时无限刷 FAIL
                # （历史 attempt_cap=0 时 while 会一直 next_attempt_index++ 直到手动停止）
                attempt_cap = min(100, max(target_successes * 3, target_successes))
        if attempt_cap > 0:
            _registration_task_log(
                f"[控制] 注册最大尝试次数: {attempt_cap}",
                stage_index=1,
                phase_label="准备",
            )
        frozen_concurrency_cap = register_control.get("concurrency_cap")
        if frozen_concurrency_cap not in (None, ""):
            mode_hard_cap = (
                REGISTER_BROWSER_MAX_CONCURRENCY
                if browser_executor
                else REGISTER_PROTOCOL_MAX_CONCURRENCY
            )
            try:
                runtime_concurrency_cap = int(frozen_concurrency_cap)
            except (TypeError, ValueError):
                runtime_concurrency_cap = mode_hard_cap
            runtime_concurrency_cap = max(1, min(runtime_concurrency_cap, mode_hard_cap))
        elif browser_executor:
            runtime_concurrency_cap = _bounded_register_config_int(
                initial_merged_extra,
                "chatgpt_register_browser_max_concurrency",
                default=REGISTER_BROWSER_DEFAULT_MAX_CONCURRENCY,
                maximum=REGISTER_BROWSER_MAX_CONCURRENCY,
            )
        else:
            runtime_concurrency_cap = _bounded_register_config_int(
                initial_merged_extra,
                "chatgpt_register_protocol_max_concurrency",
                default=REGISTER_PROTOCOL_MAX_CONCURRENCY,
                maximum=REGISTER_PROTOCOL_MAX_CONCURRENCY,
            )
        runtime_forced_serial_reason = ""
        if initial_phone_signup_entry:
            runtime_forced_serial_reason = "phone_signup"
        elif initial_mail_provider == "manual_email_otp":
            runtime_forced_serial_reason = "manual_email_otp"
        if runtime_forced_serial_reason:
            runtime_concurrency_cap = 1
        max_workers = max(
            1,
            min(
                int(req.concurrency or 1),
                runtime_concurrency_cap,
                target_successes,
                attempt_cap or target_successes,
                REGISTER_CONCURRENCY_HARD_LIMIT,
            ),
        )
        runtime_control = {
            **register_control,
            "requested_concurrency": register_control.get(
                "requested_concurrency",
                int(req.concurrency or 1),
            ),
            "effective_concurrency": max_workers,
            "concurrency_cap": runtime_concurrency_cap,
            "concurrency_reason": (
                runtime_forced_serial_reason
                or register_control.get("concurrency_reason")
                or (
                    f"{'browser' if browser_executor else 'protocol'}_cap"
                    if int(req.concurrency or 1) > runtime_concurrency_cap
                    else ""
                )
            ),
            "effective_delay_seconds": float(req.register_delay_seconds or 0),
            "effective_delay_max_seconds": float(req.register_delay_max_seconds or 0),
        }
        _task_store.update_meta(task_id, {"registration_control": runtime_control})
        if req.platform == "chatgpt":
            route_enabled = parse_route_bool(
                initial_merged_extra.get(
                    "chatgpt_existing_account_login_route_enabled"
                ),
                default=True,
            )
            _registration_task_log(
                "[控制] registration_policy "
                f"executor={req.executor_type or 'protocol'} "
                f"requested_concurrency={runtime_control.get('requested_concurrency')} "
                f"effective_concurrency={max_workers} cap={runtime_concurrency_cap} "
                f"delay={float(req.register_delay_seconds or 0):g}-"
                f"{float(req.register_delay_max_seconds or 0):g}s "
                f"existing_account_action={'login_recovery' if route_enabled else 'skip'} "
                "uncertain_browser_failure_slot=consume",
                stage_index=1,
                phase_label="准备",
            )
        stopped = False
        attempt_limit_reached = False
        consumed_browser_failure_slots = 0
        next_attempt_index = 0
        in_flight: dict[Any, int] = {}

        # 任务启动前预检代理候选：无可用 IP 时立即失败，避免刷几百条相同错误
        try:
            _preflight_proxies = _build_register_candidate_proxies(preflight=True)
            if not _preflight_proxies:
                raise RuntimeError("代理候选列表为空")
            _registration_task_log(
                f"[代理] 预检通过：候选 {len(_preflight_proxies)} 个 "
                f"(首个 source={str(_preflight_proxies[0][2] if _preflight_proxies else '-')[:80]})",
                stage_index=2,
                phase_label="选择代理",
            )
        except Exception as proxy_preflight_exc:
            fatal_registration_error = str(proxy_preflight_exc or "代理预检失败").strip()
            _registration_task_log(
                f"[FATAL] 代理预检失败，停止注册任务: {fatal_registration_error}",
                "error",
                stage_index=2,
                phase_label="选择代理",
            )
            errors.append(fatal_registration_error)
            if registration_eligibility_coordinator is not None:
                registration_eligibility_coordinator.finish()
            if registration_paypal_payment_coordinator is not None:
                registration_paypal_payment_coordinator.finish()
            _task_store.finish(
                task_id,
                status="failed",
                success=success,
                skipped=skipped,
                errors=errors,
                error=fatal_registration_error,
            )
            _persist_register_task_snapshot(
                task_id,
                req,
                attempt_outcome="register_failed",
                error=fatal_registration_error,
            )
            if initial_email_api_entry:
                try:
                    from core.base_mailbox import EmailApiMailbox

                    EmailApiMailbox.release_pool(task_id)
                except Exception:
                    pass
            _task_store.cleanup()
            return

        with ThreadPoolExecutor(max_workers=max_workers) as pool:
            def _cancel_queued_attempts() -> None:
                for pending in tuple(in_flight):
                    if pending.cancel():
                        in_flight.pop(pending, None)

            while (
                next_attempt_index < (attempt_cap or target_successes)
                and len(in_flight) < max_workers
                and not stopped
                and not control.should_stop_starting_new_attempts()
            ):
                future = pool.submit(_do_one, next_attempt_index)
                in_flight[future] = next_attempt_index
                next_attempt_index += 1

            while in_flight:
                if control.is_stop_requested():
                    stopped = True
                    _cancel_queued_attempts()
                elif control.is_stop_after_current_requested():
                    _cancel_queued_attempts()
                if not in_flight:
                    break

                done, _ = wait(
                    tuple(in_flight.keys()),
                    timeout=0.5,
                    return_when=FIRST_COMPLETED,
                )
                if not done:
                    continue

                for f in done:
                    in_flight.pop(f, None)
                    try:
                        result = f.result()
                    except CancelledError:
                        continue
                    except Exception as e:
                        _registration_task_log(
                            f"[ERROR] 任务线程异常: {e}",
                            "error",
                            stage_index=9,
                            phase_label="完成",
                        )
                        errors.append(str(e))
                        with success_lock:
                            fallback_slot = success + 1
                        result = AttemptResult.failed(
                            str(e),
                            metadata={"registration_success_slot": fallback_slot},
                        )

                    if result.outcome == AttemptOutcome.SUCCESS:
                        with success_lock:
                            success += 1
                    elif result.outcome == AttemptOutcome.SKIPPED:
                        skipped += 1
                    elif result.outcome == AttemptOutcome.STOPPED:
                        stopped = True
                    elif result.outcome == AttemptOutcome.FAILED:
                        errors.append(result.message)
                        if result.consumes_target_slot:
                            consumed_browser_failure_slots += 1
                        if _is_fatal_registration_infrastructure_error(result.message):
                            fatal_registration_error = str(result.message or "").strip()
                            _registration_task_log(
                                "[FATAL] Sentinel 浏览器基础设施不可用，立即停止后续注册尝试",
                                "error",
                                stage_index=9,
                                phase_label="完成",
                            )
                            control.request_stop()
                        elif "browser_registration_hard_timeout" in str(
                            result.message or ""
                        ).lower():
                            _registration_task_log(
                                "[WARN] 当前账号浏览器注册达到硬超时，已终止该账号进程；"
                                "任务继续调度后续账号",
                                "warning",
                                stage_index=9,
                                phase_label="完成",
                            )

                    with success_lock:
                        success_snapshot = success
                    _task_store.set_progress(task_id, f"{success_snapshot}/{target_successes}")
                    result_meta = (
                        dict(result.metadata)
                        if isinstance(result.metadata, dict)
                        else {}
                    )
                    if result.outcome != AttemptOutcome.NOT_STARTED:
                        reason_code = str(
                            result_meta.get("reason_code")
                            or result.outcome.value
                        ).strip()
                        mailbox_action = str(
                            result_meta.get("mailbox_action") or "-"
                        ).strip()
                        backfill = bool(
                            result_meta.get(
                                "backfill",
                                result.outcome
                                in {AttemptOutcome.SKIPPED, AttemptOutcome.FAILED}
                                and not result.consumes_target_slot,
                            )
                        )
                        certainty = (
                            "unknown"
                            if result.consumes_target_slot
                            else "deterministic"
                            if reason_code.startswith("existing_account")
                            else "known"
                        )
                        result_message = (
                            f"[结果] "
                            f"outcome={result.outcome.value.upper()} code={reason_code} "
                            f"reason={sanitize_error_message(result.message) if result.message else '-'} "
                            f"mailbox={mailbox_action} "
                            f"slot={1 if result.consumes_target_slot else 0} "
                            f"backfill={'yes' if backfill else 'no'} "
                            f"certainty={certainty} progress={success_snapshot}/{target_successes}"
                        )
                        result_success_slot = int(
                            result_meta.get("registration_success_slot")
                            or success_snapshot
                            or 1
                        )
                        _log(
                            task_id,
                            format_task_timeline_log(
                                "ChatGPT注册",
                                result_message,
                                success_slot=result_success_slot,
                                success_total=target_successes,
                                stage_index=9,
                                stage_total=registration_stage_total,
                                phase_label="完成",
                            ),
                        )

                if success >= target_successes:
                    stopped = True
                    control.request_stop()
                elif control.is_stop_requested():
                    stopped = True

                if (
                    fatal_registration_error
                    or stopped
                    or control.should_stop_starting_new_attempts()
                ):
                    # Future.cancel() only handles work that has not started. Keep
                    # running futures tracked so every attempt reaches its finally
                    # block and releases runtime state before the task is terminal.
                    _cancel_queued_attempts()
                    continue

                while (
                    success < target_successes
                    and len(in_flight) < max_workers
                    and next_attempt_index < (attempt_cap or target_successes)
                    and not control.should_stop_starting_new_attempts()
                ):
                    projected_target_slots = success + len(in_flight)
                    if browser_executor:
                        projected_target_slots += consumed_browser_failure_slots
                    if projected_target_slots >= target_successes:
                        break
                    # Only a serial task has a deterministic account-to-account boundary.
                    if max_workers == 1:
                        _log(task_id, "")
                    future = pool.submit(_do_one, next_attempt_index)
                    in_flight[future] = next_attempt_index
                    next_attempt_index += 1

                if (
                    success < target_successes
                    and attempt_cap > 0
                    and next_attempt_index >= attempt_cap
                    and not in_flight
                ):
                    attempt_limit_reached = True
                    _registration_task_log(
                        f"[控制] 已达到注册最大尝试次数 {attempt_cap}，停止补尝试",
                        stage_index=9,
                        phase_label="完成",
                    )

    except Exception as e:
        if registration_eligibility_coordinator is not None:
            registration_eligibility_coordinator.finish()
        if registration_paypal_payment_coordinator is not None:
            registration_paypal_payment_coordinator.finish()
        _registration_task_log(
            f"[ERROR] 致命错误: {e}",
            "error",
            stage_index=9,
            phase_label="完成",
        )
        _task_store.finish(
            task_id,
            status="failed",
            success=success,
            skipped=skipped,
            errors=errors,
            error=str(e),
        )
        _persist_register_task_snapshot(
            task_id,
            req,
            attempt_outcome="task_failed",
            error=str(e),
        )
        if 'initial_email_api_entry' in locals() and initial_email_api_entry:
            try:
                from core.base_mailbox import EmailApiMailbox

                EmailApiMailbox.release_pool(task_id)
            except Exception:
                pass
        if "_schedule_post_registration_refreshes" in locals():
            _schedule_post_registration_refreshes()
        _task_store.cleanup()
        return

    registration_eligibility_summary = (
        registration_eligibility_coordinator.finish()
        if registration_eligibility_coordinator is not None
        else {}
    )
    registration_paypal_payment_summary = (
        registration_paypal_payment_coordinator.finish()
        if registration_paypal_payment_coordinator is not None
        else {}
    )
    if 'attempt_limit_reached' in locals() and attempt_limit_reached and success < target_successes:
        errors.append(f"已达到注册最大尝试次数 {attempt_cap}，成功 {success}/{target_successes}")
    if fatal_registration_error:
        final_status = "failed"
    elif success >= target_successes:
        final_status = "done"
    elif errors and not (
        control.is_stop_requested()
        or control.is_stop_after_current_requested()
        or stopped
    ):
        final_status = "failed"
    elif control.is_stop_requested() or control.is_stop_after_current_requested() or stopped:
        final_status = "stopped"
    else:
        final_status = "done"
    if final_status == "stopped":
        summary = (
            f"任务已停止: 成功 {success} 个, 跳过 {skipped} 个, 失败 {len(errors)} 个"
        )
    elif final_status == "failed":
        summary = f"失败: 成功 {success} 个, 跳过 {skipped} 个, 失败 {len(errors)} 个"
    else:
        summary = f"完成: 成功 {success} 个, 跳过 {skipped} 个, 失败 {len(errors)} 个"
    if req.platform == "chatgpt":
        eligibility_counts = dict(registration_eligibility_summary.get("counts") or {})
        if int(eligibility_counts.get("completed") or 0):
            summary = (
                f"{summary}; 0 元资格: 可用 {int(eligibility_counts.get('eligible') or 0)} 个, "
                f"非 0 元 {int(eligibility_counts.get('ineligible') or 0)} 个, "
                f"检测失败 {int(eligibility_counts.get('probe_failed') or 0)} 个, "
                f"待补 Auth {int(eligibility_counts.get('pending_auth') or 0)} 个"
            )
        paypal_counts = dict(
            registration_paypal_payment_summary.get("counts") or {}
        )
        if int(paypal_counts.get("completed") or 0):
            summary = (
                f"{summary}; PayPal 注册链路: 仅提链成功 "
                f"{int(paypal_counts.get('link_succeeded') or 0)} 个, 已交支付队列 "
                f"{int(paypal_counts.get('submitted') or 0)} 个, "
                f"提链失败 {int(paypal_counts.get('extract_failed') or 0)} 个, "
                f"入队失败 {int(paypal_counts.get('submit_failed') or 0)} 个, "
                f"待补 Auth {int(paypal_counts.get('pending_auth') or 0)} 个"
            )
    if req.platform == "chatgpt" and (chatgpt_checkout_amount_zero + chatgpt_checkout_amount_nonzero) > 0:
        summary = (
            f"{summary}; Plus checkout amount=0: {chatgpt_checkout_amount_zero} 个, "
            f"amount!=0: {chatgpt_checkout_amount_nonzero} 个"
        )
        if chatgpt_zero_amount_stop_enabled:
            summary = (
                f"{summary}; zero-stop={'触发' if chatgpt_zero_amount_stop_triggered else '未触发'} "
                f"threshold={chatgpt_zero_amount_stop_threshold}"
            )
    _registration_task_log(
        summary,
        stage_index=9,
        phase_label="完成",
    )
    if initial_phone_signup_entry:
        try:
            final_meta = dict(_task_store.snapshot(task_id).get("meta") or {})
            prefix_summary = final_meta.get("prefix_summary") if isinstance(final_meta.get("prefix_summary"), dict) else {}
            if prefix_summary and prefix_summary.get("items"):
                _log(
                    task_id,
                    "[手机号注册号段] 汇总: "
                    f"成功样本 {int(prefix_summary.get('positive_sample_prefix_count') or 0)}，"
                    f"失败样本 {int(prefix_summary.get('negative_sample_prefix_count') or 0)}，"
                    f"结果混合 {int(prefix_summary.get('mixed_sample_prefix_count') or 0)}，"
                    f"未测试 {int(prefix_summary.get('untested_prefix_count') or 0)}；"
                    "仅更新注册号段状态，不改手机号自身状态",
                )
                if prefix_summary.get("negative_sample_prefixes"):
                    _log(
                        task_id,
                        "[手机号注册号段] 失败样本号段: "
                        f"{','.join(prefix_summary.get('negative_sample_prefixes') or [])}；"
                        "仅代表本次抽样号码",
                    )
        except Exception as prefix_exc:
            _log(task_id, f"[手机号注册号段] 汇总日志失败: {prefix_exc}", "debug")
    _task_store.finish(
        task_id,
        status=final_status,
        success=success,
        skipped=skipped,
        errors=errors,
        error=fatal_registration_error,
    )
    _persist_register_task_snapshot(
        task_id,
        req,
        attempt_outcome=(
            "register_stopped"
            if final_status == "stopped"
            else "register_completed"
            if final_status == "done"
            else "register_failed"
        ),
        error=fatal_registration_error,
    )
    _schedule_post_registration_refreshes()
    if 'initial_email_api_entry' in locals() and initial_email_api_entry:
        try:
            from core.base_mailbox import EmailApiMailbox

            EmailApiMailbox.release_pool(task_id)
        except Exception:
            pass
    _task_store.cleanup()


