@router.post("/{task_id}/stop")
def stop_task(task_id: str, body: StopTaskRequest | None = None):
    mode = body.mode if body is not None else "immediate"
    try:
        if mode == "after_current":
            control = _task_store.request_stop_after_current(task_id)
            if control.get("changed"):
                _log(task_id, "[CONTROL] 已请求完成当前执行单元后停止；不会启动后续账号、手机号或订单")
            attempt_outcome = "stop_after_current_requested"
        else:
            control = _task_store.request_stop(task_id)
            if control.get("changed"):
                _log(task_id, "[CONTROL] 已请求立即停止；正在中断进行中的任务")
            attempt_outcome = "immediate_stop_requested"
    except KeyError as exc:
        raise HTTPException(404, "任务不存在") from exc
    except ValueError as exc:
        raise HTTPException(409, str(exc)) from exc

    # Persist before returning the control response.  A process restart or a
    # worker exception after the click must not lose logs already seen in the
    # live panel.  A second terminal snapshot is written by each runner.
    _persist_task_snapshot(
        task_id,
        # The store request and its snapshot are atomic.  A runner may have
        # finalized immediately after the lock was released, so use the latest
        # terminal state if it already exists instead of resurrecting history
        # as running.
        status=str(_task_store.snapshot(task_id).get("status") or "running"),
        attempt_outcome=attempt_outcome,
    )
    return {
        "ok": True,
        "task_id": task_id,
        "mode": mode,
        "changed": bool(control.get("changed")),
        "control": control,
    }


def _get_logs_from_task_rows(
    platform: str | None = None,
    page: int = 1,
    page_size: int = 50,
    source: str | None = None,
):
    normalized_source = str(source or "").strip()
    with Session(engine) as s:
        q = select(TaskLog.id, TaskLog.task_id)
        if platform:
            q = q.where(TaskLog.platform == platform)
        q = q.order_by(TaskLog.id.desc())

        if normalized_source and getattr(engine.dialect, "name", "") == "sqlite":
            # Source is stored inside the large JSON payload for historical
            # compatibility.  Let SQLite filter it without transferring and
            # decoding every task's logs in Python.
            q = q.where(
                text(
                    """
                    COALESCE(
                        NULLIF(json_extract(
                            CASE WHEN json_valid(task_logs.detail_json)
                                 THEN task_logs.detail_json ELSE '{}' END,
                            '$.source'
                        ), ''),
                        json_extract(
                            CASE WHEN json_valid(task_logs.detail_json)
                                 THEN task_logs.detail_json ELSE '{}' END,
                            '$.meta.source'
                        )
                    ) = :task_log_source
                    """
                ).bindparams(task_log_source=normalized_source)
            )
        elif normalized_source:
            # Keep the non-SQLite compatibility path for deployments whose
            # database does not provide SQLite's JSON1 functions.
            all_items = s.exec(select(TaskLog).where(TaskLog.platform == platform) if platform else select(TaskLog)).all()
            source_matched = [
                log
                for log in all_items
                if _task_log_source(_task_log_detail_dict(log)) == normalized_source
            ]
            grouped_items = _group_latest_task_logs(source_matched)
            total = len(grouped_items)
            start = max(page - 1, 0) * page_size
            items = grouped_items[start:start + page_size]
            return {"total": total, "items": [_task_log_summary(item) for item in items]}

        index_rows = s.exec(q).all()
        legacy_ids = [int(row[0]) for row in index_rows if not str(row[1] or "").strip()]
        legacy_details: dict[int, dict[str, Any]] = {}
        if legacy_ids:
            legacy_rows = s.exec(select(TaskLog).where(TaskLog.id.in_(legacy_ids))).all()
            legacy_details = {
                int(log.id): _task_log_detail_dict(log)
                for log in legacy_rows
                if log.id is not None
            }

        grouped_ids: list[int] = []
        seen: set[str] = set()
        for row in index_rows:
            log_id = int(row[0])
            task_id = str(row[1] or "").strip()
            if not task_id:
                task_id = str(legacy_details.get(log_id, {}).get("task_id") or "").strip()
            group_key = f"task:{task_id}" if task_id else f"log:{log_id}"
            if group_key in seen:
                continue
            seen.add(group_key)
            grouped_ids.append(log_id)
        total = len(grouped_ids)
        start = max(page - 1, 0) * page_size
        page_ids = grouped_ids[start:start + page_size]
        if not page_ids:
            return {"total": total, "items": []}
        page_logs = s.exec(select(TaskLog).where(TaskLog.id.in_(page_ids))).all()
        by_id = {int(log.id): log for log in page_logs if log.id is not None}
        items = [by_id[log_id] for log_id in page_ids if log_id in by_id]
    return {"total": total, "items": [_task_log_summary(item) for item in items]}


@router.get("/logs")
def get_logs(
    platform: str = None,
    page: int = 1,
    page_size: int = 50,
    source: str = None,
):
    page_value = max(1, int(page or 1))
    page_size_value = max(1, min(int(page_size or 50), 200))
    normalized_source = str(source or "").strip()
    try:
        _ensure_task_log_summaries_current()
        with Session(engine) as session:
            index_query = select(
                TaskLogSummaryModel.log_id,
                TaskLogSummaryModel.group_key,
            )
            if platform:
                index_query = index_query.where(
                    TaskLogSummaryModel.platform == platform
                )
            if normalized_source:
                index_query = index_query.where(
                    TaskLogSummaryModel.source == normalized_source
                )
            index_rows = session.exec(
                index_query.order_by(TaskLogSummaryModel.log_id.desc())
            ).all()

            grouped_ids: list[int] = []
            seen: set[str] = set()
            for row in index_rows:
                log_id = int(row[0])
                group_key = str(row[1] or f"log:{log_id}")
                if group_key in seen:
                    continue
                seen.add(group_key)
                grouped_ids.append(log_id)

            total = len(grouped_ids)
            start = (page_value - 1) * page_size_value
            page_ids = grouped_ids[start:start + page_size_value]
            if not page_ids:
                return {"total": total, "items": []}

            summary_rows = session.exec(
                select(TaskLogSummaryModel).where(
                    TaskLogSummaryModel.log_id.in_(page_ids)
                )
            ).all()
            summaries_by_id = {
                int(row.log_id): row
                for row in summary_rows
            }
            items_by_id: dict[int, dict[str, Any]] = {}
            repair_ids: list[int] = []
            for log_id in page_ids:
                row = summaries_by_id.get(log_id)
                if row is None:
                    repair_ids.append(log_id)
                    continue
                try:
                    items_by_id[log_id] = _task_log_cached_summary(row)
                except ValueError:
                    repair_ids.append(log_id)

            if repair_ids:
                repair_logs = session.exec(
                    select(TaskLog).where(TaskLog.id.in_(repair_ids))
                ).all()
                for log in repair_logs:
                    detail = _task_log_detail_dict(log)
                    items_by_id[int(log.id or 0)] = _task_log_summary_from_detail(
                        log,
                        detail,
                    )
                    _upsert_task_log_summary(session, log, detail=detail)
                session.commit()

            return {
                "total": total,
                "items": [
                    items_by_id[log_id]
                    for log_id in page_ids
                    if log_id in items_by_id
                ],
            }
    except SQLAlchemyError as exc:
        logger.warning(
            "Task log summary cache unavailable; using detail-row fallback: %s",
            exc,
        )
        return _get_logs_from_task_rows(
            platform=platform,
            page=page_value,
            page_size=page_size_value,
            source=normalized_source,
        )


