@router.get("/logs/{log_id}")
def get_log_detail(log_id: int):
    with Session(engine) as s:
        log = s.get(TaskLog, log_id)
        if log is None:
            raise HTTPException(404, "任务历史不存在")
        task_id = str(log.task_id or "").strip()
        if task_id:
            related = s.exec(
                select(TaskLog)
                .where(TaskLog.task_id == task_id)
                .order_by(TaskLog.id.asc())
            ).all()
            if len(related) > 1:
                # This is an in-memory response merge only; do not rewrite old
                # rows as part of a read request.
                log.detail_json = json.dumps(
                    _merge_task_log_detail_rows(related),
                    ensure_ascii=False,
                )
    return _task_log_detail_payload(log)


def get_log_detail_by_task(task_id: str):
    """Return durable task history even after the runtime task is cleaned."""
    normalized_task_id = str(task_id or "").strip()
    if not normalized_task_id:
        raise HTTPException(400, "task_id 不能为空")
    with Session(engine) as session:
        rows = session.exec(
            select(TaskLog)
            .where(TaskLog.task_id == normalized_task_id)
            .order_by(TaskLog.id.asc())
        ).all()
    events = _registration_paypal_events_for_task(normalized_task_id)
    if not rows:
        if not events:
            raise HTTPException(404, "任务历史不存在")
        detail: dict[str, Any] = {
            "task_id": normalized_task_id,
            "status_snapshot": "running" if events else "stopped",
            "progress": "",
            "success": 0,
            "skipped": 0,
            "errors": [],
            "logs": [],
            "source": "registration_paypal_payment",
        }
        _attach_registration_paypal_events(detail, normalized_task_id)
        return {
            "id": None,
            "platform": "chatgpt",
            "email": "",
            "status": "running",
            "error": "",
            "created_at": events[0].get("created_at") if events else "",
            "task_id": normalized_task_id,
            "source": detail["source"],
            "detail": detail,
        }
    # Merge legacy duplicate snapshots in memory, then attach append-only
    # events.  No read request rewrites the historical rows.
    detail = _merge_task_log_detail_rows(rows) if len(rows) > 1 else _task_log_detail_dict(rows[0])
    _attach_registration_paypal_events(detail, normalized_task_id)
    latest = rows[-1]
    payload = {
        **_task_log_summary_from_detail(latest, detail),
        "detail": detail,
    }
    payload["task_id"] = normalized_task_id
    return payload


@router.post("/logs/batch-delete")
def batch_delete_logs(body: TaskLogBatchDeleteRequest):
    if not body.ids:
        raise HTTPException(400, "任务历史 ID 列表不能为空")

    unique_ids = list(dict.fromkeys(body.ids))
    if len(unique_ids) > 1000:
        raise HTTPException(400, "单次最多删除 1000 条任务历史")

    with Session(engine) as s:
        try:
            logs = s.exec(select(TaskLog).where(TaskLog.id.in_(unique_ids))).all()
            found_ids = {log.id for log in logs if log.id is not None}
            selected_task_ids = {str(log.task_id or "").strip() for log in logs if str(log.task_id or "").strip()}
            logs_to_delete: list[TaskLog] = []
            seen_delete_ids: set[int] = set()

            if selected_task_ids:
                related_logs = s.exec(select(TaskLog).where(TaskLog.task_id.in_(selected_task_ids))).all()
                for log in related_logs:
                    if log.id is None or int(log.id) in seen_delete_ids:
                        continue
                    logs_to_delete.append(log)
                    seen_delete_ids.add(int(log.id))

            for log in logs:
                if str(log.task_id or "").strip():
                    continue
                if log.id is None or int(log.id) in seen_delete_ids:
                    continue
                logs_to_delete.append(log)
                seen_delete_ids.add(int(log.id))

            summary_ids = [
                int(log.id)
                for log in logs_to_delete
                if log.id is not None
            ]
            if summary_ids:
                s.exec(
                    delete(TaskLogSummaryModel).where(
                        TaskLogSummaryModel.log_id.in_(summary_ids)
                    )
                )
            if selected_task_ids:
                s.exec(
                    delete(RegistrationPaypalPaymentEventModel).where(
                        RegistrationPaypalPaymentEventModel.task_id.in_(selected_task_ids)
                    )
                )
            for log in logs_to_delete:
                s.delete(log)

            s.commit()
            deleted_count = len(found_ids)
            not_found_ids = [log_id for log_id in unique_ids if log_id not in found_ids]
            logger.info("批量删除任务历史成功: %s 条", deleted_count)

            return {
                "deleted": deleted_count,
                "deleted_records": len(logs_to_delete),
                "not_found": not_found_ids,
                "total_requested": len(unique_ids),
            }
        except Exception as e:
            s.rollback()
            logger.exception("批量删除任务历史失败")
            raise HTTPException(500, f"批量删除任务历史失败: {str(e)}")


@router.get("/{task_id}/logs/stream")
async def stream_logs(task_id: str, since: int = 0):
    """SSE 实时日志流"""
    _ensure_task_exists(task_id)

    async def event_generator():
        sent = since
        while True:
            logs, status, start_index, next_index = _task_store.log_window_state(task_id)
            if sent < start_index:
                sent = start_index
            while sent < next_index:
                local_index = sent - start_index
                if local_index < 0 or local_index >= len(logs):
                    break
                yield f"data: {json.dumps({'line': logs[local_index]})}\n\n"
                sent += 1
            if status in TERMINAL_TASK_STATUSES:
                yield f"data: {json.dumps({'done': True, 'status': status})}\n\n"
                break
            await asyncio.sleep(0.5)

    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
        },
    )


@router.get("/active-summary")
def list_active_task_summaries(request: Request):
    snapshots = _task_store.list_snapshots()
    has_runtime_active_task = any(
        str(item.get("status") or "").strip().lower() in {"pending", "running"}
        for item in snapshots
    )
    active_items = []
    for item in snapshots:
        status = str(item.get("status") or "").strip().lower()
        if status not in {"pending", "running"}:
            continue
        meta = sanitize_task_detail(dict(item.get("meta") or {}))
        source = str(item.get("source") or "").strip()
        progress = str(item.get("progress") or "").strip()
        active_items.append(
            {
                "id": item.get("id"),
                "status": item.get("status"),
                "platform": item.get("platform"),
                "source": source,
                "meta": meta,
                "progress": item.get("progress"),
                "success": item.get("success"),
                "skipped": item.get("skipped"),
                "error": sanitize_error_message(item.get("error", "")),
                "control": dict(item.get("control") or {}),
                "pending_verification": sanitize_task_detail(item.get("pending_verification")),
            }
        )
    if _legacy_empty_task_summary_poll_guard.should_force_refresh(
        request,
        has_runtime_active_task=has_runtime_active_task,
    ):
        return JSONResponse(
            status_code=401,
            content={
                "detail": {
                    "code": "CLIENT_REFRESH_REQUIRED",
                    "message": "检测到已失效任务页面的异常轮询，已要求重新加载当前版本。",
                }
            },
            headers={"Cache-Control": "no-store"},
        )
    return active_items


@router.get("/{task_id}")
def get_task(task_id: str):
    if not _task_store.exists(task_id):
        # The in-memory runner is intentionally evicted after terminal tasks;
        # durable TaskLog/payment events are still authoritative for refreshes
        # from a registration page or after a service restart.
        with Session(engine) as session:
            persisted_rows = session.exec(
                select(TaskLog)
                .where(TaskLog.task_id == str(task_id or ""))
                .order_by(TaskLog.id.asc())
            ).all()
        if persisted_rows:
            detail = (
                _merge_task_log_detail_rows(persisted_rows)
                if len(persisted_rows) > 1
                else _task_log_detail_dict(persisted_rows[0])
            )
            _attach_registration_paypal_events(detail, task_id)
            latest = persisted_rows[-1]
            persisted_snapshot = _attach_registration_paypal_followup_summary(
                {
                    "id": task_id,
                    "task_id": task_id,
                    "platform": latest.platform,
                    "source": _task_log_source(detail),
                    "status": _effective_task_log_status(latest, detail=detail),
                    "progress": str(detail.get("progress") or ""),
                    "success": int(detail.get("success") or 0),
                    "skipped": int(detail.get("skipped") or 0),
                    "errors": list(detail.get("errors") or []),
                    "error": latest.error,
                    "logs": list(detail.get("logs") or []),
                    "meta": dict(detail.get("meta") or {}),
                    "payment_events": list(detail.get("payment_events") or []),
                    "timeline": list(detail.get("timeline") or []),
                    "expired": True,
                },
                task_id,
            )
            safe_snapshot = _sanitize_task_snapshot_for_response(persisted_snapshot)
            if _registration_paypal_followup_is_active(persisted_snapshot):
                return JSONResponse(
                    content=safe_snapshot,
                    headers={"Cache-Control": "no-store"},
                )
            return safe_snapshot
        if _registration_paypal_events_for_task(task_id):
            detail = {
                "task_id": task_id,
                "status_snapshot": "running",
                "source": "registration_paypal_payment",
                "logs": [],
                "errors": [],
            }
            _attach_registration_paypal_events(detail, task_id)
            event_snapshot = _attach_registration_paypal_followup_summary(
                {
                    "id": task_id,
                    "task_id": task_id,
                    "source": detail["source"],
                    "status": "running",
                    "logs": [],
                    "errors": [],
                    "meta": {},
                    "payment_events": detail.get("payment_events") or [],
                    "timeline": detail.get("timeline") or [],
                    "expired": True,
                },
                task_id,
                force=True,
            )
            followup_active = _registration_paypal_followup_is_active(event_snapshot)
            event_snapshot["status"] = "running" if followup_active else "done"
            safe_snapshot = _sanitize_task_snapshot_for_response(event_snapshot)
            return JSONResponse(
                content=safe_snapshot,
                headers={
                    "Cache-Control": (
                        "no-store" if followup_active else "private, max-age=300"
                    )
                },
            )
        # Keep the normal 404 contract for arbitrary IDs.  Runtime-generated
        # task_* IDs receive a short cacheable terminal tombstone so an old
        # browser bundle cannot turn a restart into a permanent 1–3 Hz retry.
        if str(task_id or "").startswith("task_"):
            return JSONResponse(
                content=_expired_task_snapshot(task_id),
                headers={"Cache-Control": "private, max-age=300"},
            )
        _ensure_task_exists(task_id)

    raw_snapshot = _attach_registration_paypal_followup_summary(
        _task_store.snapshot(task_id),
        task_id,
    )
    snapshot = _sanitize_task_snapshot_for_response(raw_snapshot)
    if str(snapshot.get("status") or "").strip().lower() in TERMINAL_TASK_STATUSES:
        # Registration is terminal before its durable PayPal followup.  Keep
        # that snapshot dynamic until reconciliation reaches a terminal state.
        return JSONResponse(
            content=snapshot,
            headers={
                "Cache-Control": (
                    "no-store"
                    if _registration_paypal_followup_is_active(raw_snapshot)
                    else "private, max-age=300"
                )
            },
        )
    return snapshot


@router.get("")
def list_tasks():
    return [
        _sanitize_task_snapshot_for_response(snapshot)
        for snapshot in _task_store.list_snapshots()
    ]
